-- ============================== 0056_branch_features.sql ==============================
begin;
do $run$ begin
  if exists (select 1 from public.app_migrations where version = '0056_branch_features.sql') then return; end if;
  execute $m0056$
-- 0056: الميزات الجديدة (C1-C8) بالفروع: كل فرع ليه بياناته وحساباته، وعرض "كل الفروع" المجمّع لصاحب المحل،
-- والموظف ما بيشوفش غير فرعه. لو المحل فرع واحد، كل ده بيشتغل على الفرع الرئيسي من غير ما يبان.
-- (الصور وسجل الـ IMEI والفحص تبع الجهاز، والجهاز أصلًا معزول بالفرع من 0034.)

-- ========== الأجهزة المستعملة ==========
-- البيع في فرع الجهاز نفسه، وبخزنة من نفس الفرع
create or replace function public.sell_used_device(p_id uuid, p_used uuid, p_price bigint, p_cashbox uuid default null, p_customer uuid default null, p_note text default null)
returns uuid
language plpgsql security definer set search_path = public as $$
declare u public.used_devices; e uuid; cb uuid;
begin
  select * into u from public.used_devices where id = p_used and shop_id = public.current_shop_id() and deleted_at is null for update;
  if not found then raise exception 'E_NOT_FOUND'; end if;
  if not public.can_branch(u.branch_id) then raise exception 'E_FORBIDDEN'; end if;
  e := public.ledger_idem(p_id);
  if e is not null then return e; end if;
  if p_cashbox is not null then
    select branch_id into cb from public.accounts where id = p_cashbox and shop_id = u.shop_id;
    if cb is distinct from u.branch_id then raise exception 'E_BAD_BRANCH'; end if;
  end if;
  perform set_config('app.branch', u.branch_id::text, true);
  perform set_config('app.used_sale', 'on', true);
  e := public.record_sale(p_id, jsonb_build_array(jsonb_build_object('item', u.item_id, 'qty', 1, 'price', p_price)), p_cashbox, p_customer, p_note);
  perform set_config('app.used_sale', 'off', true);
  update public.used_devices set sold_entry = e, sold_price = p_price, sold_customer = p_customer, sold_at = now() where id = u.id;
  return e;
end $$;

drop function if exists public.used_devices_list();
create or replace function public.used_devices_list(p_branch uuid default null)
returns table(id uuid, item_id uuid, imei text, brand text, model text, storage text, color text, condition text, branch_id uuid,
              status text, bought_at timestamptz, buy_price bigint, sale_price integer, sold_price bigint, sold_at timestamptz, profit bigint, has_seller_id boolean)
language plpgsql stable security definer set search_path = public as $$
declare amounts boolean := public.current_app_role() = 'owner' or public.has_perm('inventory', 'amounts');
begin
  if public.current_app_role() is null or public.current_app_role() = 'technician' then raise exception 'E_FORBIDDEN'; end if;
  return query
  select u.id, u.item_id, u.imei, u.brand, u.model, u.storage, u.color, u.condition, u.branch_id,
    case when q.qty > 0 then 'in_stock'
         when u.sold_entry is not null and not exists (select 1 from public.journal_entries r where r.reverses_id = u.sold_entry) then 'sold'
         else 'cancelled' end,
    u.created_at,
    case when amounts then u.buy_price end,
    i.sale_price,
    u.sold_price,
    u.sold_at,
    case when amounts and u.sold_price is not null and q.qty = 0 and not exists (select 1 from public.journal_entries r where r.reverses_id = u.sold_entry) then u.sold_price - u.buy_price end,
    u.seller_nid_secret is not null or u.seller_photo is not null
  from public.used_devices u
  join public.items i on i.id = u.item_id
  cross join lateral (select coalesce(sum(m.qty), 0)::bigint qty from public.stock_moves m where m.item_id = u.item_id) q
  where u.shop_id = public.current_shop_id() and u.deleted_at is null
    and (public.all_my_branches() or public.can_branch(u.branch_id))
    and (p_branch is null or u.branch_id = p_branch)
  order by u.created_at desc;
end $$;
revoke execute on function public.used_devices_list(uuid) from public, anon;
grant execute on function public.used_devices_list(uuid) to authenticated;

-- ========== العمولات ==========
-- قاعدة لفرع معيّن (اختياري)
alter table public.commission_rules add column if not exists branch_id uuid references public.branches(id);
drop index if exists public.commission_rules_one;
create unique index commission_rules_one on public.commission_rules(shop_id,
  coalesce(technician_id, '00000000-0000-0000-0000-000000000000'::uuid), coalesce(route_id, '00000000-0000-0000-0000-000000000000'::uuid),
  coalesce(branch_id, '00000000-0000-0000-0000-000000000000'::uuid)) where deleted_at is null;

drop function if exists public.commission_rule_for(uuid, uuid, uuid);
create or replace function public.commission_rule_for(p_shop uuid, p_tech uuid, p_route uuid, p_branch uuid) returns public.commission_rules
language sql stable security definer set search_path = public as $$
  select r.* from public.commission_rules r
  where r.shop_id = p_shop and r.deleted_at is null
    and (r.technician_id is null or r.technician_id = p_tech) and (r.route_id is null or r.route_id = p_route)
    and (r.branch_id is null or r.branch_id = p_branch)
  order by (r.technician_id is not null) desc, (r.route_id is not null) desc, (r.branch_id is not null) desc limit 1
$$;
revoke execute on function public.commission_rule_for(uuid, uuid, uuid, uuid) from public, anon, authenticated;

create or replace function public.commission_preview(p_device uuid) returns table(technician_id uuid, amount bigint)
language plpgsql stable security definer set search_path = public as $$
declare d public.devices; techs uuid[]; n int; base bigint; r public.commission_rules; t uuid; share bigint;
begin
  select * into d from public.devices where id = p_device;
  if d.id is null then return; end if;
  techs := public.device_technicians(p_device);
  n := coalesce(array_length(techs, 1), 0);
  if n = 0 then return; end if;
  base := greatest(coalesce((select c.final_cost from public.device_costs c where c.device_id = p_device and c.deleted_at is null), 0) - public.device_parts_cost(p_device), 0);
  foreach t in array techs loop
    r := public.commission_rule_for(d.shop_id, t, d.route_id, d.branch_id);
    continue when r.id is null;
    share := case when r.mode = 'fixed' then r.value else (base / n) * r.value / 10000 end;
    if share > 0 then technician_id := t; amount := share; return next; end if;
  end loop;
end $$;

-- العمولة بتتقيّد في فرع الجهاز
create or replace function public.tg_commission() returns trigger
language plpgsql security definer set search_path = public as $$
declare x record; k uuid;
begin
  if public.restoring() then return new; end if;
  if new.status <> 'delivered' or old.status = 'delivered' then return new; end if;
  for x in select * from public.commission_preview(new.id) loop
    k := md5(new.id::text || ':' || x.technician_id::text || ':commission')::uuid;
    continue when exists (select 1 from public.journal_entries j where j.idem_key = k);
    perform set_config('app.branch', new.branch_id::text, true);
    perform public.ledger_post('commission', new.id, new.order_no, jsonb_build_array(
      public.ledger_line(public.ledger_acc('exp_salaries'), x.amount, 0),
      public.ledger_line(public.ledger_acc('salaries_payable'), 0, x.amount, 'employee', x.technician_id)), new.id, k);
  end loop;
  return new;
end $$;

drop function if exists public.commissions_report(timestamptz, timestamptz);
create or replace function public.commissions_report(p_from timestamptz, p_to timestamptz, p_branch uuid default null)
returns table(technician_id uuid, full_name text, devices bigint, commission bigint, bonus bigint, penalty bigint, paid bigint, balance bigint)
language plpgsql stable security definer set search_path = public as $$
begin
  perform public.ledger_require(array['owner']::public.app_role[]);
  return query
  with l as (
    select jl.party_id pid, e.source_type st, e.reverses_id, e.id eid, e.device_id dev, e.occurred_at occ, jl.debit, jl.credit
    from public.journal_lines jl join public.journal_entries e on e.id = jl.entry_id join public.accounts a on a.id = jl.account_id
    where jl.shop_id = public.current_shop_id() and a.code = 'salaries_payable' and jl.party_type = 'employee'
      and (p_branch is null or e.branch_id = p_branch)
  ), rev as (
    select l.*, coalesce(o.source_type, l.st) kind from l left join public.journal_entries o on o.id = l.reverses_id
  )
  select p.id, p.full_name,
    (select count(distinct r.dev) from rev r where r.pid = p.id and r.kind = 'commission' and r.reverses_id is null and r.occ >= p_from and r.occ < p_to)::bigint,
    coalesce(sum(case when r.kind = 'commission' and r.occ >= p_from and r.occ < p_to then r.credit - r.debit end), 0)::bigint,
    coalesce(sum(case when r.kind = 'bonus' and r.occ >= p_from and r.occ < p_to then r.credit - r.debit end), 0)::bigint,
    coalesce(sum(case when r.kind = 'penalty' and r.occ >= p_from and r.occ < p_to then r.debit - r.credit end), 0)::bigint,
    coalesce(sum(case when r.kind = 'salary_payment' and r.occ >= p_from and r.occ < p_to then r.debit - r.credit end), 0)::bigint,
    coalesce(sum(r.credit - r.debit), 0)::bigint
  from public.profiles p
  left join rev r on r.pid = p.id
  where p.shop_id = public.current_shop_id() and p.role = 'technician'
  group by p.id, p.full_name
  order by 4 desc, p.full_name;
end $$;
revoke execute on function public.commissions_report(timestamptz, timestamptz, uuid) from public, anon;
grant execute on function public.commissions_report(timestamptz, timestamptz, uuid) to authenticated;

-- ========== قوايم الفحص: قالب للفرع بيكسب قالب المحل ==========
alter table public.check_templates add column if not exists branch_id uuid references public.branches(id);
drop index if exists public.check_templates_brand;
create unique index check_templates_brand on public.check_templates(shop_id, brand, coalesce(branch_id, '00000000-0000-0000-0000-000000000000'::uuid)) where deleted_at is null;

-- ========== الكتالوج: رابط لكل فرع (التوفر من مخزون الفرع) + رابط كل الفروع ==========
alter table public.branches add column if not exists catalog_token text unique check (catalog_token is null or length(catalog_token) = 32);

drop function if exists public.set_catalog(boolean);
create or replace function public.set_catalog(p_on boolean, p_branch uuid default null) returns text
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare s uuid := public.current_shop_id(); t text := case when p_on then encode(gen_random_bytes(16), 'hex') end;
begin
  perform public.ledger_require(array['owner']::public.app_role[]);
  if p_branch is null then
    perform set_config('warsha.system', 'on', true);
    update public.shops set catalog_token = t where id = s;
    perform set_config('warsha.system', 'off', true);
  else
    if not exists (select 1 from public.branches where id = p_branch and shop_id = s and deleted_at is null) then raise exception 'E_BAD_BRANCH'; end if;
    update public.branches set catalog_token = t where id = p_branch;
  end if;
  return t;
end $$;
revoke execute on function public.set_catalog(boolean, uuid) from public, anon;
grant execute on function public.set_catalog(boolean, uuid) to authenticated;

-- المحل والفرع (null = كل الفروع) من الـ token
create or replace function public.catalog_target(p_token text) returns table(shop_id uuid, branch_id uuid)
language sql stable security definer set search_path = public as $$
  select s.id, null::uuid from public.shops s
   where p_token is not null and length(p_token) = 32 and s.catalog_token = p_token and s.deleted_at is null and s.suspended_at is null
  union all
  select s.id, b.id from public.branches b join public.shops s on s.id = b.shop_id
   where p_token is not null and length(p_token) = 32 and b.catalog_token = p_token and b.deleted_at is null and s.deleted_at is null and s.suspended_at is null
  limit 1
$$;
revoke execute on function public.catalog_target(text) from public, anon, authenticated;

create or replace function public.catalog_shop(p_token text) returns uuid
language sql stable security definer set search_path = public as $$
  select shop_id from public.catalog_target(p_token)
$$;

create or replace function public.public_catalog(p_token text) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare s uuid; b uuid; multi boolean;
begin
  select shop_id, branch_id into s, b from public.catalog_target(p_token);
  if s is null then return null; end if;
  multi := (select count(*) from public.branches x where x.shop_id = s and x.deleted_at is null) > 1;
  return jsonb_build_object(
    'shop', (select jsonb_build_object(
               'name', sh.name,
               -- فرع معيّن: اسمه وتليفونه (لو المحل فروع)
               'branch', case when b is not null and multi then (select br.name from public.branches br where br.id = b) end,
               'phone', coalesce(case when b is not null then (select nullif(br.phone, '') from public.branches br where br.id = b) end, sh.phone),
               'currency', sh.currency,
               'logo', (select x.logo_color from public.shop_branding x where x.shop_id = sh.id and x.deleted_at is null)) from public.shops sh where sh.id = s),
    'items', coalesce((
      select jsonb_agg(x order by x->>'kind', x->>'name') from (
        select jsonb_build_object('id', i.id, 'name', i.name, 'kind', i.kind, 'price', i.sale_price, 'image', i.image_path,
                 'in_stock', coalesce((select sum(m.qty) from public.stock_moves m where m.item_id = i.id and (b is null or m.branch_id = b)), 0) > 0,
                 'details', case when i.kind = 'used' then (select jsonb_build_object('brand', u.brand, 'model', u.model, 'storage', u.storage, 'color', u.color, 'condition', u.condition)
                                                             from public.used_devices u where u.item_id = i.id) end) x
        from public.items i
        where i.shop_id = s and i.in_catalog and i.deleted_at is null and i.sale_price is not null
          and (i.kind <> 'used' or coalesce((select sum(m.qty) from public.stock_moves m where m.item_id = i.id and (b is null or m.branch_id = b)), 0) > 0)
        limit 500) q), '[]'::jsonb));
end $$;

-- ========== بوابة الجملة: البوابة ممكن تبقى لفرع (كشف حساب الفرع وطلبياته) ==========
alter table public.customers add column if not exists portal_branch uuid references public.branches(id);
alter table public.wholesale_orders add column if not exists branch_id uuid references public.branches(id);

drop function if exists public.set_portal(uuid, boolean);
create or replace function public.set_portal(p_customer uuid, p_on boolean, p_branch uuid default null) returns text
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare s uuid := public.current_shop_id(); t text := case when p_on then encode(gen_random_bytes(16), 'hex') end; b uuid := p_branch;
begin
  perform public.ledger_require(array['owner', 'reception']::public.app_role[]);
  perform public.perm_require('customers', 'edit');
  if not exists (select 1 from public.customers where id = p_customer and shop_id = s and deleted_at is null) then raise exception 'E_NOT_FOUND'; end if;
  -- الموظف اللي مش معاه كل الفروع: البوابة لفرعه هو بس
  if not public.all_my_branches() then b := public.op_branch(); end if;
  if b is not null and not exists (select 1 from public.branches where id = b and shop_id = s and deleted_at is null) then raise exception 'E_BAD_BRANCH'; end if;
  update public.customers set portal_token = t, portal_branch = case when p_on then b end where id = p_customer;
  return t;
end $$;
revoke execute on function public.set_portal(uuid, boolean, uuid) from public, anon;
grant execute on function public.set_portal(uuid, boolean, uuid) to authenticated;

create or replace function public.public_portal(p_token text) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare c public.customers := public.portal_customer(p_token); b uuid; multi boolean;
begin
  if c.id is null then return null; end if;
  b := c.portal_branch;
  multi := (select count(*) from public.branches x where x.shop_id = c.shop_id and x.deleted_at is null) > 1;
  return jsonb_build_object(
    'shop', (select jsonb_build_object('name', sh.name, 'currency', sh.currency,
               'branch', case when b is not null and multi then (select br.name from public.branches br where br.id = b) end,
               'phone', coalesce(case when b is not null then (select nullif(br.phone, '') from public.branches br where br.id = b) end, sh.phone),
               'logo', (select x.logo_color from public.shop_branding x where x.shop_id = sh.id and x.deleted_at is null)) from public.shops sh where sh.id = c.shop_id),
    'customer', jsonb_build_object('name', c.name),
    'balance', (select coalesce(sum(l.debit - l.credit), 0)::bigint from public.journal_lines l join public.accounts a on a.id = l.account_id join public.journal_entries e on e.id = l.entry_id
                where l.shop_id = c.shop_id and l.party_type = 'customer' and l.party_id = c.id and a.kind = 'receivable' and (b is null or e.branch_id = b)),
    'entries', coalesce((select jsonb_agg(x order by x->>'at' desc) from (
        select jsonb_build_object('at', e.occurred_at, 'type', e.source_type, 'no', e.entry_no, 'debit', sum(l.debit), 'credit', sum(l.credit)) x
        from public.journal_lines l join public.journal_entries e on e.id = l.entry_id join public.accounts a on a.id = l.account_id
        where l.shop_id = c.shop_id and l.party_type = 'customer' and l.party_id = c.id and a.kind = 'receivable' and (b is null or e.branch_id = b)
        group by e.id order by e.occurred_at desc limit 100) q), '[]'::jsonb),
    'orders', coalesce((select jsonb_agg(jsonb_build_object('id', o.id, 'at', o.created_at, 'status', o.status, 'lines', o.lines, 'note', o.note) order by o.created_at desc)
                        from (select * from public.wholesale_orders w where w.customer_id = c.id and w.deleted_at is null and (b is null or w.branch_id = b) order by w.created_at desc limit 20) o), '[]'::jsonb),
    'items', coalesce((select jsonb_agg(jsonb_build_object('id', i.id, 'name', i.name, 'price', i.sale_price) order by i.name)
                       from public.items i where i.shop_id = c.shop_id and i.in_catalog and i.deleted_at is null and i.kind <> 'used' and i.sale_price is not null), '[]'::jsonb));
end $$;

create or replace function public.portal_order(p_token text, p_lines jsonb, p_note text default null) returns uuid
language plpgsql security definer set search_path = public as $$
declare c public.customers := public.portal_customer(p_token); l jsonb; out jsonb := '[]'::jsonb; it public.items; q int; id uuid := gen_random_uuid();
begin
  if c.id is null then raise exception 'E_NOT_FOUND'; end if;
  if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) not between 1 and 50 then raise exception 'E_BAD_INPUT'; end if;
  if (select count(*) from public.wholesale_orders w where w.customer_id = c.id and w.created_at > now() - interval '1 day') >= 20 then raise exception 'E_TOO_MANY'; end if;
  for l in select * from jsonb_array_elements(p_lines) loop
    select * into it from public.items i where i.id = (l ->> 'item')::uuid and i.shop_id = c.shop_id and i.in_catalog and i.deleted_at is null and i.kind <> 'used';
    if it.id is null then raise exception 'E_NOT_FOUND'; end if;
    q := (l ->> 'qty')::int;
    if q is null or q < 1 or q > 10000 then raise exception 'E_BAD_AMOUNT'; end if;
    out := out || jsonb_build_array(jsonb_build_object('item', it.id, 'name', it.name, 'qty', q));
  end loop;
  perform set_config('warsha.system', 'on', true);
  insert into public.wholesale_orders(id, shop_id, customer_id, branch_id, lines, note) values (id, c.shop_id, c.id, c.portal_branch, out, nullif(trim(left(p_note, 500)), ''));
  perform set_config('warsha.system', 'off', true);
  return id;
exception when invalid_text_representation then raise exception 'E_BAD_INPUT';
end $$;

-- الطلبيات: الموظف بيشوف طلبيات فرعه بس (وطلبيات "كل الفروع" لصاحب كل الفروع)
drop policy if exists wholesale_orders_select on public.wholesale_orders;
drop policy if exists wholesale_orders_update on public.wholesale_orders;
create policy wholesale_orders_select on public.wholesale_orders for select to authenticated
  using (shop_id = public.current_shop_id() and public.current_app_role() in ('owner', 'reception')
         and (public.all_my_branches() or public.can_branch(branch_id)));
create policy wholesale_orders_update on public.wholesale_orders for update to authenticated
  using (shop_id = public.current_shop_id() and public.current_app_role() in ('owner', 'reception')
         and (public.all_my_branches() or public.can_branch(branch_id)));

-- ========== التحليلات بالفرع ==========
drop function if exists public.parts_profit(timestamptz, timestamptz);
create or replace function public.parts_profit(p_from timestamptz, p_to timestamptz, p_branch uuid default null)
returns table(item_id uuid, name text, uses bigint, devices bigint, cost bigint, revenue bigint)
language plpgsql stable security definer set search_path = public as $$
#variable_conflict use_column
begin
  perform public.ledger_require(array['owner']::public.app_role[]);
  return query
  with used as (
    select m.item_id, e.device_id, (-m.qty)::bigint q, (-m.value)::bigint v
    from public.stock_moves m join public.journal_entries e on e.id = m.entry_id
    join public.devices d on d.id = e.device_id
    where e.shop_id = public.current_shop_id() and e.source_type = 'part_use' and m.qty < 0
      and not exists (select 1 from public.journal_entries x where x.reverses_id = e.id)
      and d.status = 'delivered' and d.delivered_at >= p_from and d.delivered_at < p_to and d.deleted_at is null
      and (p_branch is null or d.branch_id = p_branch)
  ), per as (
    select u.item_id, sum(u.q)::bigint uses, count(distinct u.device_id)::bigint devs, sum(u.v)::bigint cost from used u group by u.item_id
  )
  select p.item_id, i.name, p.uses, p.devs, p.cost,
    (select coalesce(sum(c.final_cost), 0)::bigint from public.device_costs c
      where c.deleted_at is null and c.device_id in (select distinct u.device_id from used u where u.item_id = p.item_id))
  from per p join public.items i on i.id = p.item_id
  order by p.cost desc limit 30;
end $$;
revoke execute on function public.parts_profit(timestamptz, timestamptz, uuid) from public, anon;
grant execute on function public.parts_profit(timestamptz, timestamptz, uuid) to authenticated;

drop function if exists public.items_usage30();
create or replace function public.items_usage30(p_branch uuid default null) returns table(item_id uuid, used bigint)
language plpgsql stable security definer set search_path = public as $$
#variable_conflict use_column
begin
  perform public.grant_require('reports', 'view');
  return query
  select m.item_id, (-sum(m.qty))::bigint
  from public.stock_moves m join public.journal_entries e on e.id = m.entry_id
  where e.shop_id = public.current_shop_id() and m.qty < 0 and e.source_type in ('sale', 'part_use')
    and e.occurred_at >= now() - interval '30 days'
    and not exists (select 1 from public.journal_entries r where r.reverses_id = e.id)
    and (public.all_my_branches() or public.can_branch(m.branch_id))
    and (p_branch is null or m.branch_id = p_branch)
  group by m.item_id;
end $$;
revoke execute on function public.items_usage30(uuid) from public, anon;
grant execute on function public.items_usage30(uuid) to authenticated;

-- ========== تيليجرام: اسم الفرع في الرسالة لو المحل فروع ==========
create or replace function public.tg_telegram_device() returns trigger
language plpgsql security definer set search_path = public as $$
declare ev text; txt text; amt bigint; br text;
begin
  if public.restoring() then return new; end if;
  if not exists (select 1 from public.shop_telegram t where t.shop_id = new.shop_id and t.enabled) then return new; end if;
  if (select count(*) from public.branches x where x.shop_id = new.shop_id and x.deleted_at is null) > 1 then
    select ' [' || b.name || ']' into br from public.branches b where b.id = new.branch_id;
  end if;
  if tg_op = 'INSERT' then
    ev := 'intake'; txt := 'جهاز جديد ' || coalesce(new.order_no, '') || ': ' || new.brand || ' ' || new.model || ' (' || left(coalesce(new.issue, ''), 80) || ')';
  elsif new.status is distinct from old.status and new.status = 'ready' then
    ev := 'ready'; txt := 'جاهز للتسليم ' || coalesce(new.order_no, '') || ': ' || new.brand || ' ' || new.model;
  elsif new.status is distinct from old.status and new.status = 'delivered' then
    select c.final_cost into amt from public.device_costs c where c.device_id = new.id and c.deleted_at is null;
    ev := 'delivered'; txt := 'اتسلّم ' || coalesce(new.order_no, '') || ': ' || new.brand || ' ' || new.model || coalesce(' · ' || to_char(amt / 100.0, 'FM999,999,990.00'), '');
  else
    return new;
  end if;
  perform public.telegram_send(new.shop_id, ev, txt || coalesce(br, ''));
  return new;
end $$;
$m0056$;
  insert into public.app_migrations(version, how) values ('0056_branch_features.sql', 'applied');
  raise notice 'applied %', '0056_branch_features.sql';
end $run$;
commit;

-- ============================== 0057_categories.sql ==============================
begin;
do $run$ begin
  if exists (select 1 from public.app_migrations where version = '0057_categories.sql') then return; end if;
  execute $m0057$
-- 0057: K: تصفح التصنيفات (طلب صاحب المشروع بفيديو 2026-11-16، بتصميم البرنامج نفسه من غير نسخ):
-- تصنيفات بمستويين (رئيسي وفرعي) في قسمين: المنتجات والخدمات، لكل تصنيف أيقونة من أيقونات البرنامج وترتيب.
-- كل صنف ممكن يتربط بتصنيف (items.category_id)، والتصنيفات النصية القديمة بتتحول لوحدها لتصنيفات (من غير ما حاجة تضيع)،
-- والنص القديم بيفضل متزامن عشان الفلاتر والتقارير القديمة.
-- الخدمات (فحص، تنظيف، سوفت وير، نقل بيانات...) = صنف نوعه 'service': بيتباع من غير مخزون ولا تكلفة، وإيراده "إيراد الصيانة".

create table public.categories (
  id uuid primary key,
  shop_id uuid not null references public.shops(id),
  parent_id uuid references public.categories(id),
  section text not null default 'products' check (section in ('products', 'services')),
  name text not null check (length(trim(name)) between 1 and 60),
  icon text check (icon is null or icon ~ '^[a-z0-9_]{1,30}$'),
  sort integer not null default 100,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz
);
create index categories_shop on public.categories(shop_id, parent_id) where deleted_at is null;
create unique index categories_name on public.categories(shop_id, coalesce(parent_id, '00000000-0000-0000-0000-000000000000'::uuid), lower(trim(name))) where deleted_at is null;
alter table public.categories enable row level security;
create trigger set_updated_at before update on public.categories for each row execute function public.tg_set_updated_at();
create trigger block_delete before delete on public.categories for each row execute function public.tg_block_delete();
create trigger a_force_shop_id before insert or update on public.categories for each row execute function public.tg_force_shop_id();
create trigger zz_audit after insert or update on public.categories for each row execute function public.tg_audit();
create policy categories_select on public.categories for select to authenticated using (shop_id = public.current_shop_id());
-- إضافة وتعديل التصنيفات: صاحب المحل، واللي معاه "إضافة صنف جديد"
create policy categories_insert on public.categories for insert to authenticated
  with check (shop_id = public.current_shop_id() and (public.current_app_role() = 'owner' or public.has_perm('item_create', 'add')));
create policy categories_update on public.categories for update to authenticated
  using (shop_id = public.current_shop_id() and (public.current_app_role() = 'owner' or public.has_perm('item_create', 'add')));
grant select, insert, update on public.categories to authenticated;

-- مستويين بس، والفرعي في نفس قسم الرئيسي ونفس المحل
create or replace function public.tg_category_tree() returns trigger
language plpgsql security definer set search_path = public as $$
declare p public.categories;
begin
  if new.parent_id is null then return new; end if;
  if new.parent_id = new.id then raise exception 'E_BAD_INPUT'; end if;
  select * into p from public.categories where id = new.parent_id;
  if p.id is null or p.shop_id <> new.shop_id or p.deleted_at is not null then raise exception 'E_NOT_FOUND'; end if;
  if p.parent_id is not null then raise exception 'E_CATEGORY_DEPTH'; end if;
  new.section := p.section;
  return new;
end $$;
create trigger b_category_tree before insert or update on public.categories for each row execute function public.tg_category_tree();

-- التصنيف اللي فيه أصناف أو تصنيفات فرعية ما بيتأرشفش (انقل اللي فيه الأول)
create or replace function public.tg_category_archive() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.deleted_at is not null and old.deleted_at is null then
    if exists (select 1 from public.categories c where c.parent_id = new.id and c.deleted_at is null)
       or exists (select 1 from public.items i where i.category_id = new.id and i.deleted_at is null) then
      raise exception 'E_CATEGORY_NOT_EMPTY';
    end if;
  end if;
  return new;
end $$;
create trigger c_category_archive before update on public.categories for each row execute function public.tg_category_archive();

-- الأصناف: التصنيف والخدمة
alter table public.items add column if not exists category_id uuid references public.categories(id);
alter table public.items drop constraint items_kind_check;
alter table public.items add constraint items_kind_check check (kind in ('part', 'accessory', 'used', 'service'));

-- اسم التصنيف بيتنسخ في النص القديم (الفلاتر والتصدير والتقارير)
-- والعكس: صنف بتصنيف نصي بس (الاستيراد من Excel، أو البرامج القديمة) بيتربط بتصنيف بنفس الاسم، ولو مش موجود بيتعمل تصنيف رئيسي
create or replace function public.tg_item_category_text() returns trigger
language plpgsql security definer set search_path = public as $$
declare cid uuid;
begin
  if new.category_id is not null and (tg_op = 'INSERT' or new.category_id is distinct from old.category_id) then
    select c.name into new.category from public.categories c where c.id = new.category_id and c.shop_id = new.shop_id;
    if new.category is null then raise exception 'E_NOT_FOUND'; end if;
  elsif new.category_id is null and nullif(trim(new.category), '') is not null
        and (tg_op = 'INSERT' or new.category is distinct from old.category) and not public.restoring() then
    select c.id into cid from public.categories c
     where c.shop_id = new.shop_id and c.deleted_at is null and lower(trim(c.name)) = lower(trim(new.category))
     order by (c.parent_id is null), c.created_at limit 1;
    if cid is null then
      cid := gen_random_uuid();
      insert into public.categories(id, shop_id, name, icon) values (cid, new.shop_id, left(trim(new.category), 60), 'box');
    end if;
    new.category_id := cid;
    new.category := trim(new.category);
  end if;
  return new;
end $$;
create trigger b_item_category_text before insert or update of category_id, category on public.items for each row execute function public.tg_item_category_text();
create or replace function public.tg_category_rename() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.name is distinct from old.name then
    perform set_config('warsha.system', 'on', true);
    update public.items set category = new.name where category_id = new.id;
    perform set_config('warsha.system', 'off', true);
  end if;
  return new;
end $$;
create trigger d_category_rename after update of name on public.categories for each row execute function public.tg_category_rename();

-- نقل البيانات: كل تصنيف نصي قديم (في الأصناف أو في قايمة "تصنيفات الأصناف") بقى تصنيف رئيسي، والأصناف اتربطت بيه
create or replace function public.categories_from_text() returns integer
language plpgsql security definer set search_path = public as $mig$
declare r record; cid uuid; n int := 0;
begin
  perform set_config('warsha.restore', 'on', true);
  perform set_config('warsha.system', 'on', true);
  for r in
    select distinct x.shop_id, trim(x.name) as name from (
      select shop_id, category as name from public.items where category is not null and length(trim(category)) > 0 and deleted_at is null
      union select shop_id, value from public.shop_lists where list = 'item_categories' and deleted_at is null
    ) x
  loop
    select id into cid from public.categories c where c.shop_id = r.shop_id and c.parent_id is null and lower(trim(c.name)) = lower(r.name) and c.deleted_at is null;
    if cid is null then
      cid := gen_random_uuid();
      insert into public.categories(id, shop_id, name, icon) values (cid, r.shop_id, left(r.name, 60), 'box');
      n := n + 1;
    end if;
    update public.items set category_id = cid where shop_id = r.shop_id and category_id is null and lower(trim(category)) = lower(r.name);
  end loop;
  perform set_config('warsha.restore', 'off', true);
  perform set_config('warsha.system', 'off', true);
  return n;
end $mig$;
revoke execute on function public.categories_from_text() from public, anon, authenticated;
select public.categories_from_text();

-- الشجرة بالعدد: الأصناف (وأصناف الفرعي جوه الرئيسي)، واللي متوفر منها في الفرع (أو كل الفروع)
create or replace function public.category_tree(p_branch uuid default null)
returns table(id uuid, parent_id uuid, section text, name text, icon text, sort integer, items bigint, in_stock bigint)
language plpgsql stable security definer set search_path = public as $$
#variable_conflict use_column
declare s uuid := public.current_shop_id();
begin
  if s is null then raise exception 'E_FORBIDDEN'; end if;
  return query
  with st as (
    select m.item_id, sum(m.qty) q from public.stock_moves m
    where m.shop_id = s and (p_branch is null or m.branch_id = p_branch) and (public.all_my_branches() or public.can_branch(m.branch_id))
    group by m.item_id
  ), it as (
    select i.id, i.category_id, (i.kind = 'service' or coalesce(st.q, 0) > 0) avail
    from public.items i left join st on st.item_id = i.id
    where i.shop_id = s and i.deleted_at is null and i.category_id is not null
      and (i.kind <> 'used' or coalesce(st.q, 0) > 0)
  )
  select c.id, c.parent_id, c.section, c.name, c.icon, c.sort,
    (select count(*) from it where it.category_id = c.id or it.category_id in (select k.id from public.categories k where k.parent_id = c.id and k.deleted_at is null))::bigint,
    (select count(*) from it where it.avail and (it.category_id = c.id or it.category_id in (select k.id from public.categories k where k.parent_id = c.id and k.deleted_at is null)))::bigint
  from public.categories c
  where c.shop_id = s and c.deleted_at is null
  order by c.section, c.parent_id nulls first, c.sort, c.name;
end $$;
revoke execute on function public.category_tree(uuid) from public, anon;
grant execute on function public.category_tree(uuid) to authenticated;

-- ترتيب التصنيفات بالسحب (صاحب المحل)
create or replace function public.reorder_categories(p_ids uuid[]) returns void
language plpgsql security definer set search_path = public as $$
declare i int;
begin
  perform public.ledger_require(array['owner']::public.app_role[]);
  if coalesce(array_length(p_ids, 1), 0) > 200 then raise exception 'E_BAD_INPUT'; end if;
  for i in 1 .. coalesce(array_length(p_ids, 1), 0) loop
    update public.categories set sort = i * 10 where id = p_ids[i] and shop_id = public.current_shop_id();
  end loop;
end $$;
revoke execute on function public.reorder_categories(uuid[]) from public, anon;
grant execute on function public.reorder_categories(uuid[]) to authenticated;

-- التصنيفات الجاهزة (اختياري، صاحب المحل): بتتضاف بس لو اسمها مش موجود
create or replace function public.seed_categories(p_tree jsonb) returns integer
language plpgsql security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); top jsonb; sub jsonb; tid uuid; n int := 0; i int := 0; j int;
begin
  perform public.ledger_require(array['owner']::public.app_role[]);
  if jsonb_typeof(p_tree) <> 'array' or jsonb_array_length(p_tree) > 30 then raise exception 'E_BAD_INPUT'; end if;
  for top in select * from jsonb_array_elements(p_tree) loop
    i := i + 1;
    select id into tid from public.categories where shop_id = s and parent_id is null and lower(trim(name)) = lower(trim(top ->> 'name')) and deleted_at is null;
    if tid is null then
      tid := gen_random_uuid();
      insert into public.categories(id, shop_id, section, name, icon, sort) values (tid, s, coalesce(top ->> 'section', 'products'), top ->> 'name', top ->> 'icon', i * 10);
      n := n + 1;
    end if;
    j := 0;
    for sub in select * from jsonb_array_elements(coalesce(top -> 'children', '[]'::jsonb)) loop
      j := j + 1;
      if jsonb_array_length(coalesce(top -> 'children', '[]'::jsonb)) > 60 then raise exception 'E_BAD_INPUT'; end if;
      if not exists (select 1 from public.categories where shop_id = s and parent_id = tid and lower(trim(name)) = lower(trim(sub ->> 'name')) and deleted_at is null) then
        insert into public.categories(id, shop_id, parent_id, name, icon, sort) values (gen_random_uuid(), s, tid, sub ->> 'name', sub ->> 'icon', j * 10);
        n := n + 1;
      end if;
    end loop;
  end loop;
  return n;
end $$;
revoke execute on function public.seed_categories(jsonb) from public, anon;
grant execute on function public.seed_categories(jsonb) to authenticated;

-- create_item: (src: 0038_roles_grant.sql) + الخدمة
create or replace function public.create_item(
  p_id uuid, p_kind text, p_name text, p_item_type text default null, p_brand text default null, p_model text default null,
  p_quality text default null, p_color text default null, p_sale_price integer default null, p_qty integer default null, p_unit_cost bigint default null,
  p_stock_id uuid default null
) returns uuid
language plpgsql security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); nm text := trim(coalesce(p_name, ''));
begin
  perform public.ledger_require(array['owner', 'reception']::public.app_role[]);
  perform public.perm_require('item_create', 'add');
  if exists (select 1 from public.items where id = p_id and shop_id = s) then return p_id; end if;
  if p_kind not in ('part', 'accessory', 'service') or nm = '' or length(nm) > 160 then raise exception 'E_BAD_INPUT'; end if;
  if p_sale_price is not null and (p_sale_price < 0 or p_sale_price > 2000000000) then raise exception 'E_BAD_AMOUNT'; end if;
  insert into public.items(id, shop_id, kind, name, item_type, brand, model, quality, color, sale_price)
  values (p_id, s, p_kind, nm, nullif(trim(p_item_type), ''), nullif(trim(p_brand), ''), nullif(trim(p_model), ''), nullif(trim(p_quality), ''), nullif(trim(p_color), ''), p_sale_price);
  if coalesce(p_qty, 0) > 0 then
    if p_unit_cost is null or p_unit_cost <= 0 then raise exception 'E_BAD_AMOUNT'; end if;
    perform public.stock_in(coalesce(p_stock_id, gen_random_uuid()), p_id, p_qty, p_unit_cost, 'stock');
  end if;
  return p_id;
end $$;

-- record_sale: (src: 0037_item_details.sql) + الخدمات
create or replace function public.record_sale(p_id uuid, p_lines jsonb, p_cashbox uuid default null, p_customer uuid default null, p_note text default null)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  s uuid := public.current_shop_id();
  e uuid := gen_random_uuid();
  l jsonb;
  it public.items;
  q bigint; p bigint; cost bigint;
  rev_parts bigint := 0; rev_acc bigint := 0; rev_srv bigint := 0; total_cost bigint := 0;
  debit_acc uuid; pt text; pid uuid;
begin
  perform public.ledger_require(array['owner', 'reception']::public.app_role[]);
  perform public.perm_require('sales', 'add');
  if public.ledger_idem(p_id) is not null then return public.ledger_idem(p_id); end if;
  -- البيع بالآجل لصاحب المحل بس
  if p_cashbox is null and (p_customer is null or public.current_app_role() <> 'owner') then raise exception 'E_BAD_INPUT'; end if;
  if p_customer is not null and not exists (select 1 from public.customers where id = p_customer and shop_id = s and deleted_at is null) then raise exception 'E_NOT_FOUND'; end if;
  if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then raise exception 'E_BAD_INPUT'; end if;
  insert into public.journal_entries(id, shop_id, source_type, source_id, memo, idem_key, created_by)
  values (e, s, 'sale', p_id, nullif(trim(p_note), ''), p_id, auth.uid());
  -- البيع بس: لو الإعداد مفتوح، اللي مش موجود بيخرج من غير تكلفة ويتسوى بعدين
  perform set_config('app.uncosted', 'on', true);
  for l in select * from jsonb_array_elements(p_lines) loop
    select * into it from public.items where id = (l ->> 'item')::uuid and shop_id = s and deleted_at is null;
    if not found then raise exception 'E_NOT_FOUND'; end if;
    q := (l ->> 'qty')::bigint;
    p := (l ->> 'price')::bigint;
    if q is null or q <= 0 or p is null or p < 0 then raise exception 'E_BAD_AMOUNT'; end if;
    -- K: الخدمة من غير مخزون ولا تكلفة، وإيرادها إيراد الصيانة
    if it.kind = 'service' then rev_srv := rev_srv + q * p; continue; end if;
    cost := public.ledger_issue(it.id, q, e);
    total_cost := total_cost + cost;
    if it.kind = 'part' then rev_parts := rev_parts + q * p; else rev_acc := rev_acc + q * p; end if;
  end loop;
  perform set_config('app.uncosted', 'off', true);
  perform public.ledger_amount(rev_parts + rev_acc + rev_srv);
  if p_cashbox is null then
    debit_acc := public.ledger_acc('ar'); pt := 'customer'; pid := p_customer;
  else
    debit_acc := (public.ledger_cashbox(p_cashbox)).id;
  end if;
  insert into public.journal_lines(shop_id, entry_id, account_id, party_type, party_id, debit, credit)
  values (s, e, debit_acc, pt, pid, rev_parts + rev_acc + rev_srv, 0);
  if rev_parts > 0 then insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values (s, e, public.ledger_acc('rev_parts'), 0, rev_parts); end if;
  if rev_acc > 0 then insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values (s, e, public.ledger_acc('rev_accessories'), 0, rev_acc); end if;
  if rev_srv > 0 then insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values (s, e, public.ledger_acc('rev_repair'), 0, rev_srv); end if;
  if total_cost > 0 then
    insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values
      (s, e, public.ledger_acc('cogs'), total_cost, 0), (s, e, public.ledger_acc('inventory'), 0, total_cost);
  end if;
  if p_cashbox is not null and p_customer is not null then
    null; -- البيع النقدي لعميل معروف ما بيأثرش على رصيده
  end if;
  return e;
end $$;

-- النسخة الاحتياطية والاسترجاع: (src: 0049) + categories (قبل الأصناف)
create or replace function public.backup_snapshot(p_shop uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  res jsonb := jsonb_build_object('format', 'warsha-backup', 'version', 1, 'generated_at', now(), 'shop_id', p_shop);
  t text;
  rows jsonb;
begin
  foreach t in array array['shops', 'branches', 'staff_branches', 'shop_branding', 'profiles', 'customers', 'devices', 'device_costs', 'status_log', 'device_notes', 'device_photos', 'device_checks',
                           'quote_decisions', 'message_templates', 'message_log', 'accounts', 'journal_entries', 'journal_lines', 'payments', 'drawer_closings',
                           'suppliers', 'categories', 'items', 'stock_moves', 'uncosted_sales', 'payment_plans', 'plan_installments', 'branch_goals', 'printers', 'print_templates', 'check_templates', 'used_devices', 'commission_rules', 'purchases', 'labor_rates', 'specialties', 'staff_specialties', 'routes', 'repair_steps',
                           'repair_videos', 'device_ratings', 'issue_presets', 'partners', 'profit_distributions', 'party_links', 'shop_lists', 'audit_log'] loop
    execute format('select coalesce(jsonb_agg(to_jsonb(x)), ''[]''::jsonb) from public.%I x where x.shop_id = $1', t) into rows using p_shop;
    res := res || jsonb_build_object(t, rows);
  end loop;
  select coalesce(jsonb_agg(jsonb_build_object('device_id', device_id, 'kind', kind, 'erased_at', erased_at)), '[]'::jsonb)
    into rows from public.device_passcodes where shop_id = p_shop;
  return res || jsonb_build_object('device_passcodes', rows);
end $$;

-- restore_backup: (src: 0049_commissions.sql) + categories
create or replace function public.restore_backup(p_data jsonb) returns jsonb
-- extensions: فيها gen_random_bytes على Supabase
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare
  s uuid := public.current_shop_id();
  me uuid := auth.uid();
  old_shop uuid;
  old_owner uuid;
  sh jsonb;
  t text;
  r jsonb;
  rows jsonb;
  n int;
  bad int;
  counts jsonb := '{}'::jsonb;
  -- بالترتيب ده عشان كل صف يلاقي اللي بيشاور عليه
  tabs text[] := array['branches', 'profiles', 'staff_branches', 'shop_branding', 'accounts', 'customers', 'suppliers', 'party_links', 'partners', 'specialties', 'staff_specialties', 'routes', 'labor_rates',
                       'issue_presets', 'commission_rules', 'shop_lists', 'message_templates', 'categories', 'items', 'devices', 'device_costs', 'status_log', 'device_notes', 'device_checks',
                       'quote_decisions', 'repair_steps', 'repair_videos', 'device_ratings', 'journal_entries', 'journal_lines', 'profit_distributions', 'payments',
                       'purchases', 'stock_moves', 'uncosted_sales', 'used_devices', 'payment_plans', 'plan_installments', 'branch_goals', 'printers', 'print_templates', 'check_templates', 'drawer_closings', 'message_log', 'audit_log'];
  -- الجداول دي ليها نسخة اتعملت مع التسجيل: بتتطابق بالكود (أو المفتاح) وبتاخد قيم النسخة
  keyed text[] := array['branches', 'accounts', 'routes', 'specialties', 'message_templates', 'labor_rates', 'shop_branding'];
begin
  perform public.ledger_require(array['owner']::public.app_role[]);
  if s is null or me is null then raise exception 'E_FORBIDDEN'; end if;
  if p_data is null or p_data->>'format' is distinct from 'warsha-backup' or coalesce((p_data->>'version')::int, 0) <> 1 then
    raise exception 'E_BACKUP_FORMAT';
  end if;
  old_shop := (p_data->>'shop_id')::uuid;
  if old_shop is null or old_shop = s then raise exception 'E_BACKUP_FORMAT'; end if;

  -- محل جديد فاضي بس
  if exists (select 1 from public.devices where shop_id = s) or exists (select 1 from public.customers where shop_id = s)
     or exists (select 1 from public.journal_entries where shop_id = s) or exists (select 1 from public.items where shop_id = s)
     or exists (select 1 from public.suppliers where shop_id = s) or exists (select 1 from public.payments where shop_id = s)
     or exists (select 1 from public.purchases where shop_id = s) or exists (select 1 from public.drawer_closings where shop_id = s)
     or exists (select 1 from public.stock_moves where shop_id = s)
     or exists (select 1 from public.profiles where shop_id = s and id <> me) then
    raise exception 'E_RESTORE_NOT_EMPTY';
  end if;

  perform set_config('warsha.restore', 'on', true);
  drop table if exists pg_temp._rmap;
  create temp table _rmap(old uuid primary key, new uuid not null) on commit drop;
  insert into _rmap values (old_shop, s);

  -- 1) بيانات المحل نفسه (من غير الخطة والإيقاف واللوجو اللي في Storage)
  sh := p_data->'shops'->0;
  if sh is not null then
    update public.shops set
      name = coalesce(sh->>'name', name), phone = sh->>'phone', address = sh->>'address',
      receipt_terms = coalesce(sh->>'receipt_terms', receipt_terms), warranty_days = coalesce((sh->>'warranty_days')::int, warranty_days),
      country = coalesce(sh->>'country', country), currency = coalesce(sh->>'currency', currency),
      payment_methods = coalesce(array(select jsonb_array_elements_text(sh->'payment_methods')), payment_methods),
      theme = coalesce(sh->>'theme', theme), locale = coalesce(sh->>'locale', locale),
      default_margin_pct = coalesce((sh->>'default_margin_pct')::int, default_margin_pct),
      extras = coalesce(sh->'extras', extras), max_discount_pct = coalesce((sh->>'max_discount_pct')::int, max_discount_pct)
    where id = s;
  end if;

  -- 2) الـ ids الجديدة
  -- صاحب المحل في النسخة = اللي بيسترجع دلوقتي
  select (x->>'id')::uuid into old_owner from jsonb_array_elements(coalesce(p_data->'profiles', '[]')) x
   where x->>'role' = 'owner' order by x->>'created_at' limit 1;
  if old_owner is not null then insert into _rmap values (old_owner, me) on conflict do nothing; end if;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.accounts a where a.shop_id = s and a.code = x->>'code' and x->>'code' is not null), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'accounts', '[]')) x on conflict do nothing;
  -- الفرع الرئيسي في النسخة = الفرع الرئيسي للمحل الجديد
  insert into _rmap select (x->>'id')::uuid, public.main_branch(s)
    from jsonb_array_elements(coalesce(p_data->'branches', '[]')) x where (x->>'is_main')::boolean and x->>'deleted_at' is null on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.routes a where a.shop_id = s and a.code = x->>'code' and x->>'code' is not null), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'routes', '[]')) x on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.specialties a where a.shop_id = s and a.code = x->>'code' and x->>'code' is not null), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'specialties', '[]')) x on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.message_templates a where a.shop_id = s and a.key = x->>'key'), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'message_templates', '[]')) x on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.labor_rates a where a.shop_id = s and a.deleted_at is null and lower(trim(a.issue)) = lower(trim(x->>'issue')) and x->>'deleted_at' is null), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'labor_rates', '[]')) x on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.shop_branding a where a.shop_id = s), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'shop_branding', '[]')) x on conflict do nothing;
  foreach t in array tabs loop
    insert into _rmap select (x->>'id')::uuid, gen_random_uuid() from jsonb_array_elements(coalesce(p_data->t, '[]')) x where x ? 'id' on conflict do nothing;
  end loop;

  -- 3) الصفوف نفسها بالترتيب
  foreach t in array tabs loop
    rows := '[]'::jsonb;
    for r in select public.restore_remap(x) from jsonb_array_elements(coalesce(p_data->t, '[]')) x loop
      if t = 'profiles' then
        -- صاحب المحل موجود أصلًا. الباقيين موظفين سابقين (من غير حساب دخول)
        continue when (r->>'id')::uuid = me;
        r := r || jsonb_build_object('deleted_at', coalesce(r->>'deleted_at', now()::text));
      elsif t = 'devices' then
        -- كود التتبع (الـ QR) بيفضل زي ما هو، إلا لو مستخدم في المشروع ده (المحل الأصلي لسه هنا)
        if exists (select 1 from public.devices d where d.tracking_token = r->>'tracking_token') then
          r := r || jsonb_build_object('tracking_token', encode(gen_random_bytes(12), 'hex'));
        end if;
      elsif t = 'journal_entries' then
        if r->>'idem_key' is not null and exists (select 1 from public.journal_entries j where j.idem_key = (r->>'idem_key')::uuid) then
          r := r || jsonb_build_object('idem_key', gen_random_uuid());
        end if;
      elsif t = 'accounts' and r->>'kind' = 'cash' and r->>'branch_id' is null then
        -- نسخة من قبل الفروع: الخزن كلها في الفرع الرئيسي
        r := r || jsonb_build_object('branch_id', public.main_branch(s));
      elsif t = 'used_devices' then
        -- رقم بطاقة البائع (في Vault) وصورتها (في Storage) مش جوه النسخة
        r := r || jsonb_build_object('seller_nid_secret', null, 'seller_photo', null);
      elsif t = 'shop_branding' then
        -- اللوجو الملون والحراري جوه الصف نفسه. الملف الأصلي في Storage مش جوه النسخة
        r := r || jsonb_build_object('logo_path', null);
      end if;
      if t = any (keyed) and exists (select 1 from _rmap m where m.new = (r->>'id')::uuid and m.old <> m.new)
         and (t <> 'shop_branding' or exists (select 1 from public.shop_branding b where b.id = (r->>'id')::uuid)) then
        -- موجود من التسجيل: بياخد قيم النسخة
        execute format('select count(*) from public.%I where id = $1', t) into n using (r->>'id')::uuid;
        if n > 0 then
          execute format('update public.%1$I x set (%2$s) = (select %2$s from jsonb_populate_record(null::public.%1$I, $1)) where x.id = $2', t,
            (select string_agg(quote_ident(c.column_name), ', ' order by c.ordinal_position) from information_schema.columns c
              where c.table_schema = 'public' and c.table_name = t and c.column_name not in ('id', 'shop_id')))
            using r, (r->>'id')::uuid;
          continue;
        end if;
      end if;
      rows := rows || jsonb_build_array(r);
    end loop;
    if jsonb_array_length(rows) > 0 then
      -- overriding system value: أرقام القيود (entry_no) بترجع زي ما هي
      execute format('insert into public.%1$I overriding system value select * from jsonb_populate_recordset(null::public.%1$I, $1)', t) using rows;
    end if;
    counts := counts || jsonb_build_object(t, jsonb_array_length(coalesce(p_data->t, '[]')));
  end loop;

  -- 4) عدّاد أرقام الطلبات: من آخر رقم راجع في كل سنة
  -- (لكل فرع: الرقم ممكن يبقى قبله بادئة الفرع B2-2026-0001)
  insert into public.order_counters(shop_id, branch_id, year, last_value)
  select s, branch_id, (regexp_match(order_no, '(\d{4})-(\d+)$'))[1]::int, max((regexp_match(order_no, '(\d{4})-(\d+)$'))[2]::int)
    from public.devices where shop_id = s and order_no ~ '\d{4}-\d+$' group by 2, 3
  on conflict (shop_id, branch_id, year) do update set last_value = greatest(public.order_counters.last_value, excluded.last_value);

  -- 5) التأكد: كل قيد متوازن، ورصيد كل حساب = رصيده في النسخة بالظبط
  select count(*) into bad from (
    select entry_id from public.journal_lines where shop_id = s group by entry_id having sum(debit) <> sum(credit)) x;
  if bad > 0 then raise exception 'E_RESTORE_UNBALANCED'; end if;
  select count(*) into bad from (
    select m.new acc, sum((l->>'debit')::bigint - (l->>'credit')::bigint) b
      from jsonb_array_elements(coalesce(p_data->'journal_lines', '[]')) l join _rmap m on m.old = (l->>'account_id')::uuid group by m.new
  ) x full join (select account_id, sum(debit - credit) b from public.journal_lines where shop_id = s group by account_id) y on y.account_id = x.acc
  where coalesce(x.b, 0) <> coalesce(y.b, 0);
  if bad > 0 then raise exception 'E_RESTORE_MISMATCH'; end if;
  -- وعدد الصفوف في كل جدول (الحسابات والقوالب اللي اتعملت مع التسجيل ممكن تزيد عن النسخة، مش تقل)
  foreach t in array tabs loop
    execute format('select count(*) from public.%I where shop_id = $1', t) into n using s;
    if n < jsonb_array_length(coalesce(p_data->t, '[]')) - (case when t = 'profiles' and old_owner is not null then 1 else 0 end) then
      raise exception 'E_RESTORE_MISMATCH';
    end if;
  end loop;

  perform set_config('warsha.restore', 'off', true);
  insert into public.audit_log(shop_id, actor_id, action, entity, entity_id, after)
  values (s, me, 'backup_restore', 'shops', s, jsonb_build_object('from_shop', old_shop, 'generated_at', p_data->>'generated_at', 'counts', counts));
  return jsonb_build_object('restored', true, 'counts', counts);
end $$;
$m0057$;
  insert into public.app_migrations(version, how) values ('0057_categories.sql', 'applied');
  raise notice 'applied %', '0057_categories.sql';
end $run$;
commit;

-- ============================== 0058_web_push.sql ==============================
begin;
do $run$ begin
  if exists (select 1 from public.app_migrations where version = '0058_web_push.sql') then return; end if;
  execute $m0058$
-- 0058: Web Push: إشعارات على الجهاز حتى والبرنامج مقفول (N المرحلة التانية)
--
-- - مجاني: خدمات الإشعارات بتاعة المتصفحات (Chrome/Edge/Firefox/Safari) مجانية، ومفيش أي خدمة مدفوعة.
-- - كل مستخدم بيفعّلها لجهازه من الإعدادات ← التنبيهات. الاشتراك بتاع الجهاز (endpoint + المفاتيح العامة) بيتحفظ هنا،
--   وصاحبه بس اللي يشوفه. الكتابة من الدوال بس.
-- - الإشعارات نفسها هي نفس اللي في الجرس (my_notifications) بنفس الصلاحيات بالظبط: الفني ما يوصلوش أقساط ولا فلوس.
-- - كل إشعار بيتبعت مرة واحدة بس لكل مستخدم (push_sent)، وما بيتبعتش لو المستخدم قراه في البرنامج.
-- - التوقيت: من الساعة كام لحد الساعة كام (بتوقيت القاهرة) من الإعدادات. برّه الوقت ده الإشعارات بتستنى.
-- - الإرسال من Edge Function اسمها push بمفاتيح VAPID في أسرار Supabase (التشفير جوه الدالة، مش هنا).
-- - زرار "اتقرا" في الإشعار بيشتغل بـ token عشوائي لمرة واحدة (push_ack) من غير تسجيل دخول.
-- - الاشتراكات خاصة بالجهاز، فما بتدخلش في النسخة الاحتياطية (بعد الاسترجاع كل واحد بيفعّل من جهازه تاني).

create table public.push_subscriptions (
  id uuid primary key default gen_random_uuid(),
  shop_id uuid not null references public.shops(id),
  profile_id uuid not null references auth.users(id),
  endpoint text not null check (length(endpoint) between 12 and 1000 and endpoint like 'https://%'),
  p256dh text not null check (p256dh ~ '^[A-Za-z0-9_-]{80,100}$'),
  auth text not null check (auth ~ '^[A-Za-z0-9_-]{16,44}$'),
  locale text not null default 'ar' check (locale in ('ar', 'en')),
  user_agent text check (length(user_agent) <= 300),
  fails integer not null default 0,
  last_ok_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz
);
create unique index push_subscriptions_endpoint on public.push_subscriptions(endpoint) where deleted_at is null;
create index push_subscriptions_profile on public.push_subscriptions(profile_id) where deleted_at is null;

create table public.push_sent (
  id uuid primary key default gen_random_uuid(),
  shop_id uuid not null references public.shops(id),
  profile_id uuid not null references auth.users(id),
  key text not null check (length(key) <= 120),
  ack_token text not null unique,
  acked_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  unique (profile_id, key)
);

alter table public.push_subscriptions enable row level security;
alter table public.push_sent enable row level security;
create trigger set_updated_at before update on public.push_subscriptions for each row execute function public.tg_set_updated_at();
create trigger set_updated_at before update on public.push_sent for each row execute function public.tg_set_updated_at();
create trigger block_delete before delete on public.push_subscriptions for each row execute function public.tg_block_delete();
create trigger block_delete before delete on public.push_sent for each row execute function public.tg_block_delete();

-- كل واحد يشوف أجهزته هو بس (في محله). الكتابة من الدوال بس
create policy push_subs_select on public.push_subscriptions for select to authenticated
  using (profile_id = auth.uid() and shop_id = public.current_shop_id() and deleted_at is null);
create policy push_sent_select on public.push_sent for select to authenticated
  using (profile_id = auth.uid() and shop_id = public.current_shop_id());
grant select on public.push_subscriptions, public.push_sent to authenticated;

-- ---------- التوقيت (الإعدادات ← التنبيهات) ----------
-- من/لحد بتوقيت القاهرة (0-24). الافتراضي من 9 الصبح لـ 9 بالليل. من = لحد يعني طول اليوم
create or replace function public.push_window(p_shop uuid) returns int[]
language sql stable security definer set search_path = public as $$
  select array[
    least(greatest(coalesce((s.extras -> 'reminders' ->> 'push_from')::int, 9), 0), 24),
    least(greatest(coalesce((s.extras -> 'reminders' ->> 'push_to')::int, 21), 0), 24)]
  from public.shops s where s.id = p_shop
$$;
revoke execute on function public.push_window(uuid) from public, anon, authenticated;

create or replace function public.push_window_open(p_shop uuid, p_at timestamptz) returns boolean
language plpgsql stable security definer set search_path = public as $$
declare w int[] := public.push_window(p_shop); h int := extract(hour from p_at at time zone 'Africa/Cairo')::int;
begin
  if w is null then return false; end if;
  if w[1] = w[2] or (w[1] = 0 and w[2] = 24) then return true; end if;
  if w[1] < w[2] then return h >= w[1] and h < w[2]; end if;
  -- بيعدّي نص الليل (مثلًا من 20 لـ 2)
  return h >= w[1] or h < w[2];
end $$;
revoke execute on function public.push_window_open(uuid, timestamptz) from public, anon, authenticated;

-- ---------- الاشتراك (من الجهاز نفسه) ----------
create or replace function public.save_push_subscription(p_endpoint text, p_p256dh text, p_auth text, p_locale text default 'ar', p_user_agent text default null)
returns uuid
language plpgsql security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); me uuid := auth.uid(); rid uuid;
begin
  if s is null or me is null then raise exception 'E_FORBIDDEN'; end if;
  if p_endpoint is null or p_endpoint !~ '^https://[^/@\s]+\.[^/@\s]+/' or length(p_endpoint) > 1000
     or coalesce(p_p256dh, '') !~ '^[A-Za-z0-9_-]{80,100}$' or coalesce(p_auth, '') !~ '^[A-Za-z0-9_-]{16,44}$' then
    raise exception 'E_BAD_INPUT';
  end if;
  -- نفس المتصفح بقى لمستخدم تاني (حد خرج وحد دخل): الاشتراك بينتقل لللي داخل دلوقتي بس
  select id into rid from public.push_subscriptions where endpoint = p_endpoint and deleted_at is null for update;
  if rid is not null then
    update public.push_subscriptions set shop_id = s, profile_id = me, p256dh = p_p256dh, auth = p_auth,
      locale = case when p_locale = 'en' then 'en' else 'ar' end, user_agent = left(p_user_agent, 300), fails = 0
    where id = rid;
  else
    rid := gen_random_uuid();
    insert into public.push_subscriptions(id, shop_id, profile_id, endpoint, p256dh, auth, locale, user_agent)
    values (rid, s, me, p_endpoint, p_p256dh, p_auth, case when p_locale = 'en' then 'en' else 'ar' end, left(p_user_agent, 300));
  end if;
  -- 10 أجهزة بالكتير لكل مستخدم (الأقدم بيتشال)
  update public.push_subscriptions set deleted_at = now()
   where profile_id = me and deleted_at is null
     and id not in (select id from public.push_subscriptions where profile_id = me and deleted_at is null order by updated_at desc limit 10);
  return rid;
end $$;
revoke execute on function public.save_push_subscription(text, text, text, text, text) from public, anon;
grant execute on function public.save_push_subscription(text, text, text, text, text) to authenticated;

create or replace function public.remove_push_subscription(p_endpoint text) returns void
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'E_FORBIDDEN'; end if;
  update public.push_subscriptions set deleted_at = now() where endpoint = p_endpoint and profile_id = auth.uid() and deleted_at is null;
end $$;
revoke execute on function public.remove_push_subscription(text) from public, anon;
grant execute on function public.remove_push_subscription(text) to authenticated;

-- ---------- الإرسال (Edge Function push بمفتاح السيرفر بس) ----------
-- بيرجّع الإشعارات الجديدة لكل جهاز مشترك (لو التوقيت مفتوح)، وبيسجّلها إنها اتبعتت عشان ما تتكررش.
-- لكل مستخدم: الإشعارات بتتحسب بصلاحياته هو بالظبط (نفس دالة الجرس وهو داخل).
create or replace function public.push_due(p_now timestamptz default now())
returns table(sub_id uuid, endpoint text, p256dh text, auth text, locale text, key text, kind text, args jsonb, link text, token text)
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
#variable_conflict use_column
declare
  u record;
  old_claims text := current_setting('request.jwt.claims', true);
  old_sub text := current_setting('request.jwt.claim.sub', true);
begin
  drop table if exists pg_temp._push_new;
  create temp table _push_new(profile_id uuid, key text, kind text, args jsonb, link text, token text) on commit drop;
  for u in
    select distinct ps.profile_id, ps.shop_id
      from public.push_subscriptions ps
      join public.profiles p on p.id = ps.profile_id and p.shop_id = ps.shop_id and p.deleted_at is null
      join public.shops sh on sh.id = ps.shop_id and sh.suspended_at is null
     where ps.deleted_at is null and public.push_window_open(ps.shop_id, p_now)
  loop
    -- نفس صلاحيات المستخدم: كأنه داخل (aal2 لأنه فعّل الاشتراك وهو داخل بالتحقق بخطوتين لو مفعّل)
    perform set_config('request.jwt.claims', jsonb_build_object('sub', u.profile_id, 'role', 'authenticated', 'aal', 'aal2')::text, true);
    perform set_config('request.jwt.claim.sub', u.profile_id::text, true);
    begin
      insert into _push_new
      select u.profile_id, n.key, n.kind, n.args, n.link, encode(gen_random_bytes(16), 'hex')
        from public.my_notifications() n
       where not exists (select 1 from public.push_sent x where x.profile_id = u.profile_id and x.key = n.key)
         and not exists (select 1 from public.notification_reads r where r.profile_id = u.profile_id and r.key = n.key and r.deleted_at is null)
       limit 50;
    exception when others then
      -- مستخدم اتقفل أو اتشالت صلاحيته: ما يوصلوش حاجة
      null;
    end;
  end loop;
  perform set_config('request.jwt.claims', coalesce(old_claims, ''), true);
  perform set_config('request.jwt.claim.sub', coalesce(old_sub, ''), true);

  insert into public.push_sent(shop_id, profile_id, key, ack_token)
  select p.shop_id, n.profile_id, n.key, n.token from _push_new n join public.profiles p on p.id = n.profile_id
  on conflict (profile_id, key) do nothing;

  return query
  select ps.id, ps.endpoint, ps.p256dh, ps.auth, ps.locale, n.key, n.kind, n.args, n.link, n.token
    from _push_new n
    join public.push_subscriptions ps on ps.profile_id = n.profile_id and ps.deleted_at is null
   order by ps.id, n.key;
end $$;
revoke execute on function public.push_due(timestamptz) from public, anon, authenticated;
grant execute on function public.push_due(timestamptz) to service_role;

-- نتيجة الإرسال: الجهاز اللي لغى الاشتراك (404/410) أو فشل 5 مرات ورا بعض بيتشال
create or replace function public.push_result(p_rows jsonb) returns integer
language plpgsql security definer set search_path = public as $$
declare r jsonb; n int := 0; st int;
begin
  if jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) > 5000 then raise exception 'E_BAD_INPUT'; end if;
  for r in select * from jsonb_array_elements(p_rows) loop
    st := coalesce((r ->> 'status')::int, 0);
    if st between 200 and 299 then
      update public.push_subscriptions set fails = 0, last_ok_at = now() where id = (r ->> 'sub_id')::uuid;
    elsif st in (404, 410) or coalesce((r ->> 'gone')::boolean, false) then
      update public.push_subscriptions set deleted_at = now() where id = (r ->> 'sub_id')::uuid and deleted_at is null;
      n := n + 1;
    else
      update public.push_subscriptions set fails = fails + 1, deleted_at = case when fails + 1 >= 5 then now() else deleted_at end
       where id = (r ->> 'sub_id')::uuid and deleted_at is null;
    end if;
  end loop;
  return n;
end $$;
revoke execute on function public.push_result(jsonb) from public, anon, authenticated;
grant execute on function public.push_result(jsonb) to service_role;

-- ---------- زرار "اتقرا" من الإشعار نفسه (من غير تسجيل دخول) ----------
-- token عشوائي 128 بت لإشعار واحد، بيشتغل مرة واحدة وفي خلال 7 أيام. بيعلّم الإشعار مقروء في الجرس بس.
create or replace function public.push_ack(p_token text) returns boolean
language plpgsql security definer set search_path = public as $$
declare x public.push_sent;
begin
  if p_token is null or p_token !~ '^[0-9a-f]{32}$' then return false; end if;
  update public.push_sent set acked_at = now()
   where ack_token = p_token and acked_at is null and deleted_at is null and created_at > now() - interval '7 days'
  returning * into x;
  if x.id is null then return false; end if;
  insert into public.notification_reads(shop_id, profile_id, key) values (x.shop_id, x.profile_id, x.key)
  on conflict (profile_id, key) do nothing;
  return true;
end $$;
revoke execute on function public.push_ack(text) from public;
grant execute on function public.push_ack(text) to anon, authenticated;
$m0058$;
  insert into public.app_migrations(version, how) values ('0058_web_push.sql', 'applied');
  raise notice 'applied %', '0058_web_push.sql';
end $run$;
commit;

-- ============================== 0059_counters_branch.sql ==============================
begin;
do $run$ begin
  if exists (select 1 from public.app_migrations where version = '0059_counters_branch.sql') then return; end if;
  execute $m0059$
-- 0059: U6 (مراجعة عزل الفروع): ترقيم الطلبات لكل فرع
--
-- اختبار U6 (tests/db/u6.test.ts) لقى إن موظف فرع بيقدر يقرا عدّاد أرقام طلبات الفرع التاني (order_counters)،
-- وده بيكشف عدد شغل الفرع التاني في السنة. البرنامج نفسه ما بيقراش الجدول ده خالص (الترقيم جوه قاعدة البيانات)،
-- فالقراية بقت لفروع الموظف بس (صاحب المحل بيشوف الكل زي الأول).
drop policy if exists counters_select on public.order_counters;
create policy counters_select_branch on public.order_counters for select to authenticated
  using (shop_id = public.current_shop_id() and (branch_id is null or branch_id in (select unnest(public.my_branch_ids()))));
$m0059$;
  insert into public.app_migrations(version, how) values ('0059_counters_branch.sql', 'applied');
  raise notice 'applied %', '0059_counters_branch.sql';
end $run$;
commit;

-- ============================== 0060_sale_lines.sql ==============================
begin;
do $run$ begin
  if exists (select 1 from public.app_migrations where version = '0060_sale_lines.sql') then return; end if;
  execute $m0060$
-- 0060: 6ب فاتورة البيع: سطور كل بيع زي ما اتباع (الصنف، والاسم وقتها، والكمية، والسعر بالقروش)
--
-- قبل كده القيد كان فيه إجمالي البيع بس، فلو البيع فيه أكتر من صنف، سعر كل صنف ما كانش متخزّن.
-- - الجدول للإضافة بس: بيتكتب جوه record_sale في نفس الـ transaction بتاع القيد، وما بيتعدلش ولا بيتحذف.
-- - القراية بنفس صلاحيات القيد نفسه (اللي يشوف القيد يشوف سطوره)، والفني ما بيشوفش.
-- - الفاتورة من sale_invoice: صاحب المحل، أو اللي معاه صلاحية البيع في فرع القيد. المبالغ من سطور القيد (الدفتر)، والسطور للعرض بس.
-- - اسم العميل وتليفونه في الفاتورة لمين يشوف العملاء بس.
-- - البيع القديم (قبل الملف ده): الفاتورة بالإجمالي من الدفتر، والأصناف من حركة المخزون من غير سعر كل صنف.

create table public.sale_lines (
  id uuid primary key default gen_random_uuid(),
  shop_id uuid not null references public.shops(id),
  entry_id uuid not null references public.journal_entries(id),
  item_id uuid not null references public.items(id),
  name text not null check (length(name) <= 200),
  qty bigint not null check (qty > 0),
  price bigint not null check (price >= 0),
  seq integer not null default 0,
  -- العميل في البيع الكاش لعميل معروف (القيد ما بيسجّلوش لأنه ما بيأثرش على رصيده)
  customer_id uuid references public.customers(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz
);
create index sale_lines_entry on public.sale_lines(entry_id);
alter table public.sale_lines enable row level security;
create trigger set_updated_at before update on public.sale_lines for each row execute function public.tg_set_updated_at();
create trigger block_delete before delete on public.sale_lines for each row execute function public.tg_block_delete();
-- زي سطور القيد: ممنوع التعديل والحذف
create trigger ledger_immutable before update or delete on public.sale_lines for each row execute function public.tg_ledger_immutable();
create trigger ledger_no_truncate before truncate on public.sale_lines for each statement execute function public.tg_ledger_immutable();
-- نفس صلاحيات القيد (RLS بتاع journal_entries بيتطبق جوه الـ exists)
create policy sale_lines_select on public.sale_lines for select to authenticated
  using (shop_id = public.current_shop_id() and exists (select 1 from public.journal_entries e where e.id = entry_id));
revoke all on public.sale_lines from public, anon, authenticated;
grant select on public.sale_lines to authenticated;

-- record_sale: (src: 0057_categories.sql) + سطر لكل صنف في sale_lines
create or replace function public.record_sale(p_id uuid, p_lines jsonb, p_cashbox uuid default null, p_customer uuid default null, p_note text default null)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  s uuid := public.current_shop_id();
  e uuid := gen_random_uuid();
  l jsonb;
  it public.items;
  q bigint; p bigint; cost bigint;
  rev_parts bigint := 0; rev_acc bigint := 0; rev_srv bigint := 0; total_cost bigint := 0;
  debit_acc uuid; pt text; pid uuid;
  n int := 0;
begin
  perform public.ledger_require(array['owner', 'reception']::public.app_role[]);
  perform public.perm_require('sales', 'add');
  if public.ledger_idem(p_id) is not null then return public.ledger_idem(p_id); end if;
  -- البيع بالآجل لصاحب المحل بس
  if p_cashbox is null and (p_customer is null or public.current_app_role() <> 'owner') then raise exception 'E_BAD_INPUT'; end if;
  if p_customer is not null and not exists (select 1 from public.customers where id = p_customer and shop_id = s and deleted_at is null) then raise exception 'E_NOT_FOUND'; end if;
  if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then raise exception 'E_BAD_INPUT'; end if;
  insert into public.journal_entries(id, shop_id, source_type, source_id, memo, idem_key, created_by)
  values (e, s, 'sale', p_id, nullif(trim(p_note), ''), p_id, auth.uid());
  -- البيع بس: لو الإعداد مفتوح، اللي مش موجود بيخرج من غير تكلفة ويتسوى بعدين
  perform set_config('app.uncosted', 'on', true);
  for l in select * from jsonb_array_elements(p_lines) loop
    select * into it from public.items where id = (l ->> 'item')::uuid and shop_id = s and deleted_at is null;
    if not found then raise exception 'E_NOT_FOUND'; end if;
    q := (l ->> 'qty')::bigint;
    p := (l ->> 'price')::bigint;
    if q is null or q <= 0 or p is null or p < 0 then raise exception 'E_BAD_AMOUNT'; end if;
    -- 6ب: سطر البيع زي ما اتباع (الاسم والكمية والسعر) عشان فاتورة البيع
    n := n + 1;
    insert into public.sale_lines(shop_id, entry_id, item_id, name, qty, price, seq, customer_id) values (s, e, it.id, it.name, q, p, n, p_customer);
    -- K: الخدمة من غير مخزون ولا تكلفة، وإيرادها إيراد الصيانة
    if it.kind = 'service' then rev_srv := rev_srv + q * p; continue; end if;
    cost := public.ledger_issue(it.id, q, e);
    total_cost := total_cost + cost;
    if it.kind = 'part' then rev_parts := rev_parts + q * p; else rev_acc := rev_acc + q * p; end if;
  end loop;
  perform set_config('app.uncosted', 'off', true);
  perform public.ledger_amount(rev_parts + rev_acc + rev_srv);
  if p_cashbox is null then
    debit_acc := public.ledger_acc('ar'); pt := 'customer'; pid := p_customer;
  else
    debit_acc := (public.ledger_cashbox(p_cashbox)).id;
  end if;
  insert into public.journal_lines(shop_id, entry_id, account_id, party_type, party_id, debit, credit)
  values (s, e, debit_acc, pt, pid, rev_parts + rev_acc + rev_srv, 0);
  if rev_parts > 0 then insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values (s, e, public.ledger_acc('rev_parts'), 0, rev_parts); end if;
  if rev_acc > 0 then insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values (s, e, public.ledger_acc('rev_accessories'), 0, rev_acc); end if;
  if rev_srv > 0 then insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values (s, e, public.ledger_acc('rev_repair'), 0, rev_srv); end if;
  if total_cost > 0 then
    insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values
      (s, e, public.ledger_acc('cogs'), total_cost, 0), (s, e, public.ledger_acc('inventory'), 0, total_cost);
  end if;
  if p_cashbox is not null and p_customer is not null then
    null; -- البيع النقدي لعميل معروف ما بيأثرش على رصيده
  end if;
  return e;
end $$;

-- entry_args: (src: 0026_edit_delete.sql) + سطور البيع من sale_lines لو موجودة
create or replace function public.entry_args(p_entry uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  o public.journal_entries;
  cash_in uuid; cash_out uuid; amt bigint; party uuid; acc uuid; res jsonb; pay public.payments; pur public.purchases;
  ls jsonb; rev bigint; cust uuid;
begin
  if public.current_app_role() is null or not public.can_correct() then raise exception 'E_FORBIDDEN'; end if;
  select * into o from public.journal_entries where id = p_entry and shop_id = public.current_shop_id();
  if not found then raise exception 'E_NOT_FOUND'; end if;
  select max(l.account_id::text) filter (where a.kind = 'cash' and l.debit > 0)::uuid,
         max(l.account_id::text) filter (where a.kind = 'cash' and l.credit > 0)::uuid,
         max(l.party_id::text) filter (where l.party_id is not null)::uuid,
         max(l.account_id::text) filter (where a.kind = 'expense' and l.debit > 0)::uuid,
         greatest(sum(l.debit), 0)
    into cash_in, cash_out, party, acc, amt
  from public.journal_lines l join public.accounts a on a.id = l.account_id where l.entry_id = o.id;
  res := jsonb_build_object('source_type', o.source_type, 'entry_no', o.entry_no, 'note', o.memo,
    'reversed', exists (select 1 from public.journal_entries where reverses_id = o.id),
    'editable', o.source_type in ('payment', 'expense', 'transfer', 'capital', 'drawing', 'advance', 'salary', 'salary_payment', 'supplier_payment', 'purchase', 'sale'));
  if o.source_type = 'payment' then
    select * into pay from public.payments where entry_id = o.id;
    res := res || jsonb_build_object('customer', pay.customer_id, 'device', pay.device_id, 'cashbox', pay.cashbox_id, 'method', pay.method, 'amount', pay.amount);
  elsif o.source_type = 'expense' then
    res := res || jsonb_build_object('account', acc, 'cashbox', cash_out, 'amount', amt);
  elsif o.source_type = 'transfer' then
    res := res || jsonb_build_object('from', cash_out, 'to', cash_in, 'amount', amt);
  elsif o.source_type = 'capital' then
    res := res || jsonb_build_object('cashbox', cash_in, 'amount', amt);
  elsif o.source_type = 'drawing' then
    res := res || jsonb_build_object('cashbox', cash_out, 'amount', amt);
  elsif o.source_type in ('advance', 'salary_payment') then
    res := res || jsonb_build_object('employee', party, 'cashbox', cash_out, 'amount', amt);
  elsif o.source_type = 'salary' then
    res := res || jsonb_build_object('employee', party, 'amount', amt);
  elsif o.source_type = 'supplier_payment' then
    res := res || jsonb_build_object('supplier', party, 'cashbox', cash_out, 'amount', amt);
  elsif o.source_type = 'purchase' then
    select * into pur from public.purchases where entry_id = o.id;
    select jsonb_agg(jsonb_build_object('item', m.item_id, 'qty', m.qty, 'unit_cost', m.value / nullif(m.qty, 0)) order by m.created_at) into ls
    from public.stock_moves m where m.entry_id = o.id;
    res := res || jsonb_build_object('supplier', pur.supplier_id, 'cashbox', cash_out, 'lines', coalesce(ls, '[]'::jsonb));
  elsif o.source_type = 'sale' then
    -- سعر البيع: لو صنف واحد بيتحسب من الإيراد، ولو أكتر من صنف بيتاخد سعر الصنف المسجل
    select coalesce(sum(l.credit), 0) into rev from public.journal_lines l join public.accounts a on a.id = l.account_id where l.entry_id = o.id and a.type = 'revenue';
    select max(l.party_id::text) filter (where l.party_type = 'customer')::uuid into cust from public.journal_lines l where l.entry_id = o.id;
    -- 6ب: البيع الجديد بسطوره زي ما اتباع بالظبط. القديم (قبل 0060) زي الأول
    select jsonb_agg(jsonb_build_object('item', sl.item_id, 'qty', sl.qty, 'price', sl.price) order by sl.seq) into ls
    from public.sale_lines sl where sl.entry_id = o.id and sl.deleted_at is null;
    if ls is null then
    select jsonb_agg(jsonb_build_object('item', x.item_id, 'qty', x.q,
             'price', case when x.n = 1 then rev / x.q else coalesce(i.sale_price, 0) end) order by x.first)
      into ls
    from (select m.item_id, -sum(m.qty) q, count(*) over () n, min(m.created_at) first from public.stock_moves m where m.entry_id = o.id group by m.item_id) x
    join public.items i on i.id = x.item_id;
    end if;
    res := res || jsonb_build_object('customer', cust, 'cashbox', cash_in, 'lines', coalesce(ls, '[]'::jsonb));
  end if;
  return res;
end $$;

-- backup_snapshot: (src: 0057_categories.sql) + sale_lines
create or replace function public.backup_snapshot(p_shop uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  res jsonb := jsonb_build_object('format', 'warsha-backup', 'version', 1, 'generated_at', now(), 'shop_id', p_shop);
  t text;
  rows jsonb;
begin
  foreach t in array array['shops', 'branches', 'staff_branches', 'shop_branding', 'profiles', 'customers', 'devices', 'device_costs', 'status_log', 'device_notes', 'device_photos', 'device_checks',
                           'quote_decisions', 'message_templates', 'message_log', 'accounts', 'journal_entries', 'journal_lines', 'sale_lines', 'payments', 'drawer_closings',
                           'suppliers', 'categories', 'items', 'stock_moves', 'uncosted_sales', 'payment_plans', 'plan_installments', 'branch_goals', 'printers', 'print_templates', 'check_templates', 'used_devices', 'commission_rules', 'purchases', 'labor_rates', 'specialties', 'staff_specialties', 'routes', 'repair_steps',
                           'repair_videos', 'device_ratings', 'issue_presets', 'partners', 'profit_distributions', 'party_links', 'shop_lists', 'audit_log'] loop
    execute format('select coalesce(jsonb_agg(to_jsonb(x)), ''[]''::jsonb) from public.%I x where x.shop_id = $1', t) into rows using p_shop;
    res := res || jsonb_build_object(t, rows);
  end loop;
  select coalesce(jsonb_agg(jsonb_build_object('device_id', device_id, 'kind', kind, 'erased_at', erased_at)), '[]'::jsonb)
    into rows from public.device_passcodes where shop_id = p_shop;
  return res || jsonb_build_object('device_passcodes', rows);
end $$;

-- restore_backup: (src: 0057_categories.sql) + sale_lines (بعد القيود والأصناف)
create or replace function public.restore_backup(p_data jsonb) returns jsonb
-- extensions: فيها gen_random_bytes على Supabase
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare
  s uuid := public.current_shop_id();
  me uuid := auth.uid();
  old_shop uuid;
  old_owner uuid;
  sh jsonb;
  t text;
  r jsonb;
  rows jsonb;
  n int;
  bad int;
  counts jsonb := '{}'::jsonb;
  -- بالترتيب ده عشان كل صف يلاقي اللي بيشاور عليه
  tabs text[] := array['branches', 'profiles', 'staff_branches', 'shop_branding', 'accounts', 'customers', 'suppliers', 'party_links', 'partners', 'specialties', 'staff_specialties', 'routes', 'labor_rates',
                       'issue_presets', 'commission_rules', 'shop_lists', 'message_templates', 'categories', 'items', 'devices', 'device_costs', 'status_log', 'device_notes', 'device_checks',
                       'quote_decisions', 'repair_steps', 'repair_videos', 'device_ratings', 'journal_entries', 'journal_lines', 'sale_lines', 'profit_distributions', 'payments',
                       'purchases', 'stock_moves', 'uncosted_sales', 'used_devices', 'payment_plans', 'plan_installments', 'branch_goals', 'printers', 'print_templates', 'check_templates', 'drawer_closings', 'message_log', 'audit_log'];
  -- الجداول دي ليها نسخة اتعملت مع التسجيل: بتتطابق بالكود (أو المفتاح) وبتاخد قيم النسخة
  keyed text[] := array['branches', 'accounts', 'routes', 'specialties', 'message_templates', 'labor_rates', 'shop_branding'];
begin
  perform public.ledger_require(array['owner']::public.app_role[]);
  if s is null or me is null then raise exception 'E_FORBIDDEN'; end if;
  if p_data is null or p_data->>'format' is distinct from 'warsha-backup' or coalesce((p_data->>'version')::int, 0) <> 1 then
    raise exception 'E_BACKUP_FORMAT';
  end if;
  old_shop := (p_data->>'shop_id')::uuid;
  if old_shop is null or old_shop = s then raise exception 'E_BACKUP_FORMAT'; end if;

  -- محل جديد فاضي بس
  if exists (select 1 from public.devices where shop_id = s) or exists (select 1 from public.customers where shop_id = s)
     or exists (select 1 from public.journal_entries where shop_id = s) or exists (select 1 from public.items where shop_id = s)
     or exists (select 1 from public.suppliers where shop_id = s) or exists (select 1 from public.payments where shop_id = s)
     or exists (select 1 from public.purchases where shop_id = s) or exists (select 1 from public.drawer_closings where shop_id = s)
     or exists (select 1 from public.stock_moves where shop_id = s)
     or exists (select 1 from public.profiles where shop_id = s and id <> me) then
    raise exception 'E_RESTORE_NOT_EMPTY';
  end if;

  perform set_config('warsha.restore', 'on', true);
  drop table if exists pg_temp._rmap;
  create temp table _rmap(old uuid primary key, new uuid not null) on commit drop;
  insert into _rmap values (old_shop, s);

  -- 1) بيانات المحل نفسه (من غير الخطة والإيقاف واللوجو اللي في Storage)
  sh := p_data->'shops'->0;
  if sh is not null then
    update public.shops set
      name = coalesce(sh->>'name', name), phone = sh->>'phone', address = sh->>'address',
      receipt_terms = coalesce(sh->>'receipt_terms', receipt_terms), warranty_days = coalesce((sh->>'warranty_days')::int, warranty_days),
      country = coalesce(sh->>'country', country), currency = coalesce(sh->>'currency', currency),
      payment_methods = coalesce(array(select jsonb_array_elements_text(sh->'payment_methods')), payment_methods),
      theme = coalesce(sh->>'theme', theme), locale = coalesce(sh->>'locale', locale),
      default_margin_pct = coalesce((sh->>'default_margin_pct')::int, default_margin_pct),
      extras = coalesce(sh->'extras', extras), max_discount_pct = coalesce((sh->>'max_discount_pct')::int, max_discount_pct)
    where id = s;
  end if;

  -- 2) الـ ids الجديدة
  -- صاحب المحل في النسخة = اللي بيسترجع دلوقتي
  select (x->>'id')::uuid into old_owner from jsonb_array_elements(coalesce(p_data->'profiles', '[]')) x
   where x->>'role' = 'owner' order by x->>'created_at' limit 1;
  if old_owner is not null then insert into _rmap values (old_owner, me) on conflict do nothing; end if;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.accounts a where a.shop_id = s and a.code = x->>'code' and x->>'code' is not null), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'accounts', '[]')) x on conflict do nothing;
  -- الفرع الرئيسي في النسخة = الفرع الرئيسي للمحل الجديد
  insert into _rmap select (x->>'id')::uuid, public.main_branch(s)
    from jsonb_array_elements(coalesce(p_data->'branches', '[]')) x where (x->>'is_main')::boolean and x->>'deleted_at' is null on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.routes a where a.shop_id = s and a.code = x->>'code' and x->>'code' is not null), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'routes', '[]')) x on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.specialties a where a.shop_id = s and a.code = x->>'code' and x->>'code' is not null), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'specialties', '[]')) x on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.message_templates a where a.shop_id = s and a.key = x->>'key'), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'message_templates', '[]')) x on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.labor_rates a where a.shop_id = s and a.deleted_at is null and lower(trim(a.issue)) = lower(trim(x->>'issue')) and x->>'deleted_at' is null), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'labor_rates', '[]')) x on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.shop_branding a where a.shop_id = s), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'shop_branding', '[]')) x on conflict do nothing;
  foreach t in array tabs loop
    insert into _rmap select (x->>'id')::uuid, gen_random_uuid() from jsonb_array_elements(coalesce(p_data->t, '[]')) x where x ? 'id' on conflict do nothing;
  end loop;

  -- 3) الصفوف نفسها بالترتيب
  foreach t in array tabs loop
    rows := '[]'::jsonb;
    for r in select public.restore_remap(x) from jsonb_array_elements(coalesce(p_data->t, '[]')) x loop
      if t = 'profiles' then
        -- صاحب المحل موجود أصلًا. الباقيين موظفين سابقين (من غير حساب دخول)
        continue when (r->>'id')::uuid = me;
        r := r || jsonb_build_object('deleted_at', coalesce(r->>'deleted_at', now()::text));
      elsif t = 'devices' then
        -- كود التتبع (الـ QR) بيفضل زي ما هو، إلا لو مستخدم في المشروع ده (المحل الأصلي لسه هنا)
        if exists (select 1 from public.devices d where d.tracking_token = r->>'tracking_token') then
          r := r || jsonb_build_object('tracking_token', encode(gen_random_bytes(12), 'hex'));
        end if;
      elsif t = 'journal_entries' then
        if r->>'idem_key' is not null and exists (select 1 from public.journal_entries j where j.idem_key = (r->>'idem_key')::uuid) then
          r := r || jsonb_build_object('idem_key', gen_random_uuid());
        end if;
      elsif t = 'accounts' and r->>'kind' = 'cash' and r->>'branch_id' is null then
        -- نسخة من قبل الفروع: الخزن كلها في الفرع الرئيسي
        r := r || jsonb_build_object('branch_id', public.main_branch(s));
      elsif t = 'used_devices' then
        -- رقم بطاقة البائع (في Vault) وصورتها (في Storage) مش جوه النسخة
        r := r || jsonb_build_object('seller_nid_secret', null, 'seller_photo', null);
      elsif t = 'shop_branding' then
        -- اللوجو الملون والحراري جوه الصف نفسه. الملف الأصلي في Storage مش جوه النسخة
        r := r || jsonb_build_object('logo_path', null);
      end if;
      if t = any (keyed) and exists (select 1 from _rmap m where m.new = (r->>'id')::uuid and m.old <> m.new)
         and (t <> 'shop_branding' or exists (select 1 from public.shop_branding b where b.id = (r->>'id')::uuid)) then
        -- موجود من التسجيل: بياخد قيم النسخة
        execute format('select count(*) from public.%I where id = $1', t) into n using (r->>'id')::uuid;
        if n > 0 then
          execute format('update public.%1$I x set (%2$s) = (select %2$s from jsonb_populate_record(null::public.%1$I, $1)) where x.id = $2', t,
            (select string_agg(quote_ident(c.column_name), ', ' order by c.ordinal_position) from information_schema.columns c
              where c.table_schema = 'public' and c.table_name = t and c.column_name not in ('id', 'shop_id')))
            using r, (r->>'id')::uuid;
          continue;
        end if;
      end if;
      rows := rows || jsonb_build_array(r);
    end loop;
    if jsonb_array_length(rows) > 0 then
      -- overriding system value: أرقام القيود (entry_no) بترجع زي ما هي
      execute format('insert into public.%1$I overriding system value select * from jsonb_populate_recordset(null::public.%1$I, $1)', t) using rows;
    end if;
    counts := counts || jsonb_build_object(t, jsonb_array_length(coalesce(p_data->t, '[]')));
  end loop;

  -- 4) عدّاد أرقام الطلبات: من آخر رقم راجع في كل سنة
  -- (لكل فرع: الرقم ممكن يبقى قبله بادئة الفرع B2-2026-0001)
  insert into public.order_counters(shop_id, branch_id, year, last_value)
  select s, branch_id, (regexp_match(order_no, '(\d{4})-(\d+)$'))[1]::int, max((regexp_match(order_no, '(\d{4})-(\d+)$'))[2]::int)
    from public.devices where shop_id = s and order_no ~ '\d{4}-\d+$' group by 2, 3
  on conflict (shop_id, branch_id, year) do update set last_value = greatest(public.order_counters.last_value, excluded.last_value);

  -- 5) التأكد: كل قيد متوازن، ورصيد كل حساب = رصيده في النسخة بالظبط
  select count(*) into bad from (
    select entry_id from public.journal_lines where shop_id = s group by entry_id having sum(debit) <> sum(credit)) x;
  if bad > 0 then raise exception 'E_RESTORE_UNBALANCED'; end if;
  select count(*) into bad from (
    select m.new acc, sum((l->>'debit')::bigint - (l->>'credit')::bigint) b
      from jsonb_array_elements(coalesce(p_data->'journal_lines', '[]')) l join _rmap m on m.old = (l->>'account_id')::uuid group by m.new
  ) x full join (select account_id, sum(debit - credit) b from public.journal_lines where shop_id = s group by account_id) y on y.account_id = x.acc
  where coalesce(x.b, 0) <> coalesce(y.b, 0);
  if bad > 0 then raise exception 'E_RESTORE_MISMATCH'; end if;
  -- وعدد الصفوف في كل جدول (الحسابات والقوالب اللي اتعملت مع التسجيل ممكن تزيد عن النسخة، مش تقل)
  foreach t in array tabs loop
    execute format('select count(*) from public.%I where shop_id = $1', t) into n using s;
    if n < jsonb_array_length(coalesce(p_data->t, '[]')) - (case when t = 'profiles' and old_owner is not null then 1 else 0 end) then
      raise exception 'E_RESTORE_MISMATCH';
    end if;
  end loop;

  perform set_config('warsha.restore', 'off', true);
  insert into public.audit_log(shop_id, actor_id, action, entity, entity_id, after)
  values (s, me, 'backup_restore', 'shops', s, jsonb_build_object('from_shop', old_shop, 'generated_at', p_data->>'generated_at', 'counts', counts));
  return jsonb_build_object('restored', true, 'counts', counts);
end $$;

-- ---------- فاتورة البيع ----------
-- صاحب المحل، أو الموظف اللي معاه صلاحية البيع (أو يشوف المالية) في فرع القيد. الفني لأ.
create or replace function public.sale_invoice(p_entry uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  s uuid := public.current_shop_id(); r public.app_role := public.current_app_role();
  o public.journal_entries; ls jsonb; old boolean := false;
  total bigint; paid bigint; due bigint; cust uuid; cname text; cphone text; rev_no integer;
begin
  if s is null or r is null or r = 'technician' then raise exception 'E_FORBIDDEN'; end if;
  select * into o from public.journal_entries where id = p_entry and shop_id = s and source_type = 'sale';
  if not found then raise exception 'E_NOT_FOUND'; end if;
  if r <> 'owner' and not ((public.has_perm('sales', 'add') or public.has_perm('finance', 'view')) and public.can_branch(o.branch_id)) then
    raise exception 'E_FORBIDDEN';
  end if;
  -- المبالغ من الدفتر: الإجمالي = الإيراد، والمدفوع = اللي دخل الخزنة، والباقي = على العميل
  select coalesce(sum(l.credit) filter (where a.type = 'revenue'), 0),
         coalesce(sum(l.debit) filter (where a.kind = 'cash'), 0),
         coalesce(sum(l.debit) filter (where a.kind = 'receivable'), 0),
         max(l.party_id::text) filter (where l.party_type = 'customer')::uuid
    into total, paid, due, cust
  from public.journal_lines l join public.accounts a on a.id = l.account_id where l.entry_id = o.id;
  select jsonb_agg(jsonb_build_object('name', sl.name, 'qty', sl.qty, 'price', sl.price, 'amount', sl.qty * sl.price) order by sl.seq) into ls
  from public.sale_lines sl where sl.entry_id = o.id and sl.deleted_at is null;
  if ls is null then
    -- بيع قديم: الأصناف والكميات بس (السعر ما كانش متخزّن)
    old := true;
    select jsonb_agg(jsonb_build_object('name', i.name, 'qty', x.q, 'price', null, 'amount', null) order by x.first) into ls
    from (select m.item_id, -sum(m.qty) q, min(m.created_at) first from public.stock_moves m where m.entry_id = o.id group by m.item_id) x
    join public.items i on i.id = x.item_id;
  end if;
  -- البيع الكاش لعميل معروف: العميل من سطور البيع
  cust := coalesce(cust, (select max(sl.customer_id::text)::uuid from public.sale_lines sl where sl.entry_id = o.id));
  -- اسم العميل وتليفونه لمين يشوف العملاء بس (نفس صلاحية جدول العملاء)
  if cust is not null and (r = 'owner' or public.has_perm('customers', 'view') or public.has_perm('intake', 'add')) then
    select c.name, c.phone into cname, cphone from public.customers c where c.id = cust;
  end if;
  select e.entry_no into rev_no from public.journal_entries e where e.reverses_id = o.id;
  return jsonb_build_object('entry_no', o.entry_no, 'at', o.occurred_at, 'memo', o.memo, 'branch_id', o.branch_id,
    'lines', coalesce(ls, '[]'::jsonb), 'legacy', old, 'total', total, 'paid', paid, 'due', due,
    'customer', cname, 'phone', cphone, 'cancelled_by', rev_no);
end $$;
revoke execute on function public.sale_invoice(uuid) from public, anon;
grant execute on function public.sale_invoice(uuid) to authenticated;
$m0060$;
  insert into public.app_migrations(version, how) values ('0060_sale_lines.sql', 'applied');
  raise notice 'applied %', '0060_sale_lines.sql';
end $run$;
commit;

-- ============================== 0061_attendance.sql ==============================
begin;
do $run$ begin
  if exists (select 1 from public.app_migrations where version = '0061_attendance.sql') then return; end if;
  execute $m0061$
-- 0061: R1 الحضور والانصراف (من دراسة المنافسين v2)
--
-- - كل موظف (وصاحب المحل) بيسجّل حضوره وانصرافه بنفسه، في فرعه الشغال (op_branch).
-- - صاحب المحل بس بيصلّح سجل (وقت حضور أو انصراف غلط أو منسي)، أو يضيف سجل، أو يلغيه. لازم سبب، وكله في سجل النشاط.
-- - القراية: كل واحد يشوف سجله هو. وصاحب المحل، واللي معاه "الفريق ← يشوف"، يشوفوا الكل في فروعهم.
-- - التأخير بيتحسب في التقرير بس، من ميعاد بداية الشغل والسماح في إعدادات المحل (extras.attendance.start وgrace_min).
-- - مفيش أي فلوس هنا. الجزاءات والمكافآت ليها شاشتها ودوالها في المرتبات (staff_bonus/staff_penalty).

create table public.attendance (
  id uuid primary key default gen_random_uuid(),
  shop_id uuid not null references public.shops(id),
  branch_id uuid references public.branches(id),
  profile_id uuid not null references public.profiles(id),
  clock_in timestamptz not null,
  clock_out timestamptz,
  note text check (length(note) <= 300),
  fixed_by uuid references public.profiles(id),
  fix_reason text check (length(fix_reason) <= 300),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  check (clock_out is null or clock_out > clock_in),
  check (clock_out is null or clock_out - clock_in <= interval '24 hours')
);
-- سجل مفتوح واحد بس لكل موظف
create unique index attendance_open on public.attendance(profile_id) where clock_out is null and deleted_at is null;
create index attendance_shop_in on public.attendance(shop_id, clock_in);
alter table public.attendance enable row level security;
create trigger set_updated_at before update on public.attendance for each row execute function public.tg_set_updated_at();
create trigger block_delete before delete on public.attendance for each row execute function public.tg_block_delete();
create trigger zz_audit after insert or update on public.attendance for each row execute function public.tg_audit();
create policy attendance_select on public.attendance for select to authenticated
  using (shop_id = public.current_shop_id() and deleted_at is null
         and (profile_id = auth.uid() or public.current_app_role() = 'owner' or ((select public.has_perm('staff', 'view')) and public.can_branch(branch_id))));
revoke all on public.attendance from public, anon, authenticated;
grant select on public.attendance to authenticated;

-- ---------- الموظف نفسه ----------
create or replace function public.clock_in(p_id uuid, p_note text default null) returns uuid
language plpgsql security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); me uuid := auth.uid();
begin
  if s is null or me is null then raise exception 'E_FORBIDDEN'; end if;
  -- نفس الطلب مرتين (النت قطع ورجع): نفس السجل
  if exists (select 1 from public.attendance where id = p_id and profile_id = me) then return p_id; end if;
  if exists (select 1 from public.attendance where profile_id = me and clock_out is null and deleted_at is null) then raise exception 'E_ALREADY_IN'; end if;
  -- طلبين في نفس اللحظة (الطابور بيعيد والأول لسه ماشي): نفس الـ id = نفس السجل، وسجل مفتوح تاني = E_ALREADY_IN
  begin
    insert into public.attendance(id, shop_id, branch_id, profile_id, clock_in, note)
    values (p_id, s, public.op_branch(), me, now(), nullif(trim(left(p_note, 300)), ''));
  exception when unique_violation then
    if exists (select 1 from public.attendance where id = p_id and profile_id = me) then return p_id; end if;
    raise exception 'E_ALREADY_IN';
  end;
  return p_id;
end $$;
revoke execute on function public.clock_in(uuid, text) from public, anon;
grant execute on function public.clock_in(uuid, text) to authenticated;

create or replace function public.clock_out(p_note text default null) returns uuid
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); a public.attendance;
begin
  if public.current_shop_id() is null or me is null then raise exception 'E_FORBIDDEN'; end if;
  select * into a from public.attendance where profile_id = me and clock_out is null and deleted_at is null for update;
  if a.id is null then raise exception 'E_NOT_IN'; end if;
  -- أكتر من 24 ساعة: نسي ينصرف، وصاحب المحل يصلّح السجل
  if now() - a.clock_in > interval '24 hours' then raise exception 'E_OPEN_TOO_LONG'; end if;
  update public.attendance set clock_out = now(), note = coalesce(nullif(trim(left(p_note, 300)), ''), note) where id = a.id;
  return a.id;
end $$;
revoke execute on function public.clock_out(text) from public, anon;
grant execute on function public.clock_out(text) to authenticated;

-- ---------- التقرير ----------
-- الدقايق والتأخير بيتحسبوا هنا (أعداد صحيحة)، والواجهة بتعرضهم بس
create or replace function public.attendance_rows(p_from timestamptz, p_to timestamptz, p_branch uuid default null, p_me boolean default false)
returns table(id uuid, profile_id uuid, full_name text, branch_id uuid, clock_in timestamptz, clock_out timestamptz, minutes integer, late_minutes integer, note text, fix_reason text)
language plpgsql stable security definer set search_path = public as $$
#variable_conflict use_column
declare s uuid := public.current_shop_id(); r public.app_role := public.current_app_role(); me uuid := auth.uid();
  st text; grace integer; all_staff boolean;
begin
  if s is null or me is null then raise exception 'E_FORBIDDEN'; end if;
  if p_from is null or p_to is null or p_to <= p_from or p_to - p_from > interval '400 days' then raise exception 'E_BAD_INPUT'; end if;
  all_staff := not p_me and (r = 'owner' or public.has_perm('staff', 'view'));
  if not p_me and not all_staff then raise exception 'E_FORBIDDEN'; end if;
  -- السماح: رقم صحيح من 0 لـ 600، وأي قيمة تانية (فاضية أو بكسر) = 15، عشان إعداد غلط ما يوقّعش التقرير
  select sh.extras -> 'attendance' ->> 'start',
         case when (sh.extras -> 'attendance' ->> 'grace_min') ~ '^[0-9]{1,3}$' then least((sh.extras -> 'attendance' ->> 'grace_min')::int, 600) else 15 end
    into st, grace from public.shops sh where sh.id = s;
  if st !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then st := null; end if;
  return query
  select a.id, a.profile_id, p.full_name, a.branch_id, a.clock_in, a.clock_out,
         -- دقايق كاملة (من غير تقريب لفوق)
         case when a.clock_out is null then null else floor(extract(epoch from a.clock_out - a.clock_in) / 60)::int end,
         case when st is null then 0
              else greatest(0, floor(extract(epoch from (a.clock_in at time zone 'Africa/Cairo') - ((a.clock_in at time zone 'Africa/Cairo')::date + st::time)) / 60)::int - grace) end,
         a.note, a.fix_reason
  from public.attendance a join public.profiles p on p.id = a.profile_id
  where a.shop_id = s and a.deleted_at is null and a.clock_in >= p_from and a.clock_in < p_to
    and (case when p_me then a.profile_id = me
              else (r = 'owner' or public.can_branch(a.branch_id)) and (p_branch is null or a.branch_id = p_branch) end)
  order by a.clock_in desc;
end $$;
revoke execute on function public.attendance_rows(timestamptz, timestamptz, uuid, boolean) from public, anon;
grant execute on function public.attendance_rows(timestamptz, timestamptz, uuid, boolean) to authenticated;

create or replace function public.my_attendance(p_from timestamptz, p_to timestamptz)
returns table(id uuid, profile_id uuid, full_name text, branch_id uuid, clock_in timestamptz, clock_out timestamptz, minutes integer, late_minutes integer, note text, fix_reason text)
language sql stable security definer set search_path = public as $$
  select * from public.attendance_rows(p_from, p_to, null, true)
$$;
revoke execute on function public.my_attendance(timestamptz, timestamptz) from public, anon;
grant execute on function public.my_attendance(timestamptz, timestamptz) to authenticated;

create or replace function public.attendance_report(p_from timestamptz, p_to timestamptz, p_branch uuid default null)
returns table(id uuid, profile_id uuid, full_name text, branch_id uuid, clock_in timestamptz, clock_out timestamptz, minutes integer, late_minutes integer, note text, fix_reason text)
language sql stable security definer set search_path = public as $$
  select * from public.attendance_rows(p_from, p_to, p_branch, false)
$$;
revoke execute on function public.attendance_report(timestamptz, timestamptz, uuid) from public, anon;
grant execute on function public.attendance_report(timestamptz, timestamptz, uuid) to authenticated;

-- ---------- صاحب المحل بس: تصليح، أو إضافة، أو إلغاء (بسبب، وفي سجل النشاط) ----------
-- سجلين لنفس الموظف ما يتداخلوش (عشان الساعات ما تتحسبش مرتين). المفتوح لحد دلوقتي
create or replace function public.attendance_overlaps(p_profile uuid, p_in timestamptz, p_out timestamptz, p_except uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.attendance a
    where a.profile_id = p_profile and a.deleted_at is null and a.id is distinct from p_except
      and tstzrange(a.clock_in, coalesce(a.clock_out, greatest(now(), a.clock_in + interval '1 second')), '[)')
          && tstzrange(p_in, coalesce(p_out, greatest(now(), p_in + interval '1 second')), '[)'))
$$;
revoke execute on function public.attendance_overlaps(uuid, timestamptz, timestamptz, uuid) from public, anon, authenticated;
create or replace function public.attendance_fix(p_id uuid, p_in timestamptz, p_out timestamptz, p_reason text) returns void
language plpgsql security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); pr uuid;
begin
  perform public.ledger_require(array['owner']::public.app_role[]);
  if coalesce(trim(p_reason), '') = '' then raise exception 'E_REASON_REQUIRED'; end if;
  if p_in is null or (p_out is not null and (p_out <= p_in or p_out - p_in > interval '24 hours')) then raise exception 'E_BAD_INPUT'; end if;
  select profile_id into pr from public.attendance where id = p_id and shop_id = s and deleted_at is null;
  if pr is null then raise exception 'E_NOT_FOUND'; end if;
  if public.attendance_overlaps(pr, p_in, p_out, p_id) then raise exception 'E_ATT_OVERLAP'; end if;
  -- سيبه مفتوح وهو عنده سجل مفتوح تاني
  if p_out is null and exists (select 1 from public.attendance where profile_id = pr and clock_out is null and deleted_at is null and id <> p_id) then raise exception 'E_ALREADY_IN'; end if;
  update public.attendance set clock_in = p_in, clock_out = p_out, fixed_by = auth.uid(), fix_reason = left(trim(p_reason), 300)
   where id = p_id and shop_id = s and deleted_at is null;
  if not found then raise exception 'E_NOT_FOUND'; end if;
end $$;
revoke execute on function public.attendance_fix(uuid, timestamptz, timestamptz, text) from public, anon;
grant execute on function public.attendance_fix(uuid, timestamptz, timestamptz, text) to authenticated;

create or replace function public.attendance_add(p_id uuid, p_profile uuid, p_in timestamptz, p_out timestamptz, p_reason text) returns uuid
language plpgsql security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); b uuid;
begin
  perform public.ledger_require(array['owner']::public.app_role[]);
  if exists (select 1 from public.attendance where id = p_id and shop_id = s) then return p_id; end if;
  if coalesce(trim(p_reason), '') = '' then raise exception 'E_REASON_REQUIRED'; end if;
  if p_in is null or p_out is null or p_out <= p_in or p_out - p_in > interval '24 hours' then raise exception 'E_BAD_INPUT'; end if;
  if not exists (select 1 from public.profiles where id = p_profile and shop_id = s) then raise exception 'E_NOT_FOUND'; end if;
  if public.attendance_overlaps(p_profile, p_in, p_out, null) then raise exception 'E_ATT_OVERLAP'; end if;
  -- فرع الموظف (أول فرع ليه، أو الرئيسي)
  b := coalesce((select sb.branch_id from public.staff_branches sb where sb.profile_id = p_profile and sb.deleted_at is null order by sb.created_at limit 1), public.main_branch(s));
  insert into public.attendance(id, shop_id, branch_id, profile_id, clock_in, clock_out, fixed_by, fix_reason)
  values (p_id, s, b, p_profile, p_in, p_out, auth.uid(), left(trim(p_reason), 300));
  return p_id;
end $$;
revoke execute on function public.attendance_add(uuid, uuid, timestamptz, timestamptz, text) from public, anon;
grant execute on function public.attendance_add(uuid, uuid, timestamptz, timestamptz, text) to authenticated;

create or replace function public.attendance_void(p_id uuid, p_reason text) returns void
language plpgsql security definer set search_path = public as $$
begin
  perform public.ledger_require(array['owner']::public.app_role[]);
  if coalesce(trim(p_reason), '') = '' then raise exception 'E_REASON_REQUIRED'; end if;
  update public.attendance set deleted_at = now(), fixed_by = auth.uid(), fix_reason = left(trim(p_reason), 300)
   where id = p_id and shop_id = public.current_shop_id() and deleted_at is null;
  if not found then raise exception 'E_NOT_FOUND'; end if;
end $$;
revoke execute on function public.attendance_void(uuid, text) from public, anon;
grant execute on function public.attendance_void(uuid, text) to authenticated;

-- ---------- سرعة الـ RLS: دالة المحل والدور مرة واحدة في الاستعلام، مش مع كل صف ----------
-- current_shop_id() وcurrent_app_role() بيقروا الملف الشخصي (وcurrent_shop_id بيتأكد من التحقق بخطوتين كمان) مع كل صف.
-- مع كتر المحلات، استعلام بسيط كان بيعدّي مهلة الـ 8 ثواني. الحل اللي Supabase بيوصي بيه: (select ...) حوالين الدالة،
-- فبتتحسب مرة واحدة. نفس الشروط بالظبط، والنتيجة نفسها. وآمن يتعاد (السياسة اللي اتلفّت قبل كده بتتخطى).
create or replace function public.rls_wrap(t text) returns text
language plpgsql immutable as $$
begin
  if t is null then return null; end if;
  -- الملفوفة قبل كده (شكلها المحفوظ: SELECT current_shop_id() AS current_shop_id) بتتعلّم الأول عشان ما تتلفّش تاني
  t := regexp_replace(t, 'SELECT (public\.)?(current_shop_id|current_app_role)\(\) AS (current_shop_id|current_app_role)', 'SELECT @@\2@@ AS \3', 'g');
  t := regexp_replace(t, '\m(public\.)?(current_shop_id|current_app_role)\(\)', '(select public.\2())', 'g');
  -- بترجع زي ما Postgres بيحفظها بالظبط (من غير public.)، فالسياسة الملفوفة قبل كده بتتخطى فعلًا
  return regexp_replace(t, '@@(current_shop_id|current_app_role)@@', '\1()', 'g');
end $$;
revoke execute on function public.rls_wrap(text) from public, anon, authenticated;
do $rls$
declare p record; q text; c text;
begin
  for p in select schemaname, tablename, policyname, qual, with_check from pg_policies where schemaname = 'public' loop
    q := public.rls_wrap(p.qual);
    c := public.rls_wrap(p.with_check);
    if q is distinct from p.qual or c is distinct from p.with_check then
      execute format('alter policy %I on %I.%I', p.policyname, p.schemaname, p.tablename)
        || case when p.qual is not null then format(' using (%s)', q) else '' end
        || case when p.with_check is not null then format(' with check (%s)', c) else '' end;
    end if;
  end loop;
end $rls$;


-- ---------- النسخة الاحتياطية والاسترجاع ----------
-- backup_snapshot: (src: 0060_sale_lines.sql) + attendance
create or replace function public.backup_snapshot(p_shop uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  res jsonb := jsonb_build_object('format', 'warsha-backup', 'version', 1, 'generated_at', now(), 'shop_id', p_shop);
  t text;
  rows jsonb;
begin
  foreach t in array array['shops', 'branches', 'staff_branches', 'attendance', 'shop_branding', 'profiles', 'customers', 'devices', 'device_costs', 'status_log', 'device_notes', 'device_photos', 'device_checks',
                           'quote_decisions', 'message_templates', 'message_log', 'accounts', 'journal_entries', 'journal_lines', 'sale_lines', 'payments', 'drawer_closings',
                           'suppliers', 'categories', 'items', 'stock_moves', 'uncosted_sales', 'payment_plans', 'plan_installments', 'branch_goals', 'printers', 'print_templates', 'check_templates', 'used_devices', 'commission_rules', 'purchases', 'labor_rates', 'specialties', 'staff_specialties', 'routes', 'repair_steps',
                           'repair_videos', 'device_ratings', 'issue_presets', 'partners', 'profit_distributions', 'party_links', 'shop_lists', 'audit_log'] loop
    execute format('select coalesce(jsonb_agg(to_jsonb(x)), ''[]''::jsonb) from public.%I x where x.shop_id = $1', t) into rows using p_shop;
    res := res || jsonb_build_object(t, rows);
  end loop;
  select coalesce(jsonb_agg(jsonb_build_object('device_id', device_id, 'kind', kind, 'erased_at', erased_at)), '[]'::jsonb)
    into rows from public.device_passcodes where shop_id = p_shop;
  return res || jsonb_build_object('device_passcodes', rows);
end $$;

-- restore_backup: (src: 0060_sale_lines.sql) + attendance (بعد الموظفين والفروع)
create or replace function public.restore_backup(p_data jsonb) returns jsonb
-- extensions: فيها gen_random_bytes على Supabase
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare
  s uuid := public.current_shop_id();
  me uuid := auth.uid();
  old_shop uuid;
  old_owner uuid;
  sh jsonb;
  t text;
  r jsonb;
  rows jsonb;
  n int;
  bad int;
  counts jsonb := '{}'::jsonb;
  -- بالترتيب ده عشان كل صف يلاقي اللي بيشاور عليه
  tabs text[] := array['branches', 'profiles', 'staff_branches', 'attendance', 'shop_branding', 'accounts', 'customers', 'suppliers', 'party_links', 'partners', 'specialties', 'staff_specialties', 'routes', 'labor_rates',
                       'issue_presets', 'commission_rules', 'shop_lists', 'message_templates', 'categories', 'items', 'devices', 'device_costs', 'status_log', 'device_notes', 'device_checks',
                       'quote_decisions', 'repair_steps', 'repair_videos', 'device_ratings', 'journal_entries', 'journal_lines', 'sale_lines', 'profit_distributions', 'payments',
                       'purchases', 'stock_moves', 'uncosted_sales', 'used_devices', 'payment_plans', 'plan_installments', 'branch_goals', 'printers', 'print_templates', 'check_templates', 'drawer_closings', 'message_log', 'audit_log'];
  -- الجداول دي ليها نسخة اتعملت مع التسجيل: بتتطابق بالكود (أو المفتاح) وبتاخد قيم النسخة
  keyed text[] := array['branches', 'accounts', 'routes', 'specialties', 'message_templates', 'labor_rates', 'shop_branding'];
begin
  perform public.ledger_require(array['owner']::public.app_role[]);
  if s is null or me is null then raise exception 'E_FORBIDDEN'; end if;
  if p_data is null or p_data->>'format' is distinct from 'warsha-backup' or coalesce((p_data->>'version')::int, 0) <> 1 then
    raise exception 'E_BACKUP_FORMAT';
  end if;
  old_shop := (p_data->>'shop_id')::uuid;
  if old_shop is null or old_shop = s then raise exception 'E_BACKUP_FORMAT'; end if;

  -- محل جديد فاضي بس
  if exists (select 1 from public.devices where shop_id = s) or exists (select 1 from public.customers where shop_id = s)
     or exists (select 1 from public.journal_entries where shop_id = s) or exists (select 1 from public.items where shop_id = s)
     or exists (select 1 from public.suppliers where shop_id = s) or exists (select 1 from public.payments where shop_id = s)
     or exists (select 1 from public.purchases where shop_id = s) or exists (select 1 from public.drawer_closings where shop_id = s)
     or exists (select 1 from public.stock_moves where shop_id = s)
     or exists (select 1 from public.profiles where shop_id = s and id <> me) then
    raise exception 'E_RESTORE_NOT_EMPTY';
  end if;

  perform set_config('warsha.restore', 'on', true);
  drop table if exists pg_temp._rmap;
  create temp table _rmap(old uuid primary key, new uuid not null) on commit drop;
  insert into _rmap values (old_shop, s);

  -- 1) بيانات المحل نفسه (من غير الخطة والإيقاف واللوجو اللي في Storage)
  sh := p_data->'shops'->0;
  if sh is not null then
    update public.shops set
      name = coalesce(sh->>'name', name), phone = sh->>'phone', address = sh->>'address',
      receipt_terms = coalesce(sh->>'receipt_terms', receipt_terms), warranty_days = coalesce((sh->>'warranty_days')::int, warranty_days),
      country = coalesce(sh->>'country', country), currency = coalesce(sh->>'currency', currency),
      payment_methods = coalesce(array(select jsonb_array_elements_text(sh->'payment_methods')), payment_methods),
      theme = coalesce(sh->>'theme', theme), locale = coalesce(sh->>'locale', locale),
      default_margin_pct = coalesce((sh->>'default_margin_pct')::int, default_margin_pct),
      extras = coalesce(sh->'extras', extras), max_discount_pct = coalesce((sh->>'max_discount_pct')::int, max_discount_pct)
    where id = s;
  end if;

  -- 2) الـ ids الجديدة
  -- صاحب المحل في النسخة = اللي بيسترجع دلوقتي
  select (x->>'id')::uuid into old_owner from jsonb_array_elements(coalesce(p_data->'profiles', '[]')) x
   where x->>'role' = 'owner' order by x->>'created_at' limit 1;
  if old_owner is not null then insert into _rmap values (old_owner, me) on conflict do nothing; end if;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.accounts a where a.shop_id = s and a.code = x->>'code' and x->>'code' is not null), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'accounts', '[]')) x on conflict do nothing;
  -- الفرع الرئيسي في النسخة = الفرع الرئيسي للمحل الجديد
  insert into _rmap select (x->>'id')::uuid, public.main_branch(s)
    from jsonb_array_elements(coalesce(p_data->'branches', '[]')) x where (x->>'is_main')::boolean and x->>'deleted_at' is null on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.routes a where a.shop_id = s and a.code = x->>'code' and x->>'code' is not null), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'routes', '[]')) x on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.specialties a where a.shop_id = s and a.code = x->>'code' and x->>'code' is not null), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'specialties', '[]')) x on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.message_templates a where a.shop_id = s and a.key = x->>'key'), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'message_templates', '[]')) x on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.labor_rates a where a.shop_id = s and a.deleted_at is null and lower(trim(a.issue)) = lower(trim(x->>'issue')) and x->>'deleted_at' is null), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'labor_rates', '[]')) x on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.shop_branding a where a.shop_id = s), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'shop_branding', '[]')) x on conflict do nothing;
  foreach t in array tabs loop
    insert into _rmap select (x->>'id')::uuid, gen_random_uuid() from jsonb_array_elements(coalesce(p_data->t, '[]')) x where x ? 'id' on conflict do nothing;
  end loop;

  -- 3) الصفوف نفسها بالترتيب
  foreach t in array tabs loop
    rows := '[]'::jsonb;
    for r in select public.restore_remap(x) from jsonb_array_elements(coalesce(p_data->t, '[]')) x loop
      if t = 'profiles' then
        -- صاحب المحل موجود أصلًا. الباقيين موظفين سابقين (من غير حساب دخول)
        continue when (r->>'id')::uuid = me;
        r := r || jsonb_build_object('deleted_at', coalesce(r->>'deleted_at', now()::text));
      elsif t = 'devices' then
        -- كود التتبع (الـ QR) بيفضل زي ما هو، إلا لو مستخدم في المشروع ده (المحل الأصلي لسه هنا)
        if exists (select 1 from public.devices d where d.tracking_token = r->>'tracking_token') then
          r := r || jsonb_build_object('tracking_token', encode(gen_random_bytes(12), 'hex'));
        end if;
      elsif t = 'journal_entries' then
        if r->>'idem_key' is not null and exists (select 1 from public.journal_entries j where j.idem_key = (r->>'idem_key')::uuid) then
          r := r || jsonb_build_object('idem_key', gen_random_uuid());
        end if;
      elsif t = 'accounts' and r->>'kind' = 'cash' and r->>'branch_id' is null then
        -- نسخة من قبل الفروع: الخزن كلها في الفرع الرئيسي
        r := r || jsonb_build_object('branch_id', public.main_branch(s));
      elsif t = 'used_devices' then
        -- رقم بطاقة البائع (في Vault) وصورتها (في Storage) مش جوه النسخة
        r := r || jsonb_build_object('seller_nid_secret', null, 'seller_photo', null);
      elsif t = 'shop_branding' then
        -- اللوجو الملون والحراري جوه الصف نفسه. الملف الأصلي في Storage مش جوه النسخة
        r := r || jsonb_build_object('logo_path', null);
      end if;
      if t = any (keyed) and exists (select 1 from _rmap m where m.new = (r->>'id')::uuid and m.old <> m.new)
         and (t <> 'shop_branding' or exists (select 1 from public.shop_branding b where b.id = (r->>'id')::uuid)) then
        -- موجود من التسجيل: بياخد قيم النسخة
        execute format('select count(*) from public.%I where id = $1', t) into n using (r->>'id')::uuid;
        if n > 0 then
          execute format('update public.%1$I x set (%2$s) = (select %2$s from jsonb_populate_record(null::public.%1$I, $1)) where x.id = $2', t,
            (select string_agg(quote_ident(c.column_name), ', ' order by c.ordinal_position) from information_schema.columns c
              where c.table_schema = 'public' and c.table_name = t and c.column_name not in ('id', 'shop_id')))
            using r, (r->>'id')::uuid;
          continue;
        end if;
      end if;
      rows := rows || jsonb_build_array(r);
    end loop;
    if jsonb_array_length(rows) > 0 then
      -- overriding system value: أرقام القيود (entry_no) بترجع زي ما هي
      execute format('insert into public.%1$I overriding system value select * from jsonb_populate_recordset(null::public.%1$I, $1)', t) using rows;
    end if;
    counts := counts || jsonb_build_object(t, jsonb_array_length(coalesce(p_data->t, '[]')));
  end loop;

  -- 4) عدّاد أرقام الطلبات: من آخر رقم راجع في كل سنة
  -- (لكل فرع: الرقم ممكن يبقى قبله بادئة الفرع B2-2026-0001)
  insert into public.order_counters(shop_id, branch_id, year, last_value)
  select s, branch_id, (regexp_match(order_no, '(\d{4})-(\d+)$'))[1]::int, max((regexp_match(order_no, '(\d{4})-(\d+)$'))[2]::int)
    from public.devices where shop_id = s and order_no ~ '\d{4}-\d+$' group by 2, 3
  on conflict (shop_id, branch_id, year) do update set last_value = greatest(public.order_counters.last_value, excluded.last_value);

  -- 5) التأكد: كل قيد متوازن، ورصيد كل حساب = رصيده في النسخة بالظبط
  select count(*) into bad from (
    select entry_id from public.journal_lines where shop_id = s group by entry_id having sum(debit) <> sum(credit)) x;
  if bad > 0 then raise exception 'E_RESTORE_UNBALANCED'; end if;
  select count(*) into bad from (
    select m.new acc, sum((l->>'debit')::bigint - (l->>'credit')::bigint) b
      from jsonb_array_elements(coalesce(p_data->'journal_lines', '[]')) l join _rmap m on m.old = (l->>'account_id')::uuid group by m.new
  ) x full join (select account_id, sum(debit - credit) b from public.journal_lines where shop_id = s group by account_id) y on y.account_id = x.acc
  where coalesce(x.b, 0) <> coalesce(y.b, 0);
  if bad > 0 then raise exception 'E_RESTORE_MISMATCH'; end if;
  -- وعدد الصفوف في كل جدول (الحسابات والقوالب اللي اتعملت مع التسجيل ممكن تزيد عن النسخة، مش تقل)
  foreach t in array tabs loop
    execute format('select count(*) from public.%I where shop_id = $1', t) into n using s;
    if n < jsonb_array_length(coalesce(p_data->t, '[]')) - (case when t = 'profiles' and old_owner is not null then 1 else 0 end) then
      raise exception 'E_RESTORE_MISMATCH';
    end if;
  end loop;

  perform set_config('warsha.restore', 'off', true);
  insert into public.audit_log(shop_id, actor_id, action, entity, entity_id, after)
  values (s, me, 'backup_restore', 'shops', s, jsonb_build_object('from_shop', old_shop, 'generated_at', p_data->>'generated_at', 'counts', counts));
  return jsonb_build_object('restored', true, 'counts', counts);
end $$;
$m0061$;
  insert into public.app_migrations(version, how) values ('0061_attendance.sql', 'applied');
  raise notice 'applied %', '0061_attendance.sql';
end $run$;
commit;

-- ============================== 0062_vat.sql ==============================
begin;
do $run$ begin
  if exists (select 1 from public.app_migrations where version = '0062_vat.sql') then return; end if;
  execute $m0062$
-- ============================================================
-- 0062: R5 ضريبة القيمة المضافة الاختيارية (لكل محل مسجّل)
-- - مقفولة افتراضيًا. صاحب المحل بيفتحها من الإعدادات (shops.extras.vat: enabled، rate_bp، reg_no).
-- - السعر شامل الضريبة دايمًا: العميل بيدفع نفس المبلغ، والقيد بيفصل "ضريبة مستحقة" (التزام) عن الإيراد.
--   الضريبة = round(المبلغ × النسبة ÷ (1 + النسبة)) بالقروش، لكل نوع إيراد لوحده (قطع، إكسسوار، خدمة/صيانة).
-- - النسبة بتتاخد ساعة القيد وبتتخزن في القيد نفسه، فتغييرها بعدين ما بيغيّرش القديم.
-- - البيع والتسليم بس. الإلغاء بقيد عكسي (reverse_entry) بيرجّع الضريبة لوحده.
-- - سداد الضريبة للمصلحة: pay_vat (صاحب المحل بس)، وتقرير الضريبة للفترة: vat_report.
-- - الفاتورة الإلكترونية والإيصال الإلكتروني لسه ممنوعين (CLAUDE.md)، ده تجهيز بس.
-- ============================================================

-- ---------- حساب "ضريبة القيمة المضافة المستحقة" ----------
alter table public.accounts drop constraint if exists accounts_kind_check;
alter table public.accounts add constraint accounts_kind_check check (kind = any (array[
  'cash', 'receivable', 'advances', 'inventory', 'payable', 'salaries', 'capital', 'drawings', 'revenue', 'cogs', 'expense', 'shortage', 'overage',
  'partner_capital', 'partner_current', 'retained', 'fixed_asset', 'tax']));

alter table public.journal_entries drop constraint if exists journal_entries_source_type_check;
alter table public.journal_entries add constraint journal_entries_source_type_check check (source_type = any (array[
  'payment', 'delivery', 'purchase', 'supplier_payment', 'part_use', 'sale', 'expense', 'salary', 'salary_payment', 'advance', 'advance_settle',
  'capital', 'drawing', 'transfer', 'drawer_close', 'reversal', 'cost_adjust', 'write_off', 'supplier_return', 'sale_return', 'opening',
  'partner_capital', 'partner_withdrawal', 'profit_distribution', 'netting', 'stock_transfer', 'commission', 'bonus', 'penalty', 'vat_payment']));

-- ---------- النسبة والحساب ----------
-- النسبة بالـ basis points (1400 = 14%). مقفولة أو قيمة مش سليمة = 0. أقصى حاجة 30%
create or replace function public.vat_bp(p_shop uuid) returns integer
language sql stable security definer set search_path = public as $$
  select case
    -- true كـ boolean بس (مش نص)، زي readVat في الواجهة
    when (sh.extras -> 'vat' -> 'enabled') is distinct from 'true'::jsonb then 0
    when coalesce(sh.extras -> 'vat' ->> 'rate_bp', '') !~ '^[0-9]{1,5}$' then 1400
    else least((sh.extras -> 'vat' ->> 'rate_bp')::integer, 3000)
  end
  from public.shops sh where sh.id = p_shop
$$;
revoke execute on function public.vat_bp(uuid) from public, anon, authenticated;

-- الضريبة جوه مبلغ شامل: round(g × bp ÷ (10000 + bp))، تقريب نص لفوق، أعداد صحيحة بس
create or replace function public.vat_of(p_gross bigint, p_bp integer) returns bigint
language sql immutable as $$
  select case when coalesce(p_bp, 0) <= 0 or coalesce(p_gross, 0) <= 0 then 0::bigint
    else (p_gross * p_bp * 2 + (10000 + p_bp)) / (2 * (10000 + p_bp)) end
$$;
revoke execute on function public.vat_of(bigint, integer) from public, anon;
grant execute on function public.vat_of(bigint, integer) to authenticated;

-- حساب الضريبة لكل المحلات الموجودة.
-- warsha.system: الترقية بتشتغل من SQL Editor من غير مستخدم، وtg_force_shop_id كان بيرفض (E_NO_SHOP) لو فيه محلات
do $vat$
begin
  perform set_config('warsha.system', 'on', true);
  insert into public.accounts(shop_id, code, type, kind)
  select sh.id, 'vat_payable', 'liability', 'tax' from public.shops sh
  on conflict (shop_id, code) where code is not null do nothing;
  perform set_config('warsha.system', 'off', true);
end $vat$;

-- ---------- ضريبة جهاز اتسلّم (للفاتورة والإيصال) ----------
-- من قيد التسليم نفسه (مش من النسبة الحالية). الفني لأ (مفيش أسعار)
create or replace function public.device_vat(p_device uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); r public.app_role := public.current_app_role(); v bigint; g bigint;
begin
  if s is null or r is null or r = 'technician' or r = 'marketing' then raise exception 'E_FORBIDDEN'; end if;
  select coalesce(sum(l.credit) filter (where a.kind = 'tax'), 0), coalesce(sum(l.credit) filter (where a.kind in ('tax', 'revenue')), 0)
    into v, g
  from public.journal_entries e join public.journal_lines l on l.entry_id = e.id join public.accounts a on a.id = l.account_id
  where e.shop_id = s and e.source_type = 'delivery' and e.source_id = p_device
    and not exists (select 1 from public.journal_entries x where x.reverses_id = e.id);
  if g = 0 then return null; end if;
  return jsonb_build_object('vat', v, 'gross', g, 'net', g - v);
end $$;
revoke execute on function public.device_vat(uuid) from public, anon;
grant execute on function public.device_vat(uuid) to authenticated;

-- ---------- سداد الضريبة للمصلحة ----------
create or replace function public.pay_vat(p_id uuid, p_cashbox uuid, p_amount bigint, p_note text default null)
returns uuid
language plpgsql security definer set search_path = public as $$
declare cb public.accounts; e uuid;
begin
  perform public.ledger_require(array['owner']::public.app_role[]);
  e := public.ledger_idem(p_id);
  if e is not null then return e; end if;
  perform public.ledger_amount(p_amount);
  cb := public.ledger_cashbox(p_cashbox);
  if public.ledger_acc('vat_payable') is null then raise exception 'E_NOT_FOUND'; end if;
  return public.ledger_post('vat_payment', p_id, p_note, jsonb_build_array(
    public.ledger_line(public.ledger_acc('vat_payable'), p_amount, 0), public.ledger_line(cb.id, 0, p_amount)), null, p_id);
end $$;
revoke execute on function public.pay_vat(uuid, uuid, bigint, text) from public, anon;
grant execute on function public.pay_vat(uuid, uuid, bigint, text) to authenticated;

-- ---------- تقرير الضريبة للفترة ----------
-- من الدفتر بس: ضريبة المبيعات والصيانة (والصافي قبلها)، والمرتجع بالإلغاء، والمدفوع للمصلحة، والرصيد المستحق لحد آخر الفترة
create or replace function public.vat_report(p_from timestamptz, p_to timestamptz, p_branch uuid default null) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  s uuid := public.current_shop_id();
  res jsonb;
begin
  perform public.grant_require('finance', 'view');
  if p_from is null or p_to is null or p_to <= p_from then raise exception 'E_BAD_INPUT'; end if;
  if not public.all_my_branches() and (p_branch is null or not public.can_branch(p_branch)) then p_branch := public.op_branch(); end if;
  with ln as (
    -- قيد الإلغاء بيتحسب على نوع القيد الأصلي (بيع أو تسليم)
    select coalesce(o.source_type, e.source_type) as src, e.source_type as own, a.kind, l.debit, l.credit
    from public.journal_entries e
    join public.journal_lines l on l.entry_id = e.id
    join public.accounts a on a.id = l.account_id
    left join public.journal_entries o on o.id = e.reverses_id
    where e.shop_id = s and e.occurred_at >= p_from and e.occurred_at < p_to
      -- السداد على المحل كله (الضريبة على المحل مش الفرع)، والباقي بفلتر الفرع
      and (p_branch is null or e.branch_id = p_branch or coalesce(o.source_type, e.source_type) = 'vat_payment')
      and a.kind in ('tax', 'revenue')
      and coalesce(o.source_type, e.source_type) in ('sale', 'delivery', 'vat_payment', 'sale_return')
  ),
  -- الحركات اللي فيها ضريبة بس (الصافي قبل الضريبة = إيراد نفس القيود)
  tx as (
    select e.id from public.journal_entries e join public.journal_lines l on l.entry_id = e.id join public.accounts a on a.id = l.account_id
    where e.shop_id = s and e.occurred_at >= p_from and e.occurred_at < p_to and (p_branch is null or e.branch_id = p_branch) and a.kind = 'tax'
    group by e.id
  ),
  net as (
    -- الصافي قبل الضريبة من البيع والتسليم الأصليين بس (زي ضريبتهم). الإلغاء والمرتجع في سطر "ضريبة مرتجعة"
    select e.source_type as src, coalesce(sum(l.credit - l.debit), 0)::bigint as v
    from tx join public.journal_entries e on e.id = tx.id
    join public.journal_lines l on l.entry_id = e.id join public.accounts a on a.id = l.account_id
    where a.kind = 'revenue' and e.reverses_id is null and e.source_type in ('sale', 'delivery') group by 1
  )
  select jsonb_build_object(
    'from', p_from, 'to', p_to, 'branch', p_branch, 'rate_bp', public.vat_bp(s),
    'sales_vat', coalesce(sum(credit) filter (where kind = 'tax' and src = 'sale' and own <> 'reversal'), 0),
    'repair_vat', coalesce(sum(credit) filter (where kind = 'tax' and src = 'delivery' and own <> 'reversal'), 0),
    -- المرتجع: إلغاء بيع أو تسليم بقيد عكسي، أو مرتجع من عميل
    'reversed_vat', coalesce(sum(debit - credit) filter (where kind = 'tax' and ((own = 'reversal' and src in ('sale', 'delivery')) or src = 'sale_return')), 0),
    'paid', coalesce(sum(debit) filter (where kind = 'tax' and src = 'vat_payment' and own <> 'reversal'), 0)
      - coalesce(sum(credit) filter (where kind = 'tax' and src = 'vat_payment' and own = 'reversal'), 0),
    'sales_net', coalesce((select v from net where src = 'sale'), 0),
    'repair_net', coalesce((select v from net where src = 'delivery'), 0),
    -- المستحق لحد آخر الفترة (كل الفروع: الضريبة على المحل كله)
    'due', coalesce((select sum(l.credit - l.debit) from public.journal_lines l join public.journal_entries e on e.id = l.entry_id
                     join public.accounts a on a.id = l.account_id where e.shop_id = s and a.kind = 'tax' and e.occurred_at < p_to), 0)::bigint
  ) into res from ln;
  return res;
end $$;
revoke execute on function public.vat_report(timestamptz, timestamptz, uuid) from public, anon;
grant execute on function public.vat_report(timestamptz, timestamptz, uuid) to authenticated;


-- ---------- الدوال اللي اتعدلت ----------
-- ensure_ledger_accounts: (src: 0027_inventory.sql) + vat_payable
create or replace function public.ensure_ledger_accounts(p_shop uuid) returns void
language plpgsql security definer set search_path = public as $$
declare m text;
begin
  insert into public.accounts(shop_id, code, type, kind)
  select p_shop, v.code, v.type::public.account_type, v.kind from (values
    ('ar', 'asset', 'receivable'), ('advances', 'asset', 'advances'), ('inventory', 'asset', 'inventory'),
    ('ap', 'liability', 'payable'), ('salaries_payable', 'liability', 'salaries'), ('vat_payable', 'liability', 'tax'),
    ('capital', 'equity', 'capital'), ('drawings', 'equity', 'drawings'),
    ('rev_repair', 'revenue', 'revenue'), ('rev_parts', 'revenue', 'revenue'), ('rev_accessories', 'revenue', 'revenue'), ('overage', 'revenue', 'overage'),
    ('cogs', 'expense', 'cogs'), ('shortage', 'expense', 'shortage'), ('wastage', 'expense', 'cogs'),
    ('exp_salaries', 'expense', 'expense'), ('exp_rent', 'expense', 'expense'), ('exp_electricity', 'expense', 'expense'),
    ('exp_internet', 'expense', 'expense'), ('exp_purchases', 'expense', 'expense')
  ) as v(code, type, kind)
  on conflict (shop_id, code) where code is not null do nothing;
  for m in
    select unnest(array['cash', 'wallet', 'instapay', 'bank_transfer', 'card'])
    union
    select unnest(payment_methods) from public.shops where id = p_shop
  loop
    insert into public.accounts(shop_id, code, type, kind, method)
    values (p_shop, 'cash_' || m, 'asset', 'cash', m)
    on conflict (shop_id, code) where code is not null do nothing;
  end loop;
end $$;

-- record_sale: (src: 0060_sale_lines.sql) + فصل الضريبة
create or replace function public.record_sale(p_id uuid, p_lines jsonb, p_cashbox uuid default null, p_customer uuid default null, p_note text default null)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  s uuid := public.current_shop_id();
  e uuid := gen_random_uuid();
  l jsonb;
  it public.items;
  q bigint; p bigint; cost bigint;
  rev_parts bigint := 0; rev_acc bigint := 0; rev_srv bigint := 0; total_cost bigint := 0;
  debit_acc uuid; pt text; pid uuid;
  n int := 0;
  bp integer := public.vat_bp(s); v_parts bigint := 0; v_acc bigint := 0; v_srv bigint := 0;
begin
  perform public.ledger_require(array['owner', 'reception']::public.app_role[]);
  perform public.perm_require('sales', 'add');
  if public.ledger_idem(p_id) is not null then return public.ledger_idem(p_id); end if;
  -- البيع بالآجل لصاحب المحل بس
  if p_cashbox is null and (p_customer is null or public.current_app_role() <> 'owner') then raise exception 'E_BAD_INPUT'; end if;
  if p_customer is not null and not exists (select 1 from public.customers where id = p_customer and shop_id = s and deleted_at is null) then raise exception 'E_NOT_FOUND'; end if;
  if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then raise exception 'E_BAD_INPUT'; end if;
  insert into public.journal_entries(id, shop_id, source_type, source_id, memo, idem_key, created_by)
  values (e, s, 'sale', p_id, nullif(trim(p_note), ''), p_id, auth.uid());
  -- البيع بس: لو الإعداد مفتوح، اللي مش موجود بيخرج من غير تكلفة ويتسوى بعدين
  perform set_config('app.uncosted', 'on', true);
  for l in select * from jsonb_array_elements(p_lines) loop
    select * into it from public.items where id = (l ->> 'item')::uuid and shop_id = s and deleted_at is null;
    if not found then raise exception 'E_NOT_FOUND'; end if;
    q := (l ->> 'qty')::bigint;
    p := (l ->> 'price')::bigint;
    if q is null or q <= 0 or p is null or p < 0 then raise exception 'E_BAD_AMOUNT'; end if;
    -- 6ب: سطر البيع زي ما اتباع (الاسم والكمية والسعر) عشان فاتورة البيع
    n := n + 1;
    insert into public.sale_lines(shop_id, entry_id, item_id, name, qty, price, seq, customer_id) values (s, e, it.id, it.name, q, p, n, p_customer);
    -- K: الخدمة من غير مخزون ولا تكلفة، وإيرادها إيراد الصيانة
    if it.kind = 'service' then rev_srv := rev_srv + q * p; continue; end if;
    cost := public.ledger_issue(it.id, q, e);
    total_cost := total_cost + cost;
    if it.kind = 'part' then rev_parts := rev_parts + q * p; else rev_acc := rev_acc + q * p; end if;
  end loop;
  perform set_config('app.uncosted', 'off', true);
  perform public.ledger_amount(rev_parts + rev_acc + rev_srv);
  if p_cashbox is null then
    debit_acc := public.ledger_acc('ar'); pt := 'customer'; pid := p_customer;
  else
    debit_acc := (public.ledger_cashbox(p_cashbox)).id;
  end if;
  insert into public.journal_lines(shop_id, entry_id, account_id, party_type, party_id, debit, credit)
  values (s, e, debit_acc, pt, pid, rev_parts + rev_acc + rev_srv, 0);
  -- R5: السعر شامل الضريبة. الضريبة بتتفصل من كل نوع إيراد لوحده، ومجموعها في حساب الضريبة المستحقة
  if bp > 0 then
    v_parts := public.vat_of(rev_parts, bp); v_acc := public.vat_of(rev_acc, bp); v_srv := public.vat_of(rev_srv, bp);
    if v_parts + v_acc + v_srv > 0 then
      insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values (s, e, public.ledger_acc('vat_payable'), 0, v_parts + v_acc + v_srv);
    end if;
  end if;
  if rev_parts > 0 then insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values (s, e, public.ledger_acc('rev_parts'), 0, rev_parts - v_parts); end if;
  if rev_acc > 0 then insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values (s, e, public.ledger_acc('rev_accessories'), 0, rev_acc - v_acc); end if;
  if rev_srv > 0 then insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values (s, e, public.ledger_acc('rev_repair'), 0, rev_srv - v_srv); end if;
  if total_cost > 0 then
    insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values
      (s, e, public.ledger_acc('cogs'), total_cost, 0), (s, e, public.ledger_acc('inventory'), 0, total_cost);
  end if;
  if p_cashbox is not null and p_customer is not null then
    null; -- البيع النقدي لعميل معروف ما بيأثرش على رصيده
  end if;
  return e;
end $$;

-- tg_device_revenue: (src: 0008_ledger.sql) + فصل الضريبة
create or replace function public.tg_device_revenue() returns trigger
language plpgsql security definer set search_path = public as $$
declare fc integer; v bigint;
begin
  if new.status = 'delivered' and old.status is distinct from 'delivered'
     and not exists (select 1 from public.journal_entries e where e.source_type = 'delivery' and e.source_id = new.id
                     and not exists (select 1 from public.journal_entries r where r.reverses_id = e.id)) then
    select final_cost into fc from public.device_costs where device_id = new.id and deleted_at is null;
    if coalesce(fc, 0) > 0 then
      -- R5: التكلفة النهائية شاملة الضريبة (لو المحل مسجّل)
      v := public.vat_of(fc, public.vat_bp(new.shop_id));
      perform public.ledger_post('delivery', new.id, new.order_no, jsonb_build_array(
        public.ledger_line(public.ledger_acc('ar'), fc, 0, 'customer', new.customer_id),
        public.ledger_line(public.ledger_acc('rev_repair'), 0, fc - v))
        || case when v > 0 then jsonb_build_array(public.ledger_line(public.ledger_acc('vat_payable'), 0, v)) else '[]'::jsonb end, new.id);
    end if;
  end if;
  return null;
end $$;

-- sale_invoice: (src: 0060_sale_lines.sql) + الضريبة ورقم التسجيل
create or replace function public.sale_invoice(p_entry uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  s uuid := public.current_shop_id(); r public.app_role := public.current_app_role();
  o public.journal_entries; ls jsonb; old boolean := false;
  total bigint; vat bigint; paid bigint; due bigint; cust uuid; cname text; cphone text; rev_no integer;
begin
  if s is null or r is null or r = 'technician' then raise exception 'E_FORBIDDEN'; end if;
  select * into o from public.journal_entries where id = p_entry and shop_id = s and source_type = 'sale';
  if not found then raise exception 'E_NOT_FOUND'; end if;
  if r <> 'owner' and not ((public.has_perm('sales', 'add') or public.has_perm('finance', 'view')) and public.can_branch(o.branch_id)) then
    raise exception 'E_FORBIDDEN';
  end if;
  -- المبالغ من الدفتر: الإجمالي = الإيراد، والمدفوع = اللي دخل الخزنة، والباقي = على العميل
  select coalesce(sum(l.credit) filter (where a.type = 'revenue' or a.kind = 'tax'), 0),
         coalesce(sum(l.credit) filter (where a.kind = 'tax'), 0),
         coalesce(sum(l.debit) filter (where a.kind = 'cash'), 0),
         coalesce(sum(l.debit) filter (where a.kind = 'receivable'), 0),
         max(l.party_id::text) filter (where l.party_type = 'customer')::uuid
    into total, vat, paid, due, cust
  from public.journal_lines l join public.accounts a on a.id = l.account_id where l.entry_id = o.id;
  select jsonb_agg(jsonb_build_object('name', sl.name, 'qty', sl.qty, 'price', sl.price, 'amount', sl.qty * sl.price) order by sl.seq) into ls
  from public.sale_lines sl where sl.entry_id = o.id and sl.deleted_at is null;
  if ls is null then
    -- بيع قديم: الأصناف والكميات بس (السعر ما كانش متخزّن)
    old := true;
    select jsonb_agg(jsonb_build_object('name', i.name, 'qty', x.q, 'price', null, 'amount', null) order by x.first) into ls
    from (select m.item_id, -sum(m.qty) q, min(m.created_at) first from public.stock_moves m where m.entry_id = o.id group by m.item_id) x
    join public.items i on i.id = x.item_id;
  end if;
  -- البيع الكاش لعميل معروف: العميل من سطور البيع
  cust := coalesce(cust, (select max(sl.customer_id::text)::uuid from public.sale_lines sl where sl.entry_id = o.id));
  -- اسم العميل وتليفونه لمين يشوف العملاء بس (نفس صلاحية جدول العملاء)
  if cust is not null and (r = 'owner' or public.has_perm('customers', 'view') or public.has_perm('intake', 'add')) then
    select c.name, c.phone into cname, cphone from public.customers c where c.id = cust;
  end if;
  select e.entry_no into rev_no from public.journal_entries e where e.reverses_id = o.id;
  return jsonb_build_object('entry_no', o.entry_no, 'at', o.occurred_at, 'memo', o.memo, 'branch_id', o.branch_id,
    'lines', coalesce(ls, '[]'::jsonb), 'legacy', old, 'total', total, 'vat', vat, 'net', total - vat,
    'vat_no', case when vat > 0 then (select nullif(trim(sh.extras -> 'vat' ->> 'reg_no'), '') from public.shops sh where sh.id = s) end,
    'paid', paid, 'due', due,
    'customer', cname, 'phone', cphone, 'cancelled_by', rev_no);
end $$;

-- financial_position: (src: 0038_roles_grant.sql) + الضريبة المستحقة
create or replace function public.financial_position(p_from timestamptz, p_to timestamptz, p_branch uuid default null) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  s uuid := public.current_shop_id();
  res jsonb;
begin
  perform public.grant_require('finance', 'view');
  -- الموظف: فروعه بس (لو مش معاه كل الفروع)
  if not public.all_my_branches() and (p_branch is null or not public.can_branch(p_branch)) then p_branch := public.op_branch(); end if;
  with bal as (
    select a.id, a.code, a.name, a.type, a.kind, a.method, l.party_type, l.party_id,
           coalesce(sum((l.debit - l.credit) * public.account_sign(a.type)), 0)::bigint as b
    from public.accounts a
    -- B: فرع واحد: الخزن بتاعته (كل حركاتها)، وباقي الحسابات من قيود الفرع ده
    left join public.journal_lines l on l.account_id = a.id
      and (p_branch is null or a.kind = 'cash' or exists (select 1 from public.journal_entries be where be.id = l.entry_id and be.branch_id = p_branch))
    where a.shop_id = s and (p_branch is null or a.kind <> 'cash' or a.branch_id = p_branch)
    group by a.id, l.party_type, l.party_id
  ),
  -- المعادلة والتوازن دايمًا للمحل كله (الدفتر واحد)
  bal_all as (
    select a.type, coalesce(sum((l.debit - l.credit) * public.account_sign(a.type)), 0)::bigint as b
    from public.accounts a left join public.journal_lines l on l.account_id = a.id
    where a.shop_id = s group by a.id, a.type
  ),
  eq_all as (
    select coalesce(sum(b) filter (where type = 'asset'), 0)::bigint as assets,
           coalesce(sum(b) filter (where type = 'liability'), 0)::bigint as liabilities,
           coalesce(sum(b) filter (where type = 'equity'), 0)::bigint as equity,
           (coalesce(sum(b) filter (where type = 'revenue'), 0) - coalesce(sum(b) filter (where type = 'expense'), 0))::bigint as earnings
    from bal_all
  ),
  acc as (select id, code, name, type, kind, method, sum(b)::bigint as b from bal group by id, code, name, type, kind, method),
  per as (
    select coalesce(sum(case when a.type = 'revenue' then l.credit - l.debit else 0 end), 0)::bigint as revenue,
           coalesce(sum(case when a.type = 'expense' then l.debit - l.credit else 0 end), 0)::bigint as expenses
    from public.journal_lines l join public.accounts a on a.id = l.account_id join public.journal_entries e on e.id = l.entry_id
    where l.shop_id = s and e.occurred_at >= p_from and e.occurred_at < p_to and (p_branch is null or e.branch_id = p_branch)
  ),
  tot as (
    select coalesce(sum(debit), 0)::bigint as d, coalesce(sum(credit), 0)::bigint as c from public.journal_lines where shop_id = s
  ),
  unb as (
    select count(*)::int as n from (
      select e.id from public.journal_entries e left join public.journal_lines l on l.entry_id = e.id
      where e.shop_id = s group by e.id having coalesce(sum(l.debit), 0) <> coalesce(sum(l.credit), 0) or count(l.id) < 2) x
  ),
  eq as (
    select coalesce(sum(b) filter (where type = 'asset'), 0)::bigint as assets,
           coalesce(sum(b) filter (where type = 'liability'), 0)::bigint as liabilities,
           coalesce(sum(b) filter (where type = 'equity'), 0)::bigint as equity,
           (coalesce(sum(b) filter (where type = 'revenue'), 0) - coalesce(sum(b) filter (where type = 'expense'), 0))::bigint as earnings
    from acc
  ),
  parts as (
    select
      coalesce(sum(b) filter (where kind = 'cash'), 0)::bigint as cash,
      coalesce(sum(greatest(b, 0)) filter (where kind in ('receivable', 'advances')), 0)::bigint as receivables,
      (coalesce(sum(greatest(b, 0)) filter (where kind in ('payable', 'salaries', 'tax')), 0)
        + coalesce(sum(greatest(-b, 0)) filter (where kind in ('receivable', 'advances')), 0)
        + coalesce(sum(greatest(-b, 0)) filter (where kind = 'inventory'), 0))::bigint as payables,
      coalesce(sum(greatest(-b, 0)) filter (where kind in ('payable', 'salaries', 'tax')), 0)::bigint as payables_debit,
      coalesce(sum(greatest(b, 0)) filter (where kind = 'inventory'), 0)::bigint as inventory,
      coalesce(sum(b) filter (where kind = 'fixed_asset'), 0)::bigint as fixed_assets,
      -- أرباح اتوزعت على الشركاء ولسه ما اتسحبتش (حقوق ملكية، مش دين من بره)
      coalesce(sum(greatest(b, 0)) filter (where kind = 'partner_current'), 0)::bigint as partners_due
    from bal
  ),
  days as (
    select (date_trunc('day', e.occurred_at at time zone 'Africa/Cairo'))::date as day,
           coalesce(sum(case when a.type = 'revenue' then l.credit - l.debit else 0 end), 0)::bigint as revenue,
           coalesce(sum(case when a.type = 'expense' then l.debit - l.credit else 0 end), 0)::bigint as expenses
    from public.journal_lines l join public.accounts a on a.id = l.account_id join public.journal_entries e on e.id = l.entry_id
    where l.shop_id = s and e.occurred_at >= p_from and e.occurred_at < p_to and a.type in ('revenue', 'expense') and (p_branch is null or e.branch_id = p_branch)
    group by 1
  )
  select jsonb_build_object(
    'cash', p.cash,
    'receivables', p.receivables + p.payables_debit,
    'payables', p.payables,
    -- مخزون فرع: قيمة حركاته (التحويل بين الفروع بيتقابل في حساب المخزون نفسه)
    'inventory', case when p_branch is null then p.inventory else (select coalesce(sum(m.value), 0)::bigint from public.stock_moves m where m.shop_id = s and m.branch_id = p_branch) end,
    'revenue', per.revenue,
    'expenses', per.expenses,
    'profit', per.revenue - per.expenses,
    'fixed_assets', p.fixed_assets,
    -- الضريبة على المحل كله (مش الفرع المختار)
    'vat_due', (select coalesce(sum(l.credit - l.debit), 0)::bigint from public.journal_lines l join public.accounts a on a.id = l.account_id where l.shop_id = s and a.kind = 'tax'),
    'partners_due', p.partners_due,
    -- قيمة المحل = الأصول − الالتزامات اللي لناس من بره بس (رأس مال الشركاء وأرباحهم حقوق ملكية، فما بتقللهاش)
    'net_worth', p.cash + p.receivables + p.payables_debit + p.fixed_assets - p.payables
      + case when p_branch is null then p.inventory else (select coalesce(sum(m.value), 0)::bigint from public.stock_moves m where m.shop_id = s and m.branch_id = p_branch) end,
    'branch', p_branch,
    -- حقوق الملكية بالتفصيل (من أول يوم): رأس مال صاحب المحل، والسحوبات، ورأس مال وجاري كل شريك، والأرباح المحتجزة
    'equity_parts', jsonb_build_object(
      'owner_capital', coalesce((select b from acc where code = 'capital'), 0),
      'drawings', -coalesce((select b from acc where code = 'drawings'), 0),
      'retained', eq.earnings + coalesce((select b from acc where code = 'retained'), 0),
      'partners', coalesce((select jsonb_agg(jsonb_build_object('id', pt.id, 'name', pt.name, 'share_bp', pt.share_bp,
          'capital', coalesce((select sum(b.b) from bal b where b.kind = 'partner_capital' and b.party_id = pt.id), 0),
          'current', coalesce((select sum(b.b) from bal b where b.kind = 'partner_current' and b.party_id = pt.id), 0)) order by pt.share_bp desc, pt.name)
        from public.partners pt where pt.shop_id = s and (pt.deleted_at is null or exists (select 1 from bal b where b.party_id = pt.id and b.b <> 0))), '[]'::jsonb)),
    'equation', jsonb_build_object('assets', eq_all.assets, 'liabilities', eq_all.liabilities, 'equity', eq_all.equity, 'earnings', eq_all.earnings),
    'debits', tot.d, 'credits', tot.c, 'unbalanced_entries', unb.n,
    'balanced', tot.d = tot.c and unb.n = 0 and eq_all.assets = eq_all.liabilities + eq_all.equity + eq_all.earnings,
    'cashboxes', coalesce((select jsonb_agg(jsonb_build_object('id', a.id, 'code', a.code, 'name', a.name, 'method', a.method, 'balance', a.b,
         'branch_id', (select x.branch_id from public.accounts x where x.id = a.id)) order by a.code nulls last, a.name)
       from acc a where a.kind = 'cash'), '[]'::jsonb),
    'top_customers', coalesce((select jsonb_agg(x order by (x ->> 'balance')::bigint desc) from (
       select jsonb_build_object('id', b.party_id, 'name', c.name, 'balance', sum(b.b)) as x
       from bal b join public.customers c on c.id = b.party_id where b.kind = 'receivable' and b.party_type = 'customer'
       group by b.party_id, c.name having sum(b.b) > 0 order by sum(b.b) desc limit 5) t), '[]'::jsonb),
    'top_suppliers', coalesce((select jsonb_agg(x order by (x ->> 'balance')::bigint desc) from (
       select jsonb_build_object('id', b.party_id, 'name', sp.name, 'balance', sum(b.b)) as x
       from bal b join public.suppliers sp on sp.id = b.party_id where b.kind = 'payable' and b.party_type = 'supplier'
       group by b.party_id, sp.name having sum(b.b) > 0 order by sum(b.b) desc limit 5) t), '[]'::jsonb),
    'daily', coalesce((select jsonb_agg(jsonb_build_object('day', day, 'revenue', revenue, 'expenses', expenses, 'profit', revenue - expenses) order by day) from days), '[]'::jsonb),
    'by_method', coalesce((select jsonb_object_agg(method, total) from (
       select p2.method, sum(p2.amount)::bigint as total from public.payments p2
       where p2.shop_id = s and p2.created_at >= p_from and p2.created_at < p_to
         and (p_branch is null or exists (select 1 from public.journal_entries pe where pe.id = p2.entry_id and pe.branch_id = p_branch))
         and not exists (select 1 from public.journal_entries r where r.reverses_id = p2.entry_id)
       group by p2.method) m), '{}'::jsonb),
    'delivered', (select count(*) from public.devices d where d.shop_id = s and d.delivered_at >= p_from and d.delivered_at < p_to and (p_branch is null or d.branch_id = p_branch)),
    'closings', coalesce((select jsonb_agg(jsonb_build_object('cashbox', dc.cashbox_id, 'expected', dc.expected, 'counted', dc.counted, 'diff', dc.diff, 'at', dc.created_at,
       'by', (select full_name from public.profiles where id = dc.closed_by)) order by dc.created_at)
       from public.drawer_closings dc where dc.shop_id = s and dc.created_at >= p_from and dc.created_at < p_to
         and (p_branch is null or exists (select 1 from public.accounts ca where ca.id = dc.cashbox_id and ca.branch_id = p_branch))), '[]'::jsonb)
  ) into res
  from parts p, per, tot, unb, eq, eq_all;
  return res;
end $$;

-- sale_return: (src: 0036_roles.sql) + الضريبة من المبلغ المرتجع
create or replace function public.sale_return(p_id uuid, p_item uuid, p_qty integer, p_refund bigint, p_cashbox uuid default null, p_customer uuid default null, p_restock boolean default true, p_reason text default null) returns uuid
language plpgsql security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); e uuid; it public.items; cost bigint; cb uuid; rev uuid; v bigint;
begin
  perform public.ledger_require(array['owner', 'reception']::public.app_role[]);
  perform public.perm_require('sales', 'edit');
  e := public.ledger_idem(p_id);
  if e is not null then return e; end if;
  if nullif(trim(p_reason), '') is null then raise exception 'E_REASON_REQUIRED'; end if;
  if p_qty is null or p_qty <= 0 or p_refund is null or p_refund < 0 then raise exception 'E_BAD_AMOUNT'; end if;
  select * into it from public.items where id = p_item and shop_id = s and deleted_at is null for update;
  if not found then raise exception 'E_NOT_FOUND'; end if;
  if p_cashbox is null and p_refund > 0 and p_customer is null then raise exception 'E_BAD_INPUT'; end if;
  if p_customer is not null and not exists (select 1 from public.customers where id = p_customer and shop_id = s and deleted_at is null) then raise exception 'E_NOT_FOUND'; end if;
  if p_cashbox is not null then cb := (public.ledger_cashbox(p_cashbox)).id; end if;
  rev := public.ledger_acc(case when it.kind = 'part' then 'rev_parts' else 'rev_accessories' end);
  cost := public.item_last_cost(p_item) * p_qty;
  if p_refund = 0 and (cost = 0 or not p_restock) then raise exception 'E_BAD_AMOUNT'; end if;
  e := gen_random_uuid();
  insert into public.journal_entries(id, shop_id, source_type, source_id, memo, idem_key, created_by)
  values (e, s, 'sale_return', p_item, trim(p_reason), p_id, auth.uid());
  if p_refund > 0 then
    -- R5: المبلغ المرتجع شامل الضريبة: الضريبة بترجع من حساب الضريبة المستحقة، والباقي من الإيراد
    v := public.vat_of(p_refund, public.vat_bp(s));
    insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values (s, e, rev, p_refund - v, 0);
    if v > 0 then insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values (s, e, public.ledger_acc('vat_payable'), v, 0); end if;
    if cb is not null then
      insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values (s, e, cb, 0, p_refund);
    else
      insert into public.journal_lines(shop_id, entry_id, account_id, party_type, party_id, debit, credit) values (s, e, public.ledger_acc('ar'), 'customer', p_customer, 0, p_refund);
    end if;
  end if;
  -- القطعة السليمة بترجع المخزون بتكلفتها (والتكلفة بتخرج من تكلفة البضاعة). البايظة ما بترجعش، وتكلفتها فضلت مصروف.
  if p_restock and cost > 0 then
    insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values
      (s, e, public.ledger_acc('inventory'), cost, 0), (s, e, public.ledger_acc('cogs'), 0, cost);
    insert into public.stock_moves(shop_id, item_id, entry_id, qty, value) values (s, p_item, e, p_qty, cost);
  elsif p_restock then
    insert into public.stock_moves(shop_id, item_id, entry_id, qty, value) values (s, p_item, e, p_qty, 0);
  end if;
  return e;
end $$;
$m0062$;
  insert into public.app_migrations(version, how) values ('0062_vat.sql', 'applied');
  raise notice 'applied %', '0062_vat.sql';
end $run$;
commit;

-- ============================== 0063_cheques.sql ==============================
begin;
do $run$ begin
  if exists (select 1 from public.app_migrations where version = '0063_cheques.sql') then return; end if;
  execute $m0063$
-- ============================================================
-- 0063: R7 الشيكات (تحت التحصيل وبميعاد)
-- - شيك من عميل: بيقلل اللي على العميل، وبيدخل حساب "شيكات تحت التحصيل" (أصل) لحد ما يتصرف في خزنة (بنك).
-- - شيك لمورد: بيقلل اللي للمورد، وبيدخل "شيكات مستحقة الدفع" (التزام) لحد ما يتصرف من خزنة.
-- - الشيك اللي اترفض (أو اتلغى قبل الصرف): الدين بيرجع للعميل أو المورد زي ما كان.
-- - كل خطوة قيد متوازن، والقيود ما بتتعدلش. الإلغاء بقيد عكسي ممنوع لقيود الشيكات: الرفض هو الطريقة الوحيدة.
-- - صاحب المحل أو اللي معاه "المالية ← يضيف"، وفي فروعه بس.
-- ============================================================

alter table public.accounts drop constraint if exists accounts_kind_check;
alter table public.accounts add constraint accounts_kind_check check (kind = any (array[
  'cash', 'receivable', 'advances', 'inventory', 'payable', 'salaries', 'capital', 'drawings', 'revenue', 'cogs', 'expense', 'shortage', 'overage',
  'partner_capital', 'partner_current', 'retained', 'fixed_asset', 'tax', 'cheque_in', 'cheque_out']));

alter table public.journal_entries drop constraint if exists journal_entries_source_type_check;
alter table public.journal_entries add constraint journal_entries_source_type_check check (source_type = any (array[
  'payment', 'delivery', 'purchase', 'supplier_payment', 'part_use', 'sale', 'expense', 'salary', 'salary_payment', 'advance', 'advance_settle',
  'capital', 'drawing', 'transfer', 'drawer_close', 'reversal', 'cost_adjust', 'write_off', 'supplier_return', 'sale_return', 'opening',
  'partner_capital', 'partner_withdrawal', 'profit_distribution', 'netting', 'stock_transfer', 'commission', 'bonus', 'penalty', 'vat_payment',
  'cheque_in', 'cheque_out', 'cheque_clear', 'cheque_bounce']));

-- حسابات الشيكات لكل المحلات الموجودة (warsha.system: الترقية من SQL Editor من غير مستخدم)
do $chq$
begin
  perform set_config('warsha.system', 'on', true);
  insert into public.accounts(shop_id, code, type, kind)
  select sh.id, v.code, v.type::public.account_type, v.kind from public.shops sh
  cross join (values ('cheques_in', 'asset', 'cheque_in'), ('cheques_out', 'liability', 'cheque_out')) as v(code, type, kind)
  on conflict (shop_id, code) where code is not null do nothing;
  perform set_config('warsha.system', 'off', true);
end $chq$;

-- ---------- الجدول ----------
create table public.cheques (
  id uuid primary key default gen_random_uuid(),
  shop_id uuid not null references public.shops(id),
  branch_id uuid references public.branches(id),
  direction text not null check (direction in ('in', 'out')),
  party_type text not null check (party_type in ('customer', 'supplier')),
  party_id uuid not null,
  cheque_no text not null check (length(trim(cheque_no)) between 1 and 40),
  bank text check (bank is null or length(bank) <= 80),
  due_date date not null,
  amount bigint not null check (amount > 0 and amount <= 100000000000),
  status text not null default 'pending' check (status in ('pending', 'cleared', 'bounced')),
  entry_id uuid not null references public.journal_entries(id),
  settle_entry_id uuid references public.journal_entries(id),
  settled_at timestamptz,
  note text check (note is null or length(note) <= 300),
  created_by uuid references public.profiles(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  check ((direction = 'in') = (party_type = 'customer')),
  check ((status = 'pending') = (settle_entry_id is null))
);
create index cheques_due on public.cheques(shop_id, status, due_date) where deleted_at is null;
alter table public.cheques enable row level security;
create policy cheques_select on public.cheques for select to authenticated
  using (shop_id = (select public.current_shop_id()) and ((select public.current_app_role()) = 'owner' or (public.has_perm('finance', 'view') and public.can_branch(branch_id))));
-- الكتابة من الدوال بس
revoke all on public.cheques from public, anon, authenticated;
grant select on public.cheques to authenticated;
create trigger set_updated_at before update on public.cheques for each row execute function public.tg_set_updated_at();
create trigger block_delete before delete on public.cheques for each row execute function public.tg_block_delete();
create trigger zz_audit after insert or update on public.cheques for each row execute function public.tg_audit();

-- ---------- الصلاحية ----------
create or replace function public.cheque_require() returns void
language plpgsql stable security definer set search_path = public as $$
begin
  if public.current_app_role() = 'owner' then return; end if;
  perform public.grant_require('finance', 'add');
end $$;
revoke execute on function public.cheque_require() from public, anon, authenticated;

-- ---------- استلام شيك من عميل ----------
create or replace function public.cheque_receive(p_id uuid, p_customer uuid, p_no text, p_bank text, p_due date, p_amount bigint, p_note text default null)
returns uuid
language plpgsql security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); e uuid;
begin
  perform public.cheque_require();
  if exists (select 1 from public.cheques where id = p_id) then return p_id; end if;
  perform public.ledger_amount(p_amount);
  if coalesce(trim(p_no), '') = '' or p_due is null then raise exception 'E_BAD_INPUT'; end if;
  if not exists (select 1 from public.customers where id = p_customer and shop_id = s and deleted_at is null) then raise exception 'E_NOT_FOUND'; end if;
  e := public.ledger_post('cheque_in', p_id, nullif(trim(p_note), ''), jsonb_build_array(
    public.ledger_line(public.ledger_acc('cheques_in'), p_amount, 0, 'customer', p_customer),
    public.ledger_line(public.ledger_acc('ar'), 0, p_amount, 'customer', p_customer)), null, p_id);
  insert into public.cheques(id, shop_id, branch_id, direction, party_type, party_id, cheque_no, bank, due_date, amount, entry_id, note, created_by)
  values (p_id, s, public.op_branch(), 'in', 'customer', p_customer, trim(p_no), nullif(trim(p_bank), ''), p_due, p_amount, e, nullif(trim(p_note), ''), auth.uid());
  return p_id;
end $$;

-- ---------- شيك لمورد ----------
create or replace function public.cheque_issue(p_id uuid, p_supplier uuid, p_no text, p_bank text, p_due date, p_amount bigint, p_note text default null)
returns uuid
language plpgsql security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); e uuid;
begin
  perform public.cheque_require();
  if exists (select 1 from public.cheques where id = p_id) then return p_id; end if;
  perform public.ledger_amount(p_amount);
  if coalesce(trim(p_no), '') = '' or p_due is null then raise exception 'E_BAD_INPUT'; end if;
  if not exists (select 1 from public.suppliers where id = p_supplier and shop_id = s and deleted_at is null) then raise exception 'E_NOT_FOUND'; end if;
  e := public.ledger_post('cheque_out', p_id, nullif(trim(p_note), ''), jsonb_build_array(
    public.ledger_line(public.ledger_acc('ap'), p_amount, 0, 'supplier', p_supplier),
    public.ledger_line(public.ledger_acc('cheques_out'), 0, p_amount, 'supplier', p_supplier)), null, p_id);
  insert into public.cheques(id, shop_id, branch_id, direction, party_type, party_id, cheque_no, bank, due_date, amount, entry_id, note, created_by)
  values (p_id, s, public.op_branch(), 'out', 'supplier', p_supplier, trim(p_no), nullif(trim(p_bank), ''), p_due, p_amount, e, nullif(trim(p_note), ''), auth.uid());
  return p_id;
end $$;

-- الشيك نفسه (مقفول للتعديل)، في المحل وفروع المستخدم
create or replace function public.cheque_lock(p_cheque uuid) returns public.cheques
language plpgsql security definer set search_path = public as $$
declare c public.cheques;
begin
  select * into c from public.cheques where id = p_cheque and shop_id = public.current_shop_id() and deleted_at is null for update;
  if not found then raise exception 'E_NOT_FOUND'; end if;
  if public.current_app_role() <> 'owner' and not public.can_branch(c.branch_id) then raise exception 'E_FORBIDDEN'; end if;
  -- الصرف والرفض بيتسجلوا في فرع الشيك نفسه (مش الفرع المفتوح على الشاشة)، وخزنة فرع تاني بتترفض (E_BRANCH_CASHBOX)
  perform public.pin_branch(c.branch_id);
  return c;
end $$;
revoke execute on function public.cheque_lock(uuid) from public, anon, authenticated;

-- ---------- الصرف: الفلوس دخلت أو خرجت من الخزنة (البنك غالبًا) ----------
create or replace function public.cheque_clear(p_op uuid, p_cheque uuid, p_cashbox uuid)
returns uuid
language plpgsql security definer set search_path = public as $$
declare c public.cheques; cb public.accounts; e uuid;
begin
  perform public.cheque_require();
  e := public.ledger_idem(p_op);
  if e is not null then return e; end if;
  c := public.cheque_lock(p_cheque);
  if c.status <> 'pending' then raise exception 'E_CHEQUE_DONE'; end if;
  cb := public.ledger_cashbox(p_cashbox);
  if c.direction = 'in' then
    e := public.ledger_post('cheque_clear', c.id, c.cheque_no, jsonb_build_array(
      public.ledger_line(cb.id, c.amount, 0),
      public.ledger_line(public.ledger_acc('cheques_in'), 0, c.amount, 'customer', c.party_id)), null, p_op);
  else
    e := public.ledger_post('cheque_clear', c.id, c.cheque_no, jsonb_build_array(
      public.ledger_line(public.ledger_acc('cheques_out'), c.amount, 0, 'supplier', c.party_id),
      public.ledger_line(cb.id, 0, c.amount)), null, p_op);
  end if;
  update public.cheques set status = 'cleared', settle_entry_id = e, settled_at = now() where id = c.id;
  return e;
end $$;

-- ---------- الرفض (أو الإلغاء قبل الصرف): الدين بيرجع زي ما كان ----------
create or replace function public.cheque_bounce(p_op uuid, p_cheque uuid, p_reason text)
returns uuid
language plpgsql security definer set search_path = public as $$
declare c public.cheques; e uuid;
begin
  perform public.cheque_require();
  e := public.ledger_idem(p_op);
  if e is not null then return e; end if;
  if coalesce(trim(p_reason), '') = '' then raise exception 'E_REASON_REQUIRED'; end if;
  c := public.cheque_lock(p_cheque);
  if c.status <> 'pending' then raise exception 'E_CHEQUE_DONE'; end if;
  if c.direction = 'in' then
    e := public.ledger_post('cheque_bounce', c.id, left(trim(p_reason), 300), jsonb_build_array(
      public.ledger_line(public.ledger_acc('ar'), c.amount, 0, 'customer', c.party_id),
      public.ledger_line(public.ledger_acc('cheques_in'), 0, c.amount, 'customer', c.party_id)), null, p_op);
  else
    e := public.ledger_post('cheque_bounce', c.id, left(trim(p_reason), 300), jsonb_build_array(
      public.ledger_line(public.ledger_acc('cheques_out'), c.amount, 0, 'supplier', c.party_id),
      public.ledger_line(public.ledger_acc('ap'), 0, c.amount, 'supplier', c.party_id)), null, p_op);
  end if;
  update public.cheques set status = 'bounced', settle_entry_id = e, settled_at = now() where id = c.id;
  return e;
end $$;

-- قيود الشيكات ما بتتلغيش بقيد عكسي (حالة الشيك كانت هتفضل غلط): الرفض بس
create or replace function public.tg_no_cheque_reversal() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.reverses_id is not null and exists (
    select 1 from public.journal_entries o where o.id = new.reverses_id and o.source_type in ('cheque_in', 'cheque_out', 'cheque_clear', 'cheque_bounce')) then
    raise exception 'E_CHEQUE_REVERSAL';
  end if;
  return new;
end $$;
create trigger a_no_cheque_reversal before insert on public.journal_entries for each row execute function public.tg_no_cheque_reversal();

-- ---------- القايمة (بأسماء العملاء والموردين) ----------
create or replace function public.cheques_list(p_status text default null, p_branch uuid default null) returns table (
  id uuid, direction text, party_type text, party_id uuid, party_name text, cheque_no text, bank text, due_date date,
  amount bigint, status text, branch_id uuid, settled_at timestamptz, note text, created_at timestamptz)
language plpgsql stable security definer set search_path = public as $$
declare s uuid := public.current_shop_id();
begin
  perform public.grant_require('finance', 'view');
  if not public.all_my_branches() and (p_branch is null or not public.can_branch(p_branch)) then p_branch := public.op_branch(); end if;
  return query
  select c.id, c.direction, c.party_type, c.party_id, coalesce(cu.name, sp.name), c.cheque_no, c.bank, c.due_date,
         c.amount, c.status, c.branch_id, c.settled_at, c.note, c.created_at
  from public.cheques c
  left join public.customers cu on c.party_type = 'customer' and cu.id = c.party_id
  left join public.suppliers sp on c.party_type = 'supplier' and sp.id = c.party_id
  where c.shop_id = s and c.deleted_at is null
    and (p_status is null or c.status = p_status)
    and (p_branch is null or c.branch_id = p_branch)
  order by (c.status = 'pending') desc, c.due_date, c.created_at;
end $$;

revoke execute on function public.cheque_receive(uuid, uuid, text, text, date, bigint, text) from public, anon;
revoke execute on function public.cheque_issue(uuid, uuid, text, text, date, bigint, text) from public, anon;
revoke execute on function public.cheque_clear(uuid, uuid, uuid) from public, anon;
revoke execute on function public.cheque_bounce(uuid, uuid, text) from public, anon;
revoke execute on function public.cheques_list(text, uuid) from public, anon;
grant execute on function public.cheque_receive(uuid, uuid, text, text, date, bigint, text) to authenticated;
grant execute on function public.cheque_issue(uuid, uuid, text, text, date, bigint, text) to authenticated;
grant execute on function public.cheque_clear(uuid, uuid, uuid) to authenticated;
grant execute on function public.cheque_bounce(uuid, uuid, text) to authenticated;
grant execute on function public.cheques_list(text, uuid) to authenticated;
revoke execute on function public.tg_no_cheque_reversal() from public, anon, authenticated;


-- ---------- الدوال اللي اتعدلت ----------
-- ensure_ledger_accounts: (src: 0062_vat.sql) + الشيكات
create or replace function public.ensure_ledger_accounts(p_shop uuid) returns void
language plpgsql security definer set search_path = public as $$
declare m text;
begin
  insert into public.accounts(shop_id, code, type, kind)
  select p_shop, v.code, v.type::public.account_type, v.kind from (values
    ('ar', 'asset', 'receivable'), ('advances', 'asset', 'advances'), ('inventory', 'asset', 'inventory'),
    ('ap', 'liability', 'payable'), ('salaries_payable', 'liability', 'salaries'), ('vat_payable', 'liability', 'tax'),
    ('cheques_in', 'asset', 'cheque_in'), ('cheques_out', 'liability', 'cheque_out'),
    ('capital', 'equity', 'capital'), ('drawings', 'equity', 'drawings'),
    ('rev_repair', 'revenue', 'revenue'), ('rev_parts', 'revenue', 'revenue'), ('rev_accessories', 'revenue', 'revenue'), ('overage', 'revenue', 'overage'),
    ('cogs', 'expense', 'cogs'), ('shortage', 'expense', 'shortage'), ('wastage', 'expense', 'cogs'),
    ('exp_salaries', 'expense', 'expense'), ('exp_rent', 'expense', 'expense'), ('exp_electricity', 'expense', 'expense'),
    ('exp_internet', 'expense', 'expense'), ('exp_purchases', 'expense', 'expense')
  ) as v(code, type, kind)
  on conflict (shop_id, code) where code is not null do nothing;
  for m in
    select unnest(array['cash', 'wallet', 'instapay', 'bank_transfer', 'card'])
    union
    select unnest(payment_methods) from public.shops where id = p_shop
  loop
    insert into public.accounts(shop_id, code, type, kind, method)
    values (p_shop, 'cash_' || m, 'asset', 'cash', m)
    on conflict (shop_id, code) where code is not null do nothing;
  end loop;
end $$;

-- financial_position: (src: 0062_vat.sql) + الشيكات
create or replace function public.financial_position(p_from timestamptz, p_to timestamptz, p_branch uuid default null) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  s uuid := public.current_shop_id();
  res jsonb;
begin
  perform public.grant_require('finance', 'view');
  -- الموظف: فروعه بس (لو مش معاه كل الفروع)
  if not public.all_my_branches() and (p_branch is null or not public.can_branch(p_branch)) then p_branch := public.op_branch(); end if;
  with bal as (
    select a.id, a.code, a.name, a.type, a.kind, a.method, l.party_type, l.party_id,
           coalesce(sum((l.debit - l.credit) * public.account_sign(a.type)), 0)::bigint as b
    from public.accounts a
    -- B: فرع واحد: الخزن بتاعته (كل حركاتها)، وباقي الحسابات من قيود الفرع ده
    left join public.journal_lines l on l.account_id = a.id
      and (p_branch is null or a.kind = 'cash' or exists (select 1 from public.journal_entries be where be.id = l.entry_id and be.branch_id = p_branch))
    where a.shop_id = s and (p_branch is null or a.kind <> 'cash' or a.branch_id = p_branch)
    group by a.id, l.party_type, l.party_id
  ),
  -- المعادلة والتوازن دايمًا للمحل كله (الدفتر واحد)
  bal_all as (
    select a.type, coalesce(sum((l.debit - l.credit) * public.account_sign(a.type)), 0)::bigint as b
    from public.accounts a left join public.journal_lines l on l.account_id = a.id
    where a.shop_id = s group by a.id, a.type
  ),
  eq_all as (
    select coalesce(sum(b) filter (where type = 'asset'), 0)::bigint as assets,
           coalesce(sum(b) filter (where type = 'liability'), 0)::bigint as liabilities,
           coalesce(sum(b) filter (where type = 'equity'), 0)::bigint as equity,
           (coalesce(sum(b) filter (where type = 'revenue'), 0) - coalesce(sum(b) filter (where type = 'expense'), 0))::bigint as earnings
    from bal_all
  ),
  acc as (select id, code, name, type, kind, method, sum(b)::bigint as b from bal group by id, code, name, type, kind, method),
  per as (
    select coalesce(sum(case when a.type = 'revenue' then l.credit - l.debit else 0 end), 0)::bigint as revenue,
           coalesce(sum(case when a.type = 'expense' then l.debit - l.credit else 0 end), 0)::bigint as expenses
    from public.journal_lines l join public.accounts a on a.id = l.account_id join public.journal_entries e on e.id = l.entry_id
    where l.shop_id = s and e.occurred_at >= p_from and e.occurred_at < p_to and (p_branch is null or e.branch_id = p_branch)
  ),
  tot as (
    select coalesce(sum(debit), 0)::bigint as d, coalesce(sum(credit), 0)::bigint as c from public.journal_lines where shop_id = s
  ),
  unb as (
    select count(*)::int as n from (
      select e.id from public.journal_entries e left join public.journal_lines l on l.entry_id = e.id
      where e.shop_id = s group by e.id having coalesce(sum(l.debit), 0) <> coalesce(sum(l.credit), 0) or count(l.id) < 2) x
  ),
  eq as (
    select coalesce(sum(b) filter (where type = 'asset'), 0)::bigint as assets,
           coalesce(sum(b) filter (where type = 'liability'), 0)::bigint as liabilities,
           coalesce(sum(b) filter (where type = 'equity'), 0)::bigint as equity,
           (coalesce(sum(b) filter (where type = 'revenue'), 0) - coalesce(sum(b) filter (where type = 'expense'), 0))::bigint as earnings
    from acc
  ),
  parts as (
    select
      coalesce(sum(b) filter (where kind = 'cash'), 0)::bigint as cash,
      coalesce(sum(greatest(b, 0)) filter (where kind in ('receivable', 'advances', 'cheque_in')), 0)::bigint as receivables,
      (coalesce(sum(greatest(b, 0)) filter (where kind in ('payable', 'salaries', 'tax', 'cheque_out')), 0)
        + coalesce(sum(greatest(-b, 0)) filter (where kind in ('receivable', 'advances', 'cheque_in')), 0)
        + coalesce(sum(greatest(-b, 0)) filter (where kind = 'inventory'), 0))::bigint as payables,
      coalesce(sum(greatest(-b, 0)) filter (where kind in ('payable', 'salaries', 'tax', 'cheque_out')), 0)::bigint as payables_debit,
      coalesce(sum(greatest(b, 0)) filter (where kind = 'inventory'), 0)::bigint as inventory,
      coalesce(sum(b) filter (where kind = 'fixed_asset'), 0)::bigint as fixed_assets,
      -- أرباح اتوزعت على الشركاء ولسه ما اتسحبتش (حقوق ملكية، مش دين من بره)
      coalesce(sum(greatest(b, 0)) filter (where kind = 'partner_current'), 0)::bigint as partners_due
    from bal
  ),
  days as (
    select (date_trunc('day', e.occurred_at at time zone 'Africa/Cairo'))::date as day,
           coalesce(sum(case when a.type = 'revenue' then l.credit - l.debit else 0 end), 0)::bigint as revenue,
           coalesce(sum(case when a.type = 'expense' then l.debit - l.credit else 0 end), 0)::bigint as expenses
    from public.journal_lines l join public.accounts a on a.id = l.account_id join public.journal_entries e on e.id = l.entry_id
    where l.shop_id = s and e.occurred_at >= p_from and e.occurred_at < p_to and a.type in ('revenue', 'expense') and (p_branch is null or e.branch_id = p_branch)
    group by 1
  )
  select jsonb_build_object(
    'cash', p.cash,
    'receivables', p.receivables + p.payables_debit,
    'payables', p.payables,
    -- مخزون فرع: قيمة حركاته (التحويل بين الفروع بيتقابل في حساب المخزون نفسه)
    'inventory', case when p_branch is null then p.inventory else (select coalesce(sum(m.value), 0)::bigint from public.stock_moves m where m.shop_id = s and m.branch_id = p_branch) end,
    'revenue', per.revenue,
    'expenses', per.expenses,
    'profit', per.revenue - per.expenses,
    'fixed_assets', p.fixed_assets,
    'cheques_in', coalesce((select sum(b) from acc where kind = 'cheque_in'), 0),
    'cheques_out', coalesce((select sum(b) from acc where kind = 'cheque_out'), 0),
    -- الضريبة على المحل كله (مش الفرع المختار)
    'vat_due', (select coalesce(sum(l.credit - l.debit), 0)::bigint from public.journal_lines l join public.accounts a on a.id = l.account_id where l.shop_id = s and a.kind = 'tax'),
    'partners_due', p.partners_due,
    -- قيمة المحل = الأصول − الالتزامات اللي لناس من بره بس (رأس مال الشركاء وأرباحهم حقوق ملكية، فما بتقللهاش)
    'net_worth', p.cash + p.receivables + p.payables_debit + p.fixed_assets - p.payables
      + case when p_branch is null then p.inventory else (select coalesce(sum(m.value), 0)::bigint from public.stock_moves m where m.shop_id = s and m.branch_id = p_branch) end,
    'branch', p_branch,
    -- حقوق الملكية بالتفصيل (من أول يوم): رأس مال صاحب المحل، والسحوبات، ورأس مال وجاري كل شريك، والأرباح المحتجزة
    'equity_parts', jsonb_build_object(
      'owner_capital', coalesce((select b from acc where code = 'capital'), 0),
      'drawings', -coalesce((select b from acc where code = 'drawings'), 0),
      'retained', eq.earnings + coalesce((select b from acc where code = 'retained'), 0),
      'partners', coalesce((select jsonb_agg(jsonb_build_object('id', pt.id, 'name', pt.name, 'share_bp', pt.share_bp,
          'capital', coalesce((select sum(b.b) from bal b where b.kind = 'partner_capital' and b.party_id = pt.id), 0),
          'current', coalesce((select sum(b.b) from bal b where b.kind = 'partner_current' and b.party_id = pt.id), 0)) order by pt.share_bp desc, pt.name)
        from public.partners pt where pt.shop_id = s and (pt.deleted_at is null or exists (select 1 from bal b where b.party_id = pt.id and b.b <> 0))), '[]'::jsonb)),
    'equation', jsonb_build_object('assets', eq_all.assets, 'liabilities', eq_all.liabilities, 'equity', eq_all.equity, 'earnings', eq_all.earnings),
    'debits', tot.d, 'credits', tot.c, 'unbalanced_entries', unb.n,
    'balanced', tot.d = tot.c and unb.n = 0 and eq_all.assets = eq_all.liabilities + eq_all.equity + eq_all.earnings,
    'cashboxes', coalesce((select jsonb_agg(jsonb_build_object('id', a.id, 'code', a.code, 'name', a.name, 'method', a.method, 'balance', a.b,
         'branch_id', (select x.branch_id from public.accounts x where x.id = a.id)) order by a.code nulls last, a.name)
       from acc a where a.kind = 'cash'), '[]'::jsonb),
    'top_customers', coalesce((select jsonb_agg(x order by (x ->> 'balance')::bigint desc) from (
       select jsonb_build_object('id', b.party_id, 'name', c.name, 'balance', sum(b.b)) as x
       from bal b join public.customers c on c.id = b.party_id where b.kind = 'receivable' and b.party_type = 'customer'
       group by b.party_id, c.name having sum(b.b) > 0 order by sum(b.b) desc limit 5) t), '[]'::jsonb),
    'top_suppliers', coalesce((select jsonb_agg(x order by (x ->> 'balance')::bigint desc) from (
       select jsonb_build_object('id', b.party_id, 'name', sp.name, 'balance', sum(b.b)) as x
       from bal b join public.suppliers sp on sp.id = b.party_id where b.kind = 'payable' and b.party_type = 'supplier'
       group by b.party_id, sp.name having sum(b.b) > 0 order by sum(b.b) desc limit 5) t), '[]'::jsonb),
    'daily', coalesce((select jsonb_agg(jsonb_build_object('day', day, 'revenue', revenue, 'expenses', expenses, 'profit', revenue - expenses) order by day) from days), '[]'::jsonb),
    'by_method', coalesce((select jsonb_object_agg(method, total) from (
       select p2.method, sum(p2.amount)::bigint as total from public.payments p2
       where p2.shop_id = s and p2.created_at >= p_from and p2.created_at < p_to
         and (p_branch is null or exists (select 1 from public.journal_entries pe where pe.id = p2.entry_id and pe.branch_id = p_branch))
         and not exists (select 1 from public.journal_entries r where r.reverses_id = p2.entry_id)
       group by p2.method) m), '{}'::jsonb),
    'delivered', (select count(*) from public.devices d where d.shop_id = s and d.delivered_at >= p_from and d.delivered_at < p_to and (p_branch is null or d.branch_id = p_branch)),
    'closings', coalesce((select jsonb_agg(jsonb_build_object('cashbox', dc.cashbox_id, 'expected', dc.expected, 'counted', dc.counted, 'diff', dc.diff, 'at', dc.created_at,
       'by', (select full_name from public.profiles where id = dc.closed_by)) order by dc.created_at)
       from public.drawer_closings dc where dc.shop_id = s and dc.created_at >= p_from and dc.created_at < p_to
         and (p_branch is null or exists (select 1 from public.accounts ca where ca.id = dc.cashbox_id and ca.branch_id = p_branch))), '[]'::jsonb)
  ) into res
  from parts p, per, tot, unb, eq, eq_all;
  return res;
end $$;

-- backup_snapshot: (src: 0061_attendance.sql) + cheques
create or replace function public.backup_snapshot(p_shop uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  res jsonb := jsonb_build_object('format', 'warsha-backup', 'version', 1, 'generated_at', now(), 'shop_id', p_shop);
  t text;
  rows jsonb;
begin
  foreach t in array array['shops', 'branches', 'staff_branches', 'attendance', 'shop_branding', 'profiles', 'customers', 'devices', 'device_costs', 'status_log', 'device_notes', 'device_photos', 'device_checks',
                           'quote_decisions', 'message_templates', 'message_log', 'accounts', 'journal_entries', 'journal_lines', 'sale_lines', 'cheques', 'payments', 'drawer_closings',
                           'suppliers', 'categories', 'items', 'stock_moves', 'uncosted_sales', 'payment_plans', 'plan_installments', 'branch_goals', 'printers', 'print_templates', 'check_templates', 'used_devices', 'commission_rules', 'purchases', 'labor_rates', 'specialties', 'staff_specialties', 'routes', 'repair_steps',
                           'repair_videos', 'device_ratings', 'issue_presets', 'partners', 'profit_distributions', 'party_links', 'shop_lists', 'audit_log'] loop
    execute format('select coalesce(jsonb_agg(to_jsonb(x)), ''[]''::jsonb) from public.%I x where x.shop_id = $1', t) into rows using p_shop;
    res := res || jsonb_build_object(t, rows);
  end loop;
  select coalesce(jsonb_agg(jsonb_build_object('device_id', device_id, 'kind', kind, 'erased_at', erased_at)), '[]'::jsonb)
    into rows from public.device_passcodes where shop_id = p_shop;
  return res || jsonb_build_object('device_passcodes', rows);
end $$;

-- restore_backup: (src: 0061_attendance.sql) + cheques (بعد القيود)
create or replace function public.restore_backup(p_data jsonb) returns jsonb
-- extensions: فيها gen_random_bytes على Supabase
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare
  s uuid := public.current_shop_id();
  me uuid := auth.uid();
  old_shop uuid;
  old_owner uuid;
  sh jsonb;
  t text;
  r jsonb;
  rows jsonb;
  n int;
  bad int;
  counts jsonb := '{}'::jsonb;
  -- بالترتيب ده عشان كل صف يلاقي اللي بيشاور عليه
  tabs text[] := array['branches', 'profiles', 'staff_branches', 'attendance', 'shop_branding', 'accounts', 'customers', 'suppliers', 'party_links', 'partners', 'specialties', 'staff_specialties', 'routes', 'labor_rates',
                       'issue_presets', 'commission_rules', 'shop_lists', 'message_templates', 'categories', 'items', 'devices', 'device_costs', 'status_log', 'device_notes', 'device_checks',
                       'quote_decisions', 'repair_steps', 'repair_videos', 'device_ratings', 'journal_entries', 'journal_lines', 'sale_lines', 'cheques', 'profit_distributions', 'payments',
                       'purchases', 'stock_moves', 'uncosted_sales', 'used_devices', 'payment_plans', 'plan_installments', 'branch_goals', 'printers', 'print_templates', 'check_templates', 'drawer_closings', 'message_log', 'audit_log'];
  -- الجداول دي ليها نسخة اتعملت مع التسجيل: بتتطابق بالكود (أو المفتاح) وبتاخد قيم النسخة
  keyed text[] := array['branches', 'accounts', 'routes', 'specialties', 'message_templates', 'labor_rates', 'shop_branding'];
begin
  perform public.ledger_require(array['owner']::public.app_role[]);
  if s is null or me is null then raise exception 'E_FORBIDDEN'; end if;
  if p_data is null or p_data->>'format' is distinct from 'warsha-backup' or coalesce((p_data->>'version')::int, 0) <> 1 then
    raise exception 'E_BACKUP_FORMAT';
  end if;
  old_shop := (p_data->>'shop_id')::uuid;
  if old_shop is null or old_shop = s then raise exception 'E_BACKUP_FORMAT'; end if;

  -- محل جديد فاضي بس
  if exists (select 1 from public.devices where shop_id = s) or exists (select 1 from public.customers where shop_id = s)
     or exists (select 1 from public.journal_entries where shop_id = s) or exists (select 1 from public.items where shop_id = s)
     or exists (select 1 from public.suppliers where shop_id = s) or exists (select 1 from public.payments where shop_id = s)
     or exists (select 1 from public.purchases where shop_id = s) or exists (select 1 from public.drawer_closings where shop_id = s)
     or exists (select 1 from public.stock_moves where shop_id = s)
     or exists (select 1 from public.profiles where shop_id = s and id <> me) then
    raise exception 'E_RESTORE_NOT_EMPTY';
  end if;

  perform set_config('warsha.restore', 'on', true);
  drop table if exists pg_temp._rmap;
  create temp table _rmap(old uuid primary key, new uuid not null) on commit drop;
  insert into _rmap values (old_shop, s);

  -- 1) بيانات المحل نفسه (من غير الخطة والإيقاف واللوجو اللي في Storage)
  sh := p_data->'shops'->0;
  if sh is not null then
    update public.shops set
      name = coalesce(sh->>'name', name), phone = sh->>'phone', address = sh->>'address',
      receipt_terms = coalesce(sh->>'receipt_terms', receipt_terms), warranty_days = coalesce((sh->>'warranty_days')::int, warranty_days),
      country = coalesce(sh->>'country', country), currency = coalesce(sh->>'currency', currency),
      payment_methods = coalesce(array(select jsonb_array_elements_text(sh->'payment_methods')), payment_methods),
      theme = coalesce(sh->>'theme', theme), locale = coalesce(sh->>'locale', locale),
      default_margin_pct = coalesce((sh->>'default_margin_pct')::int, default_margin_pct),
      extras = coalesce(sh->'extras', extras), max_discount_pct = coalesce((sh->>'max_discount_pct')::int, max_discount_pct)
    where id = s;
  end if;

  -- 2) الـ ids الجديدة
  -- صاحب المحل في النسخة = اللي بيسترجع دلوقتي
  select (x->>'id')::uuid into old_owner from jsonb_array_elements(coalesce(p_data->'profiles', '[]')) x
   where x->>'role' = 'owner' order by x->>'created_at' limit 1;
  if old_owner is not null then insert into _rmap values (old_owner, me) on conflict do nothing; end if;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.accounts a where a.shop_id = s and a.code = x->>'code' and x->>'code' is not null), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'accounts', '[]')) x on conflict do nothing;
  -- الفرع الرئيسي في النسخة = الفرع الرئيسي للمحل الجديد
  insert into _rmap select (x->>'id')::uuid, public.main_branch(s)
    from jsonb_array_elements(coalesce(p_data->'branches', '[]')) x where (x->>'is_main')::boolean and x->>'deleted_at' is null on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.routes a where a.shop_id = s and a.code = x->>'code' and x->>'code' is not null), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'routes', '[]')) x on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.specialties a where a.shop_id = s and a.code = x->>'code' and x->>'code' is not null), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'specialties', '[]')) x on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.message_templates a where a.shop_id = s and a.key = x->>'key'), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'message_templates', '[]')) x on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.labor_rates a where a.shop_id = s and a.deleted_at is null and lower(trim(a.issue)) = lower(trim(x->>'issue')) and x->>'deleted_at' is null), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'labor_rates', '[]')) x on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.shop_branding a where a.shop_id = s), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'shop_branding', '[]')) x on conflict do nothing;
  foreach t in array tabs loop
    insert into _rmap select (x->>'id')::uuid, gen_random_uuid() from jsonb_array_elements(coalesce(p_data->t, '[]')) x where x ? 'id' on conflict do nothing;
  end loop;

  -- 3) الصفوف نفسها بالترتيب
  foreach t in array tabs loop
    rows := '[]'::jsonb;
    for r in select public.restore_remap(x) from jsonb_array_elements(coalesce(p_data->t, '[]')) x loop
      if t = 'profiles' then
        -- صاحب المحل موجود أصلًا. الباقيين موظفين سابقين (من غير حساب دخول)
        continue when (r->>'id')::uuid = me;
        r := r || jsonb_build_object('deleted_at', coalesce(r->>'deleted_at', now()::text));
      elsif t = 'devices' then
        -- كود التتبع (الـ QR) بيفضل زي ما هو، إلا لو مستخدم في المشروع ده (المحل الأصلي لسه هنا)
        if exists (select 1 from public.devices d where d.tracking_token = r->>'tracking_token') then
          r := r || jsonb_build_object('tracking_token', encode(gen_random_bytes(12), 'hex'));
        end if;
      elsif t = 'journal_entries' then
        if r->>'idem_key' is not null and exists (select 1 from public.journal_entries j where j.idem_key = (r->>'idem_key')::uuid) then
          r := r || jsonb_build_object('idem_key', gen_random_uuid());
        end if;
      elsif t = 'accounts' and r->>'kind' = 'cash' and r->>'branch_id' is null then
        -- نسخة من قبل الفروع: الخزن كلها في الفرع الرئيسي
        r := r || jsonb_build_object('branch_id', public.main_branch(s));
      elsif t = 'used_devices' then
        -- رقم بطاقة البائع (في Vault) وصورتها (في Storage) مش جوه النسخة
        r := r || jsonb_build_object('seller_nid_secret', null, 'seller_photo', null);
      elsif t = 'shop_branding' then
        -- اللوجو الملون والحراري جوه الصف نفسه. الملف الأصلي في Storage مش جوه النسخة
        r := r || jsonb_build_object('logo_path', null);
      end if;
      if t = any (keyed) and exists (select 1 from _rmap m where m.new = (r->>'id')::uuid and m.old <> m.new)
         and (t <> 'shop_branding' or exists (select 1 from public.shop_branding b where b.id = (r->>'id')::uuid)) then
        -- موجود من التسجيل: بياخد قيم النسخة
        execute format('select count(*) from public.%I where id = $1', t) into n using (r->>'id')::uuid;
        if n > 0 then
          execute format('update public.%1$I x set (%2$s) = (select %2$s from jsonb_populate_record(null::public.%1$I, $1)) where x.id = $2', t,
            (select string_agg(quote_ident(c.column_name), ', ' order by c.ordinal_position) from information_schema.columns c
              where c.table_schema = 'public' and c.table_name = t and c.column_name not in ('id', 'shop_id')))
            using r, (r->>'id')::uuid;
          continue;
        end if;
      end if;
      rows := rows || jsonb_build_array(r);
    end loop;
    if jsonb_array_length(rows) > 0 then
      -- overriding system value: أرقام القيود (entry_no) بترجع زي ما هي
      execute format('insert into public.%1$I overriding system value select * from jsonb_populate_recordset(null::public.%1$I, $1)', t) using rows;
    end if;
    counts := counts || jsonb_build_object(t, jsonb_array_length(coalesce(p_data->t, '[]')));
  end loop;

  -- 4) عدّاد أرقام الطلبات: من آخر رقم راجع في كل سنة
  -- (لكل فرع: الرقم ممكن يبقى قبله بادئة الفرع B2-2026-0001)
  insert into public.order_counters(shop_id, branch_id, year, last_value)
  select s, branch_id, (regexp_match(order_no, '(\d{4})-(\d+)$'))[1]::int, max((regexp_match(order_no, '(\d{4})-(\d+)$'))[2]::int)
    from public.devices where shop_id = s and order_no ~ '\d{4}-\d+$' group by 2, 3
  on conflict (shop_id, branch_id, year) do update set last_value = greatest(public.order_counters.last_value, excluded.last_value);

  -- 5) التأكد: كل قيد متوازن، ورصيد كل حساب = رصيده في النسخة بالظبط
  select count(*) into bad from (
    select entry_id from public.journal_lines where shop_id = s group by entry_id having sum(debit) <> sum(credit)) x;
  if bad > 0 then raise exception 'E_RESTORE_UNBALANCED'; end if;
  select count(*) into bad from (
    select m.new acc, sum((l->>'debit')::bigint - (l->>'credit')::bigint) b
      from jsonb_array_elements(coalesce(p_data->'journal_lines', '[]')) l join _rmap m on m.old = (l->>'account_id')::uuid group by m.new
  ) x full join (select account_id, sum(debit - credit) b from public.journal_lines where shop_id = s group by account_id) y on y.account_id = x.acc
  where coalesce(x.b, 0) <> coalesce(y.b, 0);
  if bad > 0 then raise exception 'E_RESTORE_MISMATCH'; end if;
  -- وعدد الصفوف في كل جدول (الحسابات والقوالب اللي اتعملت مع التسجيل ممكن تزيد عن النسخة، مش تقل)
  foreach t in array tabs loop
    execute format('select count(*) from public.%I where shop_id = $1', t) into n using s;
    if n < jsonb_array_length(coalesce(p_data->t, '[]')) - (case when t = 'profiles' and old_owner is not null then 1 else 0 end) then
      raise exception 'E_RESTORE_MISMATCH';
    end if;
  end loop;

  perform set_config('warsha.restore', 'off', true);
  insert into public.audit_log(shop_id, actor_id, action, entity, entity_id, after)
  values (s, me, 'backup_restore', 'shops', s, jsonb_build_object('from_shop', old_shop, 'generated_at', p_data->>'generated_at', 'counts', counts));
  return jsonb_build_object('restored', true, 'counts', counts);
end $$;
$m0063$;
  insert into public.app_migrations(version, how) values ('0063_cheques.sql', 'applied');
  raise notice 'applied %', '0063_cheques.sql';
end $run$;
commit;

-- ============================== 0064_day_report.sql ==============================
begin;
do $run$ begin
  if exists (select 1 from public.app_migrations where version = '0064_day_report.sql') then return; end if;
  execute $m0064$
-- ============================================================
-- 0064: التقرير اليومي (بند 1 من qa-37)
-- - "حسب طريقة الدفع" كان بيجمع من جدول payments بس (دفعات الصيانة)، فالبيع الكاش ما كانش داخل.
-- - day_cash_report: تحصيلات العملاء كلها (صيانة + بيع) حسب طريقة الدفع، والمرتجع لوحده،
--   وتسوية كل خزنة: افتتاحي + وارد − صادر = ختامي، وقيود كل خزنة عشان كل رقم يفتح قيده.
-- - القيد اللي اتلغى (أو قيد الإلغاء نفسه) ما بيدخلش في التحصيل، بس بيفضل في حركة الخزنة عشان التسوية تطابق.
-- - قراءة بس: نفس صلاحية "المالية ← يشوف"، والموظف فروعه بس.
-- ============================================================

create or replace function public.day_cash_report(p_from timestamptz, p_to timestamptz, p_branch uuid default null) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  s uuid := public.current_shop_id();
  res jsonb;
begin
  perform public.grant_require('finance', 'view');
  if not public.all_my_branches() and (p_branch is null or not public.can_branch(p_branch)) then
    p_branch := public.op_branch();
    -- موظف من غير فرع: ما يشوفش خزن المحل كله
    if p_branch is null then raise exception 'E_FORBIDDEN'; end if;
  end if;
  with boxes as (
    select a.id, a.code, a.name, a.method, a.branch_id from public.accounts a
    where a.shop_id = s and a.kind = 'cash' and (p_branch is null or a.branch_id = p_branch)
  ),
  mv as (
    select l.account_id, e.id as entry_id, e.entry_no, e.source_type, e.memo, e.occurred_at, l.debit, l.credit,
           -- الإلغاء اللي حصل بعد الفترة ما يغيّرش تقرير يوم قديم
           (e.reverses_id is not null or exists (select 1 from public.journal_entries r where r.reverses_id = e.id and r.occurred_at < p_to)) as cancelled
    from public.journal_lines l join public.journal_entries e on e.id = l.entry_id
    where l.shop_id = s and l.account_id in (select id from boxes) and e.occurred_at >= p_from and e.occurred_at < p_to
  ),
  -- طريقة الدفع = طريقة الخزنة (record_payment بيسجل p_method، بس الواجهة ما بتبعتهوش، فهي نفس طريقة الخزنة)
  -- شيك العميل: بيتحسب تحصيل يوم ما يتصرف (cheque_clear لخزنة = فلوس دخلت). شيك المورد بيخرج من الخزنة (دائن) فما بيدخلش
  col as (
    select b.method,
           coalesce(sum(m.debit) filter (where m.source_type = 'payment'), 0)::bigint as payments,
           coalesce(sum(m.debit) filter (where m.source_type = 'sale'), 0)::bigint as sales,
           coalesce(sum(m.debit) filter (where m.source_type = 'cheque_clear'), 0)::bigint as cheques,
           coalesce(sum(m.credit) filter (where m.source_type = 'sale_return'), 0)::bigint as refunds
    from mv m join boxes b on b.id = m.account_id
    where not m.cancelled and m.source_type in ('payment', 'sale', 'cheque_clear', 'sale_return')
    group by b.method
  )
  select jsonb_build_object(
    'branch', p_branch,
    'collections', coalesce((select jsonb_agg(jsonb_build_object('method', method, 'payments', payments, 'sales', sales, 'cheques', cheques, 'refunds', refunds,
        'total', payments + sales + cheques - refunds) order by method) from col where payments + sales + cheques + refunds > 0), '[]'::jsonb),
    'cashboxes', coalesce((select jsonb_agg(x order by x ->> 'code' nulls last, x ->> 'name') from (
      select jsonb_build_object('id', b.id, 'code', b.code, 'name', b.name, 'method', b.method, 'branch_id', b.branch_id,
        'opening', o.opening, 'in', coalesce(t.d, 0), 'out', coalesce(t.c, 0), 'closing', o.opening + coalesce(t.d, 0) - coalesce(t.c, 0),
        'entries', coalesce((select jsonb_agg(jsonb_build_object('entry_id', m.entry_id, 'entry_no', m.entry_no, 'source_type', m.source_type,
            'memo', m.memo, 'at', m.occurred_at, 'in', m.debit, 'out', m.credit, 'cancelled', m.cancelled) order by m.occurred_at, m.entry_no)
          from mv m where m.account_id = b.id), '[]'::jsonb)) as x
      from boxes b
      cross join lateral (select coalesce(sum(l.debit - l.credit), 0)::bigint as opening from public.journal_lines l join public.journal_entries e on e.id = l.entry_id
                          where l.account_id = b.id and e.occurred_at < p_from) o
      left join lateral (select sum(m.debit)::bigint as d, sum(m.credit)::bigint as c from mv m where m.account_id = b.id) t on true
      -- الخزنة اللي ما اتحركتش ورصيدها صفر ما بتظهرش
      where o.opening <> 0 or t.d is not null) y), '[]'::jsonb)
  ) into res;
  return res;
end $$;
revoke all on function public.day_cash_report(timestamptz, timestamptz, uuid) from public;
grant execute on function public.day_cash_report(timestamptz, timestamptz, uuid) to authenticated;
$m0064$;
  insert into public.app_migrations(version, how) values ('0064_day_report.sql', 'applied');
  raise notice 'applied %', '0064_day_report.sql';
end $run$;
commit;

-- ============================== 0065_cheque_pending.sql ==============================
begin;
do $run$ begin
  if exists (select 1 from public.app_migrations where version = '0065_cheque_pending.sql') then return; end if;
  execute $m0065$
-- ============================================================
-- 0065: قرار صاحب المشروع (2026-11-23): شيك العميل "تحت التحصيل" ما بيقللش دين العميل غير لما يتصرف.
-- - الاستلام: بيتسجل الشيك بس، من غير قيد (اللي على العميل زي ما هو).
-- - الصرف: قيد واحد: الخزنة (مدين) / العملاء (دائن)، وصف في payments (لو الشيك على جهاز بيتحسب مدفوع للجهاز).
-- - الرفض: الحالة بس، من غير قيد (الدين أصلًا ما اتغيرش).
-- - التسليم قبل الصرف: الشيك مش دفعة، فـ"منع التسليم قبل السداد" (E_UNPAID) بيوقفه، وصاحب المحل بس يقدر "يسلّم بالآجل" (deliver_on_credit).
-- - الشيكات القديمة (قبل الملف ده) ليها قيد استلام: بتكمّل بنفس طريقتها القديمة لحد ما تتصرف أو تترفض، عشان الدفتر يفضل متوازن.
-- - شيكات الموردين ما اتغيرتش.
-- ============================================================

alter table public.cheques alter column entry_id drop not null;
alter table public.cheques add column if not exists device_id uuid references public.devices(id);
-- رقم عملية الرفض للشيك الجديد (مالوش قيد): نفس الطلب لو اتبعت تاني (من غير نت) ما يطلعش خطأ
alter table public.cheques add column if not exists settle_op uuid;
-- فريد جوه المحل بس: الاسترجاع بينسخ القيمة لمحل جديد (زي idem_key)
create unique index if not exists cheques_settle_op on public.cheques(shop_id, settle_op) where settle_op is not null;
-- الرفض الجديد ما لوش قيد: الحالة مربوطة بتاريخ التسوية مش بالقيد
do $c$
declare n text;
begin
  -- القيد القديم ((status = 'pending') = (settle_entry_id is null)) من غير اسم صريح: بندوّر عليه بتعريفه
  for n in select conname from pg_constraint where conrelid = 'public.cheques'::regclass and contype = 'c'
             and pg_get_constraintdef(oid) like '%settle_entry_id IS NULL%' loop
    execute format('alter table public.cheques drop constraint %I', n);
  end loop;
end $c$;
alter table public.cheques drop constraint if exists cheques_settled_check;
alter table public.cheques add constraint cheques_settled_check check ((status = 'pending') = (settled_at is null));
-- الشيك الجديد (من غير قيد استلام) لعميل بس
alter table public.cheques drop constraint if exists cheques_entry_check;
alter table public.cheques add constraint cheques_entry_check check (entry_id is not null or direction = 'in');

-- ---------- استلام شيك من عميل (src: 0063_cheques.sql) + من غير قيد، وجهاز اختياري ----------
drop function if exists public.cheque_receive(uuid, uuid, text, text, date, bigint, text);
create or replace function public.cheque_receive(p_id uuid, p_customer uuid, p_no text, p_bank text, p_due date, p_amount bigint, p_note text default null, p_device uuid default null)
returns uuid
language plpgsql security definer set search_path = public as $$
declare s uuid := public.current_shop_id();
begin
  perform public.cheque_require();
  if exists (select 1 from public.cheques where id = p_id) then return p_id; end if;
  perform public.ledger_amount(p_amount);
  if coalesce(trim(p_no), '') = '' or p_due is null then raise exception 'E_BAD_INPUT'; end if;
  if not exists (select 1 from public.customers where id = p_customer and shop_id = s and deleted_at is null) then raise exception 'E_NOT_FOUND'; end if;
  if p_device is not null and not exists (select 1 from public.devices where id = p_device and shop_id = s and customer_id = p_customer and deleted_at is null and public.can_branch(branch_id)) then
    raise exception 'E_NOT_FOUND';
  end if;
  insert into public.cheques(id, shop_id, branch_id, direction, party_type, party_id, cheque_no, bank, due_date, amount, entry_id, device_id, note, created_by)
  values (p_id, s, public.op_branch(), 'in', 'customer', p_customer, trim(p_no), nullif(trim(p_bank), ''), p_due, p_amount, null, p_device, nullif(trim(p_note), ''), auth.uid());
  return p_id;
end $$;
revoke execute on function public.cheque_receive(uuid, uuid, text, text, date, bigint, text, uuid) from public, anon;
grant execute on function public.cheque_receive(uuid, uuid, text, text, date, bigint, text, uuid) to authenticated;

-- ---------- الصرف (src: 0063_cheques.sql) + شيك العميل الجديد بيقلل الدين وقت الصرف ----------
create or replace function public.cheque_clear(p_op uuid, p_cheque uuid, p_cashbox uuid)
returns uuid
language plpgsql security definer set search_path = public as $$
declare c public.cheques; cb public.accounts; e uuid;
begin
  perform public.cheque_require();
  e := public.ledger_idem(p_op);
  if e is not null then return e; end if;
  c := public.cheque_lock(p_cheque);
  if c.status <> 'pending' then raise exception 'E_CHEQUE_DONE'; end if;
  cb := public.ledger_cashbox(p_cashbox);
  if c.direction = 'in' and c.entry_id is null then
    -- جديد: دلوقتي بس الفلوس وصلت، فالدين بيقل
    e := public.ledger_post('cheque_clear', c.id, c.cheque_no, jsonb_build_array(
      public.ledger_line(cb.id, c.amount, 0),
      public.ledger_line(public.ledger_acc('ar'), 0, c.amount, 'customer', c.party_id)), c.device_id, p_op);
    insert into public.payments(id, shop_id, customer_id, device_id, cashbox_id, method, amount, entry_id, created_by)
    values (gen_random_uuid(), c.shop_id, c.party_id, c.device_id, cb.id, cb.method, c.amount, e, auth.uid());
  elsif c.direction = 'in' then
    -- قديم: الدين اتخصم وقت الاستلام
    e := public.ledger_post('cheque_clear', c.id, c.cheque_no, jsonb_build_array(
      public.ledger_line(cb.id, c.amount, 0),
      public.ledger_line(public.ledger_acc('cheques_in'), 0, c.amount, 'customer', c.party_id)), null, p_op);
  else
    e := public.ledger_post('cheque_clear', c.id, c.cheque_no, jsonb_build_array(
      public.ledger_line(public.ledger_acc('cheques_out'), c.amount, 0, 'supplier', c.party_id),
      public.ledger_line(cb.id, 0, c.amount)), null, p_op);
  end if;
  update public.cheques set status = 'cleared', settle_entry_id = e, settled_at = now() where id = c.id;
  return e;
end $$;

-- ---------- الرفض (src: 0063_cheques.sql) + شيك العميل الجديد من غير قيد ----------
create or replace function public.cheque_bounce(p_op uuid, p_cheque uuid, p_reason text)
returns uuid
language plpgsql security definer set search_path = public as $$
declare c public.cheques; e uuid;
begin
  perform public.cheque_require();
  e := public.ledger_idem(p_op);
  if e is not null then return e; end if;
  if exists (select 1 from public.cheques where settle_op = p_op and shop_id = public.current_shop_id()) then return null; end if;
  if coalesce(trim(p_reason), '') = '' then raise exception 'E_REASON_REQUIRED'; end if;
  c := public.cheque_lock(p_cheque);
  -- نفس الطلب اتبعت مرتين في نفس اللحظة: التاني بيستنى القفل، وبعدها يرجع من غير خطأ
  if c.settle_op = p_op then return null; end if;
  if c.status <> 'pending' then raise exception 'E_CHEQUE_DONE'; end if;
  if c.direction = 'in' and c.entry_id is null then
    -- جديد: الدين ما اتغيرش أصلًا، فمفيش قيد. السبب في الملاحظة وفي سجل النشاط (zz_audit)
    update public.cheques set status = 'bounced', settled_at = now(), settle_op = p_op,
      note = left(concat_ws(' · ', note, trim(p_reason)), 300) where id = c.id;
    return null;
  elsif c.direction = 'in' then
    e := public.ledger_post('cheque_bounce', c.id, left(trim(p_reason), 300), jsonb_build_array(
      public.ledger_line(public.ledger_acc('ar'), c.amount, 0, 'customer', c.party_id),
      public.ledger_line(public.ledger_acc('cheques_in'), 0, c.amount, 'customer', c.party_id)), null, p_op);
  else
    e := public.ledger_post('cheque_bounce', c.id, left(trim(p_reason), 300), jsonb_build_array(
      public.ledger_line(public.ledger_acc('cheques_out'), c.amount, 0, 'supplier', c.party_id),
      public.ledger_line(public.ledger_acc('ap'), 0, c.amount, 'supplier', c.party_id)), null, p_op);
  end if;
  update public.cheques set status = 'bounced', settle_entry_id = e, settled_at = now() where id = c.id;
  return e;
end $$;
$m0065$;
  insert into public.app_migrations(version, how) values ('0065_cheque_pending.sql', 'applied');
  raise notice 'applied %', '0065_cheque_pending.sql';
end $run$;
commit;

-- ============================== 0066_commission_net.sql ==============================
begin;
do $run$ begin
  if exists (select 1 from public.app_migrations where version = '0066_commission_net.sql') then return; end if;
  execute $m0066$
-- ============================================================
-- 0066: قرار صاحب المشروع (2026-11-23): عمولة الفني على السعر قبل الضريبة.
-- - المصنعية = (التكلفة النهائية − الضريبة اللي جواها) − تكلفة القطع.
-- - الضريبة بنفس طريقة قيد التسليم بالظبط (vat_of بنسبة المحل وقت التسليم)، فالعمولة والقيد دايمًا متطابقين.
-- - المحل اللي الضريبة عنده مقفولة: مفيش أي فرق (vat_of = 0).
-- - العمولات القديمة اللي اتسجلت قبل الملف ده ما بتتغيرش (القيود ما بتتعدلش).
-- ============================================================

-- commission_preview: (src: 0056_branch_features.sql) + المصنعية من غير الضريبة
create or replace function public.commission_preview(p_device uuid) returns table(technician_id uuid, amount bigint)
language plpgsql stable security definer set search_path = public as $$
declare d public.devices; techs uuid[]; n int; base bigint; fc bigint; r public.commission_rules; t uuid; share bigint;
begin
  select * into d from public.devices where id = p_device;
  if d.id is null then return; end if;
  techs := public.device_technicians(p_device);
  n := coalesce(array_length(techs, 1), 0);
  if n = 0 then return; end if;
  fc := coalesce((select c.final_cost from public.device_costs c where c.device_id = p_device and c.deleted_at is null), 0);
  base := greatest(fc - public.vat_of(fc, public.vat_bp(d.shop_id)) - public.device_parts_cost(p_device), 0);
  foreach t in array techs loop
    r := public.commission_rule_for(d.shop_id, t, d.route_id, d.branch_id);
    continue when r.id is null;
    share := case when r.mode = 'fixed' then r.value else (base / n) * r.value / 10000 end;
    if share > 0 then technician_id := t; amount := share; return next; end if;
  end loop;
end $$;
revoke execute on function public.commission_preview(uuid) from public, anon, authenticated;
$m0066$;
  insert into public.app_migrations(version, how) values ('0066_commission_net.sql', 'applied');
  raise notice 'applied %', '0066_commission_net.sql';
end $run$;
commit;

-- ============================== 0067_idem_lock.sql ==============================
begin;
do $run$ begin
  if exists (select 1 from public.app_migrations where version = '0067_idem_lock.sql') then return; end if;
  execute $m0067$
-- ============================================================
-- 0067: بند 2 من qa-37: ضغطتين متزامنتين على الحفظ = عملية واحدة من غير خطأ.
-- - كل دوال الفلوس بتبدأ بـ ledger_idem(رقم العملية): لو اتسجلت قبل كده بترجع نفس القيد.
-- - المشكلة: طلبين في نفس اللحظة الاتنين بيعدّوا الفحص، والتاني بيقع بـ unique violation على idem_key
--   (البيانات سليمة، بس المستخدم بيشوف خطأ والطابور بتاع "من غير نت" بيعيد).
-- - الحل: قفل قصير على رقم العملية لحد آخر الـ transaction. الطلب التاني بيستنى، وبعدين بيلاقي القيد ويرجّعه.
-- ============================================================

-- ledger_idem: (src: 0008_ledger.sql) + قفل على رقم العملية (volatile بدل stable عشان القفل)
create or replace function public.ledger_idem(p uuid) returns uuid
language plpgsql volatile security definer set search_path = public as $$
declare r uuid;
begin
  if p is null then return null; end if;
  perform pg_advisory_xact_lock(hashtextextended(p::text, 0));
  select id into r from public.journal_entries where idem_key = p and shop_id = public.current_shop_id();
  return r;
end $$;
revoke execute on function public.ledger_idem(uuid) from public, anon, authenticated;
$m0067$;
  insert into public.app_migrations(version, how) values ('0067_idem_lock.sql', 'applied');
  raise notice 'applied %', '0067_idem_lock.sql';
end $run$;
commit;

-- ============================== 0068_stock_adjust.sql ==============================
begin;
do $run$ begin
  if exists (select 1 from public.app_migrations where version = '0068_stock_adjust.sql') then return; end if;
  execute $m0068$
-- ============================================================
-- 0068: بند 14 من qa-37: نقص المخزون في البيع = تسوية مخزون بصلاحية لوحدها وسبب وسجل.
-- - قبل كده: شاشة البيع لما الكمية مش كفاية كانت بتعرض "سجّل الكمية والتكلفة" (stock_in) لأي حد معاه "المخزون ← يضيف"
--   (الاستقبال)، من غير سبب، والقيد على رأس المال. يعني زيادة مخزون خفية من شاشة البيع.
-- - دلوقتي: stock_in = "تسوية مخزون": صاحب المحل أو اللي معاه "المخزون ← المبالغ" بس، والسبب إجباري،
--   وبيتسجل في سجل النشاط (مين، وإمتى، والكمية، والتكلفة، والسبب). البيع نفسه عمره ما بيزوّد المخزون (E_STOCK زي ما هو).
-- - الرصيد الأول لصنف جديد (create_item) فاضل زي ما هو: بصلاحيات إضافة الصنف والمخزون (من غير "المبالغ")، عن طريق _stock_in.
-- ============================================================

-- الشغل نفسه من غير صلاحيات (داخلي بس، محدش يناديه من بره)
create or replace function public._stock_in(p_id uuid, p_item uuid, p_qty integer, p_unit_cost bigint, p_memo text) returns uuid
language plpgsql security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); e uuid; total bigint;
begin
  e := public.ledger_idem(p_id);
  if e is not null then return e; end if;
  if p_qty is null or p_qty <= 0 or p_qty > 100000 or p_unit_cost is null or p_unit_cost < 0 then raise exception 'E_BAD_AMOUNT'; end if;
  if not exists (select 1 from public.items where id = p_item and shop_id = s and deleted_at is null) then raise exception 'E_NOT_FOUND'; end if;
  total := p_qty::bigint * p_unit_cost;
  if total <= 0 then raise exception 'E_BAD_AMOUNT'; end if;
  perform public.ledger_amount(total);
  e := public.ledger_post('opening', p_item, left(coalesce(nullif(trim(p_memo), ''), 'stock'), 300),
    jsonb_build_array(public.ledger_line(public.ledger_acc('inventory'), total, 0), public.ledger_line(public.ledger_acc('capital'), 0, total)), null, p_id);
  insert into public.stock_moves(shop_id, item_id, entry_id, qty, value) values (s, p_item, e, p_qty, total);
  return e;
end $$;
revoke execute on function public._stock_in(uuid, uuid, integer, bigint, text) from public, anon, authenticated;

-- stock_in: (src: 0037_item_details.sql) = تسوية مخزون: صلاحية "المخزون ← المبالغ" والسبب إجباري وسجل
create or replace function public.stock_in(p_id uuid, p_item uuid, p_qty integer, p_unit_cost bigint, p_note text default null) returns uuid
language plpgsql security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); e uuid; reason text := left(nullif(trim(p_note), ''), 300);
begin
  perform public.grant_require('inventory', 'amounts');
  e := public.ledger_idem(p_id);
  if e is not null then return e; end if;
  if reason is null then raise exception 'E_REASON_REQUIRED'; end if;
  e := public._stock_in(p_id, p_item, p_qty, p_unit_cost, reason);
  insert into public.audit_log(shop_id, actor_id, action, entity, entity_id, after)
  values (s, auth.uid(), 'stock_adjust', 'items', p_item, jsonb_build_object('qty', p_qty, 'unit_cost', p_unit_cost, 'value', p_qty::bigint * p_unit_cost, 'reason', reason, 'entry', e));
  return e;
end $$;
revoke execute on function public.stock_in(uuid, uuid, integer, bigint, text) from public, anon;
grant execute on function public.stock_in(uuid, uuid, integer, bigint, text) to authenticated;

-- create_item: (src: 0057_categories.sql) + الرصيد الأول بـ _stock_in بنفس صلاحيات stock_in القديمة (المخزون ← يضيف)
create or replace function public.create_item(
  p_id uuid, p_kind text, p_name text, p_item_type text default null, p_brand text default null, p_model text default null,
  p_quality text default null, p_color text default null, p_sale_price integer default null, p_qty integer default null, p_unit_cost bigint default null,
  p_stock_id uuid default null
) returns uuid
language plpgsql security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); nm text := trim(coalesce(p_name, ''));
begin
  perform public.ledger_require(array['owner', 'reception']::public.app_role[]);
  perform public.perm_require('item_create', 'add');
  if exists (select 1 from public.items where id = p_id and shop_id = s) then return p_id; end if;
  if p_kind not in ('part', 'accessory', 'service') or nm = '' or length(nm) > 160 then raise exception 'E_BAD_INPUT'; end if;
  if p_sale_price is not null and (p_sale_price < 0 or p_sale_price > 2000000000) then raise exception 'E_BAD_AMOUNT'; end if;
  insert into public.items(id, shop_id, kind, name, item_type, brand, model, quality, color, sale_price)
  values (p_id, s, p_kind, nm, nullif(trim(p_item_type), ''), nullif(trim(p_brand), ''), nullif(trim(p_model), ''), nullif(trim(p_quality), ''), nullif(trim(p_color), ''), p_sale_price);
  if coalesce(p_qty, 0) > 0 then
    if p_unit_cost is null or p_unit_cost <= 0 then raise exception 'E_BAD_AMOUNT'; end if;
    perform public.perm_require('inventory', 'add');
    perform public._stock_in(coalesce(p_stock_id, gen_random_uuid()), p_id, p_qty, p_unit_cost, 'stock');
  end if;
  return p_id;
end $$;
$m0068$;
  insert into public.app_migrations(version, how) values ('0068_stock_adjust.sql', 'applied');
  raise notice 'applied %', '0068_stock_adjust.sql';
end $run$;
commit;

-- ============================== 0069_sale_errors.sql ==============================
begin;
do $run$ begin
  if exists (select 1 from public.app_migrations where version = '0069_sale_errors.sql') then return; end if;
  execute $m0069$
-- ============================================================
-- 0069: بند 13 من qa-37: أخطاء البيع برسالة الحقل، وسياسة البيع المجاني.
-- - الكمية الغلط E_BAD_QTY، والسعر الغلط E_BAD_PRICE (بدل رسالة عامة).
-- - صنف مجاني (سعر صفر): صاحب المحل أو اللي معاه "المخزون ← المبالغ"، والسبب (reason في السطر) إجباري.
--   السبب في سجل النشاط بس: ملاحظة البيع بتتطبع على فاتورة العميل، فما بيتحطش فيها.
-- - فاتورة كلها مجانية مرفوضة زي الأول (E_BAD_AMOUNT).
-- ============================================================

-- record_sale: (src: 0062_vat.sql)
create or replace function public.record_sale(p_id uuid, p_lines jsonb, p_cashbox uuid default null, p_customer uuid default null, p_note text default null)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  s uuid := public.current_shop_id();
  e uuid := gen_random_uuid();
  l jsonb;
  it public.items;
  q bigint; p bigint; cost bigint;
  rev_parts bigint := 0; rev_acc bigint := 0; rev_srv bigint := 0; total_cost bigint := 0;
  debit_acc uuid; pt text; pid uuid;
  n int := 0;
  bp integer := public.vat_bp(s); v_parts bigint := 0; v_acc bigint := 0; v_srv bigint := 0;
begin
  perform public.ledger_require(array['owner', 'reception']::public.app_role[]);
  perform public.perm_require('sales', 'add');
  if public.ledger_idem(p_id) is not null then return public.ledger_idem(p_id); end if;
  -- البيع بالآجل لصاحب المحل بس
  if p_cashbox is null and (p_customer is null or public.current_app_role() <> 'owner') then raise exception 'E_BAD_INPUT'; end if;
  if p_customer is not null and not exists (select 1 from public.customers where id = p_customer and shop_id = s and deleted_at is null) then raise exception 'E_NOT_FOUND'; end if;
  if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then raise exception 'E_BAD_INPUT'; end if;
  insert into public.journal_entries(id, shop_id, source_type, source_id, memo, idem_key, created_by)
  values (e, s, 'sale', p_id, nullif(trim(p_note), ''), p_id, auth.uid());
  -- البيع بس: لو الإعداد مفتوح، اللي مش موجود بيخرج من غير تكلفة ويتسوى بعدين
  perform set_config('app.uncosted', 'on', true);
  for l in select * from jsonb_array_elements(p_lines) loop
    select * into it from public.items where id = (l ->> 'item')::uuid and shop_id = s and deleted_at is null;
    if not found then raise exception 'E_NOT_FOUND'; end if;
    -- أعداد صحيحة بس (الكسور والفراغ وNaN والسالب بيترفضوا برسالة الحقل نفسه)
    if coalesce(l ->> 'qty', '') !~ '^[0-9]{1,6}$' or (l ->> 'qty')::bigint <= 0 then raise exception 'E_BAD_QTY'; end if;
    if coalesce(l ->> 'price', '') !~ '^[0-9]{1,12}$' then raise exception 'E_BAD_PRICE'; end if;
    q := (l ->> 'qty')::bigint;
    p := (l ->> 'price')::bigint;
    if p = 0 then
      if public.current_app_role() <> 'owner' and not public.has_perm('inventory', 'amounts') then raise exception 'E_FREE_SALE'; end if;
      if nullif(trim(l ->> 'reason'), '') is null then raise exception 'E_REASON_REQUIRED'; end if;
      insert into public.audit_log(shop_id, actor_id, action, entity, entity_id, after)
      values (s, auth.uid(), 'free_sale', 'items', it.id, jsonb_build_object('name', it.name, 'qty', q, 'reason', left(trim(l ->> 'reason'), 300), 'entry', e));
    end if;
    -- 6ب: سطر البيع زي ما اتباع (الاسم والكمية والسعر) عشان فاتورة البيع
    n := n + 1;
    insert into public.sale_lines(shop_id, entry_id, item_id, name, qty, price, seq, customer_id) values (s, e, it.id, it.name, q, p, n, p_customer);
    -- K: الخدمة من غير مخزون ولا تكلفة، وإيرادها إيراد الصيانة
    if it.kind = 'service' then rev_srv := rev_srv + q * p; continue; end if;
    cost := public.ledger_issue(it.id, q, e);
    total_cost := total_cost + cost;
    if it.kind = 'part' then rev_parts := rev_parts + q * p; else rev_acc := rev_acc + q * p; end if;
  end loop;
  perform set_config('app.uncosted', 'off', true);
  perform public.ledger_amount(rev_parts + rev_acc + rev_srv);
  if p_cashbox is null then
    debit_acc := public.ledger_acc('ar'); pt := 'customer'; pid := p_customer;
  else
    debit_acc := (public.ledger_cashbox(p_cashbox)).id;
  end if;
  insert into public.journal_lines(shop_id, entry_id, account_id, party_type, party_id, debit, credit)
  values (s, e, debit_acc, pt, pid, rev_parts + rev_acc + rev_srv, 0);
  -- R5: السعر شامل الضريبة. الضريبة بتتفصل من كل نوع إيراد لوحده، ومجموعها في حساب الضريبة المستحقة
  if bp > 0 then
    v_parts := public.vat_of(rev_parts, bp); v_acc := public.vat_of(rev_acc, bp); v_srv := public.vat_of(rev_srv, bp);
    if v_parts + v_acc + v_srv > 0 then
      insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values (s, e, public.ledger_acc('vat_payable'), 0, v_parts + v_acc + v_srv);
    end if;
  end if;
  if rev_parts > 0 then insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values (s, e, public.ledger_acc('rev_parts'), 0, rev_parts - v_parts); end if;
  if rev_acc > 0 then insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values (s, e, public.ledger_acc('rev_accessories'), 0, rev_acc - v_acc); end if;
  if rev_srv > 0 then insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values (s, e, public.ledger_acc('rev_repair'), 0, rev_srv - v_srv); end if;
  if total_cost > 0 then
    insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values
      (s, e, public.ledger_acc('cogs'), total_cost, 0), (s, e, public.ledger_acc('inventory'), 0, total_cost);
  end if;
  if p_cashbox is not null and p_customer is not null then
    null; -- البيع النقدي لعميل معروف ما بيأثرش على رصيده
  end if;
  return e;
end $$;

-- stock_in: (src: 0068_stock_adjust.sql) + اسم الصنف في سجل النشاط
create or replace function public.stock_in(p_id uuid, p_item uuid, p_qty integer, p_unit_cost bigint, p_note text default null) returns uuid
language plpgsql security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); e uuid; reason text := left(nullif(trim(p_note), ''), 300);
begin
  perform public.grant_require('inventory', 'amounts');
  e := public.ledger_idem(p_id);
  if e is not null then return e; end if;
  if reason is null then raise exception 'E_REASON_REQUIRED'; end if;
  e := public._stock_in(p_id, p_item, p_qty, p_unit_cost, reason);
  insert into public.audit_log(shop_id, actor_id, action, entity, entity_id, after)
  values (s, auth.uid(), 'stock_adjust', 'items', p_item, jsonb_build_object('name', (select name from public.items where id = p_item), 'qty', p_qty, 'unit_cost', p_unit_cost, 'value', p_qty::bigint * p_unit_cost, 'reason', reason, 'entry', e));
  return e;
end $$;
$m0069$;
  insert into public.app_migrations(version, how) values ('0069_sale_errors.sql', 'applied');
  raise notice 'applied %', '0069_sale_errors.sql';
end $run$;
commit;

-- ============================== 0070_perm_matrix.sql ==============================
begin;
do $run$ begin
  if exists (select 1 from public.app_migrations where version = '0070_perm_matrix.sql') then return; end if;
  execute $m0070$
-- 0070: (34) الصلاحيات على السيرفر لكل الأدوار: دوال كانت بتتأكد من الدور العام بس (استقبال/فني)،
-- من غير صلاحية الجدول ولا الفرع، فالكاشير والمحاسب وموظف الفرع التاني كانوا يقدروا ينادوها بالـ id.
-- من غير أي تغيير في البيانات ولا الحسابات.

-- الموظف ليه الجهاز ده؟ (فرعه أو جهاز في الطريق لفرعه، والفني أجهزته بس، زي سياسة devices_select)
create or replace function public.device_reach(p_device uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select public.current_app_role() = 'owner' or exists (
    select 1 from public.devices d where d.id = p_device and d.shop_id = public.current_shop_id()
      and (public.can_branch(d.branch_id) or public.can_branch(d.transfer_to))
      and (public.current_app_role() <> 'technician' or public.tech_can_see(d.id)))
$$;

-- صلاحية في الأجهزة + الجهاز نفسه. p_intake: اللي بيستلم أجهزة كمان (المسار وكلمة السر والصور وقت الاستلام)
create or replace function public.device_require(p_device uuid, p_op text, p_intake boolean default false) returns void
language plpgsql stable security definer set search_path = public as $$
begin
  if (public.has_perm('devices', p_op) or (p_intake and public.has_perm('intake', 'add'))) is not true then raise exception 'E_FORBIDDEN'; end if;
  if public.device_reach(p_device) is not true then raise exception 'E_FORBIDDEN'; end if;
  -- جهاز في الطريق لفرعي: أشوفه بس، والتعديل بعد الاستلام (زي سياسة devices_update)
  if p_op = 'edit' and not exists (select 1 from public.devices d where d.id = p_device and (public.current_app_role() = 'owner' or public.can_branch(d.branch_id))) then raise exception 'E_FORBIDDEN'; end if;
end $$;

-- التصحيح: الموظف (حتى لو معاه "يحذف") في فروعه بس، والمرتبات والشركاء ورأس المال وسداد الضريبة لصاحب المحل بس
create or replace function public.entry_require(p_entry uuid) returns void
language plpgsql stable security definer set search_path = public as $$
begin
  if public.current_app_role() = 'owner' then return; end if;
  if exists (select 1 from public.journal_entries e where e.id = p_entry and (e.source_type = 'vat_payment' or not public.can_branch(e.branch_id)))
     or exists (select 1 from public.journal_lines l join public.accounts a on a.id = l.account_id where l.entry_id = p_entry
                and (a.kind in ('advances', 'salaries', 'partner_capital', 'partner_current', 'capital', 'drawings') or (a.kind = 'cash' and not public.can_branch(a.branch_id))))
     or exists (select 1 from public.stock_moves m where m.entry_id = p_entry and not public.can_branch(m.branch_id)) then
    raise exception 'E_FORBIDDEN';
  end if;
end $$;
revoke execute on function public.device_reach(uuid), public.device_require(uuid, text, boolean), public.entry_require(uuid) from public, anon, authenticated;

-- send_device: (src: 0034_branches.sql) + صلاحية "يعدّل" في الأجهزة
create or replace function public.send_device(p_device uuid, p_to uuid) returns void
language plpgsql security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); d public.devices;
begin
  perform public.ledger_require(array['owner', 'reception']::public.app_role[]);
  if public.has_perm('devices', 'edit') is not true then raise exception 'E_FORBIDDEN'; end if;
  select * into d from public.devices where id = p_device and shop_id = s and deleted_at is null for update;
  if not found or not public.can_branch(d.branch_id) then raise exception 'E_NOT_FOUND'; end if;
  if d.status = 'delivered' then raise exception 'E_DELIVERED'; end if;
  if d.transfer_to is not null then raise exception 'E_IN_TRANSIT'; end if;
  if p_to = d.branch_id or not exists (select 1 from public.branches where id = p_to and shop_id = s and deleted_at is null) then raise exception 'E_BAD_BRANCH'; end if;
  perform set_config('app.device_move', 'on', true);
  update public.devices set transfer_to = p_to, transfer_at = now(), transfer_by = auth.uid() where id = d.id;
  perform set_config('app.device_move', 'off', true);
  insert into public.audit_log(shop_id, actor_id, action, entity, entity_id, before, after)
  values (s, auth.uid(), 'device_send', 'devices', d.id, jsonb_build_object('branch', d.branch_id), jsonb_build_object('to', p_to));
end $$;

-- cancel_device_transfer: (src: 0034_branches.sql) + صلاحية "يعدّل" في الأجهزة
create or replace function public.cancel_device_transfer(p_device uuid) returns void
language plpgsql security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); d public.devices;
begin
  perform public.ledger_require(array['owner', 'reception']::public.app_role[]);
  if public.has_perm('devices', 'edit') is not true then raise exception 'E_FORBIDDEN'; end if;
  select * into d from public.devices where id = p_device and shop_id = s and deleted_at is null for update;
  if not found or d.transfer_to is null then raise exception 'E_NOT_FOUND'; end if;
  if not (public.can_branch(d.branch_id) or public.can_branch(d.transfer_to)) then raise exception 'E_FORBIDDEN'; end if;
  perform set_config('app.device_move', 'on', true);
  update public.devices set transfer_to = null, transfer_at = null, transfer_by = null where id = d.id;
  perform set_config('app.device_move', 'off', true);
  insert into public.audit_log(shop_id, actor_id, action, entity, entity_id, before, after)
  values (s, auth.uid(), 'device_transfer_cancel', 'devices', d.id, jsonb_build_object('to', d.transfer_to), null);
end $$;

-- receive_device: (src: 0034_branches.sql) + صلاحية "يعدّل" في الأجهزة
create or replace function public.receive_device(p_device uuid) returns void
language plpgsql security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); d public.devices;
begin
  perform public.ledger_require(array['owner', 'reception']::public.app_role[]);
  if public.has_perm('devices', 'edit') is not true then raise exception 'E_FORBIDDEN'; end if;
  select * into d from public.devices where id = p_device and shop_id = s and deleted_at is null for update;
  if not found or d.transfer_to is null then raise exception 'E_NOT_FOUND'; end if;
  if not public.can_branch(d.transfer_to) then raise exception 'E_FORBIDDEN'; end if;
  perform set_config('app.device_move', 'on', true);
  update public.devices set branch_id = d.transfer_to, transfer_to = null, transfer_at = null, transfer_by = null where id = d.id;
  perform set_config('app.device_move', 'off', true);
  insert into public.audit_log(shop_id, actor_id, action, entity, entity_id, before, after)
  values (s, auth.uid(), 'device_receive', 'devices', d.id, jsonb_build_object('branch', d.branch_id), jsonb_build_object('branch', d.transfer_to));
end $$;

-- reassign_step: (src: 0014_technicians.sql) + الصلاحية والفرع
create or replace function public.reassign_step(p_step uuid, p_tech uuid) returns void
language plpgsql security definer set search_path = public as $$
declare s public.repair_steps;
begin
  perform public.ledger_require(array['owner', 'reception']::public.app_role[]);
  select * into s from public.repair_steps where id = p_step and shop_id = public.current_shop_id() for update;
  if not found or s.status not in ('pending', 'active') then raise exception 'E_NOT_FOUND'; end if;
  perform public.device_require(s.device_id, 'edit');
  if p_tech is not null and not exists (select 1 from public.profiles where id = p_tech and shop_id = s.shop_id and role = 'technician' and deleted_at is null) then raise exception 'E_NOT_FOUND'; end if;
  update public.repair_steps set technician_id = p_tech, status = case when status = 'active' then 'pending' else status end, started_at = null where id = s.id;
end $$;

-- suggest_device_price: (src: 0012_spec_completion.sql) + مبالغ الأجهزة والفرع
create or replace function public.suggest_device_price(p_device uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  d public.devices;
  parts bigint;
  labor bigint;
  margin int;
  markup bigint;
  price bigint;
begin
  perform public.ledger_require(array['owner', 'reception']::public.app_role[]);
  select * into d from public.devices where id = p_device and shop_id = public.current_shop_id();
  if not found then raise exception 'E_NOT_FOUND'; end if;
  perform public.device_require(p_device, 'amounts');
  select coalesce(-sum(m.value), 0) into parts from public.stock_moves m join public.journal_entries e on e.id = m.entry_id
   where e.device_id = p_device and e.source_type in ('part_use', 'reversal');
  select coalesce(sum(r.amount), 0) into labor from public.labor_rates r
   where r.shop_id = d.shop_id and r.deleted_at is null and position(lower(trim(r.issue)) in lower(d.issue)) > 0;
  select default_margin_pct into margin from public.shops where id = d.shop_id;
  markup := (parts * margin + 99) / 100;
  price := ((parts + labor + markup + 499) / 500) * 500;
  return case when public.current_app_role() = 'owner'
    then jsonb_build_object('price', price, 'parts', parts, 'labor', labor, 'margin', margin, 'markup', markup)
    else jsonb_build_object('price', price, 'labor', labor) end;
end $$;

-- device_money: (src: 0036_roles.sql) + الفرع
create or replace function public.device_money(p_device uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare fc integer; paid bigint;
begin
  perform public.ledger_require(array['owner', 'reception']::public.app_role[]);
  if not public.has_perm('devices', 'amounts') then raise exception 'E_FORBIDDEN'; end if;
  if not exists (select 1 from public.devices where id = p_device and shop_id = public.current_shop_id()) then raise exception 'E_NOT_FOUND'; end if;
  perform public.device_require(p_device, 'amounts');
  select final_cost into fc from public.device_costs where device_id = p_device and deleted_at is null;
  paid := public.device_paid(p_device);
  return jsonb_build_object(
    'final', fc, 'paid', paid, 'due', greatest(coalesce(fc, 0) - paid, 0),
    'payments', coalesce((select jsonb_agg(jsonb_build_object(
        'id', p.id, 'amount', p.amount, 'method', p.method, 'created_at', p.created_at, 'entry_id', p.entry_id,
        'by', (select full_name from public.profiles where id = p.created_by),
        'reversed', exists (select 1 from public.journal_entries r where r.reverses_id = p.entry_id)) order by p.created_at)
      from public.payments p where p.device_id = p_device), '[]'::jsonb),
    'parts_cost', case when public.current_app_role() = 'owner' then (
      select coalesce(sum(l.debit), 0) from public.journal_lines l join public.journal_entries e on e.id = l.entry_id
      where e.device_id = p_device and e.source_type in ('part_use', 'reversal') and l.account_id = public.ledger_acc('cogs')) - (
      select coalesce(sum(l.credit), 0) from public.journal_lines l join public.journal_entries e on e.id = l.entry_id
      where e.device_id = p_device and e.source_type = 'reversal' and l.account_id = public.ledger_acc('cogs')) end
  );
end $$;

-- device_vat: (src: 0062_vat.sql) + مبالغ الأجهزة أو الوضع المالي، والفرع
create or replace function public.device_vat(p_device uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); r public.app_role := public.current_app_role(); v bigint; g bigint;
begin
  if s is null or r is null or r = 'technician' or r = 'marketing' then raise exception 'E_FORBIDDEN'; end if;
  if (public.has_perm('devices', 'amounts') or public.has_perm('finance', 'view')) is not true or public.device_reach(p_device) is not true then raise exception 'E_FORBIDDEN'; end if;
  select coalesce(sum(l.credit) filter (where a.kind = 'tax'), 0), coalesce(sum(l.credit) filter (where a.kind in ('tax', 'revenue')), 0)
    into v, g
  from public.journal_entries e join public.journal_lines l on l.entry_id = e.id join public.accounts a on a.id = l.account_id
  where e.shop_id = s and e.source_type = 'delivery' and e.source_id = p_device
    and not exists (select 1 from public.journal_entries x where x.reverses_id = e.id);
  if g = 0 then return null; end if;
  return jsonb_build_object('vat', v, 'gross', g, 'net', g - v);
end $$;

-- device_parts: (src: 0012_spec_completion.sql) + الصلاحية والفرع
create or replace function public.device_parts(p_device uuid)
returns table(item_id uuid, name text, qty bigint)
language plpgsql stable security definer set search_path = public as $$
#variable_conflict use_column
begin
  if public.current_app_role() is null then raise exception 'E_FORBIDDEN'; end if;
  if not exists (select 1 from public.devices where id = p_device and shop_id = public.current_shop_id()) then raise exception 'E_NOT_FOUND'; end if;
  perform public.device_require(p_device, 'view');
  return query
  select i.id, i.name, (-sum(m.qty))::bigint
  from public.stock_moves m
  join public.journal_entries e on e.id = m.entry_id
  join public.items i on i.id = m.item_id
  where (e.device_id = p_device) and e.source_type in ('part_use', 'reversal')
  group by i.id, i.name
  having -sum(m.qty) > 0;
end $$;

-- device_manual_part: (src: 0036_roles.sql) + الفرع والجهاز نفسه
create or replace function public.device_manual_part(p_id uuid, p_device uuid, p_name text, p_cost bigint, p_cashbox uuid default null, p_supplier uuid default null) returns uuid
language plpgsql security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); e uuid; credit_line jsonb;
begin
  perform public.ledger_require(array['owner', 'reception']::public.app_role[]);
  perform public.perm_require('devices', 'edit');
  e := public.ledger_idem(p_id);
  if e is not null then return e; end if;
  if nullif(trim(p_name), '') is null then raise exception 'E_BAD_INPUT'; end if;
  perform public.ledger_amount(p_cost);
  if not exists (select 1 from public.devices where id = p_device and shop_id = s and deleted_at is null and status <> 'delivered') then raise exception 'E_NOT_FOUND'; end if;
  perform public.device_require(p_device, 'edit');
  if p_cashbox is not null then
    credit_line := public.ledger_line((public.ledger_cashbox(p_cashbox)).id, 0, p_cost);
  elsif p_supplier is not null then
    if not exists (select 1 from public.suppliers where id = p_supplier and shop_id = s and deleted_at is null) then raise exception 'E_NOT_FOUND'; end if;
    credit_line := public.ledger_line(public.ledger_acc('ap'), 0, p_cost, 'supplier', p_supplier);
  else
    raise exception 'E_BAD_INPUT';
  end if;
  return public.ledger_post('part_use', null, trim(p_name), jsonb_build_array(public.ledger_line(public.ledger_acc('cogs'), p_cost, 0), credit_line), p_device, p_id);
end $$;

-- use_part: (src: 0036_roles.sql) + الفني أجهزته بس، وفي فرعه
create or replace function public.use_part(p_id uuid, p_device uuid, p_item uuid, p_qty integer default 1)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  e uuid;
  cost bigint;
  inv uuid := public.ledger_acc('inventory');
  cg uuid := public.ledger_acc('cogs');
begin
  perform public.ledger_require(array['owner', 'technician']::public.app_role[]);
  perform public.perm_require('devices', 'edit');
  e := public.ledger_idem(p_id);
  if e is not null then return e; end if;
  if not exists (select 1 from public.devices where id = p_device and shop_id = public.current_shop_id() and deleted_at is null and status <> 'delivered') then raise exception 'E_NOT_FOUND'; end if;
  perform public.device_require(p_device, 'edit');
  -- القيد محتاج يتعمل الأول عشان حركة المخزون تتربط بيه، والتوازن بيتراجع في آخر العملية
  e := gen_random_uuid();
  insert into public.journal_entries(id, shop_id, source_type, source_id, device_id, idem_key, created_by)
  values (e, public.current_shop_id(), 'part_use', p_item, p_device, p_id, auth.uid());
  cost := public.ledger_issue(p_item, p_qty, e);
  if cost > 0 then
    insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values
      (public.current_shop_id(), e, cg, cost, 0),
      (public.current_shop_id(), e, inv, 0, cost);
  else
    raise exception 'E_BAD_AMOUNT';  -- صنف من غير تكلفة: لازم يتشتري بسعر الأول
  end if;
  return e;
end $$;

-- set_device_passcode: (src: 0005_device_passcode.sql) + الصلاحية والفرع
create or replace function public.set_device_passcode(p_device_id uuid, p_kind text, p_value text)
returns void
language plpgsql security definer set search_path = public as $$
declare
  shop uuid := public.current_shop_id();
  r public.app_role := public.current_app_role();
  dev public.devices;
  existing public.device_passcodes;
  sid uuid;
begin
  if shop is null then raise exception 'E_NO_SHOP'; end if;
  if r not in ('owner', 'reception') then raise exception 'E_FORBIDDEN'; end if;
  if p_kind not in ('pin', 'pattern') then raise exception 'E_BAD_INPUT'; end if;
  if p_value is null or length(trim(p_value)) = 0 or length(p_value) > 64 then raise exception 'E_BAD_INPUT'; end if;
  select * into dev from public.devices where id = p_device_id and shop_id = shop and deleted_at is null;
  if not found then raise exception 'E_NOT_FOUND'; end if;
  perform public.device_require(p_device_id, 'edit', true);
  if dev.status = 'delivered' then raise exception 'E_DELIVERED_LOCKED'; end if;

  select * into existing from public.device_passcodes where device_id = p_device_id;
  if found and existing.secret_id is not null then
    perform vault.update_secret(existing.secret_id, p_value);
    update public.device_passcodes set kind = p_kind, erased_at = null where id = existing.id;
  else
    sid := vault.create_secret(p_value, 'device-passcode-' || p_device_id::text, 'device lock');
    if found then
      update public.device_passcodes set kind = p_kind, secret_id = sid, erased_at = null where id = existing.id;
    else
      insert into public.device_passcodes(shop_id, device_id, kind, secret_id) values (shop, p_device_id, p_kind, sid);
    end if;
  end if;
  -- السجل فيه نوع العملية بس، مش القيمة
  insert into public.audit_log(shop_id, actor_id, action, entity, entity_id, after)
  values (shop, auth.uid(), 'passcode_set', 'device_passcodes', p_device_id, jsonb_build_object('kind', p_kind));
end $$;

-- reveal_device_passcode: (src: 0005_device_passcode.sql) + صلاحية "يشوف" في الأجهزة، والفني أجهزته بس، وفي فرعه
create or replace function public.reveal_device_passcode(p_device_id uuid)
returns table(kind text, value text)
language plpgsql security definer set search_path = public as $$
declare
  shop uuid := public.current_shop_id();
  r public.app_role := public.current_app_role();
  pc public.device_passcodes;
  v text;
begin
  if shop is null then raise exception 'E_NO_SHOP'; end if;
  if r not in ('owner', 'technician') then raise exception 'E_FORBIDDEN'; end if;
  select * into pc from public.device_passcodes where device_id = p_device_id and shop_id = shop and deleted_at is null;
  if not found or pc.secret_id is null then raise exception 'E_NOT_FOUND'; end if;
  perform public.device_require(p_device_id, 'view');
  select ds.decrypted_secret into v from vault.decrypted_secrets ds where ds.id = pc.secret_id;
  insert into public.audit_log(shop_id, actor_id, action, entity, entity_id, after)
  values (shop, auth.uid(), 'passcode_viewed', 'device_passcodes', p_device_id, jsonb_build_object('kind', pc.kind));
  return query select pc.kind, v;
end $$;

-- set_route: (src: 0014_technicians.sql) + الصلاحية والفرع
create or replace function public.set_route(p_device uuid, p_route uuid) returns void
language plpgsql security definer set search_path = public as $$
declare
  d public.devices;
  r public.routes;
  n int;
  sp uuid;
  i int := 0;
  first_step uuid;
begin
  select * into d from public.devices where id = p_device and shop_id = public.current_shop_id() and deleted_at is null for update;
  if not found then raise exception 'E_NOT_FOUND'; end if;
  select * into r from public.routes where id = p_route and shop_id = d.shop_id and deleted_at is null;
  if not found then raise exception 'E_NOT_FOUND'; end if;
  -- الفني بيحدد المسار بس لو هو اللي فحص (خطوة فحص في مسار "غير معروف" متعيّنة له)
  if public.current_app_role() = 'technician' and not exists (
      select 1 from public.repair_steps s join public.routes rr on rr.id = s.route_id and rr.diagnose
      where s.device_id = d.id and s.technician_id = auth.uid() and s.status in ('active', 'done')) then
    raise exception 'E_FORBIDDEN';
  end if;
  if public.current_app_role() is null then raise exception 'E_FORBIDDEN'; end if;
  perform public.device_require(d.id, 'edit', true);
  update public.repair_steps set status = 'skipped', finished_at = now() where device_id = d.id and status in ('pending', 'active');
  select coalesce(max(step_no), 0) into n from public.repair_steps where device_id = d.id;
  foreach sp in array r.steps loop
    i := i + 1;
    insert into public.repair_steps(shop_id, device_id, route_id, step_no, specialty_id, technician_id)
    values (d.shop_id, d.id, r.id, n + i, sp, case when i = 1 then public.pick_technician(d.id, sp) end)
    returning id into first_step;
  end loop;
  perform set_config('warsha.routing', 'on', true);
  update public.devices set route_id = r.id where id = d.id;
  perform set_config('warsha.routing', 'off', true);
end $$;

-- start_photo_upload: (src: 0044_capture.sql) + الصلاحية والفرع
create or replace function public.start_photo_upload(p_device uuid)
returns table(token text, expires_at timestamptz)
-- extensions: فيها gen_random_bytes على Supabase
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare d public.devices; t text := encode(gen_random_bytes(16), 'hex'); e timestamptz := now() + interval '30 minutes';
begin
  if public.current_app_role() not in ('owner', 'reception') then raise exception 'E_FORBIDDEN'; end if;
  select * into d from public.devices where id = p_device and shop_id = public.current_shop_id() and deleted_at is null;
  if d.id is null then raise exception 'E_NOT_FOUND'; end if;
  perform public.device_require(d.id, 'edit', true);
  if d.status = 'delivered' then raise exception 'E_DELIVERED'; end if;
  -- الجلسات القديمة لنفس الجهاز بتتقفل (رابط واحد شغال في نفس الوقت)
  update public.photo_upload_sessions s set deleted_at = now() where s.device_id = d.id and s.deleted_at is null;
  insert into public.photo_upload_sessions(shop_id, device_id, token, expires_at, created_by)
  values (d.shop_id, d.id, t, e, auth.uid());
  return query select t, e;
end $$;

-- apply_status_lww: (src: 0015_offline_backup.sql) + الصلاحية والفرع
create or replace function public.apply_status_lww(p_device uuid, p_status public.device_status, p_client_ts timestamptz)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare d public.devices;
begin
  if public.current_app_role() is null then raise exception 'E_FORBIDDEN'; end if;
  select * into d from public.devices where id = p_device and shop_id = public.current_shop_id() and deleted_at is null for update;
  if not found then raise exception 'E_NOT_FOUND'; end if;
  perform public.device_require(d.id, 'edit');
  if d.status = p_status then
    return jsonb_build_object('applied', true, 'same', true);
  end if;
  if d.updated_at > p_client_ts then
    insert into public.audit_log(shop_id, actor_id, action, entity, entity_id, before, after)
    values (d.shop_id, auth.uid(), 'sync_conflict', 'devices', d.id,
            jsonb_build_object('status', d.status, 'updated_at', d.updated_at),
            jsonb_build_object('status', p_status, 'client_ts', p_client_ts, 'kept', 'server'));
    return jsonb_build_object('applied', false, 'reason', 'newer_on_server', 'server_status', d.status);
  end if;
  begin
    update public.devices set status = p_status where id = d.id;
  exception when others then
    -- التعديل ما ينفعش يتطبق (مثلًا الانتقال مش مسموح دلوقتي): بيتسجل تعارض بسببه
    insert into public.audit_log(shop_id, actor_id, action, entity, entity_id, before, after)
    values (d.shop_id, auth.uid(), 'sync_conflict', 'devices', d.id,
            jsonb_build_object('status', d.status, 'updated_at', d.updated_at),
            jsonb_build_object('status', p_status, 'client_ts', p_client_ts, 'kept', 'server', 'error', sqlerrm));
    return jsonb_build_object('applied', false, 'reason', 'rejected', 'error', sqlerrm, 'server_status', d.status);
  end;
  return jsonb_build_object('applied', true);
end $$;

-- models_report: (src: 0034_branches.sql) + صلاحية التقارير، والموظف فرعه بس
create or replace function public.models_report(p_from timestamptz, p_to timestamptz, p_branch uuid default null)
returns table(kind text, label text, devices integer)
language plpgsql stable security definer set search_path = public as $$
#variable_conflict use_column
begin
  perform public.grant_require('reports', 'view');
  if not public.all_my_branches() and (p_branch is null or not public.can_branch(p_branch)) then p_branch := public.op_branch(); end if;
  return query
  (select 'model'::text, d.brand || ' ' || d.model, count(*)::int from public.devices d
    where d.shop_id = public.current_shop_id() and d.received_at >= p_from and d.received_at < p_to and d.deleted_at is null and (p_branch is null or d.branch_id = p_branch)
    group by d.brand, d.model order by 3 desc limit 10)
  union all
  (select 'route'::text, coalesce(r.code, r.name, '-'), count(*)::int from public.devices d left join public.routes r on r.id = d.route_id
    where d.shop_id = public.current_shop_id() and d.received_at >= p_from and d.received_at < p_to and d.deleted_at is null and (p_branch is null or d.branch_id = p_branch)
    group by r.code, r.name order by 3 desc limit 10);
end $$;

-- marketing_due: (src: 0021_spec_rules.sql) + صلاحية الأجهزة والعملاء، والموظف فرعه بس
create or replace function public.marketing_due(p_days integer default 180)
returns table(device_id uuid, order_no text, brand text, model text, issue text, delivered_at timestamptz,
              customer_id uuid, customer_name text, phone text, tracking_token text)
language plpgsql stable security definer set search_path = public as $$
#variable_conflict use_column
declare s uuid := public.current_shop_id(); days integer := greatest(30, least(coalesce(p_days, 180), 720));
begin
  if public.current_app_role() not in ('owner', 'reception') then raise exception 'E_FORBIDDEN'; end if;
  if (public.has_perm('devices', 'view') and public.has_perm('customers', 'view')) is not true then raise exception 'E_FORBIDDEN'; end if;
  return query
  with last_dev as (
    select distinct on (d.customer_id) d.*
    from public.devices d
    where d.shop_id = s and d.deleted_at is null and d.status = 'delivered' and d.delivered_at is not null
      and (public.all_my_branches() or public.can_branch(d.branch_id))
    order by d.customer_id, d.delivered_at desc
  )
  select d.id, d.order_no, d.brand, d.model, d.issue, d.delivered_at, c.id, c.name, c.phone, d.tracking_token
  from last_dev d join public.customers c on c.id = d.customer_id and c.deleted_at is null
  where c.marketing_ok
    and d.delivered_at <= now() - make_interval(days => days)
    and d.delivered_at > now() - make_interval(days => days + 365)
    and not exists (select 1 from public.message_log m where m.customer_id = c.id and m.template_key = 'marketing' and m.created_at >= d.delivered_at and m.deleted_at is null)
  order by d.delivered_at
  limit 200;
end $$;

-- item_branch_stock: (src: 0034_branches.sql) + القيمة (التكلفة) بصلاحية مبالغ المخزون
create or replace function public.item_branch_stock(p_item uuid) returns table(branch_id uuid, qty bigint, value bigint)
language sql stable security definer set search_path = public as $$
  select b.id, coalesce(sum(m.qty), 0)::bigint, case when (select public.has_perm('inventory', 'amounts')) then coalesce(sum(m.value), 0)::bigint end
  from public.branches b left join public.stock_moves m on m.branch_id = b.id and m.item_id = p_item
  where b.shop_id = public.current_shop_id() and b.deleted_at is null and b.id = any (public.my_branch_ids())
    and public.current_app_role() in ('owner', 'reception', 'technician')
  group by b.id
$$;

-- reverse_entry: (src: 0046_master.sql) + الموظف فروعه بس، والمرتبات والشركاء لصاحب المحل
CREATE OR REPLACE FUNCTION public.reverse_entry(p_entry uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  o public.journal_entries;
  e uuid;
  lines jsonb;
  mv record;
begin
  if public.current_app_role() is null or not public.can_correct() then raise exception 'E_FORBIDDEN'; end if;
  -- C3: كلمة السر الرئيسية (لو صاحب المحل حددها)
  perform public.master_require();
  if nullif(trim(p_reason), '') is null then raise exception 'E_REASON_REQUIRED'; end if;
  select * into o from public.journal_entries where id = p_entry and shop_id = public.current_shop_id() for update;
  if not found then raise exception 'E_NOT_FOUND'; end if;
  perform public.entry_require(o.id);
  if o.source_type in ('reversal', 'cost_adjust') or exists (select 1 from public.journal_entries where reverses_id = o.id) then
    raise exception 'E_ALREADY_REVERSED';
  end if;
  select jsonb_agg(public.ledger_line(account_id, credit, debit, party_type, party_id)) into lines
  from public.journal_lines where entry_id = o.id;
  -- العكس بيتسجل في نفس فرع القيد الأصلي
  perform set_config('app.branch', o.branch_id::text, true);
  e := public.ledger_post('reversal', o.source_id, p_reason, lines, o.device_id, null, o.id);
  for mv in select * from public.stock_moves where entry_id = o.id loop
    perform 1 from public.items where id = mv.item_id for update;
    if (select coalesce(sum(qty), 0) from public.stock_moves where item_id = mv.item_id and branch_id = mv.branch_id) - mv.qty < 0 then
      raise exception 'E_STOCK';
    end if;
    insert into public.stock_moves(shop_id, item_id, entry_id, qty, value, branch_id) values (mv.shop_id, mv.item_id, e, -mv.qty, -mv.value, mv.branch_id);
  end loop;
  for mv in select distinct item_id, branch_id from public.stock_moves where entry_id = o.id loop
    perform public.ledger_settle_item(mv.item_id, o.device_id, mv.branch_id);
  end loop;
  insert into public.audit_log(shop_id, actor_id, action, entity, entity_id, before, after)
  values (o.shop_id, auth.uid(), 'reverse_entry', 'journal_entries', o.id, to_jsonb(o), jsonb_build_object('reversal_id', e, 'reason', p_reason));
  return e;
end $function$;

-- entry_args: (src: 0060_sale_lines.sql) + نفس شرط reverse_entry
create or replace function public.entry_args(p_entry uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  o public.journal_entries;
  cash_in uuid; cash_out uuid; amt bigint; party uuid; acc uuid; res jsonb; pay public.payments; pur public.purchases;
  ls jsonb; rev bigint; cust uuid;
begin
  if public.current_app_role() is null or not public.can_correct() then raise exception 'E_FORBIDDEN'; end if;
  select * into o from public.journal_entries where id = p_entry and shop_id = public.current_shop_id();
  if not found then raise exception 'E_NOT_FOUND'; end if;
  perform public.entry_require(o.id);
  select max(l.account_id::text) filter (where a.kind = 'cash' and l.debit > 0)::uuid,
         max(l.account_id::text) filter (where a.kind = 'cash' and l.credit > 0)::uuid,
         max(l.party_id::text) filter (where l.party_id is not null)::uuid,
         max(l.account_id::text) filter (where a.kind = 'expense' and l.debit > 0)::uuid,
         greatest(sum(l.debit), 0)
    into cash_in, cash_out, party, acc, amt
  from public.journal_lines l join public.accounts a on a.id = l.account_id where l.entry_id = o.id;
  res := jsonb_build_object('source_type', o.source_type, 'entry_no', o.entry_no, 'note', o.memo,
    'reversed', exists (select 1 from public.journal_entries where reverses_id = o.id),
    'editable', o.source_type in ('payment', 'expense', 'transfer', 'capital', 'drawing', 'advance', 'salary', 'salary_payment', 'supplier_payment', 'purchase', 'sale'));
  if o.source_type = 'payment' then
    select * into pay from public.payments where entry_id = o.id;
    res := res || jsonb_build_object('customer', pay.customer_id, 'device', pay.device_id, 'cashbox', pay.cashbox_id, 'method', pay.method, 'amount', pay.amount);
  elsif o.source_type = 'expense' then
    res := res || jsonb_build_object('account', acc, 'cashbox', cash_out, 'amount', amt);
  elsif o.source_type = 'transfer' then
    res := res || jsonb_build_object('from', cash_out, 'to', cash_in, 'amount', amt);
  elsif o.source_type = 'capital' then
    res := res || jsonb_build_object('cashbox', cash_in, 'amount', amt);
  elsif o.source_type = 'drawing' then
    res := res || jsonb_build_object('cashbox', cash_out, 'amount', amt);
  elsif o.source_type in ('advance', 'salary_payment') then
    res := res || jsonb_build_object('employee', party, 'cashbox', cash_out, 'amount', amt);
  elsif o.source_type = 'salary' then
    res := res || jsonb_build_object('employee', party, 'amount', amt);
  elsif o.source_type = 'supplier_payment' then
    res := res || jsonb_build_object('supplier', party, 'cashbox', cash_out, 'amount', amt);
  elsif o.source_type = 'purchase' then
    select * into pur from public.purchases where entry_id = o.id;
    select jsonb_agg(jsonb_build_object('item', m.item_id, 'qty', m.qty, 'unit_cost', m.value / nullif(m.qty, 0)) order by m.created_at) into ls
    from public.stock_moves m where m.entry_id = o.id;
    res := res || jsonb_build_object('supplier', pur.supplier_id, 'cashbox', cash_out, 'lines', coalesce(ls, '[]'::jsonb));
  elsif o.source_type = 'sale' then
    -- سعر البيع: لو صنف واحد بيتحسب من الإيراد، ولو أكتر من صنف بيتاخد سعر الصنف المسجل
    select coalesce(sum(l.credit), 0) into rev from public.journal_lines l join public.accounts a on a.id = l.account_id where l.entry_id = o.id and a.type = 'revenue';
    select max(l.party_id::text) filter (where l.party_type = 'customer')::uuid into cust from public.journal_lines l where l.entry_id = o.id;
    -- 6ب: البيع الجديد بسطوره زي ما اتباع بالظبط. القديم (قبل 0060) زي الأول
    select jsonb_agg(jsonb_build_object('item', sl.item_id, 'qty', sl.qty, 'price', sl.price) order by sl.seq) into ls
    from public.sale_lines sl where sl.entry_id = o.id and sl.deleted_at is null;
    if ls is null then
    select jsonb_agg(jsonb_build_object('item', x.item_id, 'qty', x.q,
             'price', case when x.n = 1 then rev / x.q else coalesce(i.sale_price, 0) end) order by x.first)
      into ls
    from (select m.item_id, -sum(m.qty) q, count(*) over () n, min(m.created_at) first from public.stock_moves m where m.entry_id = o.id group by m.item_id) x
    join public.items i on i.id = x.item_id;
    end if;
    res := res || jsonb_build_object('customer', cust, 'cashbox', cash_in, 'lines', coalesce(ls, '[]'::jsonb));
  end if;
  return res;
end $$;

-- soft_delete: (src: 0046_master.sql) + الجهاز في فرع الموظف بس
create or replace function public.soft_delete(p_kind text, p_id uuid, p_reason text default null) returns void
language plpgsql security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); before jsonb; tbl text;
begin
  if public.current_app_role() is null or not public.can_correct() then raise exception 'E_FORBIDDEN'; end if;
  -- C3: كلمة السر الرئيسية (لو صاحب المحل حددها)
  perform public.master_require();
  if p_kind = 'customer' then
    tbl := 'customers';
    select to_jsonb(c) into before from public.customers c where id = p_id and shop_id = s and deleted_at is null for update;
    if before is null then raise exception 'E_NOT_FOUND'; end if;
    if exists (select 1 from public.journal_lines l where l.party_id = p_id and l.shop_id = s group by l.account_id having sum(l.debit - l.credit) <> 0) then raise exception 'E_HAS_BALANCE'; end if;
    if exists (select 1 from public.devices d where d.customer_id = p_id and d.deleted_at is null and d.status not in ('delivered', 'unrepairable')) then raise exception 'E_HAS_OPEN_DEVICES'; end if;
  elsif p_kind = 'supplier' then
    tbl := 'suppliers';
    select to_jsonb(x) into before from public.suppliers x where id = p_id and shop_id = s and deleted_at is null for update;
    if before is null then raise exception 'E_NOT_FOUND'; end if;
    if exists (select 1 from public.journal_lines l where l.party_id = p_id and l.shop_id = s group by l.account_id having sum(l.debit - l.credit) <> 0) then raise exception 'E_HAS_BALANCE'; end if;
  elsif p_kind = 'item' then
    tbl := 'items';
    select to_jsonb(x) into before from public.items x where id = p_id and shop_id = s and deleted_at is null for update;
    if before is null then raise exception 'E_NOT_FOUND'; end if;
    if (select coalesce(sum(qty), 0) <> 0 or coalesce(sum(value), 0) <> 0 from public.stock_moves where item_id = p_id) then raise exception 'E_HAS_STOCK'; end if;
  elsif p_kind = 'device' then
    tbl := 'devices';
    select to_jsonb(x) into before from public.devices x where id = p_id and shop_id = s and deleted_at is null for update;
    if before is null then raise exception 'E_NOT_FOUND'; end if;
    if public.current_app_role() <> 'owner' and not public.can_branch((before ->> 'branch_id')::uuid) then raise exception 'E_FORBIDDEN'; end if;
    if exists (select 1 from public.journal_entries e where e.device_id = p_id and not exists (select 1 from public.journal_entries r where r.reverses_id = e.id) and e.source_type not in ('reversal', 'cost_adjust')) then
      raise exception 'E_HAS_MONEY';
    end if;
  else
    raise exception 'E_BAD_INPUT';
  end if;
  perform set_config('warsha.system', 'on', true);
  execute format('update public.%I set deleted_at = now(), updated_at = now() where id = $1', tbl) using p_id;
  perform set_config('warsha.system', 'off', true);
  insert into public.audit_log(shop_id, actor_id, action, entity, entity_id, before, after)
  values (s, auth.uid(), 'soft_delete', tbl, p_id, before, jsonb_build_object('reason', nullif(trim(p_reason), '')));
end $$;
$m0070$;
  insert into public.app_migrations(version, how) values ('0070_perm_matrix.sql', 'applied');
  raise notice 'applied %', '0070_perm_matrix.sql';
end $run$;
commit;

-- ============================== 0071_device_children.sql ==============================
begin;
do $run$ begin
  if exists (select 1 from public.app_migrations where version = '0071_device_children.sql') then return; end if;
  execute $m0071$
-- 0071: (24ب) تفاصيل الجهاز (التكلفة والدفعات والصور والملاحظات والسجل والفحص والخطوات والرسايل وكلمة السر)
-- كانت معزولة بالمحل بس. بقت: اللي بيشوف الجهاز نفسه (فرعه، والفني أجهزته بس)، والكتابة في فرع الجهاز.
-- سياسات مقيّدة فوق الموجود (وسياسة قراية ملفات الصور اتعادت أضيق)، من غير أي تغيير في البيانات.
-- الدفعات بالخزنة مش بالجهاز: الكاشير والمحاسب بيشوفوا دفعات خزنهم، وكشف العميل محتاجها.

-- الكتابة على الجهاز: فرع الموظف نفسه (مش جهاز في الطريق)، والفني أجهزته بس
create or replace function public.device_writable(p_device uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.devices d where d.id = p_device and d.shop_id = public.current_shop_id()
      and (public.current_app_role() = 'owner' or public.can_branch(d.branch_id))
      and (public.current_app_role() <> 'technician' or public.tech_can_see(d.id)))
$$;
revoke execute on function public.device_writable(uuid) from public, anon;
grant execute on function public.device_writable(uuid) to authenticated;

-- ---------- القراية: الاستعلام على devices بيمشي بسياسات devices نفسها ----------
do $$
declare t text;
begin
  foreach t in array array['device_costs', 'device_photos', 'device_notes', 'status_log', 'device_checks', 'repair_steps', 'device_passcodes', 'quote_decisions', 'device_ratings', 'photo_upload_sessions'] loop
    execute format('create policy reach_%1$s_select on public.%1$I as restrictive for select to authenticated using (exists (select 1 from public.devices d where d.id = device_id))', t);
  end loop;
end $$;
-- رابط الرفع (token) للي بيستلم أو بيعدّل بس
create policy perm_upload_sessions_select on public.photo_upload_sessions as restrictive for select to authenticated
  using ((select public.has_perm('devices', 'edit')) or (select public.has_perm('intake', 'add')));
-- رسالة من غير جهاز (كشف حساب مثلًا): لأصحاب العملاء
create policy reach_message_log_select on public.message_log as restrictive for select to authenticated
  using (case when device_id is null then (select public.has_perm('customers', 'view')) else exists (select 1 from public.devices d where d.id = device_id) end);
-- الدفعة: خزنتها لازم تكون باينة للموظف (فرعه)
create policy reach_payments_select on public.payments as restrictive for select to authenticated
  using (exists (select 1 from public.accounts a where a.id = cashbox_id));

-- ---------- الكتابة ----------
-- التحديث using (true): الصف باين (القراية فوق)، والممنوع بيرجّع خطأ بدل ما يعدّي من غير ما حاجة تتحفظ
create policy reach_device_costs_insert on public.device_costs as restrictive for insert to authenticated with check (public.device_writable(device_id));
create policy reach_device_costs_update on public.device_costs as restrictive for update to authenticated using (true) with check (public.device_writable(device_id));
create policy reach_device_notes_insert on public.device_notes as restrictive for insert to authenticated
  with check ((select public.has_perm('devices', 'view')) and public.device_writable(device_id));
create policy reach_device_notes_update on public.device_notes as restrictive for update to authenticated using (true) with check (public.device_writable(device_id));
create policy reach_device_photos_insert on public.device_photos as restrictive for insert to authenticated
  with check (((select public.has_perm('devices', 'edit')) or (select public.has_perm('intake', 'add'))) and public.device_writable(device_id));
create policy reach_device_photos_update on public.device_photos as restrictive for update to authenticated
  using (true) with check ((select public.has_perm('devices', 'edit')) and public.device_writable(device_id));
create policy reach_device_checks_insert on public.device_checks as restrictive for insert to authenticated
  with check (((select public.has_perm('devices', 'edit')) or (select public.has_perm('intake', 'add'))) and public.device_writable(device_id));
create policy reach_device_checks_update on public.device_checks as restrictive for update to authenticated
  using (true) with check (((select public.has_perm('devices', 'edit')) or (select public.has_perm('intake', 'add'))) and public.device_writable(device_id));
create policy reach_message_log_insert on public.message_log as restrictive for insert to authenticated
  with check (case when device_id is null then (select public.has_perm('customers', 'view')) else exists (select 1 from public.devices d where d.id = device_id) end);

-- ---------- ملفات الصور نفسها ----------
drop policy if exists device_photos_read on storage.objects;
create policy device_photos_read on storage.objects for select to authenticated
  using (
    bucket_id = 'device-photos'
    and (storage.foldername(name))[1] = (select public.current_shop_id())::text
    and exists (select 1 from public.devices d where d.id = case when (storage.foldername(objects.name))[2] ~ '^[0-9a-f]{8}-([0-9a-f]{4}-){3}[0-9a-f]{12}$' then (storage.foldername(objects.name))[2]::uuid end)
  );
-- الرفع: مقيّدة فوق سياسة 0002 (جلسة الرفع من الموبايل بـ token ليها فحصها)
create policy device_photos_upload_reach on storage.objects as restrictive for insert to authenticated
  with check (
    bucket_id <> 'device-photos'
    or public.photo_upload_allowed(name)
    or (((select public.has_perm('devices', 'edit')) or (select public.has_perm('intake', 'add')))
        and public.device_writable(case when (storage.foldername(objects.name))[2] ~ '^[0-9a-f]{8}-([0-9a-f]{4}-){3}[0-9a-f]{12}$' then (storage.foldername(objects.name))[2]::uuid end))
  );

-- ---------- التوزيع: الفني في فرع الجهاز بس ----------
create or replace function public.tech_in_branch(p_tech uuid, p_branch uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(
    (select bool_or(sb.branch_id = p_branch) from public.staff_branches sb join public.branches b on b.id = sb.branch_id and b.deleted_at is null
      where sb.profile_id = p_tech and sb.deleted_at is null),
    -- من غير فروع: الرئيسي (زي my_branch_ids)
    exists (select 1 from public.branches b where b.id = p_branch and b.is_main and b.deleted_at is null))
$$;
revoke execute on function public.tech_in_branch(uuid, uuid) from public, anon, authenticated;

-- pick_technician: (src: 0014_technicians.sql) + فني في فرع الجهاز بس
create or replace function public.pick_technician(p_device uuid, p_specialty uuid) returns uuid
language sql stable security definer set search_path = public as $$
  select coalesce(
    (select s.technician_id from public.repair_steps s join public.profiles p on p.id = s.technician_id and p.deleted_at is null
      where s.device_id = p_device and s.specialty_id = p_specialty and s.technician_id is not null and s.status = 'done'
        and public.tech_in_branch(s.technician_id, (select branch_id from public.devices where id = p_device))
      order by s.step_no desc limit 1),
    (select ss.profile_id from public.staff_specialties ss join public.profiles p on p.id = ss.profile_id and p.deleted_at is null and p.role = 'technician'
      where ss.specialty_id = p_specialty and ss.deleted_at is null and ss.shop_id = public.current_shop_id()
        and public.tech_in_branch(ss.profile_id, (select branch_id from public.devices where id = p_device))
      order by (select count(*) from public.repair_steps x where x.technician_id = ss.profile_id and x.status in ('pending', 'active')), p.full_name
      limit 1),
    -- مفيش حد عنده التخصص: فني عام (ملوش تخصصات)
    (select p.id from public.profiles p
      where p.shop_id = public.current_shop_id() and p.role = 'technician' and p.deleted_at is null
        and public.tech_in_branch(p.id, (select branch_id from public.devices where id = p_device))
        and not exists (select 1 from public.staff_specialties ss where ss.profile_id = p.id and ss.deleted_at is null)
      order by (select count(*) from public.repair_steps x where x.technician_id = p.id and x.status in ('pending', 'active')), p.full_name
      limit 1))
$$;

-- my_queue: (src: 0014_technicians.sql) + فروع الفني بس
create or replace function public.my_queue()
returns table(step_id uuid, device_id uuid, order_no text, brand text, model text, issue text, priority text, status public.device_status,
              received_at timestamptz, est_minutes integer, step_no integer, steps_total integer, specialty_id uuid, step_status text,
              started_at timestamptz, diagnose boolean, late boolean, is_return boolean)
language plpgsql stable security definer set search_path = public as $$
#variable_conflict use_column
begin
  if public.current_app_role() is null then raise exception 'E_FORBIDDEN'; end if;
  return query
  select s.id, d.id, d.order_no, d.brand, d.model, d.issue, d.priority, d.status, d.received_at, d.est_minutes, s.step_no,
         (select count(*)::int from public.repair_steps x where x.device_id = d.id and x.status <> 'skipped'),
         s.specialty_id, s.status, s.started_at, coalesce(r.diagnose, false),
         (d.est_minutes is not null and now() > d.received_at + make_interval(mins => d.est_minutes)) or now() - d.received_at > interval '7 days',
         d.return_of_tech is not null
  from public.repair_steps s
  join public.devices d on d.id = s.device_id and d.deleted_at is null
  left join public.routes r on r.id = s.route_id
  where s.shop_id = public.current_shop_id() and s.status in ('pending', 'active')
    and public.can_branch(d.branch_id)
    and (s.technician_id = auth.uid()
         or (s.technician_id is null and public.tech_has_specialty(auth.uid(), s.specialty_id)))
    and not exists (select 1 from public.repair_steps p where p.device_id = s.device_id and p.step_no < s.step_no and p.status in ('pending', 'active'))
  order by case d.priority when 'urgent' then 0 when 'warranty' then 1 else 2 end, d.received_at;
end $$;

-- start_step: (src: 0014_technicians.sql) + صلاحية الأجهزة وفرع الجهاز
create or replace function public.start_step(p_step uuid) returns void
language plpgsql security definer set search_path = public as $$
declare s public.repair_steps; d public.devices; r public.routes;
begin
  select * into s from public.repair_steps where id = p_step and shop_id = public.current_shop_id() for update;
  if not found then raise exception 'E_NOT_FOUND'; end if;
  if public.current_app_role() = 'technician' then
    if s.technician_id is null and public.tech_has_specialty(auth.uid(), s.specialty_id) then
      s.technician_id := auth.uid();  -- خطوة مش متعيّنة لحد وهو عنده التخصص: بياخدها
    elsif s.technician_id is distinct from auth.uid() then
      raise exception 'E_FORBIDDEN';
    end if;
  elsif public.current_app_role() is distinct from 'owner' then
    raise exception 'E_FORBIDDEN';
  end if;
  if s.status <> 'pending' then raise exception 'E_BAD_TRANSITION'; end if;
  if exists (select 1 from public.repair_steps x where x.device_id = s.device_id and x.step_no < s.step_no and x.status in ('pending', 'active')) then
    raise exception 'E_STEP_ORDER';
  end if;
  perform public.device_require(s.device_id, 'edit');
  select * into d from public.devices where id = s.device_id;
  if d.status = 'awaiting_approval' then raise exception 'E_AWAITING_APPROVAL'; end if;
  if d.status in ('delivered', 'ready', 'unrepairable') then raise exception 'E_BAD_TRANSITION'; end if;
  update public.repair_steps set status = 'active', started_at = now(), technician_id = s.technician_id where id = s.id;
  select * into r from public.routes where id = s.route_id;
  perform public.walk_status(d.id, case when coalesce(r.diagnose, false) or d.status = 'received' then 'inspecting'::public.device_status else 'in_repair'::public.device_status end);
end $$;

-- finish_step: (src: 0014_technicians.sql) + صلاحية الأجهزة وفرع الجهاز
create or replace function public.finish_step(p_step uuid, p_check jsonb default null, p_next_route uuid default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  s public.repair_steps;
  r public.routes;
  nxt public.repair_steps;
  ck uuid;
begin
  select * into s from public.repair_steps where id = p_step and shop_id = public.current_shop_id() for update;
  if not found then raise exception 'E_NOT_FOUND'; end if;
  if public.current_app_role() = 'technician' and s.technician_id is distinct from auth.uid() then raise exception 'E_FORBIDDEN'; end if;
  if public.current_app_role() not in ('owner', 'technician') then raise exception 'E_FORBIDDEN'; end if;
  perform public.device_require(s.device_id, 'edit');
  if s.status <> 'active' then raise exception 'E_BAD_TRANSITION'; end if;
  if (select status from public.devices where id = s.device_id) = 'awaiting_approval' then raise exception 'E_AWAITING_APPROVAL'; end if;
  select * into r from public.routes where id = s.route_id;
  select * into nxt from public.repair_steps where device_id = s.device_id and step_no > s.step_no and status = 'pending' order by step_no limit 1;

  if nxt.id is null and coalesce(r.diagnose, false) then
    -- الفحص خلص: الفني بيحدد المسار
    if p_next_route is null then raise exception 'E_ROUTE_REQUIRED'; end if;
    update public.repair_steps set status = 'done', finished_at = now() where id = s.id;
    perform public.set_route(s.device_id, p_next_route);
    select * into nxt from public.repair_steps where device_id = s.device_id and status = 'pending' order by step_no limit 1;
    return jsonb_build_object('next_step', nxt.id, 'next_tech', nxt.technician_id, 'ready', false);
  end if;

  if nxt.id is null then
    -- آخر خطوة: الفحص النهائي بنفس قائمة الفحص السريع
    if p_check is null or jsonb_typeof(p_check) <> 'object' or p_check = '{}'::jsonb then raise exception 'E_FINAL_CHECK_REQUIRED'; end if;
    select id into ck from public.device_checks where device_id = s.device_id and stage = 'delivery' and deleted_at is null;
    if ck is null then
      insert into public.device_checks(id, shop_id, device_id, stage, items) values (gen_random_uuid(), s.shop_id, s.device_id, 'delivery', p_check);
    else
      update public.device_checks set items = p_check where id = ck;
    end if;
    update public.repair_steps set status = 'done', finished_at = now() where id = s.id;
    perform public.walk_status(s.device_id, 'ready');
    return jsonb_build_object('next_step', null, 'ready', true);
  end if;

  update public.repair_steps set status = 'done', finished_at = now() where id = s.id;
  if nxt.technician_id is null then
    update public.repair_steps set technician_id = public.pick_technician(s.device_id, nxt.specialty_id) where id = nxt.id returning * into nxt;
  end if;
  return jsonb_build_object('next_step', nxt.id, 'next_tech', nxt.technician_id, 'ready', false);
end $$;

-- reassign_step: (src: 0070_perm_matrix.sql) + الفني لازم يكون في فرع الجهاز
create or replace function public.reassign_step(p_step uuid, p_tech uuid) returns void
language plpgsql security definer set search_path = public as $$
declare s public.repair_steps;
begin
  perform public.ledger_require(array['owner', 'reception']::public.app_role[]);
  select * into s from public.repair_steps where id = p_step and shop_id = public.current_shop_id() for update;
  if not found or s.status not in ('pending', 'active') then raise exception 'E_NOT_FOUND'; end if;
  perform public.device_require(s.device_id, 'edit');
  if p_tech is not null and not exists (select 1 from public.profiles where id = p_tech and shop_id = s.shop_id and role = 'technician' and deleted_at is null) then raise exception 'E_NOT_FOUND'; end if;
  if p_tech is not null and not public.tech_in_branch(p_tech, (select branch_id from public.devices where id = s.device_id)) then raise exception 'E_TECH_BRANCH'; end if;
  update public.repair_steps set technician_id = p_tech, status = case when status = 'active' then 'pending' else status end, started_at = null where id = s.id;
end $$;

-- record_payment: (src: 0036_roles.sql) + جهاز يوصله الموظف بس
create or replace function public.record_payment(p_id uuid, p_customer uuid, p_cashbox uuid, p_amount bigint, p_device uuid default null, p_method text default null, p_note text default null)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  cb public.accounts;
  e uuid;
  dev public.devices;
begin
  perform public.ledger_require(array['owner', 'reception']::public.app_role[]);
  perform public.perm_require('cashbox', 'add');
  e := public.ledger_idem(p_id);
  if e is not null then return e; end if;
  perform public.ledger_amount(p_amount);
  cb := public.ledger_cashbox(p_cashbox);
  if not exists (select 1 from public.customers where id = p_customer and shop_id = cb.shop_id and deleted_at is null) then raise exception 'E_NOT_FOUND'; end if;
  if p_device is not null then
    select * into dev from public.devices where id = p_device and shop_id = cb.shop_id and deleted_at is null;
    if not found or dev.customer_id <> p_customer then raise exception 'E_CROSS_SHOP'; end if;
    -- أو كان في فرعي واتنقل: كاش اتحصّل أوفلاين قبل النقل لازم يتسجل
    if public.device_reach(p_device) is not true and not exists (
        select 1 from public.audit_log l where l.shop_id = cb.shop_id and l.entity = 'devices' and l.entity_id = p_device and l.action = 'device_receive' and public.can_branch((l.before ->> 'branch')::uuid)) then
      raise exception 'E_FORBIDDEN';
    end if;
  end if;
  e := public.ledger_post('payment', p_id, p_note, jsonb_build_array(
    public.ledger_line(cb.id, p_amount, 0),
    public.ledger_line(public.ledger_acc('ar'), 0, p_amount, 'customer', p_customer)
  ), p_device, p_id);
  insert into public.payments(id, shop_id, customer_id, device_id, cashbox_id, method, amount, entry_id, created_by)
  values (p_id, cb.shop_id, p_customer, p_device, cb.id, coalesce(p_method, cb.method), p_amount, e, auth.uid());
  return e;
end $$;

-- receive_device: (src: 0070_perm_matrix.sql) + الخطوات المفتوحة بتتوزع على فنيين الفرع الجديد
create or replace function public.receive_device(p_device uuid) returns void
language plpgsql security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); d public.devices;
begin
  perform public.ledger_require(array['owner', 'reception']::public.app_role[]);
  if public.has_perm('devices', 'edit') is not true then raise exception 'E_FORBIDDEN'; end if;
  select * into d from public.devices where id = p_device and shop_id = s and deleted_at is null for update;
  if not found or d.transfer_to is null then raise exception 'E_NOT_FOUND'; end if;
  if not public.can_branch(d.transfer_to) then raise exception 'E_FORBIDDEN'; end if;
  perform set_config('app.device_move', 'on', true);
  update public.devices set branch_id = d.transfer_to, transfer_to = null, transfer_at = null, transfer_by = null where id = d.id;
  perform set_config('app.device_move', 'off', true);
  update public.repair_steps st set technician_id = public.pick_technician(d.id, st.specialty_id), status = 'pending', started_at = null
  where st.device_id = d.id and st.status in ('pending', 'active') and st.technician_id is not null and not public.tech_in_branch(st.technician_id, d.transfer_to);
  insert into public.audit_log(shop_id, actor_id, action, entity, entity_id, before, after)
  values (s, auth.uid(), 'device_receive', 'devices', d.id, jsonb_build_object('branch', d.branch_id), jsonb_build_object('branch', d.transfer_to));
end $$;

-- tg_device_warranty_tech: (src: 0014_technicians.sql) + الفني لازم يكون لسه في فرع الجهاز، وإلا توزيع جديد
create or replace function public.tg_device_warranty_tech() returns trigger
language plpgsql security definer set search_path = public as $$
declare t uuid; sp uuid; n int;
begin
  if new.status = 'warranty_return' and old.status is distinct from 'warranty_return' then
    select s.technician_id, s.specialty_id into t, sp from public.repair_steps s
     where s.device_id = new.id and s.status = 'done' and s.technician_id is not null order by s.step_no desc limit 1;
    if t is not null and not public.tech_in_branch(t, new.branch_id) then t := public.pick_technician(new.id, sp); end if;
    perform set_config('warsha.routing', 'on', true);
    update public.devices set priority = 'warranty', return_of_tech = t where id = new.id;
    perform set_config('warsha.routing', 'off', true);
    if sp is not null then
      select coalesce(max(step_no), 0) into n from public.repair_steps where device_id = new.id;
      insert into public.repair_steps(shop_id, device_id, route_id, step_no, specialty_id, technician_id)
      values (new.shop_id, new.id, new.route_id, n + 1, sp, t);
    end if;
  end if;
  return null;
end $$;

-- device_tech_name: (src: 0014_technicians.sql) + جهاز يوصله الموظف بس
create or replace function public.device_tech_name(p_device uuid) returns text
language sql stable security definer set search_path = public as $$
  select split_part(p.full_name, ' ', 1) from public.repair_steps s join public.profiles p on p.id = s.technician_id
  where s.device_id = p_device and s.shop_id = public.current_shop_id() and public.device_reach(p_device) and s.status in ('active', 'pending', 'done')
  order by case s.status when 'active' then 0 when 'pending' then 1 else 2 end, s.step_no desc limit 1
$$;
$m0071$;
  insert into public.app_migrations(version, how) values ('0071_device_children.sql', 'applied');
  raise notice 'applied %', '0071_device_children.sql';
end $run$;
commit;

-- ============================== 0072_sale_line_return.sql ==============================
begin;
do $run$ begin
  if exists (select 1 from public.app_migrations where version = '0072_sale_line_return.sql') then return; end if;
  execute $m0072$
-- 0072: (3) مرتجع مربوط بسطر البيع: بكميته وسعره وضريبته وتكلفته وقت البيع، وما يزيدش عن اللي اتباع.
-- صف المرتجع في sale_lines نفسه: return_of = سطر البيع الأصلي، وentry_id = قيد المرتجع. إضافة بس زي الباقي.

alter table public.sale_lines add column return_of uuid references public.sale_lines(id);
create index sale_lines_return_of on public.sale_lines(return_of) where return_of is not null;

-- نوع الصنف بيحدد حساب إيراده: صنف اتباع ما يتغيّرش نوعه (المرتجع وتقسيم الإيراد بيعتمدوا عليه)
create or replace function public.tg_item_kind_fixed() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.kind is distinct from old.kind and not public.restoring() and exists (select 1 from public.sale_lines l where l.item_id = old.id) then
    raise exception 'E_ITEM_KIND';
  end if;
  return new;
end $$;
create trigger b_item_kind_fixed before update of kind on public.items for each row execute function public.tg_item_kind_fixed();
create index sale_lines_item on public.sale_lines(item_id);

-- حساب الإيراد من نوع الصنف (نفس تقسيم record_sale)
create or replace function public.item_rev_code(p_kind text) returns text
language sql immutable as $$
  select case p_kind when 'service' then 'rev_repair' when 'part' then 'rev_parts' else 'rev_accessories' end
$$;
revoke execute on function public.item_rev_code(text) from public, anon, authenticated;

-- اللي رجع من سطر بيع (المرتجع الملغي بقيد عكسي ما بيتحسبش)
create or replace function public.sale_line_returned(p_line uuid) returns bigint
language sql stable security definer set search_path = public as $$
  select coalesce(sum(r.qty), 0)::bigint from public.sale_lines r
  where r.return_of = p_line and not exists (select 1 from public.journal_entries x where x.reverses_id = r.entry_id)
$$;
revoke execute on function public.sale_line_returned(uuid) from public, anon, authenticated;

-- الفاتورة برقمها عشان المرتجع: السطور واللي رجع من كل سطر، من غير تكلفة ولا بيانات العميل
create or replace function public.sale_for_return(p_no bigint) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); o public.journal_entries;
begin
  perform public.ledger_require(array['owner', 'reception']::public.app_role[]);
  if public.has_perm('sales', 'edit') is not true then raise exception 'E_FORBIDDEN'; end if;
  select * into o from public.journal_entries where entry_no = p_no and shop_id = s and source_type = 'sale'
    and (public.current_app_role() = 'owner' or public.can_branch(branch_id))
    -- بعد الاسترجاع ممكن رقم قديم يتكرر: الأحدث (والشاشة بتعرض التاريخ)
    order by occurred_at desc limit 1;
  if not found then raise exception 'E_NOT_FOUND'; end if;
  return jsonb_build_object('entry', o.id, 'entry_no', o.entry_no, 'at', o.occurred_at, 'branch_id', o.branch_id,
    'cancelled', exists (select 1 from public.journal_entries r where r.reverses_id = o.id),
    'credit', exists (select 1 from public.journal_lines l join public.accounts a on a.id = l.account_id where l.entry_id = o.id and a.kind = 'receivable'),
    'has_customer', exists (select 1 from public.sale_lines l join public.customers c on c.id = l.customer_id and c.deleted_at is null where l.entry_id = o.id),
    'lines', coalesce((select jsonb_agg(jsonb_build_object('id', l.id, 'name', l.name, 'qty', l.qty, 'price', l.price, 'returned', public.sale_line_returned(l.id),
        'service', i.kind = 'service') order by l.seq)
      from public.sale_lines l join public.items i on i.id = l.item_id where l.entry_id = o.id), '[]'::jsonb));
end $$;
revoke execute on function public.sale_for_return(bigint) from public, anon;
grant execute on function public.sale_for_return(bigint) to authenticated;

create or replace function public.sale_line_return(p_id uuid, p_line uuid, p_qty integer, p_cashbox uuid default null, p_restock boolean default true, p_reason text default null) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  s uuid := public.current_shop_id(); e uuid; sl public.sale_lines; o public.journal_entries; it public.items; cb public.accounts;
  cust uuid; amt bigint; rev uuid; gross bigint; net bigint; back bigint; vat_back bigint; v bigint;
  sold bigint; sold_cost bigint; item_back bigint; cost_back bigint; cost bigint := 0;
begin
  perform public.ledger_require(array['owner', 'reception']::public.app_role[]);
  perform public.perm_require('sales', 'edit');
  e := public.ledger_idem(p_id);
  if e is not null then return e; end if;
  if nullif(trim(p_reason), '') is null then raise exception 'E_REASON_REQUIRED'; end if;
  select * into sl from public.sale_lines where id = p_line and shop_id = s and return_of is null;
  if not found then raise exception 'E_NOT_FOUND'; end if;
  -- القفل على قيد البيع: مرتجعين في نفس اللحظة (أو مرتجع وإلغاء) ما يعدّوش مع بعض
  select * into o from public.journal_entries where id = sl.entry_id and shop_id = s and source_type = 'sale' for update;
  if not found then raise exception 'E_NOT_FOUND'; end if;
  if public.current_app_role() <> 'owner' and not public.can_branch(o.branch_id) then raise exception 'E_FORBIDDEN'; end if;
  if exists (select 1 from public.journal_entries r where r.reverses_id = o.id) then raise exception 'E_ALREADY_REVERSED'; end if;
  -- موبايل مستعمل: بيترجع بإلغاء بيعه (عشان حالته ترجع "متاح")
  if exists (select 1 from public.used_devices u where u.sold_entry = o.id and u.item_id = sl.item_id) then raise exception 'E_USED_RETURN'; end if;
  if p_qty is null or p_qty <= 0 or p_qty > sl.qty - public.sale_line_returned(sl.id) then raise exception 'E_RETURN_QTY'; end if;
  select * into it from public.items where id = sl.item_id and shop_id = s for update;
  if p_restock and it.deleted_at is not null then raise exception 'E_NOT_FOUND'; end if;
  amt := p_qty * sl.price;
  perform set_config('app.branch', o.branch_id::text, true);

  -- البيع الآجل بيتخصم من حساب العميل بس (ما ياخدش كاش على حاجة ما دفعهاش)، والكاش من خزنة فرع البيع أو رصيد للعميل المعروف
  select max(l.party_id::text)::uuid into cust from public.journal_lines l join public.accounts a on a.id = l.account_id where l.entry_id = o.id and a.kind = 'receivable';
  if cust is not null then
    if p_cashbox is not null then raise exception 'E_RETURN_CREDIT'; end if;
  elsif p_cashbox is not null then
    cb := public.ledger_cashbox(p_cashbox);
    if cb.branch_id is distinct from o.branch_id then raise exception 'E_BAD_BRANCH'; end if;
  else
    select c.id into cust from public.customers c where c.id = sl.customer_id and c.deleted_at is null;
    if cust is null and amt > 0 then raise exception 'E_BAD_INPUT'; end if;
  end if;

  -- الضريبة من قيد البيع نفسه (مش النسبة الحالية): نصيب تراكمي من نفس نوع الإيراد، فآخر مرتجع بيقفلها بالقرش
  rev := public.ledger_acc(public.item_rev_code(it.kind));
  select coalesce(sum(l.qty * l.price), 0) into gross from public.sale_lines l join public.items i on i.id = l.item_id
    where l.entry_id = o.id and public.item_rev_code(i.kind) = public.item_rev_code(it.kind);
  select coalesce(sum(l.credit), 0) into net from public.journal_lines l where l.entry_id = o.id and l.account_id = rev;
  -- نوع الصنف اتغيّر قبل ما يتمنع تغييره: الإيراد مش في نفس الحساب
  if amt > 0 and (net <= 0 or net > gross or (gross > net and not exists (
      select 1 from public.journal_lines l join public.accounts a on a.id = l.account_id where l.entry_id = o.id and a.kind = 'tax' and l.credit >= gross - net))) then raise exception 'E_BAD_INPUT'; end if;
  select coalesce(sum(r.qty * r.price), 0),
         coalesce(sum((select sum(l.debit) from public.journal_lines l join public.accounts a on a.id = l.account_id where l.entry_id = r.entry_id and a.kind = 'tax')), 0)
    into back, vat_back
  from public.sale_lines r join public.sale_lines b on b.id = r.return_of join public.items i on i.id = b.item_id
  where b.entry_id = o.id and not exists (select 1 from public.journal_entries x where x.reverses_id = r.entry_id)
    and public.item_rev_code(i.kind) = public.item_rev_code(it.kind);
  v := 0;
  if gross > net then
    -- أقرب قرش بأعداد صحيحة (numeric عشان المبالغ الكبيرة ما تفيضش)
    v := div((gross - net)::numeric * (back + amt) * 2 + gross, 2 * gross::numeric)::bigint - vat_back;
    v := least(greatest(v, 0), amt);
  end if;

  -- التكلفة زي ما خرجت في البيع نفسه، بنصيب تراكمي من اللي رجع المخزون فعلًا
  if it.kind <> 'service' and p_restock then
    select coalesce(-sum(m.qty), 0), coalesce(-sum(m.value), 0) into sold, sold_cost from public.stock_moves m where m.entry_id = o.id and m.item_id = sl.item_id;
    -- بيع من غير تكلفة (بيتسوى وقت الشراء): تكلفته مش معروفة من البيع، فبيترجع من غير فاتورة
    if sold <= 0 or exists (select 1 from public.uncosted_sales u where u.entry_id = o.id and u.item_id = sl.item_id and u.deleted_at is null) then raise exception 'E_RETURN_UNCOSTED'; end if;
    select coalesce(sum(m.qty), 0), coalesce(sum(m.value), 0) into item_back, cost_back
      from public.stock_moves m join public.sale_lines r on r.entry_id = m.entry_id and r.item_id = m.item_id join public.sale_lines b on b.id = r.return_of
      where b.entry_id = o.id and m.item_id = sl.item_id and not exists (select 1 from public.journal_entries x where x.reverses_id = r.entry_id);
    cost := greatest(0, div(sold_cost::numeric * (item_back + p_qty), sold::numeric)::bigint - cost_back);
  end if;
  if amt = 0 and cost = 0 then raise exception 'E_BAD_AMOUNT'; end if;

  e := gen_random_uuid();
  insert into public.journal_entries(id, shop_id, source_type, source_id, memo, idem_key, created_by)
  values (e, s, 'sale_return', sl.item_id, left(trim(p_reason), 300), p_id, auth.uid());
  insert into public.sale_lines(shop_id, entry_id, item_id, name, qty, price, seq, customer_id, return_of)
  values (s, e, sl.item_id, sl.name, p_qty, sl.price, 1, coalesce(cust, sl.customer_id), sl.id);
  if amt > 0 then
    if amt > v then insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values (s, e, rev, amt - v, 0); end if;
    if v > 0 then insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values (s, e, public.ledger_acc('vat_payable'), v, 0); end if;
    if cb.id is not null then
      insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values (s, e, cb.id, 0, amt);
    else
      insert into public.journal_lines(shop_id, entry_id, account_id, party_type, party_id, debit, credit) values (s, e, public.ledger_acc('ar'), 'customer', cust, 0, amt);
    end if;
  end if;
  -- السليم بيرجع المخزون، والتالف تكلفته بتفضل مصروف (زي sale_return)
  if it.kind <> 'service' and p_restock then
    if cost > 0 then
      insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values
        (s, e, public.ledger_acc('inventory'), cost, 0), (s, e, public.ledger_acc('cogs'), 0, cost);
    end if;
    insert into public.stock_moves(shop_id, item_id, entry_id, qty, value) values (s, sl.item_id, e, p_qty, cost);
  end if;
  return e;
end $$;
revoke execute on function public.sale_line_return(uuid, uuid, integer, uuid, boolean, text) from public, anon;
grant execute on function public.sale_line_return(uuid, uuid, integer, uuid, boolean, text) to authenticated;

-- reverse_entry: (src: 0070_perm_matrix.sql) + بيع رجع منه حاجة ما يتلغيش قبل ما المرتجع نفسه يتلغي (الفلوس ما ترجعش مرتين)
CREATE OR REPLACE FUNCTION public.reverse_entry(p_entry uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  o public.journal_entries;
  e uuid;
  lines jsonb;
  mv record;
begin
  if public.current_app_role() is null or not public.can_correct() then raise exception 'E_FORBIDDEN'; end if;
  -- C3: كلمة السر الرئيسية (لو صاحب المحل حددها)
  perform public.master_require();
  if nullif(trim(p_reason), '') is null then raise exception 'E_REASON_REQUIRED'; end if;
  select * into o from public.journal_entries where id = p_entry and shop_id = public.current_shop_id() for update;
  if not found then raise exception 'E_NOT_FOUND'; end if;
  perform public.entry_require(o.id);
  if o.source_type in ('reversal', 'cost_adjust') or exists (select 1 from public.journal_entries where reverses_id = o.id) then
    raise exception 'E_ALREADY_REVERSED';
  end if;
  if o.source_type = 'sale' and exists (select 1 from public.sale_lines sl where sl.entry_id = o.id and public.sale_line_returned(sl.id) > 0) then
    raise exception 'E_HAS_RETURNS';
  end if;
  select jsonb_agg(public.ledger_line(account_id, credit, debit, party_type, party_id)) into lines
  from public.journal_lines where entry_id = o.id;
  -- العكس بيتسجل في نفس فرع القيد الأصلي
  perform set_config('app.branch', o.branch_id::text, true);
  e := public.ledger_post('reversal', o.source_id, p_reason, lines, o.device_id, null, o.id);
  for mv in select * from public.stock_moves where entry_id = o.id loop
    perform 1 from public.items where id = mv.item_id for update;
    if (select coalesce(sum(qty), 0) from public.stock_moves where item_id = mv.item_id and branch_id = mv.branch_id) - mv.qty < 0 then
      raise exception 'E_STOCK';
    end if;
    insert into public.stock_moves(shop_id, item_id, entry_id, qty, value, branch_id) values (mv.shop_id, mv.item_id, e, -mv.qty, -mv.value, mv.branch_id);
  end loop;
  for mv in select distinct item_id, branch_id from public.stock_moves where entry_id = o.id loop
    perform public.ledger_settle_item(mv.item_id, o.device_id, mv.branch_id);
  end loop;
  insert into public.audit_log(shop_id, actor_id, action, entity, entity_id, before, after)
  values (o.shop_id, auth.uid(), 'reverse_entry', 'journal_entries', o.id, to_jsonb(o), jsonb_build_object('reversal_id', e, 'reason', p_reason));
  return e;
end $function$;
$m0072$;
  insert into public.app_migrations(version, how) values ('0072_sale_line_return.sql', 'applied');
  raise notice 'applied %', '0072_sale_line_return.sql';
end $run$;
commit;

-- ============================== 0073_shop_extras.sql ==============================
begin;
do $run$ begin
  if exists (select 1 from public.app_migrations where version = '0073_shop_extras.sql') then return; end if;
  execute $m0073$
-- 0073: (26) حفظ إعدادات المحل (shops.extras) مفتاح بمفتاح، وفحص "المحل فاضي" في الاسترجاع يشمل الحضور.

-- كل شاشة كانت بتكتب extras كله من نسختها، فتعديلين قريبين واحد يمسح التاني. هنا بيتعدّل المفاتيح المبعوتة بس.
-- p_merge: لو القيمة القديمة والجديدة object، الجديدة بتتحط فوق القديمة (مثلًا reminders اللي شاشتين بتعدّله)
-- shortcut: الدمج مستوى واحد، وقيمة واحدة بتتعدّل من جهازين في نفس اللحظة (مصفوفة أو اختصارات) الأخيرة تكسب. لو احتجناها: دمج أعمق
create or replace function public.set_shop_extras(p_patch jsonb, p_merge boolean default false) returns void
language plpgsql security definer set search_path = public as $$
begin
  perform public.ledger_require(array['owner']::public.app_role[]);
  if p_patch is null or jsonb_typeof(p_patch) <> 'object' or p_patch = '{}'::jsonb then raise exception 'E_BAD_INPUT'; end if;
  -- نفس الـ update: التعديل التاني بيستنى الأول وبيبني على اللي اتحفظ
  update public.shops sh set extras = coalesce(sh.extras, '{}'::jsonb) || (
    select jsonb_object_agg(k.key, case when p_merge and jsonb_typeof(k.value) = 'object' and jsonb_typeof(sh.extras -> k.key) = 'object'
                                        then (sh.extras -> k.key) || k.value else k.value end)
    from jsonb_each(p_patch) k)
  where sh.id = public.current_shop_id();
  if not found then raise exception 'E_FORBIDDEN'; end if;
end $$;
revoke execute on function public.set_shop_extras(jsonb, boolean) from public, anon;
grant execute on function public.set_shop_extras(jsonb, boolean) to authenticated;

-- restore_backup: (src: 0063_cheques.sql) + سجل حضور (مش ملغي) = المحل مش فاضي
create or replace function public.restore_backup(p_data jsonb) returns jsonb
-- extensions: فيها gen_random_bytes على Supabase
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare
  s uuid := public.current_shop_id();
  me uuid := auth.uid();
  old_shop uuid;
  old_owner uuid;
  sh jsonb;
  t text;
  r jsonb;
  rows jsonb;
  n int;
  bad int;
  counts jsonb := '{}'::jsonb;
  -- بالترتيب ده عشان كل صف يلاقي اللي بيشاور عليه
  tabs text[] := array['branches', 'profiles', 'staff_branches', 'attendance', 'shop_branding', 'accounts', 'customers', 'suppliers', 'party_links', 'partners', 'specialties', 'staff_specialties', 'routes', 'labor_rates',
                       'issue_presets', 'commission_rules', 'shop_lists', 'message_templates', 'categories', 'items', 'devices', 'device_costs', 'status_log', 'device_notes', 'device_checks',
                       'quote_decisions', 'repair_steps', 'repair_videos', 'device_ratings', 'journal_entries', 'journal_lines', 'sale_lines', 'cheques', 'profit_distributions', 'payments',
                       'purchases', 'stock_moves', 'uncosted_sales', 'used_devices', 'payment_plans', 'plan_installments', 'branch_goals', 'printers', 'print_templates', 'check_templates', 'drawer_closings', 'message_log', 'audit_log'];
  -- الجداول دي ليها نسخة اتعملت مع التسجيل: بتتطابق بالكود (أو المفتاح) وبتاخد قيم النسخة
  keyed text[] := array['branches', 'accounts', 'routes', 'specialties', 'message_templates', 'labor_rates', 'shop_branding'];
begin
  perform public.ledger_require(array['owner']::public.app_role[]);
  if s is null or me is null then raise exception 'E_FORBIDDEN'; end if;
  if p_data is null or p_data->>'format' is distinct from 'warsha-backup' or coalesce((p_data->>'version')::int, 0) <> 1 then
    raise exception 'E_BACKUP_FORMAT';
  end if;
  old_shop := (p_data->>'shop_id')::uuid;
  if old_shop is null or old_shop = s then raise exception 'E_BACKUP_FORMAT'; end if;

  -- محل جديد فاضي بس
  if exists (select 1 from public.devices where shop_id = s) or exists (select 1 from public.customers where shop_id = s)
     or exists (select 1 from public.journal_entries where shop_id = s) or exists (select 1 from public.items where shop_id = s)
     or exists (select 1 from public.suppliers where shop_id = s) or exists (select 1 from public.payments where shop_id = s)
     or exists (select 1 from public.purchases where shop_id = s) or exists (select 1 from public.drawer_closings where shop_id = s)
     or exists (select 1 from public.stock_moves where shop_id = s)
     or exists (select 1 from public.attendance where shop_id = s and deleted_at is null)
     or exists (select 1 from public.profiles where shop_id = s and id <> me) then
    raise exception 'E_RESTORE_NOT_EMPTY';
  end if;

  perform set_config('warsha.restore', 'on', true);
  drop table if exists pg_temp._rmap;
  create temp table _rmap(old uuid primary key, new uuid not null) on commit drop;
  insert into _rmap values (old_shop, s);

  -- 1) بيانات المحل نفسه (من غير الخطة والإيقاف واللوجو اللي في Storage)
  sh := p_data->'shops'->0;
  if sh is not null then
    update public.shops set
      name = coalesce(sh->>'name', name), phone = sh->>'phone', address = sh->>'address',
      receipt_terms = coalesce(sh->>'receipt_terms', receipt_terms), warranty_days = coalesce((sh->>'warranty_days')::int, warranty_days),
      country = coalesce(sh->>'country', country), currency = coalesce(sh->>'currency', currency),
      payment_methods = coalesce(array(select jsonb_array_elements_text(sh->'payment_methods')), payment_methods),
      theme = coalesce(sh->>'theme', theme), locale = coalesce(sh->>'locale', locale),
      default_margin_pct = coalesce((sh->>'default_margin_pct')::int, default_margin_pct),
      extras = coalesce(sh->'extras', extras), max_discount_pct = coalesce((sh->>'max_discount_pct')::int, max_discount_pct)
    where id = s;
  end if;

  -- 2) الـ ids الجديدة
  -- صاحب المحل في النسخة = اللي بيسترجع دلوقتي
  select (x->>'id')::uuid into old_owner from jsonb_array_elements(coalesce(p_data->'profiles', '[]')) x
   where x->>'role' = 'owner' order by x->>'created_at' limit 1;
  if old_owner is not null then insert into _rmap values (old_owner, me) on conflict do nothing; end if;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.accounts a where a.shop_id = s and a.code = x->>'code' and x->>'code' is not null), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'accounts', '[]')) x on conflict do nothing;
  -- الفرع الرئيسي في النسخة = الفرع الرئيسي للمحل الجديد
  insert into _rmap select (x->>'id')::uuid, public.main_branch(s)
    from jsonb_array_elements(coalesce(p_data->'branches', '[]')) x where (x->>'is_main')::boolean and x->>'deleted_at' is null on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.routes a where a.shop_id = s and a.code = x->>'code' and x->>'code' is not null), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'routes', '[]')) x on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.specialties a where a.shop_id = s and a.code = x->>'code' and x->>'code' is not null), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'specialties', '[]')) x on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.message_templates a where a.shop_id = s and a.key = x->>'key'), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'message_templates', '[]')) x on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.labor_rates a where a.shop_id = s and a.deleted_at is null and lower(trim(a.issue)) = lower(trim(x->>'issue')) and x->>'deleted_at' is null), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'labor_rates', '[]')) x on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.shop_branding a where a.shop_id = s), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'shop_branding', '[]')) x on conflict do nothing;
  foreach t in array tabs loop
    insert into _rmap select (x->>'id')::uuid, gen_random_uuid() from jsonb_array_elements(coalesce(p_data->t, '[]')) x where x ? 'id' on conflict do nothing;
  end loop;

  -- 3) الصفوف نفسها بالترتيب
  foreach t in array tabs loop
    rows := '[]'::jsonb;
    for r in select public.restore_remap(x) from jsonb_array_elements(coalesce(p_data->t, '[]')) x loop
      if t = 'profiles' then
        -- صاحب المحل موجود أصلًا. الباقيين موظفين سابقين (من غير حساب دخول)
        continue when (r->>'id')::uuid = me;
        r := r || jsonb_build_object('deleted_at', coalesce(r->>'deleted_at', now()::text));
      elsif t = 'devices' then
        -- كود التتبع (الـ QR) بيفضل زي ما هو، إلا لو مستخدم في المشروع ده (المحل الأصلي لسه هنا)
        if exists (select 1 from public.devices d where d.tracking_token = r->>'tracking_token') then
          r := r || jsonb_build_object('tracking_token', encode(gen_random_bytes(12), 'hex'));
        end if;
      elsif t = 'journal_entries' then
        if r->>'idem_key' is not null and exists (select 1 from public.journal_entries j where j.idem_key = (r->>'idem_key')::uuid) then
          r := r || jsonb_build_object('idem_key', gen_random_uuid());
        end if;
      elsif t = 'accounts' and r->>'kind' = 'cash' and r->>'branch_id' is null then
        -- نسخة من قبل الفروع: الخزن كلها في الفرع الرئيسي
        r := r || jsonb_build_object('branch_id', public.main_branch(s));
      elsif t = 'used_devices' then
        -- رقم بطاقة البائع (في Vault) وصورتها (في Storage) مش جوه النسخة
        r := r || jsonb_build_object('seller_nid_secret', null, 'seller_photo', null);
      elsif t = 'shop_branding' then
        -- اللوجو الملون والحراري جوه الصف نفسه. الملف الأصلي في Storage مش جوه النسخة
        r := r || jsonb_build_object('logo_path', null);
      end if;
      if t = any (keyed) and exists (select 1 from _rmap m where m.new = (r->>'id')::uuid and m.old <> m.new)
         and (t <> 'shop_branding' or exists (select 1 from public.shop_branding b where b.id = (r->>'id')::uuid)) then
        -- موجود من التسجيل: بياخد قيم النسخة
        execute format('select count(*) from public.%I where id = $1', t) into n using (r->>'id')::uuid;
        if n > 0 then
          execute format('update public.%1$I x set (%2$s) = (select %2$s from jsonb_populate_record(null::public.%1$I, $1)) where x.id = $2', t,
            (select string_agg(quote_ident(c.column_name), ', ' order by c.ordinal_position) from information_schema.columns c
              where c.table_schema = 'public' and c.table_name = t and c.column_name not in ('id', 'shop_id')))
            using r, (r->>'id')::uuid;
          continue;
        end if;
      end if;
      rows := rows || jsonb_build_array(r);
    end loop;
    if jsonb_array_length(rows) > 0 then
      -- overriding system value: أرقام القيود (entry_no) بترجع زي ما هي
      execute format('insert into public.%1$I overriding system value select * from jsonb_populate_recordset(null::public.%1$I, $1)', t) using rows;
    end if;
    counts := counts || jsonb_build_object(t, jsonb_array_length(coalesce(p_data->t, '[]')));
  end loop;

  -- 4) عدّاد أرقام الطلبات: من آخر رقم راجع في كل سنة
  -- (لكل فرع: الرقم ممكن يبقى قبله بادئة الفرع B2-2026-0001)
  insert into public.order_counters(shop_id, branch_id, year, last_value)
  select s, branch_id, (regexp_match(order_no, '(\d{4})-(\d+)$'))[1]::int, max((regexp_match(order_no, '(\d{4})-(\d+)$'))[2]::int)
    from public.devices where shop_id = s and order_no ~ '\d{4}-\d+$' group by 2, 3
  on conflict (shop_id, branch_id, year) do update set last_value = greatest(public.order_counters.last_value, excluded.last_value);

  -- 5) التأكد: كل قيد متوازن، ورصيد كل حساب = رصيده في النسخة بالظبط
  select count(*) into bad from (
    select entry_id from public.journal_lines where shop_id = s group by entry_id having sum(debit) <> sum(credit)) x;
  if bad > 0 then raise exception 'E_RESTORE_UNBALANCED'; end if;
  select count(*) into bad from (
    select m.new acc, sum((l->>'debit')::bigint - (l->>'credit')::bigint) b
      from jsonb_array_elements(coalesce(p_data->'journal_lines', '[]')) l join _rmap m on m.old = (l->>'account_id')::uuid group by m.new
  ) x full join (select account_id, sum(debit - credit) b from public.journal_lines where shop_id = s group by account_id) y on y.account_id = x.acc
  where coalesce(x.b, 0) <> coalesce(y.b, 0);
  if bad > 0 then raise exception 'E_RESTORE_MISMATCH'; end if;
  -- وعدد الصفوف في كل جدول (الحسابات والقوالب اللي اتعملت مع التسجيل ممكن تزيد عن النسخة، مش تقل)
  foreach t in array tabs loop
    execute format('select count(*) from public.%I where shop_id = $1', t) into n using s;
    if n < jsonb_array_length(coalesce(p_data->t, '[]')) - (case when t = 'profiles' and old_owner is not null then 1 else 0 end) then
      raise exception 'E_RESTORE_MISMATCH';
    end if;
  end loop;

  perform set_config('warsha.restore', 'off', true);
  insert into public.audit_log(shop_id, actor_id, action, entity, entity_id, after)
  values (s, me, 'backup_restore', 'shops', s, jsonb_build_object('from_shop', old_shop, 'generated_at', p_data->>'generated_at', 'counts', counts));
  return jsonb_build_object('restored', true, 'counts', counts);
end $$;
$m0073$;
  insert into public.app_migrations(version, how) values ('0073_shop_extras.sql', 'applied');
  raise notice 'applied %', '0073_shop_extras.sql';
end $run$;
commit;

-- ============================== 0074_idem_cheque_plan.sql ==============================
begin;
do $run$ begin
  if exists (select 1 from public.app_migrations where version = '0074_idem_cheque_plan.sql') then return; end if;
  execute $m0074$
-- 0074: (22ب) ضغطتين متزامنتين على استلام شيك أو إصداره أو حفظ خطة أقساط: التاني بيستنى الأول ويرجّع نفس الرقم من غير خطأ.
-- ledger_idem (0067) بياخد القفل على رقم العملية قبل ما الدالة تبص هي موجودة ولا لأ.

-- cheque_receive: (src: 0065_cheque_pending.sql) + القفل
create or replace function public.cheque_receive(p_id uuid, p_customer uuid, p_no text, p_bank text, p_due date, p_amount bigint, p_note text default null, p_device uuid default null)
returns uuid
language plpgsql security definer set search_path = public as $$
declare s uuid := public.current_shop_id();
begin
  perform public.cheque_require();
  perform public.ledger_idem(p_id);
  if exists (select 1 from public.cheques where id = p_id) then return p_id; end if;
  perform public.ledger_amount(p_amount);
  if coalesce(trim(p_no), '') = '' or p_due is null then raise exception 'E_BAD_INPUT'; end if;
  if not exists (select 1 from public.customers where id = p_customer and shop_id = s and deleted_at is null) then raise exception 'E_NOT_FOUND'; end if;
  if p_device is not null and not exists (select 1 from public.devices where id = p_device and shop_id = s and customer_id = p_customer and deleted_at is null and public.can_branch(branch_id)) then
    raise exception 'E_NOT_FOUND';
  end if;
  insert into public.cheques(id, shop_id, branch_id, direction, party_type, party_id, cheque_no, bank, due_date, amount, entry_id, device_id, note, created_by)
  values (p_id, s, public.op_branch(), 'in', 'customer', p_customer, trim(p_no), nullif(trim(p_bank), ''), p_due, p_amount, null, p_device, nullif(trim(p_note), ''), auth.uid());
  return p_id;
end $$;

-- cheque_issue: (src: 0063_cheques.sql) + القفل
create or replace function public.cheque_issue(p_id uuid, p_supplier uuid, p_no text, p_bank text, p_due date, p_amount bigint, p_note text default null)
returns uuid
language plpgsql security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); e uuid;
begin
  perform public.cheque_require();
  perform public.ledger_idem(p_id);
  if exists (select 1 from public.cheques where id = p_id) then return p_id; end if;
  perform public.ledger_amount(p_amount);
  if coalesce(trim(p_no), '') = '' or p_due is null then raise exception 'E_BAD_INPUT'; end if;
  if not exists (select 1 from public.suppliers where id = p_supplier and shop_id = s and deleted_at is null) then raise exception 'E_NOT_FOUND'; end if;
  e := public.ledger_post('cheque_out', p_id, nullif(trim(p_note), ''), jsonb_build_array(
    public.ledger_line(public.ledger_acc('ap'), p_amount, 0, 'supplier', p_supplier),
    public.ledger_line(public.ledger_acc('cheques_out'), 0, p_amount, 'supplier', p_supplier)), null, p_id);
  insert into public.cheques(id, shop_id, branch_id, direction, party_type, party_id, cheque_no, bank, due_date, amount, entry_id, note, created_by)
  values (p_id, s, public.op_branch(), 'out', 'supplier', p_supplier, trim(p_no), nullif(trim(p_bank), ''), p_due, p_amount, e, nullif(trim(p_note), ''), auth.uid());
  return p_id;
end $$;

-- save_plan: (src: 0039_payment_plans.sql) + القفل
create or replace function public.save_plan(p_id uuid, p_party_type text, p_party uuid, p_rows jsonb, p_title text default null, p_note text default null) returns uuid
language plpgsql security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); r jsonb; n integer := 0; tot bigint := 0; a bigint; d date;
begin
  perform public.grant_require('finance', 'add');
  perform public.ledger_idem(p_id);
  if exists (select 1 from public.payment_plans where id = p_id) then
    if exists (select 1 from public.payment_plans where id = p_id and shop_id = s) then return p_id; end if;
    raise exception 'E_NOT_FOUND';
  end if;
  if p_party_type not in ('customer', 'supplier') then raise exception 'E_BAD_INPUT'; end if;
  if p_party_type = 'customer' and not exists (select 1 from public.customers where id = p_party and shop_id = s and deleted_at is null) then raise exception 'E_NOT_FOUND'; end if;
  if p_party_type = 'supplier' and not exists (select 1 from public.suppliers where id = p_party and shop_id = s and deleted_at is null) then raise exception 'E_NOT_FOUND'; end if;
  if jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) not between 1 and 120 then raise exception 'E_BAD_INPUT'; end if;
  insert into public.payment_plans(id, shop_id, branch_id, party_type, party_id, title, total, note, created_by)
  values (p_id, s, public.op_branch(), p_party_type, p_party, nullif(trim(p_title), ''), 1, nullif(trim(p_note), ''), auth.uid());
  for r in select * from jsonb_array_elements(p_rows) loop
    n := n + 1;
    a := (r ->> 'amount')::bigint;
    d := (r ->> 'due')::date;
    if a is null or a <= 0 or d is null then raise exception 'E_BAD_AMOUNT'; end if;
    perform public.ledger_amount(a);
    tot := tot + a;
    insert into public.plan_installments(shop_id, plan_id, seq, due_date, amount) values (s, p_id, n, d, a);
  end loop;
  perform public.ledger_amount(tot);
  update public.payment_plans set total = tot where id = p_id;
  return p_id;
end $$;
$m0074$;
  insert into public.app_migrations(version, how) values ('0074_idem_cheque_plan.sql', 'applied');
  raise notice 'applied %', '0074_idem_cheque_plan.sql';
end $run$;
commit;

-- ============================== 0075_delete_by_section.sql ==============================
begin;
do $run$ begin
  if exists (select 1 from public.app_migrations where version = '0075_delete_by_section.sql') then return; end if;
  execute $m0075$
-- 0075: قرارات صاحب المشروع (2026-11-24):
-- 1) "يحذف" في قسم = إلغاء وتعديل وحذف حاجة القسم ده بس (كان أي "يحذف" بيفتح كل حاجة).
--    إذن "يصحح ويحذف" الكامل (profiles.can_correct) اللي صاحب المحل بيديه لموظف بعينه زي ما هو.
-- 2) المرتجع من غير فاتورة لصاحب المحل بس.

create or replace function public.can_delete(p_section text) returns boolean
language sql stable security definer set search_path = public as $$
  -- الفني ما يلغيش ولا يحذف (القيود فيها مبالغ)، حتى لو متعلّمله
  select public.current_app_role() in ('owner', 'reception')
     and (coalesce(public.has_perm(p_section, 'delete'), false)
          or coalesce((select p.can_correct from public.profiles p where p.id = auth.uid() and p.deleted_at is null), false))
$$;
-- القيد بتاع أنهي قسم (اللي مش مذكور: الوضع المالي)
create or replace function public.entry_section(p_source text) returns text
language sql immutable as $$
  select case
    when p_source in ('sale', 'sale_return') then 'sales'
    when p_source in ('payment', 'transfer', 'drawer_close') then 'cashbox'
    when p_source = 'expense' then 'expenses'
    when p_source in ('purchase', 'supplier_payment', 'supplier_return') then 'purchases'
    when p_source in ('write_off', 'stock_transfer') then 'inventory'
    when p_source in ('part_use', 'delivery') then 'devices'
    else 'finance' end
$$;
revoke execute on function public.can_delete(text), public.entry_section(text) from public, anon, authenticated;

-- entry_require: (src: 0070_perm_matrix.sql) + قسم القيد
create or replace function public.entry_require(p_entry uuid) returns void
language plpgsql stable security definer set search_path = public as $$
begin
  if public.current_app_role() = 'owner' then return; end if;
  if public.can_delete((select public.entry_section(e.source_type) from public.journal_entries e where e.id = p_entry)) is not true then raise exception 'E_FORBIDDEN'; end if;
  if exists (select 1 from public.journal_entries e where e.id = p_entry and (e.source_type = 'vat_payment' or not public.can_branch(e.branch_id)))
     or exists (select 1 from public.journal_lines l join public.accounts a on a.id = l.account_id where l.entry_id = p_entry
                and (a.kind in ('advances', 'salaries', 'partner_capital', 'partner_current', 'capital', 'drawings') or (a.kind = 'cash' and not public.can_branch(a.branch_id))))
     or exists (select 1 from public.stock_moves m where m.entry_id = p_entry and not public.can_branch(m.branch_id)) then
    raise exception 'E_FORBIDDEN';
  end if;
end $$;

-- soft_delete: (src: 0070_perm_matrix.sql) + قسم الحاجة اللي بتتحذف
create or replace function public.soft_delete(p_kind text, p_id uuid, p_reason text default null) returns void
language plpgsql security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); before jsonb; tbl text;
begin
  if public.current_app_role() is null or not public.can_correct() then raise exception 'E_FORBIDDEN'; end if;
  if public.can_delete(case p_kind when 'customer' then 'customers' when 'supplier' then 'purchases' when 'item' then 'inventory' when 'device' then 'devices' end) is not true then raise exception 'E_FORBIDDEN'; end if;
  -- C3: كلمة السر الرئيسية (لو صاحب المحل حددها)
  perform public.master_require();
  if p_kind = 'customer' then
    tbl := 'customers';
    select to_jsonb(c) into before from public.customers c where id = p_id and shop_id = s and deleted_at is null for update;
    if before is null then raise exception 'E_NOT_FOUND'; end if;
    if exists (select 1 from public.journal_lines l where l.party_id = p_id and l.shop_id = s group by l.account_id having sum(l.debit - l.credit) <> 0) then raise exception 'E_HAS_BALANCE'; end if;
    if exists (select 1 from public.devices d where d.customer_id = p_id and d.deleted_at is null and d.status not in ('delivered', 'unrepairable')) then raise exception 'E_HAS_OPEN_DEVICES'; end if;
  elsif p_kind = 'supplier' then
    tbl := 'suppliers';
    select to_jsonb(x) into before from public.suppliers x where id = p_id and shop_id = s and deleted_at is null for update;
    if before is null then raise exception 'E_NOT_FOUND'; end if;
    if exists (select 1 from public.journal_lines l where l.party_id = p_id and l.shop_id = s group by l.account_id having sum(l.debit - l.credit) <> 0) then raise exception 'E_HAS_BALANCE'; end if;
  elsif p_kind = 'item' then
    tbl := 'items';
    select to_jsonb(x) into before from public.items x where id = p_id and shop_id = s and deleted_at is null for update;
    if before is null then raise exception 'E_NOT_FOUND'; end if;
    if (select coalesce(sum(qty), 0) <> 0 or coalesce(sum(value), 0) <> 0 from public.stock_moves where item_id = p_id) then raise exception 'E_HAS_STOCK'; end if;
  elsif p_kind = 'device' then
    tbl := 'devices';
    select to_jsonb(x) into before from public.devices x where id = p_id and shop_id = s and deleted_at is null for update;
    if before is null then raise exception 'E_NOT_FOUND'; end if;
    if public.current_app_role() <> 'owner' and not public.can_branch((before ->> 'branch_id')::uuid) then raise exception 'E_FORBIDDEN'; end if;
    if exists (select 1 from public.journal_entries e where e.device_id = p_id and not exists (select 1 from public.journal_entries r where r.reverses_id = e.id) and e.source_type not in ('reversal', 'cost_adjust')) then
      raise exception 'E_HAS_MONEY';
    end if;
  else
    raise exception 'E_BAD_INPUT';
  end if;
  perform set_config('warsha.system', 'on', true);
  execute format('update public.%I set deleted_at = now(), updated_at = now() where id = $1', tbl) using p_id;
  perform set_config('warsha.system', 'off', true);
  insert into public.audit_log(shop_id, actor_id, action, entity, entity_id, before, after)
  values (s, auth.uid(), 'soft_delete', tbl, p_id, before, jsonb_build_object('reason', nullif(trim(p_reason), '')));
end $$;

-- sale_return: (src: 0062_vat.sql) + صاحب المحل بس
create or replace function public.sale_return(p_id uuid, p_item uuid, p_qty integer, p_refund bigint, p_cashbox uuid default null, p_customer uuid default null, p_restock boolean default true, p_reason text default null) returns uuid
language plpgsql security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); e uuid; it public.items; cost bigint; cb uuid; rev uuid; v bigint;
begin
  perform public.ledger_require(array['owner']::public.app_role[]);
  perform public.perm_require('sales', 'edit');
  e := public.ledger_idem(p_id);
  if e is not null then return e; end if;
  if nullif(trim(p_reason), '') is null then raise exception 'E_REASON_REQUIRED'; end if;
  if p_qty is null or p_qty <= 0 or p_refund is null or p_refund < 0 then raise exception 'E_BAD_AMOUNT'; end if;
  select * into it from public.items where id = p_item and shop_id = s and deleted_at is null for update;
  if not found then raise exception 'E_NOT_FOUND'; end if;
  if p_cashbox is null and p_refund > 0 and p_customer is null then raise exception 'E_BAD_INPUT'; end if;
  if p_customer is not null and not exists (select 1 from public.customers where id = p_customer and shop_id = s and deleted_at is null) then raise exception 'E_NOT_FOUND'; end if;
  if p_cashbox is not null then cb := (public.ledger_cashbox(p_cashbox)).id; end if;
  rev := public.ledger_acc(case when it.kind = 'part' then 'rev_parts' else 'rev_accessories' end);
  cost := public.item_last_cost(p_item) * p_qty;
  if p_refund = 0 and (cost = 0 or not p_restock) then raise exception 'E_BAD_AMOUNT'; end if;
  e := gen_random_uuid();
  insert into public.journal_entries(id, shop_id, source_type, source_id, memo, idem_key, created_by)
  values (e, s, 'sale_return', p_item, trim(p_reason), p_id, auth.uid());
  if p_refund > 0 then
    -- R5: المبلغ المرتجع شامل الضريبة: الضريبة بترجع من حساب الضريبة المستحقة، والباقي من الإيراد
    v := public.vat_of(p_refund, public.vat_bp(s));
    insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values (s, e, rev, p_refund - v, 0);
    if v > 0 then insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values (s, e, public.ledger_acc('vat_payable'), v, 0); end if;
    if cb is not null then
      insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values (s, e, cb, 0, p_refund);
    else
      insert into public.journal_lines(shop_id, entry_id, account_id, party_type, party_id, debit, credit) values (s, e, public.ledger_acc('ar'), 'customer', p_customer, 0, p_refund);
    end if;
  end if;
  -- القطعة السليمة بترجع المخزون بتكلفتها (والتكلفة بتخرج من تكلفة البضاعة). البايظة ما بترجعش، وتكلفتها فضلت مصروف.
  if p_restock and cost > 0 then
    insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values
      (s, e, public.ledger_acc('inventory'), cost, 0), (s, e, public.ledger_acc('cogs'), 0, cost);
    insert into public.stock_moves(shop_id, item_id, entry_id, qty, value) values (s, p_item, e, p_qty, cost);
  elsif p_restock then
    insert into public.stock_moves(shop_id, item_id, entry_id, qty, value) values (s, p_item, e, p_qty, 0);
  end if;
  return e;
end $$;
$m0075$;
  insert into public.app_migrations(version, how) values ('0075_delete_by_section.sql', 'applied');
  raise notice 'applied %', '0075_delete_by_section.sql';
end $run$;
commit;

-- ============================== 0076_debt_aging.sql ==============================
begin;
do $run$ begin
  if exists (select 1 from public.app_migrations where version = '0076_debt_aging.sql') then return; end if;
  execute $m0076$
-- 0076: (5) أعمار المديونية: رصيد كل عميل أو مورد متقسم على عمر العملية اللي عملته (0–29، 30–59، 60 يوم أو أكتر).
-- - من القيود بس، لحد تاريخ معيّن (as-of) بتوقيت القاهرة. مفيش رصيد متخزن.
-- - الدفعة بتغطي الأقدم الأول (زي party_balances)، والمرتجع بفاتورة من بيع آجل بيقلّل بيعه هو.
-- - العمر من تاريخ القيد: شيك مرفوض أو رصيد افتتاحي أو قيد اتعدّل عمره من يوم القيد الجديد.
-- القيد الملغي وعكسه بيتشالوا الاتنين، فإلغاء بيع جديد ما يغطيش دين قديم.
-- - اللي رصيده صفر أو ليه فلوس عندنا مش في الكشف. مجموع الشرايح = الرصيد بالظبط.
create or replace function public.debt_aging(p_kind text, p_as_of date default null, p_branch uuid default null)
returns table(party_id uuid, name text, balance bigint, d0 bigint, d30 bigint, d60 bigint, oldest date, as_of date)
language plpgsql stable security definer set search_path = public as $$
#variable_conflict use_column
declare s uuid := public.current_shop_id(); today date := (now() at time zone 'Africa/Cairo')::date; d date := coalesce(p_as_of, today);
  upto timestamptz := (d + 1)::timestamp at time zone 'Africa/Cairo';  -- أول لحظة بعد التاريخ
begin
  perform public.grant_require('finance', 'view');
  if p_kind is null or p_kind not in ('customers', 'suppliers') then raise exception 'E_BAD_INPUT'; end if;
  if d > today then raise exception 'E_BAD_INPUT'; end if;
  -- الموظف اللي مش معاه كل الفروع: فرعه هو، حتى لو طلب غيره (زي باقي التقارير)
  if not public.all_my_branches() and (p_branch is null or not public.can_branch(p_branch)) then
    p_branch := public.op_branch();
    if p_branch is null then raise exception 'E_FORBIDDEN'; end if;
  end if;
  return query
  with ent as (
    select e.id, e.entry_no, e.occurred_at, (e.occurred_at at time zone 'Africa/Cairo')::date as day
    from public.journal_entries e
    where e.shop_id = s and e.occurred_at < upto and (p_branch is null or e.branch_id = p_branch)
      and e.reverses_id is null
      and not exists (select 1 from public.journal_entries r where r.reverses_id = e.id and r.occurred_at < upto)
  ),
  raw as (
    select l.party_id, ent.id as entry_id, ent.day, ent.occurred_at, ent.entry_no, l.id as line_id,
           (case when p_kind = 'customers' then l.debit else l.credit end)::bigint as plus,
           (case when p_kind = 'customers' then l.credit else l.debit end)::bigint as minus
    from ent join public.journal_lines l on l.entry_id = ent.id join public.accounts a on a.id = l.account_id
    where l.party_id is not null and a.kind = case when p_kind = 'customers' then 'receivable' else 'payable' end
  ),
  -- مرتجع بفاتورة من بيع آجل: بيقلّل دين البيع نفسه (مش الأقدم)
  ret as (
    select distinct x.line_id, sale.line_id as sale_line
    from raw x join public.sale_lines rl on rl.entry_id = x.entry_id join public.sale_lines b on b.id = rl.return_of
    join raw sale on sale.entry_id = b.entry_id and sale.party_id = x.party_id and sale.plus > 0
    where p_kind = 'customers' and x.minus > 0
  ),
  ln as (
    select x.party_id, x.day, x.occurred_at, x.entry_no, x.line_id,
           x.plus - coalesce((select sum(q.minus) from ret join raw q on q.line_id = ret.line_id where ret.sale_line = x.line_id), 0)::bigint as plus,
           case when exists (select 1 from ret where ret.line_id = x.line_id) then 0 else x.minus end as minus
    from raw x
  ),
  paid as (select ln.party_id, sum(ln.minus) as m, sum(ln.plus) as p from ln group by 1 having sum(ln.plus) > sum(ln.minus)),
  cum as (
    select ln.party_id, ln.day, least(ln.plus, greatest(0, sum(ln.plus) over (partition by ln.party_id order by ln.occurred_at, ln.entry_no, ln.line_id) - paid.m))::bigint as open
    from ln join paid on paid.party_id = ln.party_id where ln.plus > 0
  )
  select c.party_id, coalesce(cu.name, sp.name), sum(c.open)::bigint,
         coalesce(sum(c.open) filter (where d - c.day < 30), 0)::bigint,
         coalesce(sum(c.open) filter (where d - c.day between 30 and 59), 0)::bigint,
         coalesce(sum(c.open) filter (where d - c.day >= 60), 0)::bigint,
         min(c.day) filter (where c.open > 0), d
  from cum c
  left join public.customers cu on p_kind = 'customers' and cu.id = c.party_id
  left join public.suppliers sp on p_kind = 'suppliers' and sp.id = c.party_id
  group by c.party_id, coalesce(cu.name, sp.name)
  order by 6 desc, 5 desc, 3 desc;
end $$;
revoke execute on function public.debt_aging(text, date, uuid) from public, anon;
grant execute on function public.debt_aging(text, date, uuid) to authenticated;
$m0076$;
  insert into public.app_migrations(version, how) values ('0076_debt_aging.sql', 'applied');
  raise notice 'applied %', '0076_debt_aging.sql';
end $run$;
commit;

-- ============================== 0077_period_lock.sql ==============================
begin;
do $run$ begin
  if exists (select 1 from public.app_migrations where version = '0077_period_lock.sql') then return; end if;
  execute $m0077$
-- 0077: (6) قفل الفترة المحاسبية: لحد يوم معيّن (بتوقيت القاهرة) ممنوع قيد بتاريخ جوه الفترة، وممنوع إلغاء أو تعديل قيد جواها.
-- - صاحب المحل بس بيقفل ويفتح. الفتح (أو تأخير القفل لورا) بسبب وكلمة السر الرئيسية لو متحددة، والاتنين في سجل النشاط.
-- - التقفيل لحد امبارح بالكتير: شغل النهارده ما بيقفش. ومرتجع النهارده لبيع قديم قيد جديد بتاريخ النهارده، فمسموح.
-- - القفل مش جزء من الاسترجاع (المحل المسترجع مفتوح)، ومسح بيانات التجربة محتاج الفترة مفتوحة لو قيودها جواها.
-- - الحماية على الجدول نفسه، فأي دالة (حتى اللي هتتعمل بعدين) ممنوعة.
alter table public.shops add column books_locked_until date;

create or replace function public.tg_period_lock() returns trigger
language plpgsql security definer set search_path = public as $$
declare d date := (new.occurred_at at time zone 'Africa/Cairo')::date; lck date;
begin
  if public.restoring() then return new; end if;
  -- الشغل العادي (تاريخه النهارده ومش عكس) ما بيلمسش القفل
  if new.reverses_id is null and d >= (now() at time zone 'Africa/Cairo')::date then return new; end if;
  if new.reverses_id is not null then
    d := least(d, (select (o.occurred_at at time zone 'Africa/Cairo')::date from public.journal_entries o where o.id = new.reverses_id));
  end if;
  -- for share: قفل بيتسجل في نفس اللحظة بيستنى القيد ده، والعكس
  select sh.books_locked_until into lck from public.shops sh where sh.id = new.shop_id for share;
  if lck is not null and d <= lck then raise exception 'E_PERIOD_LOCKED'; end if;
  return new;
end $$;
create trigger c_period_lock before insert on public.journal_entries for each row execute function public.tg_period_lock();

-- التاريخ بيتغيّر من set_period_lock بس (صاحب المحل بيعدّل صف المحل مباشرة في الإعدادات)
create or replace function public.tg_shop_period_guard() returns trigger
language plpgsql set search_path = public as $$
begin
  if new.books_locked_until is distinct from old.books_locked_until and coalesce(current_setting('warsha.period', true), '') <> 'on' then
    raise exception 'E_FORBIDDEN';
  end if;
  return new;
end $$;
create trigger zy_shop_period_guard before update on public.shops for each row execute function public.tg_shop_period_guard();

-- p_until = آخر يوم مقفول. null = فتح كل حاجة. بيرجّع التاريخ بعد التعديل
create or replace function public.set_period_lock(p_until date, p_reason text default null) returns date
language plpgsql security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); old date; opening boolean;
begin
  perform public.ledger_require(array['owner']::public.app_role[]);
  select sh.books_locked_until into old from public.shops sh where sh.id = s for update;
  if not found then raise exception 'E_FORBIDDEN'; end if;
  if p_until is not distinct from old then return old; end if;
  if p_until >= (now() at time zone 'Africa/Cairo')::date then raise exception 'E_PERIOD_DATE'; end if;
  opening := old is not null and (p_until is null or p_until < old);
  if opening then
    perform public.master_require();
    if nullif(trim(p_reason), '') is null then raise exception 'E_REASON_REQUIRED'; end if;
  end if;
  perform set_config('warsha.period', 'on', true);
  update public.shops set books_locked_until = p_until where id = s;
  perform set_config('warsha.period', '', true);
  insert into public.audit_log(shop_id, actor_id, action, entity, entity_id, before, after)
  values (s, auth.uid(), case when opening then 'period_unlock' else 'period_lock' end, 'shops', s,
          jsonb_build_object('until', old), jsonb_build_object('until', p_until, 'reason', left(nullif(trim(p_reason), ''), 300)));
  return p_until;
end $$;
revoke execute on function public.set_period_lock(date, text) from public, anon;
grant execute on function public.set_period_lock(date, text) to authenticated;
$m0077$;
  insert into public.app_migrations(version, how) values ('0077_period_lock.sql', 'applied');
  raise notice 'applied %', '0077_period_lock.sql';
end $run$;
commit;

-- ============================== 0078_accountant_export.sql ==============================
begin;
do $run$ begin
  if exists (select 1 from public.app_migrations where version = '0078_accountant_export.sql') then return; end if;
  execute $m0078$
-- 0078: (4) تصدير للمحاسب: كل القيود بسطورها، والمدفوعات، وسطور البيع، لفترة وفرع. المبالغ بالقروش، ومجموع المدين = مجموع الدائن.
-- - صلاحية "يصدّر" في الوضع المالي. الموظف فرعه بس، ومن غير قيود المرتبات والسلف والشركاء ورأس المال، ولا تحويل لخزنة فرع تاني (restricted = true).
-- - sales = سطور البيع بأسعارها شاملة الضريبة (المرتجع بالسالب)، ومش بديل القيود: المرتجع من غير فاتورة والصيانة في lines بس.
-- - الأيام بتوقيت القاهرة، من وإلى داخلين. وكل تصدير في سجل النشاط.
create or replace function public.accountant_export(p_from date, p_to date, p_branch uuid default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  s uuid := public.current_shop_id(); own boolean := public.current_app_role() = 'owner'; names boolean; res jsonb;
  f timestamptz; t timestamptz;
begin
  perform public.grant_require('finance', 'view');
  perform public.grant_require('finance', 'export');
  if p_from is null or p_to is null or not isfinite(p_from) or not isfinite(p_to) or p_to < p_from or p_to - p_from > 366 then raise exception 'E_BAD_INPUT'; end if;
  f := p_from::timestamp at time zone 'Africa/Cairo';
  t := (p_to + 1)::timestamp at time zone 'Africa/Cairo';
  if not public.all_my_branches() and (p_branch is null or not public.can_branch(p_branch)) then
    p_branch := public.op_branch();
    if p_branch is null then raise exception 'E_FORBIDDEN'; end if;
  end if;
  if p_branch is not null and not exists (select 1 from public.branches where id = p_branch and shop_id = s) then raise exception 'E_BAD_BRANCH'; end if;
  names := own or public.has_perm('customers', 'view');
  with ent as materialized (
    select e.* from public.journal_entries e
    where e.shop_id = s and e.occurred_at >= f and e.occurred_at < t and (p_branch is null or e.branch_id = p_branch)
      and (own or not exists (select 1 from public.journal_lines l join public.accounts a on a.id = l.account_id
                              where l.entry_id = e.id and (a.kind in ('advances', 'salaries', 'partner_capital', 'partner_current', 'capital', 'drawings')
                                or a.kind = 'cash' and not public.can_branch(a.branch_id))))
  ),
  ln as (
    select ent.entry_no, ent.occurred_at, ent.source_type, ent.memo, b.name as branch, a.code, a.name as account, a.type::text as account_type, l.debit, l.credit, l.id,
           (select o.entry_no from public.journal_entries o where o.id = ent.reverses_id) as reverses_no,
           case l.party_type when 'customer' then case when names then (select c.name from public.customers c where c.id = l.party_id) end
                             when 'supplier' then case when own or public.has_perm('purchases', 'view') then (select sp.name from public.suppliers sp where sp.id = l.party_id) end
                             when 'employee' then (select p.full_name from public.profiles p where p.id = l.party_id)
                             when 'partner' then (select pr.name from public.partners pr where pr.id = l.party_id) end as party
    from ent join public.journal_lines l on l.entry_id = ent.id join public.accounts a on a.id = l.account_id left join public.branches b on b.id = ent.branch_id
  )
  select jsonb_build_object(
    'from', p_from, 'to', p_to, 'branch', p_branch, 'restricted', not own,
    'lines', coalesce((select jsonb_agg(jsonb_build_object('entry_no', entry_no, 'at', occurred_at, 'source', source_type, 'memo', memo, 'branch', branch, 'code', code, 'account', account,
        'type', account_type, 'party', party, 'debit', debit, 'credit', credit, 'reverses_no', reverses_no) order by occurred_at, entry_no, debit = 0, id) from ln), '[]'::jsonb),
    'payments', coalesce((select jsonb_agg(jsonb_build_object('entry_no', ent.entry_no, 'at', ent.occurred_at, 'method', p.method, 'amount', p.amount, 'cashbox', a.code, 'cashbox_name', a.name,
        'customer', case when names then c.name end, 'order_no', d.order_no,
        'reversed', exists (select 1 from public.journal_entries r where r.reverses_id = ent.id and r.occurred_at < t)) order by ent.occurred_at, ent.entry_no)
      from ent join public.payments p on p.entry_id = ent.id join public.accounts a on a.id = p.cashbox_id
      left join public.customers c on c.id = p.customer_id left join public.devices d on d.id = p.device_id), '[]'::jsonb),
    'sales', coalesce((select jsonb_agg(jsonb_build_object('entry_no', ent.entry_no, 'at', ent.occurred_at, 'item', sl.name, 'qty', sl.qty, 'price', sl.price, 'amount', case when sl.return_of is null then 1 else -1 end * sl.qty * sl.price,
        'return_of', (select o.entry_no from public.sale_lines b join public.journal_entries o on o.id = b.entry_id where b.id = sl.return_of),
        'reversed', exists (select 1 from public.journal_entries r where r.reverses_id = ent.id and r.occurred_at < t)) order by ent.occurred_at, ent.entry_no, sl.seq)
      from ent join public.sale_lines sl on sl.entry_id = ent.id and sl.deleted_at is null), '[]'::jsonb),
    'debit', (select coalesce(sum(debit), 0) from ln), 'credit', (select coalesce(sum(credit), 0) from ln))
  into res;
  insert into public.audit_log(shop_id, actor_id, action, entity, entity_id, after)
  values (s, auth.uid(), 'accountant_export', 'shops', s, jsonb_build_object('from', p_from, 'to', p_to, 'branch', p_branch));
  return res;
end $$;
revoke execute on function public.accountant_export(date, date, uuid) from public, anon;
grant execute on function public.accountant_export(date, date, uuid) to authenticated;
$m0078$;
  insert into public.app_migrations(version, how) values ('0078_accountant_export.sql', 'applied');
  raise notice 'applied %', '0078_accountant_export.sql';
end $run$;
commit;

-- ============================== 0079_purchase_orders.sql ==============================
begin;
do $run$ begin
  if exists (select 1 from public.app_migrations where version = '0079_purchase_orders.sql') then return; end if;
  execute $m0079$
-- 0079: (27) أوامر الشراء: أمر لمورد بأصنافه، واستلام جزئي لحد ما يكمل من غير تضاعف، ومرتجع مورد مربوط بسطر الاستلام نفسه.
-- - الأمر نفسه ما بيعملش قيد. القيد وقت الاستلام (شراء عادي)، والمستلم والمرتجع بيتحسبوا من حركة المخزون بس.
-- - سطر الاستلام = حركة مخزون مربوطة بسطر الأمر (order_line_id)، والمرتجع = حركة مربوطة بحركة الاستلام (return_of).
create table public.purchase_orders (
  id uuid primary key default gen_random_uuid(),
  shop_id uuid not null references public.shops(id),
  branch_id uuid not null references public.branches(id),
  supplier_id uuid not null references public.suppliers(id),
  order_no bigint generated always as identity,
  expected_on date,
  note text check (note is null or length(note) <= 300),
  cancelled_at timestamptz,
  cancel_reason text check (cancel_reason is null or length(cancel_reason) <= 300),
  created_by uuid references public.profiles(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  check ((cancelled_at is null) = (cancel_reason is null))
);
create table public.purchase_order_lines (
  id uuid primary key default gen_random_uuid(),
  shop_id uuid not null references public.shops(id),
  order_id uuid not null references public.purchase_orders(id),
  item_id uuid not null references public.items(id),
  qty integer not null check (qty > 0 and qty <= 100000),
  unit_cost bigint not null check (unit_cost >= 0),
  seq integer not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  unique (order_id, item_id)
);
create index purchase_orders_shop on public.purchase_orders(shop_id, created_at);
alter table public.stock_moves add column order_line_id uuid references public.purchase_order_lines(id);
alter table public.stock_moves add column return_of uuid references public.stock_moves(id);
create index stock_moves_order_line on public.stock_moves(order_line_id) where order_line_id is not null;
create index stock_moves_return_of on public.stock_moves(return_of) where return_of is not null;
do $$
declare t text;
begin
  foreach t in array array['purchase_orders', 'purchase_order_lines'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from public, anon, authenticated', t);
    execute format('grant select on public.%I to authenticated', t);
    execute format('create trigger set_updated_at before update on public.%I for each row execute function public.tg_set_updated_at()', t);
    execute format('create trigger block_delete before delete on public.%I for each row execute function public.tg_block_delete()', t);
    execute format('create trigger zz_audit after insert or update on public.%I for each row execute function public.tg_audit()', t);
  end loop;
end $$;
-- سطور الأمر ما بتتعدلش (الغلط: إلغاء الأمر وأمر جديد)
create trigger ledger_immutable before update or delete on public.purchase_order_lines for each row execute function public.tg_ledger_immutable();
create policy purchase_orders_select on public.purchase_orders for select to authenticated
  using (shop_id = (select public.current_shop_id()) and ((select public.current_app_role()) = 'owner'
         or ((select public.current_app_role()) = 'reception' and (select public.has_perm('purchases', 'view')) and public.can_branch(branch_id))));
create policy purchase_order_lines_select on public.purchase_order_lines for select to authenticated
  using (shop_id = (select public.current_shop_id()) and exists (select 1 from public.purchase_orders o where o.id = order_id));

-- المستلم من سطر أمر (الاستلام الملغي بقيد عكسي ما بيتحسبش)
create or replace function public.order_line_received(p_line uuid) returns bigint
language sql stable security definer set search_path = public as $$
  select coalesce(sum(m.qty), 0)::bigint from public.stock_moves m
  where m.order_line_id = p_line and not exists (select 1 from public.journal_entries x where x.reverses_id = m.entry_id)
$$;
-- الراجع للمورد من سطر استلام
create or replace function public.move_returned(p_move uuid) returns bigint
language sql stable security definer set search_path = public as $$
  select coalesce(-sum(m.qty), 0)::bigint from public.stock_moves m
  where m.return_of = p_move and not exists (select 1 from public.journal_entries x where x.reverses_id = m.entry_id)
$$;
revoke execute on function public.order_line_received(uuid), public.move_returned(uuid) from public, anon, authenticated;

create or replace function public.save_purchase_order(p_id uuid, p_supplier uuid, p_lines jsonb, p_expected date default null, p_note text default null) returns uuid
language plpgsql security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); l jsonb; n int := 0; total numeric := 0; it uuid;
begin
  perform public.grant_require('purchases', 'add');
  perform public.ledger_idem(p_id);
  if exists (select 1 from public.purchase_orders where id = p_id) then
    if exists (select 1 from public.purchase_orders where id = p_id and shop_id = s and (public.current_app_role() = 'owner' or public.can_branch(branch_id))) then return p_id; end if;
    raise exception 'E_NOT_FOUND';
  end if;
  if not exists (select 1 from public.suppliers where id = p_supplier and shop_id = s and deleted_at is null) then raise exception 'E_NOT_FOUND'; end if;
  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) not between 1 and 300 then raise exception 'E_BAD_INPUT'; end if;
  insert into public.purchase_orders(id, shop_id, branch_id, supplier_id, expected_on, note, created_by)
  values (p_id, s, public.op_branch(), p_supplier, p_expected, left(nullif(trim(p_note), ''), 300), auth.uid());
  for l in select * from jsonb_array_elements(p_lines) loop
    n := n + 1;
    if coalesce(l ->> 'qty', '') !~ '^[0-9]{1,6}$' or (l ->> 'qty')::int not between 1 and 100000 then raise exception 'E_BAD_QTY'; end if;
    if coalesce(l ->> 'unit_cost', '') !~ '^[0-9]{1,12}$' then raise exception 'E_BAD_PRICE'; end if;
    it := (l ->> 'item')::uuid;
    if not exists (select 1 from public.items where id = it and shop_id = s and deleted_at is null and kind <> 'service') then raise exception 'E_NOT_FOUND'; end if;
    if exists (select 1 from public.purchase_order_lines where order_id = p_id and item_id = it) then raise exception 'E_BAD_INPUT'; end if;
    insert into public.purchase_order_lines(shop_id, order_id, item_id, qty, unit_cost, seq) values (s, p_id, it, (l ->> 'qty')::int, (l ->> 'unit_cost')::bigint, n);
    total := total + (l ->> 'qty')::numeric * (l ->> 'unit_cost')::numeric;
  end loop;
  if total <= 0 or total > 100000000000 then raise exception 'E_BAD_AMOUNT'; end if;
  return p_id;
end $$;

create or replace function public.cancel_purchase_order(p_order uuid, p_reason text) returns void
language plpgsql security definer set search_path = public as $$
declare o public.purchase_orders;
begin
  perform public.grant_require('purchases', 'edit');
  select * into o from public.purchase_orders where id = p_order and shop_id = public.current_shop_id() and deleted_at is null for update;
  if not found or (public.current_app_role() <> 'owner' and not public.can_branch(o.branch_id)) then raise exception 'E_NOT_FOUND'; end if;
  if o.cancelled_at is not null then return; end if;
  if nullif(trim(p_reason), '') is null then raise exception 'E_REASON_REQUIRED'; end if;
  -- المستلم بيفضل مستلم، والباقي مش هييجي
  update public.purchase_orders set cancelled_at = now(), cancel_reason = left(trim(p_reason), 300) where id = o.id;
end $$;

-- p_lines: [{"line": سطر الأمر، "qty": اللي وصل، "unit_cost": سعره الفعلي (اختياري، الافتراضي سعر الأمر)}]
create or replace function public.receive_purchase_order(p_id uuid, p_order uuid, p_lines jsonb, p_cashbox uuid default null, p_note text default null) returns uuid
language plpgsql security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); o public.purchase_orders; ol public.purchase_order_lines; l jsonb; e uuid; q int; u bigint; total bigint := 0; cb public.accounts; credit_line jsonb; seen uuid[] := '{}';
begin
  perform public.grant_require('purchases', 'add');
  e := public.ledger_idem(p_id);
  if e is not null then return e; end if;
  -- القفل على الأمر: استلامين في نفس اللحظة ما يزيدوش عن المطلوب
  select * into o from public.purchase_orders where id = p_order and shop_id = s and deleted_at is null for update;
  if not found or (public.current_app_role() <> 'owner' and not public.can_branch(o.branch_id)) then raise exception 'E_NOT_FOUND'; end if;
  if o.cancelled_at is not null then raise exception 'E_ORDER_CANCELLED'; end if;
  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then raise exception 'E_BAD_INPUT'; end if;
  perform set_config('app.branch', o.branch_id::text, true);
  for l in select * from jsonb_array_elements(p_lines) loop
    select * into ol from public.purchase_order_lines where id = (l ->> 'line')::uuid and order_id = o.id;
    if not found then raise exception 'E_NOT_FOUND'; end if;
    if ol.id = any (seen) then raise exception 'E_BAD_INPUT'; end if;
    seen := seen || ol.id;
    if coalesce(l ->> 'qty', '') !~ '^[0-9]{1,6}$' or (l ->> 'qty')::int <= 0 then raise exception 'E_BAD_QTY'; end if;
    if l ->> 'unit_cost' is not null and l ->> 'unit_cost' !~ '^[0-9]{1,12}$' then raise exception 'E_BAD_PRICE'; end if;
    q := (l ->> 'qty')::int;
    if q > ol.qty - public.order_line_received(ol.id) then raise exception 'E_ORDER_QTY'; end if;
    if not exists (select 1 from public.items where id = ol.item_id and deleted_at is null) then raise exception 'E_NOT_FOUND'; end if;
    if q::numeric * coalesce((l ->> 'unit_cost')::numeric, ol.unit_cost) > 100000000000 then raise exception 'E_BAD_AMOUNT'; end if;
    total := total + q::bigint * coalesce((l ->> 'unit_cost')::bigint, ol.unit_cost);
  end loop;
  perform public.ledger_amount(total);
  if p_cashbox is not null then
    cb := public.ledger_cashbox(p_cashbox);
    if cb.branch_id is distinct from o.branch_id then raise exception 'E_BAD_BRANCH'; end if;
    credit_line := public.ledger_line(cb.id, 0, total);
  else
    credit_line := public.ledger_line(public.ledger_acc('ap'), 0, total, 'supplier', o.supplier_id);
  end if;
  e := public.ledger_post('purchase', p_id, p_note, jsonb_build_array(public.ledger_line(public.ledger_acc('inventory'), total, 0), credit_line), null, p_id);
  for l in select * from jsonb_array_elements(p_lines) loop
    select * into ol from public.purchase_order_lines where id = (l ->> 'line')::uuid;
    u := coalesce((l ->> 'unit_cost')::bigint, ol.unit_cost);
    insert into public.stock_moves(shop_id, item_id, entry_id, qty, value, order_line_id)
    values (s, ol.item_id, e, (l ->> 'qty')::int, (l ->> 'qty')::bigint * u, ol.id);
  end loop;
  insert into public.purchases(id, shop_id, supplier_id, entry_id, on_credit, created_by) values (p_id, s, o.supplier_id, e, p_cashbox is null, auth.uid());
  return e;
end $$;

-- مرتجع من سطر استلام (شراء عادي أو بأمر): بسعر شراه هو، وما يزيدش عن اللي وصل فيه
create or replace function public.purchase_move_return(p_id uuid, p_move uuid, p_qty integer, p_cashbox uuid default null, p_reason text default null) returns uuid
language plpgsql security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); mv public.stock_moves; o public.journal_entries; sup uuid; e uuid; back bigint; refund bigint; cost bigint; diff bigint; cb public.accounts; st record;
begin
  perform public.grant_require('purchases', 'edit');
  e := public.ledger_idem(p_id);
  if e is not null then return e; end if;
  if nullif(trim(p_reason), '') is null then raise exception 'E_REASON_REQUIRED'; end if;
  select * into mv from public.stock_moves where id = p_move and shop_id = s and qty > 0 and return_of is null;
  if not found then raise exception 'E_NOT_FOUND'; end if;
  select * into o from public.journal_entries where id = mv.entry_id and shop_id = s and source_type = 'purchase' for update;
  if not found then raise exception 'E_NOT_FOUND'; end if;
  if public.current_app_role() <> 'owner' and not public.can_branch(o.branch_id) then raise exception 'E_FORBIDDEN'; end if;
  if exists (select 1 from public.journal_entries x where x.reverses_id = o.id) then raise exception 'E_ALREADY_REVERSED'; end if;
  if exists (select 1 from public.used_devices u where u.item_id = mv.item_id) then raise exception 'E_USED_RETURN'; end if;
  select p.supplier_id into sup from public.purchases p where p.entry_id = o.id;
  if sup is null then raise exception 'E_NOT_FOUND'; end if;
  back := public.move_returned(mv.id);
  if p_qty is null or p_qty <= 0 or p_qty > mv.qty - back then raise exception 'E_RETURN_QTY'; end if;
  -- قيمة سطر الشرا = الكمية × سعر الوحدة، فالقسمة من غير باقي
  refund := mv.value / mv.qty * p_qty;
  perform set_config('app.branch', o.branch_id::text, true);
  if p_cashbox is not null then
    cb := public.ledger_cashbox(p_cashbox);
    if cb.branch_id is distinct from o.branch_id then raise exception 'E_BAD_BRANCH'; end if;
  end if;
  e := gen_random_uuid();
  insert into public.journal_entries(id, shop_id, source_type, source_id, memo, idem_key, created_by)
  values (e, s, 'supplier_return', sup, left(trim(p_reason), 300), p_id, auth.uid());
  -- نفس ledger_issue، والحركة مربوطة بسطر الاستلام (الحركات ما بتتعدلش بعدين)
  perform 1 from public.items where id = mv.item_id and shop_id = s for update;
  select * into st from public.item_stock_at(mv.item_id, o.branch_id);
  if st.qty < p_qty then raise exception 'E_STOCK'; end if;
  cost := public.ledger_issue_cost(st.qty, st.value, p_qty);
  insert into public.stock_moves(shop_id, item_id, entry_id, qty, value, branch_id, return_of) values (s, mv.item_id, e, -p_qty, -cost, o.branch_id, mv.id);
  if cost = 0 and refund = 0 then raise exception 'E_BAD_AMOUNT'; end if;
  if cost > 0 then
    insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values (s, e, public.ledger_acc('inventory'), 0, cost);
  end if;
  if refund > 0 then
    if cb.id is null then
      insert into public.journal_lines(shop_id, entry_id, account_id, party_type, party_id, debit, credit) values (s, e, public.ledger_acc('ap'), 'supplier', sup, refund, 0);
    else
      insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values (s, e, cb.id, refund, 0);
    end if;
  end if;
  -- الفرق بين متوسط التكلفة وسعر الشرا: تكلفة بضاعة (زي supplier_return)
  diff := cost - refund;
  if diff > 0 then
    insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values (s, e, public.ledger_acc('cogs'), diff, 0);
  elsif diff < 0 then
    insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values (s, e, public.ledger_acc('cogs'), 0, -diff);
  end if;
  return e;
end $$;

-- الأوامر بحالتها: open (ما وصلش حاجة)، partial، received، cancelled. وكل سطر: المطلوب والمستلم وحركات استلامه (للمرتجع)
create or replace function public.purchase_orders_list(p_status text default null, p_branch uuid default null) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare s uuid := public.current_shop_id();
begin
  perform public.grant_require('purchases', 'view');
  return coalesce((
    -- shortcut: آخر 300 أمر، ولو محل عدّاهم نضيف صفحات
    with po0 as materialized (
      select o.* from public.purchase_orders o
      where o.shop_id = s and o.deleted_at is null and (p_branch is null or o.branch_id = p_branch)
        and (public.current_app_role() = 'owner' or public.can_branch(o.branch_id))
      order by o.created_at desc, o.id limit 300
    ),
    ln as materialized (
      select l.order_id, l.id, l.seq, l.item_id, i.name, l.qty, l.unit_cost, public.order_line_received(l.id) as got,
             coalesce((select jsonb_agg(jsonb_build_object('move', m.id, 'entry', m.entry_id, 'at', e.occurred_at, 'qty', m.qty, 'value', m.value, 'returned', public.move_returned(m.id)) order by e.occurred_at, m.id)
               from public.stock_moves m join public.journal_entries e on e.id = m.entry_id
               where m.order_line_id = l.id and not exists (select 1 from public.journal_entries x where x.reverses_id = m.entry_id)), '[]'::jsonb) as receipts
      from po0 join public.purchase_order_lines l on l.order_id = po0.id join public.items i on i.id = l.item_id
    ),
    po as (
      select o.*, sp.name as supplier,
             (select case when o.cancelled_at is not null then 'cancelled' when sum(ln.got) = 0 then 'open' when sum(ln.got) < sum(ln.qty) then 'partial' else 'received' end from ln where ln.order_id = o.id) as status
      from po0 o join public.suppliers sp on sp.id = o.supplier_id
    )
    select jsonb_agg(jsonb_build_object('id', po.id, 'order_no', po.order_no, 'branch_id', po.branch_id, 'supplier_id', po.supplier_id, 'supplier', po.supplier, 'status', po.status,
        'expected_on', po.expected_on, 'note', po.note, 'created_at', po.created_at, 'cancel_reason', po.cancel_reason,
        'lines', (select jsonb_agg(jsonb_build_object('id', ln.id, 'item', ln.item_id, 'name', ln.name, 'qty', ln.qty, 'unit_cost', ln.unit_cost, 'received', ln.got, 'receipts', ln.receipts) order by ln.seq)
                  from ln where ln.order_id = po.id)) order by po.created_at desc, po.id)
    from po where p_status is null or po.status = p_status), '[]'::jsonb);
end $$;
do $$
declare f text;
begin
  foreach f in array array['save_purchase_order(uuid, uuid, jsonb, date, text)', 'cancel_purchase_order(uuid, text)', 'receive_purchase_order(uuid, uuid, jsonb, uuid, text)',
                           'purchase_move_return(uuid, uuid, integer, uuid, text)', 'purchase_orders_list(text, uuid)'] loop
    execute format('revoke execute on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;

-- reverse_entry: (src: 0072_sale_line_return.sql) + شرا رجع منه حاجة ما يتلغيش قبل المرتجع
CREATE OR REPLACE FUNCTION public.reverse_entry(p_entry uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  o public.journal_entries;
  e uuid;
  lines jsonb;
  mv record;
begin
  if public.current_app_role() is null or not public.can_correct() then raise exception 'E_FORBIDDEN'; end if;
  -- C3: كلمة السر الرئيسية (لو صاحب المحل حددها)
  perform public.master_require();
  if nullif(trim(p_reason), '') is null then raise exception 'E_REASON_REQUIRED'; end if;
  select * into o from public.journal_entries where id = p_entry and shop_id = public.current_shop_id() for update;
  if not found then raise exception 'E_NOT_FOUND'; end if;
  perform public.entry_require(o.id);
  if o.source_type in ('reversal', 'cost_adjust') or exists (select 1 from public.journal_entries where reverses_id = o.id) then
    raise exception 'E_ALREADY_REVERSED';
  end if;
  if o.source_type = 'sale' and exists (select 1 from public.sale_lines sl where sl.entry_id = o.id and public.sale_line_returned(sl.id) > 0) then
    raise exception 'E_HAS_RETURNS';
  end if;
  if o.source_type = 'purchase' and exists (select 1 from public.stock_moves m where m.entry_id = o.id and m.qty > 0 and public.move_returned(m.id) > 0) then
    raise exception 'E_HAS_RETURNS';
  end if;
  select jsonb_agg(public.ledger_line(account_id, credit, debit, party_type, party_id)) into lines
  from public.journal_lines where entry_id = o.id;
  -- العكس بيتسجل في نفس فرع القيد الأصلي
  perform set_config('app.branch', o.branch_id::text, true);
  e := public.ledger_post('reversal', o.source_id, p_reason, lines, o.device_id, null, o.id);
  for mv in select * from public.stock_moves where entry_id = o.id loop
    perform 1 from public.items where id = mv.item_id for update;
    if (select coalesce(sum(qty), 0) from public.stock_moves where item_id = mv.item_id and branch_id = mv.branch_id) - mv.qty < 0 then
      raise exception 'E_STOCK';
    end if;
    insert into public.stock_moves(shop_id, item_id, entry_id, qty, value, branch_id) values (mv.shop_id, mv.item_id, e, -mv.qty, -mv.value, mv.branch_id);
  end loop;
  for mv in select distinct item_id, branch_id from public.stock_moves where entry_id = o.id loop
    perform public.ledger_settle_item(mv.item_id, o.device_id, mv.branch_id);
  end loop;
  insert into public.audit_log(shop_id, actor_id, action, entity, entity_id, before, after)
  values (o.shop_id, auth.uid(), 'reverse_entry', 'journal_entries', o.id, to_jsonb(o), jsonb_build_object('reversal_id', e, 'reason', p_reason));
  return e;
end $function$;

-- backup_snapshot: (src: 0063_cheques.sql) + أوامر الشراء
create or replace function public.backup_snapshot(p_shop uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  res jsonb := jsonb_build_object('format', 'warsha-backup', 'version', 1, 'generated_at', now(), 'shop_id', p_shop);
  t text;
  rows jsonb;
begin
  foreach t in array array['shops', 'branches', 'staff_branches', 'attendance', 'shop_branding', 'profiles', 'customers', 'devices', 'device_costs', 'status_log', 'device_notes', 'device_photos', 'device_checks',
                           'quote_decisions', 'message_templates', 'message_log', 'accounts', 'journal_entries', 'journal_lines', 'sale_lines', 'cheques', 'payments', 'drawer_closings',
                           'suppliers', 'categories', 'items', 'purchase_orders', 'purchase_order_lines', 'stock_moves', 'uncosted_sales', 'payment_plans', 'plan_installments', 'branch_goals', 'printers', 'print_templates', 'check_templates', 'used_devices', 'commission_rules', 'purchases', 'labor_rates', 'specialties', 'staff_specialties', 'routes', 'repair_steps',
                           'repair_videos', 'device_ratings', 'issue_presets', 'partners', 'profit_distributions', 'party_links', 'shop_lists', 'audit_log'] loop
    execute format('select coalesce(jsonb_agg(to_jsonb(x)), ''[]''::jsonb) from public.%I x where x.shop_id = $1', t) into rows using p_shop;
    res := res || jsonb_build_object(t, rows);
  end loop;
  select coalesce(jsonb_agg(jsonb_build_object('device_id', device_id, 'kind', kind, 'erased_at', erased_at)), '[]'::jsonb)
    into rows from public.device_passcodes where shop_id = p_shop;
  return res || jsonb_build_object('device_passcodes', rows);
end $$;

-- restore_backup: (src: 0073_shop_extras.sql) + أوامر الشراء (قبل حركة المخزون)
create or replace function public.restore_backup(p_data jsonb) returns jsonb
-- extensions: فيها gen_random_bytes على Supabase
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare
  s uuid := public.current_shop_id();
  me uuid := auth.uid();
  old_shop uuid;
  old_owner uuid;
  sh jsonb;
  t text;
  r jsonb;
  rows jsonb;
  n int;
  bad int;
  counts jsonb := '{}'::jsonb;
  -- بالترتيب ده عشان كل صف يلاقي اللي بيشاور عليه
  tabs text[] := array['branches', 'profiles', 'staff_branches', 'attendance', 'shop_branding', 'accounts', 'customers', 'suppliers', 'party_links', 'partners', 'specialties', 'staff_specialties', 'routes', 'labor_rates',
                       'issue_presets', 'commission_rules', 'shop_lists', 'message_templates', 'categories', 'items', 'devices', 'device_costs', 'status_log', 'device_notes', 'device_checks',
                       'quote_decisions', 'repair_steps', 'repair_videos', 'device_ratings', 'journal_entries', 'journal_lines', 'sale_lines', 'cheques', 'profit_distributions', 'payments',
                       'purchases', 'purchase_orders', 'purchase_order_lines', 'stock_moves', 'uncosted_sales', 'used_devices', 'payment_plans', 'plan_installments', 'branch_goals', 'printers', 'print_templates', 'check_templates', 'drawer_closings', 'message_log', 'audit_log'];
  -- الجداول دي ليها نسخة اتعملت مع التسجيل: بتتطابق بالكود (أو المفتاح) وبتاخد قيم النسخة
  keyed text[] := array['branches', 'accounts', 'routes', 'specialties', 'message_templates', 'labor_rates', 'shop_branding'];
begin
  perform public.ledger_require(array['owner']::public.app_role[]);
  if s is null or me is null then raise exception 'E_FORBIDDEN'; end if;
  if p_data is null or p_data->>'format' is distinct from 'warsha-backup' or coalesce((p_data->>'version')::int, 0) <> 1 then
    raise exception 'E_BACKUP_FORMAT';
  end if;
  old_shop := (p_data->>'shop_id')::uuid;
  if old_shop is null or old_shop = s then raise exception 'E_BACKUP_FORMAT'; end if;

  -- محل جديد فاضي بس
  if exists (select 1 from public.devices where shop_id = s) or exists (select 1 from public.customers where shop_id = s)
     or exists (select 1 from public.journal_entries where shop_id = s) or exists (select 1 from public.items where shop_id = s)
     or exists (select 1 from public.suppliers where shop_id = s) or exists (select 1 from public.payments where shop_id = s)
     or exists (select 1 from public.purchases where shop_id = s) or exists (select 1 from public.drawer_closings where shop_id = s)
     or exists (select 1 from public.stock_moves where shop_id = s)
     or exists (select 1 from public.attendance where shop_id = s and deleted_at is null)
     or exists (select 1 from public.profiles where shop_id = s and id <> me) then
    raise exception 'E_RESTORE_NOT_EMPTY';
  end if;

  perform set_config('warsha.restore', 'on', true);
  drop table if exists pg_temp._rmap;
  create temp table _rmap(old uuid primary key, new uuid not null) on commit drop;
  insert into _rmap values (old_shop, s);

  -- 1) بيانات المحل نفسه (من غير الخطة والإيقاف واللوجو اللي في Storage)
  sh := p_data->'shops'->0;
  if sh is not null then
    update public.shops set
      name = coalesce(sh->>'name', name), phone = sh->>'phone', address = sh->>'address',
      receipt_terms = coalesce(sh->>'receipt_terms', receipt_terms), warranty_days = coalesce((sh->>'warranty_days')::int, warranty_days),
      country = coalesce(sh->>'country', country), currency = coalesce(sh->>'currency', currency),
      payment_methods = coalesce(array(select jsonb_array_elements_text(sh->'payment_methods')), payment_methods),
      theme = coalesce(sh->>'theme', theme), locale = coalesce(sh->>'locale', locale),
      default_margin_pct = coalesce((sh->>'default_margin_pct')::int, default_margin_pct),
      extras = coalesce(sh->'extras', extras), max_discount_pct = coalesce((sh->>'max_discount_pct')::int, max_discount_pct)
    where id = s;
  end if;

  -- 2) الـ ids الجديدة
  -- صاحب المحل في النسخة = اللي بيسترجع دلوقتي
  select (x->>'id')::uuid into old_owner from jsonb_array_elements(coalesce(p_data->'profiles', '[]')) x
   where x->>'role' = 'owner' order by x->>'created_at' limit 1;
  if old_owner is not null then insert into _rmap values (old_owner, me) on conflict do nothing; end if;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.accounts a where a.shop_id = s and a.code = x->>'code' and x->>'code' is not null), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'accounts', '[]')) x on conflict do nothing;
  -- الفرع الرئيسي في النسخة = الفرع الرئيسي للمحل الجديد
  insert into _rmap select (x->>'id')::uuid, public.main_branch(s)
    from jsonb_array_elements(coalesce(p_data->'branches', '[]')) x where (x->>'is_main')::boolean and x->>'deleted_at' is null on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.routes a where a.shop_id = s and a.code = x->>'code' and x->>'code' is not null), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'routes', '[]')) x on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.specialties a where a.shop_id = s and a.code = x->>'code' and x->>'code' is not null), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'specialties', '[]')) x on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.message_templates a where a.shop_id = s and a.key = x->>'key'), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'message_templates', '[]')) x on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.labor_rates a where a.shop_id = s and a.deleted_at is null and lower(trim(a.issue)) = lower(trim(x->>'issue')) and x->>'deleted_at' is null), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'labor_rates', '[]')) x on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.shop_branding a where a.shop_id = s), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'shop_branding', '[]')) x on conflict do nothing;
  foreach t in array tabs loop
    insert into _rmap select (x->>'id')::uuid, gen_random_uuid() from jsonb_array_elements(coalesce(p_data->t, '[]')) x where x ? 'id' on conflict do nothing;
  end loop;

  -- 3) الصفوف نفسها بالترتيب
  foreach t in array tabs loop
    rows := '[]'::jsonb;
    for r in select public.restore_remap(x) from jsonb_array_elements(coalesce(p_data->t, '[]')) x loop
      if t = 'profiles' then
        -- صاحب المحل موجود أصلًا. الباقيين موظفين سابقين (من غير حساب دخول)
        continue when (r->>'id')::uuid = me;
        r := r || jsonb_build_object('deleted_at', coalesce(r->>'deleted_at', now()::text));
      elsif t = 'devices' then
        -- كود التتبع (الـ QR) بيفضل زي ما هو، إلا لو مستخدم في المشروع ده (المحل الأصلي لسه هنا)
        if exists (select 1 from public.devices d where d.tracking_token = r->>'tracking_token') then
          r := r || jsonb_build_object('tracking_token', encode(gen_random_bytes(12), 'hex'));
        end if;
      elsif t = 'journal_entries' then
        if r->>'idem_key' is not null and exists (select 1 from public.journal_entries j where j.idem_key = (r->>'idem_key')::uuid) then
          r := r || jsonb_build_object('idem_key', gen_random_uuid());
        end if;
      elsif t = 'accounts' and r->>'kind' = 'cash' and r->>'branch_id' is null then
        -- نسخة من قبل الفروع: الخزن كلها في الفرع الرئيسي
        r := r || jsonb_build_object('branch_id', public.main_branch(s));
      elsif t = 'used_devices' then
        -- رقم بطاقة البائع (في Vault) وصورتها (في Storage) مش جوه النسخة
        r := r || jsonb_build_object('seller_nid_secret', null, 'seller_photo', null);
      elsif t = 'shop_branding' then
        -- اللوجو الملون والحراري جوه الصف نفسه. الملف الأصلي في Storage مش جوه النسخة
        r := r || jsonb_build_object('logo_path', null);
      end if;
      if t = any (keyed) and exists (select 1 from _rmap m where m.new = (r->>'id')::uuid and m.old <> m.new)
         and (t <> 'shop_branding' or exists (select 1 from public.shop_branding b where b.id = (r->>'id')::uuid)) then
        -- موجود من التسجيل: بياخد قيم النسخة
        execute format('select count(*) from public.%I where id = $1', t) into n using (r->>'id')::uuid;
        if n > 0 then
          execute format('update public.%1$I x set (%2$s) = (select %2$s from jsonb_populate_record(null::public.%1$I, $1)) where x.id = $2', t,
            (select string_agg(quote_ident(c.column_name), ', ' order by c.ordinal_position) from information_schema.columns c
              where c.table_schema = 'public' and c.table_name = t and c.column_name not in ('id', 'shop_id')))
            using r, (r->>'id')::uuid;
          continue;
        end if;
      end if;
      rows := rows || jsonb_build_array(r);
    end loop;
    if jsonb_array_length(rows) > 0 then
      -- overriding system value: أرقام القيود (entry_no) بترجع زي ما هي
      execute format('insert into public.%1$I overriding system value select * from jsonb_populate_recordset(null::public.%1$I, $1)', t) using rows;
    end if;
    counts := counts || jsonb_build_object(t, jsonb_array_length(coalesce(p_data->t, '[]')));
  end loop;

  -- 4) عدّاد أرقام الطلبات: من آخر رقم راجع في كل سنة
  -- (لكل فرع: الرقم ممكن يبقى قبله بادئة الفرع B2-2026-0001)
  insert into public.order_counters(shop_id, branch_id, year, last_value)
  select s, branch_id, (regexp_match(order_no, '(\d{4})-(\d+)$'))[1]::int, max((regexp_match(order_no, '(\d{4})-(\d+)$'))[2]::int)
    from public.devices where shop_id = s and order_no ~ '\d{4}-\d+$' group by 2, 3
  on conflict (shop_id, branch_id, year) do update set last_value = greatest(public.order_counters.last_value, excluded.last_value);

  -- 5) التأكد: كل قيد متوازن، ورصيد كل حساب = رصيده في النسخة بالظبط
  select count(*) into bad from (
    select entry_id from public.journal_lines where shop_id = s group by entry_id having sum(debit) <> sum(credit)) x;
  if bad > 0 then raise exception 'E_RESTORE_UNBALANCED'; end if;
  select count(*) into bad from (
    select m.new acc, sum((l->>'debit')::bigint - (l->>'credit')::bigint) b
      from jsonb_array_elements(coalesce(p_data->'journal_lines', '[]')) l join _rmap m on m.old = (l->>'account_id')::uuid group by m.new
  ) x full join (select account_id, sum(debit - credit) b from public.journal_lines where shop_id = s group by account_id) y on y.account_id = x.acc
  where coalesce(x.b, 0) <> coalesce(y.b, 0);
  if bad > 0 then raise exception 'E_RESTORE_MISMATCH'; end if;
  -- وعدد الصفوف في كل جدول (الحسابات والقوالب اللي اتعملت مع التسجيل ممكن تزيد عن النسخة، مش تقل)
  foreach t in array tabs loop
    execute format('select count(*) from public.%I where shop_id = $1', t) into n using s;
    if n < jsonb_array_length(coalesce(p_data->t, '[]')) - (case when t = 'profiles' and old_owner is not null then 1 else 0 end) then
      raise exception 'E_RESTORE_MISMATCH';
    end if;
  end loop;

  perform set_config('warsha.restore', 'off', true);
  insert into public.audit_log(shop_id, actor_id, action, entity, entity_id, after)
  values (s, me, 'backup_restore', 'shops', s, jsonb_build_object('from_shop', old_shop, 'generated_at', p_data->>'generated_at', 'counts', counts));
  return jsonb_build_object('restored', true, 'counts', counts);
end $$;

-- edit_entry: (src: 0026_edit_delete.sql) + استلام أمر شراء ما يتعدلش (الجديد بيبقى من غير ربط بالأمر فيتستلم تاني): يتلغي ويتستلم من الأمر
create or replace function public.edit_entry(p_entry uuid, p_reason text, p_new jsonb) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  o public.journal_entries;
  nid uuid := (p_new ->> 'id')::uuid;
  e uuid;
  amt bigint := (p_new ->> 'amount')::bigint;
  note text := nullif(trim(p_new ->> 'note'), '');
begin
  if public.current_app_role() is null or not public.can_correct() then raise exception 'E_FORBIDDEN'; end if;
  if nid is null then raise exception 'E_BAD_INPUT'; end if;
  e := public.ledger_idem(nid);
  if e is not null then return e; end if;
  select * into o from public.journal_entries where id = p_entry and shop_id = public.current_shop_id();
  if not found then raise exception 'E_NOT_FOUND'; end if;
  if exists (select 1 from public.stock_moves m where m.entry_id = o.id and m.order_line_id is not null) then raise exception 'E_ORDER_EDIT'; end if;
  perform public.reverse_entry(p_entry, p_reason);
  case o.source_type
    when 'payment' then e := public.record_payment(nid, (p_new ->> 'customer')::uuid, (p_new ->> 'cashbox')::uuid, amt, (p_new ->> 'device')::uuid, p_new ->> 'method', note);
    when 'expense' then e := public.record_expense(nid, (p_new ->> 'account')::uuid, (p_new ->> 'cashbox')::uuid, amt, note);
    when 'transfer' then e := public.transfer_cash(nid, (p_new ->> 'from')::uuid, (p_new ->> 'to')::uuid, amt, note);
    when 'capital' then e := public.owner_capital(nid, (p_new ->> 'cashbox')::uuid, amt, note);
    when 'drawing' then e := public.owner_drawing(nid, (p_new ->> 'cashbox')::uuid, amt, note);
    when 'advance' then e := public.give_advance(nid, (p_new ->> 'employee')::uuid, (p_new ->> 'cashbox')::uuid, amt, note);
    when 'salary' then e := public.accrue_salary(nid, (p_new ->> 'employee')::uuid, amt, note);
    when 'salary_payment' then e := public.pay_salary(nid, (p_new ->> 'employee')::uuid, (p_new ->> 'cashbox')::uuid, amt, note);
    when 'supplier_payment' then e := public.pay_supplier(nid, (p_new ->> 'supplier')::uuid, (p_new ->> 'cashbox')::uuid, amt, note);
    when 'purchase' then e := public.record_purchase(nid, (p_new ->> 'supplier')::uuid, p_new -> 'lines', (p_new ->> 'cashbox')::uuid, note);
    when 'sale' then e := public.record_sale(nid, p_new -> 'lines', (p_new ->> 'cashbox')::uuid, (p_new ->> 'customer')::uuid, note);
    else raise exception 'E_NOT_EDITABLE';
  end case;
  insert into public.audit_log(shop_id, actor_id, action, entity, entity_id, before, after)
  values (o.shop_id, auth.uid(), 'edit_entry', 'journal_entries', o.id, to_jsonb(o), jsonb_build_object('new_entry', e, 'reason', p_reason));
  return e;
end $$;
$m0079$;
  insert into public.app_migrations(version, how) values ('0079_purchase_orders.sql', 'applied');
  raise notice 'applied %', '0079_purchase_orders.sql';
end $run$;
commit;

-- ============================== 0080_stock_count.sql ==============================
begin;
do $run$ begin
  if exists (select 1 from public.app_migrations where version = '0080_stock_count.sql') then return; end if;
  execute $m0080$
-- 0080: (29) الجرد الدوري لفرع: رصيد بداية الجرد، والعد صنف صنف، وكشف الفروق، والاعتماد بقيد واحد.
-- - العد لوحده ما بيعملش تسوية. الفرق = المعدود − رصيد النظام لحظة عدّ الصنف، فالبيع بعد العد ما يلخبطش الفرق.
-- - اللي ما اتعدّش ما بيتسواش. المستعمل (IMEI) والخدمات مش في الجرد.
-- - العد بصلاحية "يعدّل" في المخزون، والاعتماد بصلاحية "المبالغ" و"يحذف" (زي الهالك).
alter table public.journal_entries drop constraint if exists journal_entries_source_type_check;
alter table public.journal_entries add constraint journal_entries_source_type_check check (source_type = any (array[
  'payment', 'delivery', 'purchase', 'supplier_payment', 'part_use', 'sale', 'expense', 'salary', 'salary_payment', 'advance', 'advance_settle',
  'capital', 'drawing', 'transfer', 'drawer_close', 'reversal', 'cost_adjust', 'write_off', 'supplier_return', 'sale_return', 'opening',
  'partner_capital', 'partner_withdrawal', 'profit_distribution', 'netting', 'stock_transfer', 'commission', 'bonus', 'penalty', 'vat_payment',
  'cheque_in', 'cheque_out', 'cheque_clear', 'cheque_bounce', 'stock_count']));

create table public.stock_counts (
  id uuid primary key default gen_random_uuid(),
  shop_id uuid not null references public.shops(id),
  branch_id uuid not null references public.branches(id),
  status text not null default 'open' check (status in ('open', 'posted', 'cancelled')),
  note text check (note is null or length(note) <= 300),
  entry_id uuid references public.journal_entries(id),
  closed_at timestamptz,
  closed_by uuid references public.profiles(id),
  created_by uuid references public.profiles(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  check ((status = 'open') = (closed_at is null))
);
-- جرد مفتوح واحد لكل فرع
create unique index stock_counts_open on public.stock_counts(branch_id) where status = 'open' and deleted_at is null;
create table public.stock_count_lines (
  id uuid primary key default gen_random_uuid(),
  shop_id uuid not null references public.shops(id),
  count_id uuid not null references public.stock_counts(id),
  item_id uuid not null references public.items(id),
  opening_qty bigint not null,
  system_qty bigint,
  counted_qty bigint check (counted_qty is null or (counted_qty >= 0 and counted_qty <= 1000000)),
  counted_at timestamptz,
  counted_by uuid references public.profiles(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  unique (count_id, item_id),
  check ((counted_qty is null) = (system_qty is null))
);
do $$
declare t text;
begin
  foreach t in array array['stock_counts', 'stock_count_lines'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from public, anon, authenticated', t);
    execute format('grant select on public.%I to authenticated', t);
    execute format('create trigger set_updated_at before update on public.%I for each row execute function public.tg_set_updated_at()', t);
    execute format('create trigger block_delete before delete on public.%I for each row execute function public.tg_block_delete()', t);
  end loop;
end $$;
create trigger zz_audit after insert or update on public.stock_counts for each row execute function public.tg_audit();
create trigger zz_audit after update on public.stock_count_lines for each row execute function public.tg_audit();
create policy stock_counts_select on public.stock_counts for select to authenticated
  using (shop_id = (select public.current_shop_id()) and ((select public.current_app_role()) = 'owner'
         or ((select public.current_app_role()) = 'reception' and (select public.has_perm('inventory', 'edit')) and public.can_branch(branch_id))));
create policy stock_count_lines_select on public.stock_count_lines for select to authenticated
  using (shop_id = (select public.current_shop_id()) and exists (select 1 from public.stock_counts c where c.id = count_id));

-- الجرد لو الموظف ليه فرعه (والقفل عليه لو p_lock)
create or replace function public.stock_count_get(p_count uuid, p_open boolean) returns public.stock_counts
language plpgsql security definer set search_path = public as $$
declare c public.stock_counts;
begin
  select * into c from public.stock_counts where id = p_count and shop_id = public.current_shop_id() and deleted_at is null for update;
  if not found or (public.current_app_role() <> 'owner' and not public.can_branch(c.branch_id)) then raise exception 'E_NOT_FOUND'; end if;
  if p_open and c.status <> 'open' then raise exception 'E_COUNT_CLOSED'; end if;
  return c;
end $$;
revoke execute on function public.stock_count_get(uuid, boolean) from public, anon, authenticated;

-- تكلفة الوحدة في الفرع: متوسطه، ولو مفيش رصيد بقيمة: آخر سعر شرا (متوسط كل الفروع ممكن يتلخبط برصيد من غير تكلفة)
create or replace function public.stock_count_cost(p_item uuid, p_branch uuid) returns bigint
language sql stable security definer set search_path = public as $$
  select coalesce(
    (select case when st.qty > 0 and st.value > 0 then st.value / st.qty end from public.item_stock_at(p_item, p_branch) st),
    (select m.value / m.qty from public.stock_moves m join public.journal_entries e on e.id = m.entry_id
      where m.item_id = p_item and m.qty > 0 and e.source_type = 'purchase' order by e.occurred_at desc, m.created_at desc limit 1),
    0)::bigint
$$;
revoke execute on function public.stock_count_cost(uuid, uuid) from public, anon, authenticated;

create or replace function public.start_stock_count(p_id uuid, p_note text default null) returns uuid
language plpgsql security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); b uuid;
begin
  perform public.grant_require('inventory', 'edit');
  perform public.ledger_idem(p_id);
  if exists (select 1 from public.stock_counts where id = p_id) then
    return (public.stock_count_get(p_id, false)).id;
  end if;
  b := public.op_branch();
  begin
    insert into public.stock_counts(id, shop_id, branch_id, note, created_by) values (p_id, s, b, left(nullif(trim(p_note), ''), 300), auth.uid());
  exception when unique_violation then raise exception 'E_COUNT_OPEN';
  end;
  insert into public.stock_count_lines(shop_id, count_id, item_id, opening_qty)
  select s, p_id, i.id, coalesce((select sum(m.qty) from public.stock_moves m where m.item_id = i.id and m.branch_id = b), 0)
  from public.items i where i.shop_id = s and i.deleted_at is null and i.kind in ('part', 'accessory') order by i.id;
  return p_id;
end $$;

-- p_counted = null: مسح العد. صنف اتضاف بعد بداية الجرد بيتعدّ عادي
create or replace function public.save_stock_count(p_count uuid, p_item uuid, p_counted bigint) returns void
language plpgsql security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); c public.stock_counts; q bigint;
begin
  perform public.grant_require('inventory', 'edit');
  c := public.stock_count_get(p_count, true);
  if p_counted is not null and (p_counted < 0 or p_counted > 1000000) then raise exception 'E_BAD_QTY'; end if;
  -- قفل الصنف: بيع في نفس اللحظة يبقى قبل العد أو بعده
  perform 1 from public.items where id = p_item and shop_id = s and deleted_at is null and kind in ('part', 'accessory') for update;
  if not found then raise exception 'E_NOT_FOUND'; end if;
  select st.qty into q from public.item_stock_at(p_item, c.branch_id) st;
  insert into public.stock_count_lines(shop_id, count_id, item_id, opening_qty) values (s, c.id, p_item, q) on conflict (count_id, item_id) do nothing;
  update public.stock_count_lines set counted_qty = p_counted, system_qty = case when p_counted is not null then q end,
         counted_at = case when p_counted is not null then now() end, counted_by = case when p_counted is not null then auth.uid() end
  where count_id = c.id and item_id = p_item;
end $$;

create or replace function public.cancel_stock_count(p_count uuid) returns void
language plpgsql security definer set search_path = public as $$
declare c public.stock_counts;
begin
  perform public.grant_require('inventory', 'edit');
  c := public.stock_count_get(p_count, false);
  if c.status = 'cancelled' then return; end if;
  if c.status = 'posted' then raise exception 'E_COUNT_CLOSED'; end if;
  update public.stock_counts set status = 'cancelled', closed_at = now(), closed_by = auth.uid() where id = c.id;
end $$;

-- الاعتماد: النقص بيخرج بمتوسط تكلفته، والزيادة بتدخل بآخر تكلفة، والفرق في "هالك المخزون". من غير فروق: بيتقفل من غير قيد
create or replace function public.post_stock_count(p_id uuid, p_count uuid, p_reason text) returns uuid
language plpgsql security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); c public.stock_counts; l record; e uuid; diff bigint; cost bigint; net bigint := 0; gross bigint := 0; n int := 0;
begin
  perform public.grant_require('inventory', 'amounts');
  perform public.grant_require('inventory', 'delete');
  e := public.ledger_idem(p_id);
  if e is not null then return e; end if;
  c := public.stock_count_get(p_count, false);
  if c.status = 'posted' then return c.entry_id; end if;
  if c.status <> 'open' then raise exception 'E_COUNT_CLOSED'; end if;
  if nullif(trim(p_reason), '') is null then raise exception 'E_REASON_REQUIRED'; end if;
  if not exists (select 1 from public.stock_count_lines where count_id = c.id and counted_qty is not null) then raise exception 'E_COUNT_EMPTY'; end if;
  if exists (select 1 from public.stock_count_lines sl join public.items i on i.id = sl.item_id and i.deleted_at is null where sl.count_id = c.id and sl.counted_qty <> sl.system_qty) then
    perform set_config('app.branch', c.branch_id::text, true);
    e := gen_random_uuid();
    insert into public.journal_entries(id, shop_id, source_type, source_id, memo, idem_key, created_by, branch_id)
    values (e, s, 'stock_count', c.id, left(trim(p_reason), 300), p_id, auth.uid(), c.branch_id);
    -- بترتيب ثابت عشان جردين ما يستنوش بعض. صنف اتحذف بعد العد (رصيده صفر): مفيش حاجة تتسوى
    for l in select sl.* from public.stock_count_lines sl join public.items i on i.id = sl.item_id and i.deleted_at is null
             where sl.count_id = c.id and sl.counted_qty <> sl.system_qty order by sl.item_id loop
      perform 1 from public.items where id = l.item_id for update;
      diff := l.counted_qty - l.system_qty;
      if diff < 0 then
        cost := public.ledger_issue(l.item_id, -diff, e);
        net := net + cost;
      else
        cost := public.stock_count_cost(l.item_id, c.branch_id) * diff;
        -- زيادة في صنف تكلفته مش معروفة: بتتسجل من "تسوية مخزون" بتكلفتها
        if cost <= 0 then raise exception 'E_COUNT_COST'; end if;
        insert into public.stock_moves(shop_id, item_id, entry_id, qty, value, branch_id) values (s, l.item_id, e, diff, cost, c.branch_id);
        net := net - cost;
      end if;
      gross := gross + cost;
      n := n + 1;
    end loop;
    if gross = 0 then raise exception 'E_COUNT_COST'; end if;
    -- الزيادة والنقص كل واحد بسطره (القيد بيبان منه الاتنين حتى لو صافيهم صفر)
    if (gross + net) / 2 > 0 then
      insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values
        (s, e, public.ledger_acc('wastage'), (gross + net) / 2, 0), (s, e, public.ledger_acc('inventory'), 0, (gross + net) / 2);
    end if;
    if (gross - net) / 2 > 0 then
      insert into public.journal_lines(shop_id, entry_id, account_id, debit, credit) values
        (s, e, public.ledger_acc('inventory'), (gross - net) / 2, 0), (s, e, public.ledger_acc('wastage'), 0, (gross - net) / 2);
    end if;
  end if;
  update public.stock_counts set status = 'posted', closed_at = now(), closed_by = auth.uid(), entry_id = e where id = c.id;
  insert into public.audit_log(shop_id, actor_id, action, entity, entity_id, after)
  values (s, auth.uid(), 'stock_count_post', 'stock_counts', c.id, jsonb_build_object('items', n, 'shortage', (gross + net) / 2, 'surplus', (gross - net) / 2, 'reason', left(trim(p_reason), 300), 'entry', e));
  return e;
end $$;

-- كشف الفروق: القيمة (بالتكلفة) لأصحاب "المبالغ" بس
create or replace function public.stock_count_sheet(p_count uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare c public.stock_counts; m boolean := public.has_perm('inventory', 'amounts');
begin
  perform public.grant_require('inventory', 'edit');
  select * into c from public.stock_counts where id = p_count and shop_id = public.current_shop_id() and deleted_at is null;
  if not found or (public.current_app_role() <> 'owner' and not public.can_branch(c.branch_id)) then raise exception 'E_NOT_FOUND'; end if;
  return jsonb_build_object('id', c.id, 'branch_id', c.branch_id, 'status', c.status, 'note', c.note, 'started_at', c.created_at, 'closed_at', c.closed_at, 'entry', c.entry_id,
    'reversed', exists (select 1 from public.journal_entries x where x.reverses_id = c.entry_id),
    'lines', coalesce((select jsonb_agg(jsonb_build_object('item', l.item_id, 'name', i.name, 'opening', l.opening_qty, 'system', l.system_qty, 'counted', l.counted_qty, 'diff', l.counted_qty - l.system_qty,
        'counted_at', l.counted_at, 'value', case when m and l.counted_qty is not null then (l.counted_qty - l.system_qty) * public.stock_count_cost(l.item_id, c.branch_id) end) order by i.name, i.id)
      from public.stock_count_lines l join public.items i on i.id = l.item_id where l.count_id = c.id), '[]'::jsonb));
end $$;
do $$
declare f text;
begin
  foreach f in array array['start_stock_count(uuid, text)', 'save_stock_count(uuid, uuid, bigint)', 'cancel_stock_count(uuid)', 'post_stock_count(uuid, uuid, text)', 'stock_count_sheet(uuid)'] loop
    execute format('revoke execute on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;

-- entry_section: (src: 0075_delete_by_section.sql) + قيد الجرد تبع المخزون
create or replace function public.entry_section(p_source text) returns text
language sql immutable as $$
  select case
    when p_source in ('sale', 'sale_return') then 'sales'
    when p_source in ('payment', 'transfer', 'drawer_close') then 'cashbox'
    when p_source = 'expense' then 'expenses'
    when p_source in ('purchase', 'supplier_payment', 'supplier_return') then 'purchases'
    when p_source in ('write_off', 'stock_transfer', 'stock_count') then 'inventory'
    when p_source in ('part_use', 'delivery') then 'devices'
    else 'finance' end
$$;

-- backup_snapshot: (src: 0079_purchase_orders.sql) + الجرد
create or replace function public.backup_snapshot(p_shop uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  res jsonb := jsonb_build_object('format', 'warsha-backup', 'version', 1, 'generated_at', now(), 'shop_id', p_shop);
  t text;
  rows jsonb;
begin
  foreach t in array array['shops', 'branches', 'staff_branches', 'attendance', 'shop_branding', 'profiles', 'customers', 'devices', 'device_costs', 'status_log', 'device_notes', 'device_photos', 'device_checks',
                           'quote_decisions', 'message_templates', 'message_log', 'accounts', 'journal_entries', 'journal_lines', 'sale_lines', 'cheques', 'payments', 'drawer_closings',
                           'suppliers', 'categories', 'items', 'purchase_orders', 'purchase_order_lines', 'stock_counts', 'stock_count_lines', 'stock_moves', 'uncosted_sales', 'payment_plans', 'plan_installments', 'branch_goals', 'printers', 'print_templates', 'check_templates', 'used_devices', 'commission_rules', 'purchases', 'labor_rates', 'specialties', 'staff_specialties', 'routes', 'repair_steps',
                           'repair_videos', 'device_ratings', 'issue_presets', 'partners', 'profit_distributions', 'party_links', 'shop_lists', 'audit_log'] loop
    execute format('select coalesce(jsonb_agg(to_jsonb(x)), ''[]''::jsonb) from public.%I x where x.shop_id = $1', t) into rows using p_shop;
    res := res || jsonb_build_object(t, rows);
  end loop;
  select coalesce(jsonb_agg(jsonb_build_object('device_id', device_id, 'kind', kind, 'erased_at', erased_at)), '[]'::jsonb)
    into rows from public.device_passcodes where shop_id = p_shop;
  return res || jsonb_build_object('device_passcodes', rows);
end $$;

-- restore_backup: (src: 0079_purchase_orders.sql) + الجرد
create or replace function public.restore_backup(p_data jsonb) returns jsonb
-- extensions: فيها gen_random_bytes على Supabase
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare
  s uuid := public.current_shop_id();
  me uuid := auth.uid();
  old_shop uuid;
  old_owner uuid;
  sh jsonb;
  t text;
  r jsonb;
  rows jsonb;
  n int;
  bad int;
  counts jsonb := '{}'::jsonb;
  -- بالترتيب ده عشان كل صف يلاقي اللي بيشاور عليه
  tabs text[] := array['branches', 'profiles', 'staff_branches', 'attendance', 'shop_branding', 'accounts', 'customers', 'suppliers', 'party_links', 'partners', 'specialties', 'staff_specialties', 'routes', 'labor_rates',
                       'issue_presets', 'commission_rules', 'shop_lists', 'message_templates', 'categories', 'items', 'devices', 'device_costs', 'status_log', 'device_notes', 'device_checks',
                       'quote_decisions', 'repair_steps', 'repair_videos', 'device_ratings', 'journal_entries', 'journal_lines', 'sale_lines', 'cheques', 'profit_distributions', 'payments',
                       'purchases', 'purchase_orders', 'purchase_order_lines', 'stock_counts', 'stock_count_lines', 'stock_moves', 'uncosted_sales', 'used_devices', 'payment_plans', 'plan_installments', 'branch_goals', 'printers', 'print_templates', 'check_templates', 'drawer_closings', 'message_log', 'audit_log'];
  -- الجداول دي ليها نسخة اتعملت مع التسجيل: بتتطابق بالكود (أو المفتاح) وبتاخد قيم النسخة
  keyed text[] := array['branches', 'accounts', 'routes', 'specialties', 'message_templates', 'labor_rates', 'shop_branding'];
begin
  perform public.ledger_require(array['owner']::public.app_role[]);
  if s is null or me is null then raise exception 'E_FORBIDDEN'; end if;
  if p_data is null or p_data->>'format' is distinct from 'warsha-backup' or coalesce((p_data->>'version')::int, 0) <> 1 then
    raise exception 'E_BACKUP_FORMAT';
  end if;
  old_shop := (p_data->>'shop_id')::uuid;
  if old_shop is null or old_shop = s then raise exception 'E_BACKUP_FORMAT'; end if;

  -- محل جديد فاضي بس
  if exists (select 1 from public.devices where shop_id = s) or exists (select 1 from public.customers where shop_id = s)
     or exists (select 1 from public.journal_entries where shop_id = s) or exists (select 1 from public.items where shop_id = s)
     or exists (select 1 from public.suppliers where shop_id = s) or exists (select 1 from public.payments where shop_id = s)
     or exists (select 1 from public.purchases where shop_id = s) or exists (select 1 from public.drawer_closings where shop_id = s)
     or exists (select 1 from public.stock_moves where shop_id = s)
     or exists (select 1 from public.attendance where shop_id = s and deleted_at is null)
     or exists (select 1 from public.stock_counts where shop_id = s and status = 'open')
     or exists (select 1 from public.profiles where shop_id = s and id <> me) then
    raise exception 'E_RESTORE_NOT_EMPTY';
  end if;

  perform set_config('warsha.restore', 'on', true);
  drop table if exists pg_temp._rmap;
  create temp table _rmap(old uuid primary key, new uuid not null) on commit drop;
  insert into _rmap values (old_shop, s);

  -- 1) بيانات المحل نفسه (من غير الخطة والإيقاف واللوجو اللي في Storage)
  sh := p_data->'shops'->0;
  if sh is not null then
    update public.shops set
      name = coalesce(sh->>'name', name), phone = sh->>'phone', address = sh->>'address',
      receipt_terms = coalesce(sh->>'receipt_terms', receipt_terms), warranty_days = coalesce((sh->>'warranty_days')::int, warranty_days),
      country = coalesce(sh->>'country', country), currency = coalesce(sh->>'currency', currency),
      payment_methods = coalesce(array(select jsonb_array_elements_text(sh->'payment_methods')), payment_methods),
      theme = coalesce(sh->>'theme', theme), locale = coalesce(sh->>'locale', locale),
      default_margin_pct = coalesce((sh->>'default_margin_pct')::int, default_margin_pct),
      extras = coalesce(sh->'extras', extras), max_discount_pct = coalesce((sh->>'max_discount_pct')::int, max_discount_pct)
    where id = s;
  end if;

  -- 2) الـ ids الجديدة
  -- صاحب المحل في النسخة = اللي بيسترجع دلوقتي
  select (x->>'id')::uuid into old_owner from jsonb_array_elements(coalesce(p_data->'profiles', '[]')) x
   where x->>'role' = 'owner' order by x->>'created_at' limit 1;
  if old_owner is not null then insert into _rmap values (old_owner, me) on conflict do nothing; end if;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.accounts a where a.shop_id = s and a.code = x->>'code' and x->>'code' is not null), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'accounts', '[]')) x on conflict do nothing;
  -- الفرع الرئيسي في النسخة = الفرع الرئيسي للمحل الجديد
  insert into _rmap select (x->>'id')::uuid, public.main_branch(s)
    from jsonb_array_elements(coalesce(p_data->'branches', '[]')) x where (x->>'is_main')::boolean and x->>'deleted_at' is null on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.routes a where a.shop_id = s and a.code = x->>'code' and x->>'code' is not null), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'routes', '[]')) x on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.specialties a where a.shop_id = s and a.code = x->>'code' and x->>'code' is not null), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'specialties', '[]')) x on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.message_templates a where a.shop_id = s and a.key = x->>'key'), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'message_templates', '[]')) x on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.labor_rates a where a.shop_id = s and a.deleted_at is null and lower(trim(a.issue)) = lower(trim(x->>'issue')) and x->>'deleted_at' is null), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'labor_rates', '[]')) x on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.shop_branding a where a.shop_id = s), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'shop_branding', '[]')) x on conflict do nothing;
  foreach t in array tabs loop
    insert into _rmap select (x->>'id')::uuid, gen_random_uuid() from jsonb_array_elements(coalesce(p_data->t, '[]')) x where x ? 'id' on conflict do nothing;
  end loop;

  -- 3) الصفوف نفسها بالترتيب
  foreach t in array tabs loop
    rows := '[]'::jsonb;
    for r in select public.restore_remap(x) from jsonb_array_elements(coalesce(p_data->t, '[]')) x loop
      if t = 'profiles' then
        -- صاحب المحل موجود أصلًا. الباقيين موظفين سابقين (من غير حساب دخول)
        continue when (r->>'id')::uuid = me;
        r := r || jsonb_build_object('deleted_at', coalesce(r->>'deleted_at', now()::text));
      elsif t = 'devices' then
        -- كود التتبع (الـ QR) بيفضل زي ما هو، إلا لو مستخدم في المشروع ده (المحل الأصلي لسه هنا)
        if exists (select 1 from public.devices d where d.tracking_token = r->>'tracking_token') then
          r := r || jsonb_build_object('tracking_token', encode(gen_random_bytes(12), 'hex'));
        end if;
      elsif t = 'journal_entries' then
        if r->>'idem_key' is not null and exists (select 1 from public.journal_entries j where j.idem_key = (r->>'idem_key')::uuid) then
          r := r || jsonb_build_object('idem_key', gen_random_uuid());
        end if;
      elsif t = 'accounts' and r->>'kind' = 'cash' and r->>'branch_id' is null then
        -- نسخة من قبل الفروع: الخزن كلها في الفرع الرئيسي
        r := r || jsonb_build_object('branch_id', public.main_branch(s));
      elsif t = 'used_devices' then
        -- رقم بطاقة البائع (في Vault) وصورتها (في Storage) مش جوه النسخة
        r := r || jsonb_build_object('seller_nid_secret', null, 'seller_photo', null);
      elsif t = 'shop_branding' then
        -- اللوجو الملون والحراري جوه الصف نفسه. الملف الأصلي في Storage مش جوه النسخة
        r := r || jsonb_build_object('logo_path', null);
      end if;
      if t = any (keyed) and exists (select 1 from _rmap m where m.new = (r->>'id')::uuid and m.old <> m.new)
         and (t <> 'shop_branding' or exists (select 1 from public.shop_branding b where b.id = (r->>'id')::uuid)) then
        -- موجود من التسجيل: بياخد قيم النسخة
        execute format('select count(*) from public.%I where id = $1', t) into n using (r->>'id')::uuid;
        if n > 0 then
          execute format('update public.%1$I x set (%2$s) = (select %2$s from jsonb_populate_record(null::public.%1$I, $1)) where x.id = $2', t,
            (select string_agg(quote_ident(c.column_name), ', ' order by c.ordinal_position) from information_schema.columns c
              where c.table_schema = 'public' and c.table_name = t and c.column_name not in ('id', 'shop_id')))
            using r, (r->>'id')::uuid;
          continue;
        end if;
      end if;
      rows := rows || jsonb_build_array(r);
    end loop;
    if jsonb_array_length(rows) > 0 then
      -- overriding system value: أرقام القيود (entry_no) بترجع زي ما هي
      execute format('insert into public.%1$I overriding system value select * from jsonb_populate_recordset(null::public.%1$I, $1)', t) using rows;
    end if;
    counts := counts || jsonb_build_object(t, jsonb_array_length(coalesce(p_data->t, '[]')));
  end loop;

  -- 4) عدّاد أرقام الطلبات: من آخر رقم راجع في كل سنة
  -- (لكل فرع: الرقم ممكن يبقى قبله بادئة الفرع B2-2026-0001)
  insert into public.order_counters(shop_id, branch_id, year, last_value)
  select s, branch_id, (regexp_match(order_no, '(\d{4})-(\d+)$'))[1]::int, max((regexp_match(order_no, '(\d{4})-(\d+)$'))[2]::int)
    from public.devices where shop_id = s and order_no ~ '\d{4}-\d+$' group by 2, 3
  on conflict (shop_id, branch_id, year) do update set last_value = greatest(public.order_counters.last_value, excluded.last_value);

  -- 5) التأكد: كل قيد متوازن، ورصيد كل حساب = رصيده في النسخة بالظبط
  select count(*) into bad from (
    select entry_id from public.journal_lines where shop_id = s group by entry_id having sum(debit) <> sum(credit)) x;
  if bad > 0 then raise exception 'E_RESTORE_UNBALANCED'; end if;
  select count(*) into bad from (
    select m.new acc, sum((l->>'debit')::bigint - (l->>'credit')::bigint) b
      from jsonb_array_elements(coalesce(p_data->'journal_lines', '[]')) l join _rmap m on m.old = (l->>'account_id')::uuid group by m.new
  ) x full join (select account_id, sum(debit - credit) b from public.journal_lines where shop_id = s group by account_id) y on y.account_id = x.acc
  where coalesce(x.b, 0) <> coalesce(y.b, 0);
  if bad > 0 then raise exception 'E_RESTORE_MISMATCH'; end if;
  -- وعدد الصفوف في كل جدول (الحسابات والقوالب اللي اتعملت مع التسجيل ممكن تزيد عن النسخة، مش تقل)
  foreach t in array tabs loop
    execute format('select count(*) from public.%I where shop_id = $1', t) into n using s;
    if n < jsonb_array_length(coalesce(p_data->t, '[]')) - (case when t = 'profiles' and old_owner is not null then 1 else 0 end) then
      raise exception 'E_RESTORE_MISMATCH';
    end if;
  end loop;

  perform set_config('warsha.restore', 'off', true);
  insert into public.audit_log(shop_id, actor_id, action, entity, entity_id, after)
  values (s, me, 'backup_restore', 'shops', s, jsonb_build_object('from_shop', old_shop, 'generated_at', p_data->>'generated_at', 'counts', counts));
  return jsonb_build_object('restored', true, 'counts', counts);
end $$;
$m0080$;
  insert into public.app_migrations(version, how) values ('0080_stock_count.sql', 'applied');
  raise notice 'applied %', '0080_stock_count.sql';
end $run$;
commit;

-- ============================== 0081_repair_invoice.sql ==============================
begin;
do $run$ begin
  if exists (select 1 from public.app_migrations where version = '0081_repair_invoice.sql') then return; end if;
  execute $m0081$
-- 0081: (19) فاتورة صيانة ثابتة: رقم مستقل وتاريخ إصدار لكل تسليم، والبيانات زي ما كانت وقت الإصدار.
-- - بتتعمل أول مرة الفاتورة تتطلب بعد التسليم، وبعدها نفس الفاتورة دايمًا (إعادة الطباعة ما بتغيّرش حاجة).
-- - مربوطة بقيد التسليم: لو اتلغى، الفاتورة بتبان ملغية (reversed)، والتسليم الجديد ليه رقم جديد. مرتجع الضمان بيرجع بنفس فاتورته.
-- - المبلغ والضريبة من القيد نفسه. المدفوع والباقي مش جوه الفاتورة (بيتغيّروا)، والشاشة بتقراهم لحظتها.
create table public.repair_invoices (
  id uuid primary key default gen_random_uuid(),
  shop_id uuid not null references public.shops(id),
  branch_id uuid not null references public.branches(id),
  device_id uuid not null references public.devices(id),
  entry_id uuid not null unique references public.journal_entries(id),
  prefix text not null default '',
  year integer not null,
  seq integer not null check (seq > 0),
  invoice_no text not null,
  issued_at timestamptz not null default now(),
  issued_by uuid references public.profiles(id),
  data jsonb not null check (jsonb_typeof(data) = 'object'),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  -- الترقيم بالبادئة مش بالفرع: بادئة اتنقلت لفرع تاني بتكمّل نفس الترقيم
  unique (shop_id, prefix, year, seq),
  unique (shop_id, invoice_no)
);
create index repair_invoices_device on public.repair_invoices(device_id);
alter table public.repair_invoices enable row level security;
revoke all on public.repair_invoices from public, anon, authenticated;
grant select on public.repair_invoices to authenticated;
create trigger set_updated_at before update on public.repair_invoices for each row execute function public.tg_set_updated_at();
create trigger block_delete before delete on public.repair_invoices for each row execute function public.tg_block_delete();
create trigger ledger_immutable before update or delete on public.repair_invoices for each row execute function public.tg_ledger_immutable();
create trigger ledger_no_truncate before truncate on public.repair_invoices for each statement execute function public.tg_ledger_immutable();
-- فيها اسم العميل والمبلغ: مبالغ الأجهزة + الجهاز نفسه باين (فرعه دلوقتي). الفني لأ. وسجل النشاط فيه الرقم بس
create policy repair_invoices_select on public.repair_invoices for select to authenticated
  using (shop_id = (select public.current_shop_id()) and (select public.current_app_role()) in ('owner', 'reception')
         and (select public.has_perm('devices', 'amounts')) and exists (select 1 from public.devices d where d.id = device_id));

-- p_issue = false: اقرا الموجودة بس (null لو لسه ما صدرتش)
create or replace function public.repair_invoice(p_device uuid, p_issue boolean default true) returns jsonb
language plpgsql security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); d public.devices; e public.journal_entries; inv public.repair_invoices; y integer; n integer; pre text; gross bigint; vat bigint;
begin
  perform public.ledger_require(array['owner', 'reception']::public.app_role[]);
  select * into d from public.devices where id = p_device and shop_id = s and deleted_at is null;
  if not found then raise exception 'E_NOT_FOUND'; end if;
  perform public.device_require(d.id, 'amounts');
  if p_issue then select * into d from public.devices where id = d.id for update; end if;
  select * into e from public.journal_entries j where j.shop_id = s and j.source_type = 'delivery' and j.source_id = d.id
    and not exists (select 1 from public.journal_entries x where x.reverses_id = j.id) order by j.occurred_at desc limit 1;
  if e.id is not null then select * into inv from public.repair_invoices where entry_id = e.id; end if;
  if inv.id is null then
    if not p_issue then return null; end if;
    -- لسه ما اتسلّمش، أو اتسلّم من غير تكلفة: مفيش فاتورة
    if e.id is null then raise exception 'E_NO_INVOICE'; end if;
    -- الجهاز راجع ضمان: قطع الضمان ما تدخلش فاتورة التسليم الأول
    if d.status <> 'delivered' then raise exception 'E_NO_INVOICE'; end if;
    select coalesce(sum(l.credit), 0), coalesce(sum(l.credit) filter (where a.kind = 'tax'), 0) into gross, vat
      from public.journal_lines l join public.accounts a on a.id = l.account_id where l.entry_id = e.id and a.kind in ('revenue', 'tax');
    y := extract(year from (now() at time zone 'Africa/Cairo'))::int;
    -- رقم ورا رقم من غير فجوات ولا تكرار للبادئة والسنة
    select coalesce(b.prefix, '') into pre from public.branches b where b.id = e.branch_id;
    perform pg_advisory_xact_lock(hashtextextended('repair_invoice:' || s || ':' || pre || ':' || y, 0));
    select coalesce(max(seq), 0) + 1 into n from public.repair_invoices where shop_id = s and prefix = pre and year = y;
    insert into public.repair_invoices(shop_id, branch_id, device_id, entry_id, prefix, year, seq, invoice_no, issued_by, data)
    values (s, e.branch_id, d.id, e.id, pre, y, n, concat_ws('-', nullif(pre, ''), 'F', y, lpad(n::text, greatest(4, length(n::text)), '0')), auth.uid(), jsonb_build_object(
      'order_no', d.order_no, 'brand', d.brand, 'model', d.model, 'imei', d.imei, 'issue', d.issue, 'received_at', d.received_at, 'delivered_at', e.occurred_at, 'warranty_until', d.warranty_until,
      'customer', (select c.name from public.customers c where c.id = d.customer_id), 'phone', (select c.phone from public.customers c where c.id = d.customer_id),
      'parts', coalesce((select jsonb_agg(jsonb_build_object('name', x.name, 'qty', x.qty) order by x.name) from public.device_parts(d.id) x), '[]'::jsonb),
      'total', gross, 'vat', vat, 'net', gross - vat,
      'vat_no', case when vat > 0 then (select nullif(trim(sh.extras -> 'vat' ->> 'reg_no'), '') from public.shops sh where sh.id = s) end,
      'currency', (select sh.currency from public.shops sh where sh.id = s)))
    returning * into inv;
    insert into public.audit_log(shop_id, actor_id, action, entity, entity_id, after)
    values (s, auth.uid(), 'insert', 'repair_invoices', inv.id, jsonb_build_object('invoice_no', inv.invoice_no, 'order_no', d.order_no));
  end if;
  return inv.data || jsonb_build_object('id', inv.id, 'invoice_no', inv.invoice_no, 'issued_at', inv.issued_at, 'branch_id', inv.branch_id, 'device_id', inv.device_id);
end $$;
revoke execute on function public.repair_invoice(uuid, boolean) from public, anon;
grant execute on function public.repair_invoice(uuid, boolean) to authenticated;

-- كل فواتير الجهاز (والملغي منها باين)
create or replace function public.repair_invoices_of(p_device uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  perform public.ledger_require(array['owner', 'reception']::public.app_role[]);
  if not exists (select 1 from public.devices where id = p_device and shop_id = public.current_shop_id()) then raise exception 'E_NOT_FOUND'; end if;
  perform public.device_require(p_device, 'amounts');
  return coalesce((select jsonb_agg(v.data || jsonb_build_object('id', v.id, 'invoice_no', v.invoice_no, 'issued_at', v.issued_at,
      'reversed', exists (select 1 from public.journal_entries x where x.reverses_id = v.entry_id)) order by v.issued_at, v.seq)
    from public.repair_invoices v where v.device_id = p_device), '[]'::jsonb);
end $$;
revoke execute on function public.repair_invoices_of(uuid) from public, anon;
grant execute on function public.repair_invoices_of(uuid) to authenticated;

-- backup_snapshot: (src: 0080_stock_count.sql) + فواتير الصيانة
create or replace function public.backup_snapshot(p_shop uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  res jsonb := jsonb_build_object('format', 'warsha-backup', 'version', 1, 'generated_at', now(), 'shop_id', p_shop);
  t text;
  rows jsonb;
begin
  foreach t in array array['shops', 'branches', 'staff_branches', 'attendance', 'shop_branding', 'profiles', 'customers', 'devices', 'device_costs', 'status_log', 'device_notes', 'device_photos', 'device_checks',
                           'quote_decisions', 'message_templates', 'message_log', 'accounts', 'journal_entries', 'journal_lines', 'repair_invoices', 'sale_lines', 'cheques', 'payments', 'drawer_closings',
                           'suppliers', 'categories', 'items', 'purchase_orders', 'purchase_order_lines', 'stock_counts', 'stock_count_lines', 'stock_moves', 'uncosted_sales', 'payment_plans', 'plan_installments', 'branch_goals', 'printers', 'print_templates', 'check_templates', 'used_devices', 'commission_rules', 'purchases', 'labor_rates', 'specialties', 'staff_specialties', 'routes', 'repair_steps',
                           'repair_videos', 'device_ratings', 'issue_presets', 'partners', 'profit_distributions', 'party_links', 'shop_lists', 'audit_log'] loop
    execute format('select coalesce(jsonb_agg(to_jsonb(x)), ''[]''::jsonb) from public.%I x where x.shop_id = $1', t) into rows using p_shop;
    res := res || jsonb_build_object(t, rows);
  end loop;
  select coalesce(jsonb_agg(jsonb_build_object('device_id', device_id, 'kind', kind, 'erased_at', erased_at)), '[]'::jsonb)
    into rows from public.device_passcodes where shop_id = p_shop;
  return res || jsonb_build_object('device_passcodes', rows);
end $$;

-- restore_backup: (src: 0080_stock_count.sql) + فواتير الصيانة
create or replace function public.restore_backup(p_data jsonb) returns jsonb
-- extensions: فيها gen_random_bytes على Supabase
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare
  s uuid := public.current_shop_id();
  me uuid := auth.uid();
  old_shop uuid;
  old_owner uuid;
  sh jsonb;
  t text;
  r jsonb;
  rows jsonb;
  n int;
  bad int;
  counts jsonb := '{}'::jsonb;
  -- بالترتيب ده عشان كل صف يلاقي اللي بيشاور عليه
  tabs text[] := array['branches', 'profiles', 'staff_branches', 'attendance', 'shop_branding', 'accounts', 'customers', 'suppliers', 'party_links', 'partners', 'specialties', 'staff_specialties', 'routes', 'labor_rates',
                       'issue_presets', 'commission_rules', 'shop_lists', 'message_templates', 'categories', 'items', 'devices', 'device_costs', 'status_log', 'device_notes', 'device_checks',
                       'quote_decisions', 'repair_steps', 'repair_videos', 'device_ratings', 'journal_entries', 'journal_lines', 'repair_invoices', 'sale_lines', 'cheques', 'profit_distributions', 'payments',
                       'purchases', 'purchase_orders', 'purchase_order_lines', 'stock_counts', 'stock_count_lines', 'stock_moves', 'uncosted_sales', 'used_devices', 'payment_plans', 'plan_installments', 'branch_goals', 'printers', 'print_templates', 'check_templates', 'drawer_closings', 'message_log', 'audit_log'];
  -- الجداول دي ليها نسخة اتعملت مع التسجيل: بتتطابق بالكود (أو المفتاح) وبتاخد قيم النسخة
  keyed text[] := array['branches', 'accounts', 'routes', 'specialties', 'message_templates', 'labor_rates', 'shop_branding'];
begin
  perform public.ledger_require(array['owner']::public.app_role[]);
  if s is null or me is null then raise exception 'E_FORBIDDEN'; end if;
  if p_data is null or p_data->>'format' is distinct from 'warsha-backup' or coalesce((p_data->>'version')::int, 0) <> 1 then
    raise exception 'E_BACKUP_FORMAT';
  end if;
  old_shop := (p_data->>'shop_id')::uuid;
  if old_shop is null or old_shop = s then raise exception 'E_BACKUP_FORMAT'; end if;

  -- محل جديد فاضي بس
  if exists (select 1 from public.devices where shop_id = s) or exists (select 1 from public.customers where shop_id = s)
     or exists (select 1 from public.journal_entries where shop_id = s) or exists (select 1 from public.items where shop_id = s)
     or exists (select 1 from public.suppliers where shop_id = s) or exists (select 1 from public.payments where shop_id = s)
     or exists (select 1 from public.purchases where shop_id = s) or exists (select 1 from public.drawer_closings where shop_id = s)
     or exists (select 1 from public.stock_moves where shop_id = s)
     or exists (select 1 from public.attendance where shop_id = s and deleted_at is null)
     or exists (select 1 from public.stock_counts where shop_id = s and status = 'open')
     or exists (select 1 from public.profiles where shop_id = s and id <> me) then
    raise exception 'E_RESTORE_NOT_EMPTY';
  end if;

  perform set_config('warsha.restore', 'on', true);
  drop table if exists pg_temp._rmap;
  create temp table _rmap(old uuid primary key, new uuid not null) on commit drop;
  insert into _rmap values (old_shop, s);

  -- 1) بيانات المحل نفسه (من غير الخطة والإيقاف واللوجو اللي في Storage)
  sh := p_data->'shops'->0;
  if sh is not null then
    update public.shops set
      name = coalesce(sh->>'name', name), phone = sh->>'phone', address = sh->>'address',
      receipt_terms = coalesce(sh->>'receipt_terms', receipt_terms), warranty_days = coalesce((sh->>'warranty_days')::int, warranty_days),
      country = coalesce(sh->>'country', country), currency = coalesce(sh->>'currency', currency),
      payment_methods = coalesce(array(select jsonb_array_elements_text(sh->'payment_methods')), payment_methods),
      theme = coalesce(sh->>'theme', theme), locale = coalesce(sh->>'locale', locale),
      default_margin_pct = coalesce((sh->>'default_margin_pct')::int, default_margin_pct),
      extras = coalesce(sh->'extras', extras), max_discount_pct = coalesce((sh->>'max_discount_pct')::int, max_discount_pct)
    where id = s;
  end if;

  -- 2) الـ ids الجديدة
  -- صاحب المحل في النسخة = اللي بيسترجع دلوقتي
  select (x->>'id')::uuid into old_owner from jsonb_array_elements(coalesce(p_data->'profiles', '[]')) x
   where x->>'role' = 'owner' order by x->>'created_at' limit 1;
  if old_owner is not null then insert into _rmap values (old_owner, me) on conflict do nothing; end if;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.accounts a where a.shop_id = s and a.code = x->>'code' and x->>'code' is not null), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'accounts', '[]')) x on conflict do nothing;
  -- الفرع الرئيسي في النسخة = الفرع الرئيسي للمحل الجديد
  insert into _rmap select (x->>'id')::uuid, public.main_branch(s)
    from jsonb_array_elements(coalesce(p_data->'branches', '[]')) x where (x->>'is_main')::boolean and x->>'deleted_at' is null on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.routes a where a.shop_id = s and a.code = x->>'code' and x->>'code' is not null), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'routes', '[]')) x on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.specialties a where a.shop_id = s and a.code = x->>'code' and x->>'code' is not null), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'specialties', '[]')) x on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.message_templates a where a.shop_id = s and a.key = x->>'key'), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'message_templates', '[]')) x on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.labor_rates a where a.shop_id = s and a.deleted_at is null and lower(trim(a.issue)) = lower(trim(x->>'issue')) and x->>'deleted_at' is null), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'labor_rates', '[]')) x on conflict do nothing;
  insert into _rmap select (x->>'id')::uuid, coalesce((select a.id from public.shop_branding a where a.shop_id = s), gen_random_uuid())
    from jsonb_array_elements(coalesce(p_data->'shop_branding', '[]')) x on conflict do nothing;
  foreach t in array tabs loop
    insert into _rmap select (x->>'id')::uuid, gen_random_uuid() from jsonb_array_elements(coalesce(p_data->t, '[]')) x where x ? 'id' on conflict do nothing;
  end loop;

  -- 3) الصفوف نفسها بالترتيب
  foreach t in array tabs loop
    rows := '[]'::jsonb;
    for r in select public.restore_remap(x) from jsonb_array_elements(coalesce(p_data->t, '[]')) x loop
      if t = 'profiles' then
        -- صاحب المحل موجود أصلًا. الباقيين موظفين سابقين (من غير حساب دخول)
        continue when (r->>'id')::uuid = me;
        r := r || jsonb_build_object('deleted_at', coalesce(r->>'deleted_at', now()::text));
      elsif t = 'devices' then
        -- كود التتبع (الـ QR) بيفضل زي ما هو، إلا لو مستخدم في المشروع ده (المحل الأصلي لسه هنا)
        if exists (select 1 from public.devices d where d.tracking_token = r->>'tracking_token') then
          r := r || jsonb_build_object('tracking_token', encode(gen_random_bytes(12), 'hex'));
        end if;
      elsif t = 'journal_entries' then
        if r->>'idem_key' is not null and exists (select 1 from public.journal_entries j where j.idem_key = (r->>'idem_key')::uuid) then
          r := r || jsonb_build_object('idem_key', gen_random_uuid());
        end if;
      elsif t = 'accounts' and r->>'kind' = 'cash' and r->>'branch_id' is null then
        -- نسخة من قبل الفروع: الخزن كلها في الفرع الرئيسي
        r := r || jsonb_build_object('branch_id', public.main_branch(s));
      elsif t = 'used_devices' then
        -- رقم بطاقة البائع (في Vault) وصورتها (في Storage) مش جوه النسخة
        r := r || jsonb_build_object('seller_nid_secret', null, 'seller_photo', null);
      elsif t = 'shop_branding' then
        -- اللوجو الملون والحراري جوه الصف نفسه. الملف الأصلي في Storage مش جوه النسخة
        r := r || jsonb_build_object('logo_path', null);
      end if;
      if t = any (keyed) and exists (select 1 from _rmap m where m.new = (r->>'id')::uuid and m.old <> m.new)
         and (t <> 'shop_branding' or exists (select 1 from public.shop_branding b where b.id = (r->>'id')::uuid)) then
        -- موجود من التسجيل: بياخد قيم النسخة
        execute format('select count(*) from public.%I where id = $1', t) into n using (r->>'id')::uuid;
        if n > 0 then
          execute format('update public.%1$I x set (%2$s) = (select %2$s from jsonb_populate_record(null::public.%1$I, $1)) where x.id = $2', t,
            (select string_agg(quote_ident(c.column_name), ', ' order by c.ordinal_position) from information_schema.columns c
              where c.table_schema = 'public' and c.table_name = t and c.column_name not in ('id', 'shop_id')))
            using r, (r->>'id')::uuid;
          continue;
        end if;
      end if;
      rows := rows || jsonb_build_array(r);
    end loop;
    if jsonb_array_length(rows) > 0 then
      -- overriding system value: أرقام القيود (entry_no) بترجع زي ما هي
      execute format('insert into public.%1$I overriding system value select * from jsonb_populate_recordset(null::public.%1$I, $1)', t) using rows;
    end if;
    counts := counts || jsonb_build_object(t, jsonb_array_length(coalesce(p_data->t, '[]')));
  end loop;

  -- 4) عدّاد أرقام الطلبات: من آخر رقم راجع في كل سنة
  -- (لكل فرع: الرقم ممكن يبقى قبله بادئة الفرع B2-2026-0001)
  insert into public.order_counters(shop_id, branch_id, year, last_value)
  select s, branch_id, (regexp_match(order_no, '(\d{4})-(\d+)$'))[1]::int, max((regexp_match(order_no, '(\d{4})-(\d+)$'))[2]::int)
    from public.devices where shop_id = s and order_no ~ '\d{4}-\d+$' group by 2, 3
  on conflict (shop_id, branch_id, year) do update set last_value = greatest(public.order_counters.last_value, excluded.last_value);

  -- 5) التأكد: كل قيد متوازن، ورصيد كل حساب = رصيده في النسخة بالظبط
  select count(*) into bad from (
    select entry_id from public.journal_lines where shop_id = s group by entry_id having sum(debit) <> sum(credit)) x;
  if bad > 0 then raise exception 'E_RESTORE_UNBALANCED'; end if;
  select count(*) into bad from (
    select m.new acc, sum((l->>'debit')::bigint - (l->>'credit')::bigint) b
      from jsonb_array_elements(coalesce(p_data->'journal_lines', '[]')) l join _rmap m on m.old = (l->>'account_id')::uuid group by m.new
  ) x full join (select account_id, sum(debit - credit) b from public.journal_lines where shop_id = s group by account_id) y on y.account_id = x.acc
  where coalesce(x.b, 0) <> coalesce(y.b, 0);
  if bad > 0 then raise exception 'E_RESTORE_MISMATCH'; end if;
  -- وعدد الصفوف في كل جدول (الحسابات والقوالب اللي اتعملت مع التسجيل ممكن تزيد عن النسخة، مش تقل)
  foreach t in array tabs loop
    execute format('select count(*) from public.%I where shop_id = $1', t) into n using s;
    if n < jsonb_array_length(coalesce(p_data->t, '[]')) - (case when t = 'profiles' and old_owner is not null then 1 else 0 end) then
      raise exception 'E_RESTORE_MISMATCH';
    end if;
  end loop;

  perform set_config('warsha.restore', 'off', true);
  insert into public.audit_log(shop_id, actor_id, action, entity, entity_id, after)
  values (s, me, 'backup_restore', 'shops', s, jsonb_build_object('from_shop', old_shop, 'generated_at', p_data->>'generated_at', 'counts', counts));
  return jsonb_build_object('restored', true, 'counts', counts);
end $$;
$m0081$;
  insert into public.app_migrations(version, how) values ('0081_repair_invoice.sql', 'applied');
  raise notice 'applied %', '0081_repair_invoice.sql';
end $run$;
commit;

-- ============================== 0082_order_prefix.sql ==============================
begin;
do $run$ begin
  if exists (select 1 from public.app_migrations where version = '0082_order_prefix.sql') then return; end if;
  execute $m0082$
-- 0082: (35ج) بادئة فرع اتعاد استخدامها كانت بتكرّر رقم الطلب والاستلام بيقف.
-- - save_branch بيرفض بادئة اتستخدمت قبل كده في المحل (أجهزة أو فواتير)، حتى لو فرعها اتقفل أو غيّر بادئته.
-- - المحلات اللي وقعت فيها خلاص: العدّاد بيعدّي الأرقام المستخدمة. (وبيغطي جهاز اتنقل لفرع تاني قبل استرجاع نسخة.)
-- - الرقم بعد 9999 بيكمّل بخانات أكتر (lpad كانت بتقصّه وتكرّره).

-- tg_device_defaults: (src: 0034_branches.sql)
create or replace function public.tg_device_defaults() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  y integer := extract(year from (now() at time zone 'Africa/Cairo'))::integer;
  n integer;
  pre text;
begin
  -- وقت الاسترجاع: الصف راجع زي ما هو من النسخة (src: 0023)
  if public.restoring() then return new; end if;
  select b.prefix into pre from public.branches b where b.id = new.branch_id;
  insert into public.order_counters(shop_id, branch_id, year, last_value)
  values (new.shop_id, new.branch_id, y, 1)
  on conflict (shop_id, branch_id, year) do update set last_value = public.order_counters.last_value + 1
  returning last_value into n;
  -- الرئيسي: 2026-0042 زي الأول. فرع تاني: B2-2026-0001
  loop
    new.order_no := concat_ws('-', nullif(pre, ''), y, lpad(n::text, greatest(4, length(n::text)), '0'));
    exit when not exists (select 1 from public.devices d where d.shop_id = new.shop_id and d.order_no = new.order_no);
    n := n + 1;
  end loop;
  update public.order_counters set last_value = n where shop_id = new.shop_id and branch_id = new.branch_id and year = y and last_value <> n;
  new.status := 'received';
  new.received_by := auth.uid();
  new.received_at := now();
  new.delivered_at := null;
  return new;
end $$;

create or replace function public.prefix_used(p_shop uuid, p_prefix text) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.devices where shop_id = p_shop and order_no ~ ('^' || p_prefix || '-[0-9]{4}-[0-9]+$'))
      or exists (select 1 from public.repair_invoices where shop_id = p_shop and prefix = p_prefix)
$$;
revoke execute on function public.prefix_used(uuid, text) from public, anon, authenticated;

-- save_branch: (src: 0034_branches.sql) + E_PREFIX_USED
create or replace function public.save_branch(p_id uuid, p_name text, p_prefix text, p_phone text default null, p_address text default null) returns uuid
language plpgsql security definer set search_path = public as $$
declare s uuid := public.current_shop_id(); b public.branches; pre text := upper(trim(coalesce(p_prefix, ''))); m text; nm text := trim(coalesce(p_name, ''));
begin
  perform public.ledger_require(array['owner']::public.app_role[]);
  if nm = '' or length(nm) > 80 then raise exception 'E_BAD_INPUT'; end if;
  select * into b from public.branches where id = p_id and shop_id = s for update;
  if found then
    if b.deleted_at is not null then raise exception 'E_NOT_FOUND'; end if;
    if b.is_main then pre := b.prefix; end if; -- الرئيسي: أرقامه زي ما هي
    if pre !~ '^[A-Z0-9]{1,4}$' and not b.is_main then raise exception 'E_BAD_PREFIX'; end if;
    if exists (select 1 from public.branches x where x.shop_id = s and x.deleted_at is null and x.id <> b.id and x.prefix = pre) then raise exception 'E_DUP_PREFIX'; end if;
    if pre <> b.prefix and public.prefix_used(s, pre) then raise exception 'E_PREFIX_USED'; end if;
    if exists (select 1 from public.branches x where x.shop_id = s and x.deleted_at is null and x.id <> b.id and lower(trim(x.name)) = lower(nm)) then raise exception 'E_DUP_NAME'; end if;
    update public.branches set name = nm, prefix = pre, phone = nullif(trim(p_phone), ''), address = nullif(trim(p_address), '') where id = b.id;
    return b.id;
  end if;
  if pre !~ '^[A-Z0-9]{1,4}$' then raise exception 'E_BAD_PREFIX'; end if;
  if exists (select 1 from public.branches x where x.shop_id = s and x.deleted_at is null and x.prefix = pre) then raise exception 'E_DUP_PREFIX'; end if;
  if public.prefix_used(s, pre) then raise exception 'E_PREFIX_USED'; end if;
  if exists (select 1 from public.branches x where x.shop_id = s and x.deleted_at is null and lower(trim(x.name)) = lower(nm)) then raise exception 'E_DUP_NAME'; end if;
  insert into public.branches(id, shop_id, name, prefix, phone, address) values (p_id, s, nm, pre, nullif(trim(p_phone), ''), nullif(trim(p_address), ''));
  for m in select unnest(array['cash']) union select unnest(payment_methods) from public.shops where id = s loop
    insert into public.accounts(shop_id, name, type, kind, method, branch_id) values (s, nm, 'asset', 'cash', m, p_id);
  end loop;
  return p_id;
end $$;
$m0082$;
  insert into public.app_migrations(version, how) values ('0082_order_prefix.sql', 'applied');
  raise notice 'applied %', '0082_order_prefix.sql';
end $run$;
commit;

